window.PYTHON_COURSES = [{"id":"python-ch01","slug":"ch01","number":1,"title":"프로그램을 읽고 실행하기","description":"입력과 처리, 코드와 출력, 실행과 오류의 차이를 작은 프로그램으로 이해합니다.","prerequisite":"처음 시작해도 괜찮아요.","runtime":"Python 3","testedVersion":"3.12.14","lessons":[{"id":"python-l001","order":1,"title":"프로그램·명령·실행 결과","subtitle":"주어진 데이터에 어떤 일을 해서 어떤 결과를 만들지, 세 부분으로 읽어 봅니다.","minutes":7,"goal":"작은 프로그램에서 사용하는 데이터, 처리 과정, 출력 결과를 구분한다.","intro":"컴퓨터에게 ‘알아서 잘 계산해 줘’라고만 말하면 무엇을 계산할지 정해지지 않습니다. 사용할 값과 해야 할 일을 정확하게 적어야 합니다. 프로그래밍의 첫걸음은 낯선 기호를 외우는 것보다, 내가 원하는 결과까지의 과정을 나누어 보는 데 있습니다.","sections":[{"title":"프로그램은 실행할 일을 적은 절차입니다","body":["프로그램은 컴퓨터가 수행할 일을 정해진 문법으로 적은 것입니다. 파이썬으로 적은 프로그램의 글을 파이썬 코드라고 합니다. 사람에게 부탁하는 말과 달리, 코드에서는 기호와 순서에 정해진 뜻이 있습니다.","아래의 print(...)는 괄호 안의 값을 화면의 출력 영역에 보여 달라는 요청입니다. 따옴표로 둘러싼 부분은 글자 내용입니다. 아직 괄호와 따옴표를 모두 외울 필요는 없습니다. 지금은 두 요청이 실행되면 두 줄의 결과가 나온다는 관계부터 살펴보세요."],"code":{"source":"print(\"준비\")\nprint(\"시작\")","kind":"python","output":"준비\n시작","error":null,"caption":"코드는 할 일이고, 출력은 그 일을 실행한 뒤 나타나는 결과입니다."}},{"title":"데이터와 처리를 나누면 코드가 읽힙니다","body":["입력은 프로그램이 작업에 사용하는 데이터를 받아들이는 쪽, 처리는 그 데이터로 계산하거나 판단하는 일, 출력은 만들어진 결과를 밖으로 내보내는 쪽입니다. 계산기에서 1200과 800을 받아 더한 뒤 2000을 보여 주는 상황을 떠올리면 됩니다.","아래 코드는 키보드에서 값을 새로 받지 않습니다. 사용할 숫자 1200과 800을 코드 안에 미리 적었습니다. 이 숫자들은 계산할 데이터이고, +는 더하는 처리이며, print는 계산된 값을 출력합니다. 입력을 받는 방식은 여러 가지이므로 모든 프로그램이 실행할 때마다 사람의 입력을 기다리는 것은 아닙니다."],"code":{"source":"print(1200 + 800)","kind":"python","output":"2000","error":null,"caption":"먼저 1200 + 800의 값이 계산되고, print가 그 값 2000을 보여 줍니다."}},{"title":"코드와 결과는 서로 다른 것입니다","body":["print(1200 + 800)라는 글 전체가 화면에 나오는 것은 아닙니다. 파이썬은 이 코드를 지시로 해석하여 덧셈을 한 뒤 결과를 출력합니다. 코드를 읽을 때는 ‘어떤 글이 적혀 있나’에서 한 걸음 더 나아가 ‘이 지시가 실행되면 무엇이 나타날까’를 생각해야 합니다.","출력은 화면에 나타나는 글자만 뜻하지도 않습니다. 사진을 받아 크기를 줄이고 새 파일로 저장하는 프로그램이라면, 입력은 원본 사진이고 처리는 크기 변경이며 출력은 새 사진 파일입니다. 이 챕터에서는 결과를 쉽게 확인할 수 있도록 화면 출력부터 사용합니다."]}],"worked":{"question":"1000원짜리 물건과 500원짜리 물건을 하나씩 산 금액을 보여 주려면, 아래 코드를 어떻게 읽으면 될까요?","code":{"source":"print(1000 + 500)","kind":"python","output":"1500","error":null,"caption":"출력에는 단위인 ‘원’을 따로 적지 않았으므로 숫자 1500만 나타납니다."},"steps":["계산할 데이터는 코드 안에 적힌 1000과 500입니다. 별도의 키보드 입력은 없습니다.","+가 두 수를 더합니다. 이 식의 값은 1500입니다.","print가 계산된 값을 출력합니다. 식 자체나 ‘원’이라는 글자를 자동으로 덧붙이지 않습니다."],"answer":"데이터 1000과 500에 덧셈을 적용하여 1500을 출력하는 프로그램입니다."},"misconception":{"question":"실행할 때 키보드로 입력하지 않으면 입력 데이터가 없는 건가요?","answer":"사람이 매번 타이핑해야만 프로그램이 데이터를 사용할 수 있는 것은 아닙니다. 코드에 미리 적은 값, 읽어 온 파일, 다른 프로그램이 보낸 값도 작업에 사용됩니다. 다만 print(1000 + 500)에는 외부에서 새 값을 받아들이는 동작이 없다는 점은 구분해야 합니다."},"keypoints":["코드는 할 일을 적은 글이고, 실행 결과는 그 지시를 수행한 뒤 나타나는 것입니다.","사용할 데이터, 데이터를 다루는 처리, 밖으로 내보내는 출력을 나누어 읽습니다.","print(...)는 괄호 안의 값을 출력하며, 키보드 입력을 받는 명령은 아닙니다."],"examples":[{"question":"본문의 print(...)는 괄호 안의 값을 출력합니다. 아래 코드를 직접 적고, 실행하면 어떤 한 줄이 나올지 먼저 예상해 보세요. 실행 결과와 코드 자체가 어떻게 다른지도 한 문장으로 적어 보세요.","skill":"코드와 실행 결과","solution":{"answer":"출력은 5입니다. 코드는 덧셈과 출력을 요청하는 글이고, 화면에는 그 요청을 수행한 결과가 나타납니다.","code":{"source":"print(2 + 3)","kind":"python","output":"5","error":null}},"explanation":"2 + 3을 계산한 값이 print에 전달됩니다. print라는 이름과 괄호, 식 전체를 그대로 출력하는 것은 아닙니다.","code":"print(2 + 3)","codeKind":"python"},{"question":"1000원짜리 물건과 500원짜리 물건을 하나씩 산 금액을 계산해 출력하는 코드 한 줄을 작성하세요. 사용할 두 숫자, 처리할 일, 예상 출력을 각각 적은 뒤 확인해 보세요. 출력에는 원이라는 단위를 붙이지 않습니다.","skill":"데이터·처리·출력 구분","solution":{"answer":"사용할 데이터는 1000과 500, 처리는 덧셈, 출력은 1500입니다. 아래는 코드의 한 가지 예시입니다.","code":{"source":"print(1000 + 500)","kind":"python","output":"1500","error":null}},"explanation":"코드에 계산할 숫자를 미리 적고 +로 더합니다. print는 계산 결과를 보여 주며 단위를 자동으로 덧붙이지 않습니다."},{"question":"아래 두 줄을 직접 적은 다음, 마지막 줄에 끝이라는 글자를 출력하는 요청을 하나 더 적어 보세요. 본문처럼 print와 따옴표를 사용하고, 세 줄의 결과가 나오는지 확인하세요.","skill":"출력 요청 추가","solution":{"answer":"준비, 시작, 끝이 각각 한 줄씩 나타납니다. 아래는 큰따옴표를 사용한 예시입니다.","code":{"source":"print(\"준비\")\nprint(\"시작\")\nprint(\"끝\")","kind":"python","output":"준비\n시작\n끝","error":null}},"explanation":"화면에 보일 글자는 따옴표 안에 적습니다. 이 프로그램은 적힌 순서대로 세 번의 출력 요청을 수행합니다.","code":"print(\"준비\")\nprint(\"시작\")","codeKind":"python"},{"question":"아래 코드를 직접 적어 실행하고, 숫자 7만 9로 바꾸어 다시 확인하세요. 바꾸기 전과 후의 출력을 적고, 실행할 때 사람에게 숫자를 묻지 않아도 되는 이유를 설명해 보세요.","skill":"데이터가 주어지는 방식","solution":{"answer":"처음에는 8, 숫자를 바꾼 뒤에는 10이 나옵니다. 사용할 숫자가 코드 안에 이미 적혀 있으므로 새 값을 입력받을 필요가 없습니다.","code":{"source":"print(9 + 1)","kind":"python","output":"10","error":null,"caption":"7을 9로 바꾼 뒤의 코드와 결과입니다."}},"explanation":"print는 값을 출력하는 기능입니다. 여기에는 키보드로 숫자를 받는 동작이 없으며, 코드에 적어 둔 숫자를 계산에 사용합니다.","code":"print(7 + 1)","codeKind":"python"},{"question":"더하고 싶은 숫자 두 개를 정하세요. 본문의 print(1200 + 800)과 같은 모양으로 코드를 직접 작성하고, 예상한 합과 실제 출력을 비교해 보세요. 사용한 두 숫자도 함께 적으세요.","skill":"새 데이터로 적용","solution":{"answer":"예를 들어 200과 300을 골랐다면 합은 500입니다. 숫자는 자유롭게 정해도 되며, 자신이 적은 두 수의 합이 출력되면 됩니다.","code":{"source":"print(200 + 300)","kind":"python","output":"500","error":null,"caption":"200과 300을 고른 경우의 예시입니다."}},"explanation":"계산할 데이터가 달라져도 두 수를 더한 뒤 출력하는 원리는 같습니다. 아래 코드는 가능한 답의 한 가지입니다."}]},{"id":"python-l002","order":2,"title":"인터프리터와 코드 파일","subtitle":"코드를 적는 곳과 실행하는 곳을 구분하면, 같은 프로그램을 다시 실행할 수 있습니다.","minutes":10,"goal":"대화형 실행과 저장한 코드 파일의 실행을 구분하고, 짧은 .py 파일을 실행하는 과정을 설명한다.","intro":"첫 레슨에서는 코드와 출력 결과를 나누어 보았습니다. 그런데 코드를 메모장에 적는 것만으로는 계산 결과가 나타나지 않습니다. 코드를 읽고 실행하는 파이썬 인터프리터가 필요합니다. 이 레슨에서는 코드를 적는 글과 그것을 실행하는 프로그램을 연결해 봅니다.","sections":[{"title":"편집기는 코드를 적고, 인터프리터는 실행합니다","body":["코드 편집기는 프로그램의 글을 만들고 고치는 도구입니다. 파이썬 인터프리터는 그 글을 파이썬의 규칙에 따라 해석하고 실행하는 프로그램입니다. 하나의 개발 도구에 편집기와 실행 기능이 함께 들어 있어도 두 역할은 구분할 수 있습니다.","직접 실행하려면 PC에 Python 3 실행 환경이 있어야 합니다. Windows와 macOS는 python.org/downloads에서 자신의 운영체제에 맞는 공식 안내를 따라 준비할 수 있습니다. Linux는 배포판에서 제공하는 Python 3 설치 안내를 따릅니다. 이 사이트에서는 설치 없이 코드와 예상 결과를 읽을 수 있으며, 코드 블록 자체가 실행기는 아닙니다."]},{"title":"대화형 실행은 작은 확인에 편리합니다","body":["IDLE의 Shell 창을 열거나, 터미널에 Windows에서는 py, macOS·Linux에서는 python3만 입력하면 대화형 실행을 시작할 수 있습니다. 보통 >>> 표시가 나타나는데, 이는 ‘다음 코드를 입력해도 된다’는 안내인 프롬프트입니다. 코드의 일부가 아니므로 직접 입력하거나 코드 파일에 복사하지 않습니다. 아래 기록에서 >>> 뒤의 글이 입력한 코드이고, 표시가 없는 다음 줄이 결과입니다.","대화형 모드에서는 2 + 3처럼 값을 계산하는 식을 입력하면 그 값이 곧바로 보입니다. print(...)를 입력해 값을 명시적으로 출력할 수도 있습니다. 계산 하나나 짧은 코드를 확인하기 좋지만, 다시 사용할 프로그램은 파일로 저장하는 편이 편리합니다."],"code":{"source":">>> 2 + 3\n5\n>>> print(\"안녕\")\n안녕","kind":"console","caption":"대화형 창의 기록입니다. >>>와 출력 결과를 코드 파일에 함께 붙여 넣지 않습니다."}},{"title":"파일은 다시 실행할 코드를 모아 둡니다","body":["파이썬 코드를 일반 텍스트 파일에 적고 hello.py처럼 .py로 끝나는 이름으로 저장할 수 있습니다. 이 파일을 실행하도록 요청하면 인터프리터가 저장된 내용을 읽습니다. 문서 편집기의 화면을 고친 것과 파일에 저장한 것은 다를 수 있으므로, 고친 뒤에는 저장하고 다시 실행해야 합니다.","파일 실행에서는 계산식만 적었다고 그 값이 자동으로 화면에 나타나지 않습니다. 아래 파일의 첫 줄도 2 + 3을 계산하지만, 출력 요청은 두 번째 줄의 print에만 있습니다. 따라서 5가 한 번만 출력됩니다. 또 파일을 실행할 때는 그 파일의 문법을 먼저 분석하므로, ‘언제나 한 줄을 읽는 즉시 실행한다’고 이해하지 않아야 합니다. 문법 오류가 있는 경우는 레슨 5에서 살펴봅니다."],"code":{"source":"2 + 3\nprint(2 + 3)","kind":"python","output":"5","error":null,"caption":".py 파일로 실행했을 때의 결과입니다. 대화형 창에 식을 입력했을 때와 구분합니다."}},{"title":"첫 파일은 저장하고, 실행하고, 다시 고칩니다","body":["설치된 환경에 IDLE이 있다면 이를 열고 File → New File로 편집 창을 만듭니다. 아래 풀이 예시의 두 줄을 적고 File → Save로 hello.py에 저장한 뒤 Run → Run Module을 선택합니다. 결과는 IDLE의 Shell 창에서 확인합니다. 편집 창의 코드와 Shell 창의 결과를 오가며 비교해 보세요.","터미널은 운영체제에 실행할 프로그램과 파일을 글로 전달하는 창입니다. 터미널을 사용하는 경우 먼저 hello.py를 저장한 폴더에서 창을 열고, Windows에서 py --version으로 Python 3.x가 표시되는지 확인한 뒤 py hello.py를 실행합니다. macOS·Linux에서는 각각 python3 --version과 python3 hello.py를 사용합니다. 실행 명령이 없다고 나오면 설치 환경부터 확인합니다.","py hello.py와 python3 hello.py는 운영체제의 터미널에 입력하는 실행 명령입니다. 파이썬의 >>> 뒤나 hello.py 파일 안에 쓰는 코드가 아닙니다. 대화형 창에서 터미널로 돌아가야 한다면 quit()를 입력해 대화형 실행을 마칠 수 있습니다. 파일을 못 찾았다는 메시지가 나오면 파일 이름과 터미널이 열린 폴더를 먼저 비교합니다."],"code":{"source":"py --version\npy hello.py","kind":"console","caption":"Windows 터미널에서 Python 3 설치를 확인하고 파일을 실행하는 명령입니다. macOS·Linux에서는 py 대신 python3를 사용합니다."}}],"worked":{"question":"hello.py 파일에 아래 코드를 저장했습니다. 파일을 실행하고, 인사말을 바꾼 뒤 다시 확인하는 과정을 따라가 보세요.","code":{"source":"print(\"안녕\")\nprint(2 + 3)","kind":"python","output":"안녕\n5","error":null,"caption":"hello.py에 저장할 파이썬 코드입니다. 실행 명령이나 >>> 표시는 넣지 않습니다."},"steps":["코드만 hello.py에 저장하고, IDLE의 Run Module 또는 터미널의 파일 실행 명령으로 인터프리터에 실행을 요청합니다.","첫 print는 안녕을, 두 번째 print는 덧셈 결과 5를 출력합니다. 두 줄의 코드를 실행하여 두 줄의 출력을 얻습니다.","첫 줄의 안녕을 반가워로 고쳤다면 파일을 다시 저장한 뒤 실행합니다. 첫 출력이 반가워로 달라지고 두 번째 출력 5는 유지되는지 확인합니다."],"answer":"작성 → 저장 → 실행 → 결과 확인의 흐름을 반복합니다. 파일 이름, 저장된 내용, 실행 결과를 함께 확인해야 바꾼 코드가 반영됐는지 알 수 있습니다."},"misconception":{"question":"대화형 창에서 2 + 3은 5가 보였는데, 같은 식만 적은 파일에서는 왜 조용한가요?","answer":"대화형 모드는 입력한 식의 값을 보여 주는 기능이 있습니다. 일반적인 파일 실행에서는 그 자동 표시를 하지 않습니다. 계산에 실패한 것이 아니라 결과를 보여 달라는 요청이 없는 것이므로, 화면에서 확인하려면 print(2 + 3)처럼 출력합니다."},"keypoints":["편집기는 코드를 작성·저장하고, 인터프리터는 그 코드를 해석·실행합니다.",">>>는 대화형 창의 안내 표시이며 코드 파일이나 실행 명령의 일부가 아닙니다.","파일의 계산 결과를 보려면 출력 요청이 필요하며, 수정한 코드는 저장한 뒤 다시 실행합니다."],"examples":[{"question":"아래 대화형 창의 기록에서 실행할 코드만 골라 hello.py에 직접 적으세요. >>>와 이미 나온 결과는 옮기지 않습니다. 파일을 저장하고 실행해 같은 결과가 나오는지 확인하세요.","skill":"프롬프트와 코드 구분","solution":{"answer":"hello.py에는 print(6 + 2) 한 줄만 저장합니다. 파일을 실행하면 8이 출력됩니다.","code":{"source":"print(6 + 2)","kind":"python","output":"8","error":null,"caption":"hello.py에 저장할 내용입니다."}},"explanation":">>>는 입력을 기다리는 표시이고, 그 다음 줄의 8은 결과입니다. 파일에 필요한 것은 실행할 파이썬 코드입니다.","code":">>> print(6 + 2)\n8","codeKind":"console","codeLabel":"대화형 창의 기록"},{"question":"아래 두 줄을 hello.py에 적어 저장하고 실행하세요. 8이 몇 번 나타날지 먼저 예상해 보세요. 이어서 대화형 창에 6 + 2만 입력했을 때와 비교해 차이를 적으세요.","skill":"대화형 실행과 파일 실행","solution":{"answer":"파일에서는 8이 한 번만 출력됩니다. 대화형 창에서는 6 + 2만 입력해도 계산값 8을 보여 줍니다.","code":{"source":"6 + 2\nprint(6 + 2)","kind":"python","output":"8","error":null,"caption":"두 줄을 하나의 파일로 실행한 결과입니다."}},"explanation":"파일은 식의 값을 자동으로 화면에 표시하지 않으므로 print가 있는 두 번째 줄에서만 출력합니다. 대화형 모드에는 입력한 식의 값을 보여 주는 기능이 있습니다.","code":"6 + 2\nprint(6 + 2)","codeKind":"python"},{"question":"hello.py라는 새 파일에 첫 줄은 안녕, 다음 줄은 2 + 3의 계산 결과를 출력하는 코드를 직접 작성하세요. 저장한 뒤 IDLE의 Run Module이나 본문에서 안내한 터미널 명령으로 실행해 보세요.","skill":"작성·저장·실행","solution":{"answer":"안녕과 5가 각각 한 줄씩 나타나면 됩니다. 아래는 파일에 적을 수 있는 코드의 한 가지 예시입니다.","code":{"source":"print(\"안녕\")\nprint(2 + 3)","kind":"python","output":"안녕\n5","error":null}},"explanation":"편집기에 코드를 적는 것과 실행하는 것은 다른 단계입니다. 저장한 파일을 인터프리터로 실행해야 출력 결과를 확인할 수 있습니다."},{"question":"hello.py에 아래 코드를 저장해 실행하세요. 편집기에서 처음을 수정으로 바꾼 뒤 저장하고 다시 실행해 보세요. 결과가 계속 처음으로 보인다면 무엇부터 확인할지도 적으세요.","skill":"수정·저장·재실행","solution":{"answer":"다시 실행한 결과는 수정입니다. 이전 결과가 나오면 수정 내용을 저장했는지와 같은 위치의 hello.py를 실행했는지 확인합니다.","code":{"source":"print(\"수정\")","kind":"python","output":"수정","error":null,"caption":"수정한 내용을 저장한 뒤 실행합니다."}},"explanation":"파일 실행은 편집 화면이 아니라 저장된 내용을 읽습니다. 파일 이름이 같아도 다른 폴더에 있는 파일을 실행하면 수정이 반영되지 않을 수 있습니다.","code":"print(\"처음\")","codeKind":"python"},{"question":"hello.py에 아래 코드를 저장했습니다. 그 파일이 있는 폴더의 터미널에서 실행하려고 합니다. 자신의 운영체제에 맞는 실행 명령을 직접 적고 실행해 보세요. 파이썬의 >>> 창과 운영체제 터미널을 구분하세요.","skill":"실행 명령의 위치","solution":{"answer":"Windows에서는 py hello.py, macOS·Linux에서는 python3 hello.py를 입력합니다. 출력은 실행 성공입니다. >>>가 보이는 파이썬 대화형 창에 있다면 quit()로 마친 뒤 운영체제 터미널에서 명령을 입력합니다."},"explanation":"py 또는 python3는 실행할 인터프리터이고 hello.py는 읽을 파일입니다. 실행 명령을 hello.py 안에 쓰지 않습니다. 명령을 찾지 못하면 본문의 설치 환경 안내를 확인합니다.","code":"print(\"실행 성공\")","codeKind":"python","codeLabel":"hello.py에 저장된 코드"}]},{"id":"python-l003","order":3,"title":"첫 출력과 문자열 리터럴","subtitle":"코드에 적는 표시와 화면에 나타나는 값을 나누어 봅니다.","minutes":8,"goal":"문자열을 감싸는 따옴표와 실제 문자 값을 구분하고 print의 출력을 예측한다.","intro":"화면에 인사말을 보여 주려면 컴퓨터에 무엇을 적어야 할까요? 코드에는 print, 괄호, 따옴표까지 있지만 화면에는 인사말만 나타납니다. 이 차이는 기호가 사라진 실수가 아니라, 각 기호가 맡은 역할이 다르기 때문에 생깁니다.","sections":[{"title":"print는 값을 화면으로 보내는 요청입니다.","body":["print는 Python에 기본으로 준비된 함수입니다. 함수는 맡겨진 일을 수행하도록 부르는 기능이라고 생각하면 됩니다. 지금은 함수를 직접 만드는 법보다, print 뒤의 괄호 안에 보여 줄 값을 넣는 사용법부터 익힙니다.","print(\"안녕하세요\")에서 print는 출력할 기능의 이름, 괄호는 그 기능에 전달할 값을 둘 자리입니다. 실행되면 안녕하세요라는 글자가 나타나고 기본적으로 줄이 바뀝니다. 다음 print의 결과가 다음 줄에 보이는 이유입니다."],"code":{"source":"print(\"안녕하세요\")\nprint(\"반가워요\")","kind":"python","output":"안녕하세요\n반가워요","error":null,"caption":"코드의 괄호와 print라는 이름은 출력되지 않습니다. 두 번의 출력이 두 줄에 나타납니다."}},{"title":"따옴표는 문자열의 시작과 끝을 표시합니다.","body":["문자열은 글자들을 하나의 값으로 다루는 자료입니다. \"안녕\"처럼 원하는 문자 값을 코드에 직접 적은 표현을 문자열 리터럴이라고 부릅니다. 바깥의 따옴표는 Python에게 어디부터 어디까지가 그 문자 값인지 알려 주는 경계 표시입니다.","작은따옴표와 큰따옴표 모두 사용할 수 있지만, 하나의 문자열은 시작한 종류와 같은 따옴표로 닫아야 합니다. 아래 두 줄은 같은 문자 값을 print에 전달하므로 같은 결과를 만듭니다. 코드에는 일반 작은따옴표(')나 큰따옴표(\")를 사용하고, 문서용으로 굽은 따옴표를 대신 넣지 않습니다."],"code":{"source":"print('안녕')\nprint(\"안녕\")","kind":"python","output":"안녕\n안녕","error":null,"caption":"두 표현에서 값은 모두 안녕입니다. 바깥 따옴표의 모양이 출력 내용을 바꾸지는 않습니다."}},{"title":"따옴표 안의 계산식도 글자입니다.","body":["같은 2 + 3이라는 모양이라도 따옴표 안에 있으면 문자 값입니다. Python은 그 안의 더하기 기호를 계산 명령으로 읽지 않습니다. 반대로 따옴표 없이 2 + 3을 적으면 수의 덧셈을 계산하고 그 결과를 print에 전달합니다.","그래서 출력을 예상할 때는 먼저 괄호 안이 글자를 직접 적은 표현인지, 값을 계산하는 식인지 살펴봅니다. print가 계산식의 글자를 마음대로 바꾸는 것이 아닙니다. 두 줄은 print에 전달되는 값부터 다릅니다."],"code":{"source":"print(\"2 + 3\")\nprint(2 + 3)","kind":"python","output":"2 + 3\n5","error":null,"caption":"첫 줄은 글자를 그대로, 둘째 줄은 계산한 값을 출력합니다."}},{"title":"문자열 안에 넣을 따옴표는 내용으로 남습니다.","body":["출력할 문장 자체에 작은따옴표가 들어갈 수도 있습니다. 그때 바깥을 큰따옴표로 감싸면, 안쪽 작은따옴표가 문자열을 끝내지 않습니다. 반대로 문장 안에 큰따옴표를 넣으려면 바깥을 작은따옴표로 감쌀 수 있습니다.","아래 문장에서 바깥 경계와 안쪽 내용을 각각 찾아보세요. print가 모든 따옴표를 삭제하는 것은 아닙니다. 경계 표시는 문자 값에 포함되지 않지만, 문자 값 안에 넣은 따옴표는 다른 글자처럼 출력됩니다."],"code":{"source":"print(\"I'm learning Python.\")\nprint('그는 \"안녕\"이라고 말했다.')","kind":"python","output":"I'm learning Python.\n그는 \"안녕\"이라고 말했다.","error":null,"caption":"경계로 쓰지 않은 안쪽 따옴표는 출력 내용에 포함됩니다."}}],"worked":{"question":"아래 세 줄을 파일에 저장해 실행하면 무엇이 보일까요? 각 줄에서 print에 전달되는 값부터 구분해 봅시다.","code":{"source":"print(\"계산 결과\")\nprint(3 + 4)\nprint(\"3 + 4\")","kind":"python","output":"계산 결과\n7\n3 + 4","error":null,"caption":"같은 더하기 표시가 계산에 쓰일 때와 글자에 쓰일 때를 비교합니다."},"steps":["첫 줄의 큰따옴표는 계산 결과라는 문자 값의 경계입니다. 화면에는 그 글자만 나타납니다.","둘째 줄의 3 + 4에는 따옴표가 없으므로 먼저 7을 계산합니다. print는 그 값을 보여 줍니다.","셋째 줄은 따옴표 안의 글자를 전달합니다. 따라서 계산하지 않고 3 + 4를 보여 줍니다. 각 print 뒤에는 기본 줄바꿈이 생깁니다."],"answer":"출력은 계산 결과, 7, 3 + 4의 세 줄입니다. 코드의 모습과 전달되는 값을 구분하면 결과를 설명할 수 있습니다."},"misconception":{"question":"print는 따옴표를 전부 지우는 기능인가요?","answer":"아닙니다. 문자열 바깥의 따옴표는 값의 경계이므로 애초에 문자 값에 포함되지 않습니다. 값 안에 넣은 따옴표는 그대로 출력될 수 있습니다. 또 print(\"5\")와 print(5)는 둘 다 화면에 5를 보여 주므로, 출력 모양만으로 원래 값이 문자열인지 숫자인지 항상 알 수 있는 것도 아닙니다."},"keypoints":["문자열 리터럴은 문자 값을 코드에 직접 적은 표현이며, 바깥 따옴표는 그 값의 경계입니다.","print는 전달받은 값을 보여 줍니다. 따옴표 안의 식은 글자이고, 밖의 계산식은 계산한 값을 전달합니다.","한 문자열의 시작과 끝은 같은 종류의 따옴표로 맞춥니다. 내용 안에 있는 따옴표는 출력될 수 있습니다."],"examples":[{"question":"아래 코드의 출력을 먼저 예상하고 직접 실행하세요. 이어서 바깥의 큰따옴표를 모두 작은따옴표로 바꾸어 다시 실행해 보세요. 출력이 달라지는지와 그 이유를 적으세요.","skill":"문자열의 경계","solution":{"answer":"두 코드 모두 안녕을 출력합니다. 시작과 끝의 따옴표 종류를 맞추면 큰따옴표와 작은따옴표로 같은 문자열을 나타낼 수 있습니다.","code":{"source":"print('안녕')","kind":"python","output":"안녕","error":null,"caption":"작은따옴표로 바꾼 예시입니다."}},"explanation":"문자열을 감싸는 바깥 따옴표는 내용의 경계입니다. 그 경계 표시는 문자 값에 포함되지 않아 출력되지 않습니다.","code":"print(\"안녕\")","codeKind":"python"},{"question":"Python 다음 줄에 공부 시작을 출력하는 코드를 작성하세요. print를 두 번 사용하고, 코드의 이름이나 바깥 따옴표가 결과에 나타나지 않는지도 확인해 보세요.","skill":"문자열 출력 작성","solution":{"answer":"Python과 공부 시작이 두 줄로 나타나면 됩니다. 큰따옴표 또는 작은따옴표를 짝에 맞게 사용할 수 있습니다.","code":{"source":"print(\"Python\")\nprint(\"공부 시작\")","kind":"python","output":"Python\n공부 시작","error":null}},"explanation":"각 print는 괄호 안의 문자열 값을 출력하고 기본적으로 줄을 바꿉니다. 기능 이름과 괄호는 출력할 내용이 아닙니다."},{"question":"아래 두 줄의 출력을 줄바꿈까지 먼저 적어 보세요. 코드를 직접 입력해 실행한 뒤, 같은 6 + 1이 왜 서로 다른 결과를 만드는지 설명하세요.","skill":"문자와 계산의 구분","solution":{"answer":"첫 줄에는 6 + 1, 둘째 줄에는 7이 나타납니다.","code":{"source":"print(\"6 + 1\")\nprint(6 + 1)","kind":"python","output":"6 + 1\n7","error":null}},"explanation":"첫 줄의 따옴표 안은 문자 내용이므로 계산하지 않습니다. 둘째 줄에는 숫자와 덧셈이 적혀 있으므로 계산한 값 7을 출력합니다.","code":"print(\"6 + 1\")\nprint(6 + 1)","codeKind":"python"},{"question":"아래 코드는 시작과 끝의 따옴표가 다릅니다. 따옴표를 고쳐 안녕을 출력하는 코드로 만들고 실행해 보세요. 어느 부분을 고쳤는지도 적으세요.","skill":"문자열 구문 수정","solution":{"answer":"끝의 작은따옴표를 큰따옴표로 바꾸면 됩니다. 반대로 시작을 작은따옴표로 맞추는 방법도 가능합니다.","code":{"source":"print(\"안녕\")","kind":"python","output":"안녕","error":null,"caption":"두 따옴표를 큰따옴표로 맞춘 예시입니다."}},"explanation":"문자열의 시작과 끝을 같은 종류의 따옴표로 표시해야 합니다. print의 괄호도 한 쌍으로 닫혀 있어야 합니다.","code":"print(\"안녕')","codeKind":"python"},{"question":"화면에 He's ready.를 한 줄로 출력하는 코드를 작성하세요. 문장 안의 작은따옴표와 마침표도 그대로 보여야 합니다. 바깥을 어떤 따옴표로 감싸면 되는지 생각해 보세요.","skill":"따옴표가 있는 문장 적용","solution":{"answer":"바깥을 큰따옴표로 감싸면 문장 속 작은따옴표를 내용으로 넣을 수 있습니다. 아래는 가능한 코드의 한 가지입니다.","code":{"source":"print(\"He's ready.\")","kind":"python","output":"He's ready.","error":null}},"explanation":"바깥 큰따옴표는 문자열의 경계를 나타내고, 안쪽 작은따옴표는 문자 값에 남습니다. 바깥 따옴표까지 출력할 필요는 없습니다."}]},{"id":"python-l004","order":4,"title":"순서·들여쓰기·주석","subtitle":"줄의 순서는 실행 흐름을, 들여쓰기는 코드가 속한 묶음을 알려 줍니다.","minutes":9,"goal":"짧은 코드에서 실행 순서, 들여쓰기 블록, 주석과 문자열 속 #을 구분한다.","intro":"같은 print 세 줄이라도 순서를 바꾸면 화면에 나타나는 이야기가 달라집니다. 줄 앞의 공백이나 #도 각각 맡은 역할이 있습니다. 코드를 글자 목록으로만 보지 않고, 실행할 순서와 함께 묶인 부분을 읽어 봅시다.","sections":[{"title":"먼저 실행한 출력이 먼저 나타납니다.","body":["조건이나 반복이 없는 아래 파일에서는 print가 위에서 아래로 실행됩니다. 시작을 출력한 뒤 준비를 출력하고, 마지막에 끝을 출력합니다. 코드를 읽을 때는 이미 실행한 줄과 다음에 실행할 줄을 나누어 생각해 보세요.","여기서 위에서 아래로 실행된다는 말은 파일의 문법 검사를 건너뛰고 한 줄씩 무조건 실행한다는 뜻은 아닙니다. 파일 실행에서는 코드가 문법에 맞는지 먼저 분석합니다. 문법 오류와 실행 중 오류의 차이는 다음 레슨에서 확인합니다."],"code":{"source":"print(\"시작\")\nprint(\"준비\")\nprint(\"끝\")","kind":"python","output":"시작\n준비\n끝","error":null,"caption":"이 예시는 조건과 반복이 없는 순차 실행입니다. 줄의 순서와 출력 순서를 나란히 읽어 보세요."}},{"title":"들여쓰기는 같은 블록에 속한다는 표시입니다.","body":["블록은 어떤 문장에 속해 함께 묶인 코드입니다. 이를 보기 위해 if True:라는 문장을 잠깐 사용하겠습니다. True는 참이라는 값이고, 이 예시의 if True:는 뒤에 들여쓴 블록을 실행한다는 뜻입니다. 조건에 따라 선택하는 자세한 규칙은 뒤의 조건 챕터에서 배웁니다.","콜론(:) 다음 줄의 print 두 개는 같은 너비로 들여썼으므로 같은 블록에 속합니다. 마지막 print는 왼쪽으로 돌아왔으므로 그 블록 밖에 있습니다. Python에서는 이 위치 관계가 코드의 구조이므로, 보기 좋게 만들려고 줄 앞의 공백을 마음대로 바꾸면 안 됩니다."],"code":{"source":"print(\"밖에서 시작\")\nif True:\n    print(\"블록의 첫 줄\")\n    print(\"블록의 둘째 줄\")\nprint(\"블록 밖에서 끝\")","kind":"python","output":"밖에서 시작\n블록의 첫 줄\n블록의 둘째 줄\n블록 밖에서 끝","error":null,"caption":"들여쓴 두 줄만 if True:에 속합니다. 여기서는 조건이 참이어서 두 줄이 순서대로 실행됩니다."}},{"title":"같은 깊이는 맞추고, 이 강좌에서는 공백 4칸을 씁니다.","body":["한 블록의 같은 깊이에 있는 줄은 들여쓰기 너비를 맞춰야 합니다. 블록을 시작하는 문장도 없는데 파일 맨 위의 print 앞에 공백을 붙이면, Python은 이유 없이 들여쓴 줄로 판단할 수 있습니다. 아래 코드는 그 때문에 실행되지 않는 예시입니다.","공백 4칸은 널리 쓰이는 Python 스타일 권장이며 이 강좌에서도 따릅니다. 문법이 모든 블록에 정확히 4칸만 허용한다는 뜻은 아닙니다. 지금은 공백을 사용하고 같은 깊이를 일관되게 맞추세요. 탭과 공백을 섞으면 보이는 정렬과 Python의 해석이 어긋나 오류가 생길 수 있습니다."],"code":{"source":"    print(\"안녕\")","kind":"python","output":"","error":"IndentationError","caption":"파일의 첫 줄에 블록을 여는 문장 없이 들여쓰면 IndentationError가 발생합니다."}},{"title":"주석은 설명이고, 문자열 속 #은 글자입니다.","body":["문자열 밖에서 #을 만나면 그 지점부터 해당 줄의 끝까지는 주석입니다. 주석은 사람이 코드를 읽을 때 참고할 설명이며, 아래 예시에서 출력 명령으로 실행되지 않습니다. 줄 하나 전체를 주석으로 쓸 수도 있고, 코드 뒤에 짧은 설명을 붙일 수도 있습니다.","하지만 따옴표 안의 #은 문자열의 내용입니다. print(\"# 시작\")은 # 시작이라는 글자를 보여 줍니다. 코드 파일의 빈 줄은 이 예시의 실행 결과를 바꾸지 않고 덩어리를 읽기 쉽게 나누는 데 쓰입니다. 출력에 빈 줄을 넣고 싶다면 코드의 빈 줄과 구분해야 합니다."],"code":{"source":"# 제목을 표시합니다.\nprint(\"# 시작\")  # 여기부터는 설명입니다.\n\nprint(\"완료\")","kind":"python","output":"# 시작\n완료","error":null,"caption":"문자열 안의 #만 출력됩니다. 주석 두 개와 코드 파일의 빈 줄은 출력 줄을 추가하지 않습니다."}}],"worked":{"question":"이 파일의 설명 글자와 출력되는 글자를 구분하고, 실행 순서를 따라가 봅시다.","code":{"source":"# 간단한 안내\nprint(\"입장\")\nif True:\n    print(\"# 안내\")\n    print(\"환영합니다\")\n\nprint(\"종료\")","kind":"python","output":"입장\n# 안내\n환영합니다\n종료","error":null,"caption":"첫 줄의 주석은 실행하지 않습니다. True 블록의 두 줄을 지나 블록 밖의 마지막 줄로 이어집니다."},"steps":["첫 줄은 문자열 밖의 #으로 시작하는 주석입니다. 첫 출력은 그다음 줄의 입장입니다.","if True:의 블록에는 같은 깊이로 들여쓴 print 두 개가 있습니다. 조건이 참이므로 # 안내, 환영합니다를 순서대로 출력합니다.","마지막 print는 들여쓰기가 끝난 블록 밖의 줄입니다. 코드의 빈 줄은 출력에 추가되지 않고, 마지막으로 종료가 나타납니다."],"answer":"입장, # 안내, 환영합니다, 종료의 네 줄입니다. 실행 순서와 블록 소속, 문자열과 주석의 경계를 각각 확인하면 결과를 읽을 수 있습니다."},"misconception":{"question":"들여쓰기는 보기 좋게 정렬하는 꾸밈인가요?","answer":"Python에서 줄 앞의 들여쓰기는 어떤 블록에 속하는지 나타내는 문법입니다. 같은 블록의 같은 깊이는 맞춰야 합니다. 다만 공백 4칸은 이 강좌가 따르는 스타일 권장입니다. 모든 줄을 4칸 들여쓰는 것이 아니며, 블록 밖의 줄은 왼쪽에서 시작합니다."},"keypoints":["조건이나 반복이 없는 순차 코드에서는 문장이 위에서 아래로 실행됩니다.","들여쓰기는 블록 소속을 나타냅니다. 같은 깊이는 맞추고 이 강좌에서는 공백 4칸을 사용합니다.","문자열 밖의 #은 줄 끝까지의 주석을 시작합니다. 문자열 안의 #은 출력할 글자가 될 수 있습니다."],"examples":[{"question":"아래 파일의 출력 순서를 먼저 예상하고 실행하세요. 이어서 첫째 다음에 둘째가 나오도록 코드 두 줄의 순서만 바꾸어 다시 실행해 보세요.","skill":"실행 순서 추적","solution":{"answer":"원래는 둘째, 첫째 순서입니다. 두 줄의 위치를 바꾸면 첫째, 둘째 순서가 됩니다.","code":{"source":"print(\"첫째\")\nprint(\"둘째\")","kind":"python","output":"첫째\n둘째","error":null,"caption":"두 출력 요청의 위치만 바꾼 코드입니다."}},"explanation":"문자열의 뜻이 실행 순서를 정하지 않습니다. 이 순차 프로그램에서는 위에 적힌 출력 요청부터 실행합니다.","code":"print(\"둘째\")\nprint(\"첫째\")","codeKind":"python"},{"question":"이 예시의 if True: 아래 블록은 실행됩니다. 먼저 어느 출력 명령들이 그 블록에 속하는지 적으세요. 이어서 진행 다음에 확인을 출력하는 줄을 같은 블록 안에 추가하세요. 완료는 블록 밖에 그대로 두고 파일로 실행하세요.","skill":"블록 소속 읽기와 적용","solution":{"answer":"원래 블록 안에는 준비와 진행을 출력하는 두 줄이 있습니다. 확인을 출력하는 새 줄도 공백 4칸으로 맞추면 준비, 진행, 확인, 완료가 차례로 나옵니다.","code":{"source":"if True:\n    print(\"준비\")\n    print(\"진행\")\n    print(\"확인\")\nprint(\"완료\")","kind":"python","output":"준비\n진행\n확인\n완료","error":null}},"explanation":"같은 블록의 같은 깊이는 들여쓰기를 맞춥니다. 완료를 출력하는 줄은 왼쪽으로 돌아와 있으므로 if True:의 블록 밖입니다.","code":"if True:\n    print(\"준비\")\n    print(\"진행\")\nprint(\"완료\")","codeKind":"python"},{"question":"아래 파일은 블록 안의 두 줄을 공백 2칸으로 맞췄습니다. 그대로 실행해 본 뒤, 두 줄을 모두 공백 4칸으로 바꾸어 다시 실행하세요. 결과가 같은지 확인하고, 공백 4칸이 권장 스타일이라는 뜻을 설명해 보세요. if True: 아래 블록은 실행됩니다.","skill":"문법과 스타일 구분","solution":{"answer":"두 경우 모두 A, B, 완료가 차례로 출력됩니다. 공백 4칸은 이 강좌와 Python 스타일 가이드의 권장이며, 2칸은 무조건 문법 오류라는 뜻이 아닙니다.","code":{"source":"if True:\n    print(\"A\")\n    print(\"B\")\nprint(\"완료\")","kind":"python","output":"A\nB\n완료","error":null,"caption":"블록 안의 두 줄을 각각 공백 4칸으로 맞춘 코드입니다."}},"explanation":"문법의 핵심은 블록의 깊이와 같은 깊이의 일관성입니다. 이 문제에서는 블록의 구조를 유지한 채 두 줄의 들여쓰기를 함께 바꿉니다. 마지막 줄은 블록 밖이므로 들여쓰지 않습니다.","code":"if True:\n  print(\"A\")\n  print(\"B\")\nprint(\"완료\")","codeKind":"python"},{"question":"아래 한 줄만 들어 있는 파일은 처음부터 이유 없이 들여써져 있습니다. 안녕을 출력하도록 고치고 파일로 실행하세요. 앞의 공백을 더 넣거나 줄을 주석으로 만드는 방법이 목표에 맞지 않는 이유도 적으세요.","skill":"불필요한 들여쓰기 수정","solution":{"answer":"print 앞의 공백을 지워 왼쪽에서 시작하게 하면 안녕이 출력됩니다.","code":{"source":"print(\"안녕\")","kind":"python","output":"안녕","error":null}},"explanation":"앞에서 블록을 여는 문장이 없으므로 처음부터 들여쓰면 오류가 납니다. 공백을 더 넣어도 해결되지 않으며, 주석으로 바꾸면 필요한 출력이 사라집니다.","code":"    print(\"안녕\")","codeKind":"python"},{"question":"아래 파일의 출력을 예상하고 직접 실행하세요. 이어서 맨 아래에 자신만의 주석 한 줄을 추가하고 다시 실행해 출력이 그대로인지 확인하세요. 따옴표 안팎의 #이 어떻게 다른지도 적으세요.","skill":"주석과 문자 구분","solution":{"answer":"출력은 # 메모 한 줄입니다. 예를 들어 # 다시 확인함을 마지막 줄에 추가해도 출력은 같습니다. 주석 내용은 자유롭게 적어도 됩니다.","code":{"source":"# 제목\nprint(\"# 메모\")  # 화면에 표시\n# 다시 확인함","kind":"python","output":"# 메모","error":null,"caption":"마지막 주석은 자유롭게 바꿀 수 있습니다."}},"explanation":"문자열 밖의 # 뒤는 설명용 주석입니다. 따옴표 안의 #은 문자열의 내용이므로 출력에 포함됩니다. 주석을 추가해도 print 요청 자체는 바뀌지 않습니다.","code":"# 제목\nprint(\"# 메모\")  # 화면에 표시","codeKind":"python"}]},{"id":"python-l005","order":5,"title":"문법 오류와 실행 중 오류","subtitle":"오류 메시지는 틀렸다는 판정이 아니라, 멈춘 이유와 살펴볼 위치를 알려 줍니다.","minutes":9,"goal":"문법 오류와 실행 중 오류를 구분하고, 파일·줄 번호·오류 종류를 근거로 작은 수정을 시도한다.","intro":"코드를 실행했는데 기대한 글자 대신 영어 메시지가 나올 수 있습니다. 이때 메시지를 통째로 외우거나 여러 줄을 한꺼번에 고칠 필요는 없어요. 먼저 실행을 시작하지 못한 것인지, 실행하다가 멈춘 것인지를 나누면 확인할 곳이 줄어듭니다.","sections":[{"title":"문법 오류는 코드를 읽는 단계에서 발견됩니다","body":["파이썬이 코드를 실행하려면 먼저 괄호, 따옴표, 들여쓰기처럼 문장을 이루는 약속을 해석할 수 있어야 합니다. 이 약속에 맞지 않아 읽을 수 없으면 SyntaxError라는 문법 오류가 발생합니다. 예를 들어 여는 괄호를 썼는데 닫는 괄호가 없다면 어디까지 하나의 명령인지 완성되지 않았습니다.","아래 두 줄을 한 .py 파일에 저장해 실행한다고 생각해 보세요. 파이썬은 그 파일의 문법을 먼저 확인하므로, 두 번째 줄에 문법 오류가 있으면 첫 번째 print도 실행되지 않습니다. 이것은 대화형 창에서 앞선 입력을 이미 실행한 뒤 새 입력을 보내는 상황과 다릅니다."],"code":{"source":"print(\"시작\")\nprint(\"끝\"","kind":"python","output":"","error":"SyntaxError","caption":"한 파일로 실행하면 문법 오류 때문에 시작도 출력되지 않습니다."}},{"title":"실행 중 오류는 그 지점에서 흐름을 멈춥니다","body":["문법에 맞는 코드라도 실제 계산이나 동작을 할 수 없는 경우가 있습니다. 0으로 나누는 식은 파이썬 문법으로 읽을 수 있지만 계산할 수 없어서 ZeroDivisionError가 발생합니다. 이런 실행 중 오류를 예외라고 부릅니다.","아래 파일에서는 첫 번째 출력까지 마친 뒤 두 번째 줄의 계산에서 멈춥니다. 이미 출력한 시작은 남고, 마지막의 끝은 출력되지 않습니다. 여기서는 오류를 따로 처리하지 않은 짧은 프로그램을 보고 있습니다. 예외를 처리하며 계속 실행하는 방법은 나중에 배우며, 지금은 어디까지 실행됐는지 읽는 데 집중합니다."],"code":{"source":"print(\"시작\")\nprint(6 / 0)\nprint(\"끝\")","kind":"python","output":"시작","error":"ZeroDivisionError","caption":"시작을 출력한 뒤 0으로 나누는 계산에서 멈춥니다. 오류 메시지는 일반 출력과 구분해 읽습니다."}},{"title":"파일, 줄 번호, 오류 종류를 연결해서 읽습니다","body":["실행 중 오류의 메시지에는 Traceback이라는 안내가 붙을 수 있습니다. 그 아래의 File은 살펴볼 파일을, line 뒤의 수는 줄 번호를 알려 줍니다. 마지막 줄에서는 ZeroDivisionError 같은 오류 종류와 이유를 읽을 수 있습니다. 아래는 앞의 코드를 practice.py에 저장해 실행했을 때 볼 수 있는 메시지의 핵심 부분입니다.","문법 오류에도 파일과 줄 번호, 표시 화살표가 나올 수 있습니다. 표시된 위치는 파이썬이 문제를 알아차린 자리이므로, 반드시 그 글자만 고치면 된다는 뜻은 아닙니다. 앞줄에서 괄호나 따옴표를 닫지 않았는지도 함께 확인하세요. 파이썬 버전과 실행 도구에 따라 화살표와 문구의 모양은 달라질 수 있습니다."],"code":{"source":"Traceback (most recent call last):\n  File \"practice.py\", line 2, in <module>\n    print(6 / 0)\nZeroDivisionError: division by zero","kind":"text","caption":"오류 메시지에서 파일 practice.py, 줄 번호 2, 오류 종류 ZeroDivisionError를 찾습니다. 실행할 코드는 아닙니다."}},{"title":"한 가지 원인을 고치고 같은 파일을 다시 실행합니다","body":["먼저 어떤 결과를 기대했는지 적고, 메시지가 가리킨 위치와 주변 코드를 비교합니다. 닫는 괄호가 빠졌다면 그것을 보충하고, 명령 이름의 철자가 틀렸다면 철자를 바로잡습니다. 한 번에 많은 부분을 바꾸면 어떤 수정이 효과가 있었는지 알기 어려우므로 확인한 원인부터 작게 고칩니다.","수정한 코드를 저장한 다음 같은 파일을 다시 실행합니다. 오류 메시지가 없어졌는지와 원하는 결과가 나왔는지는 따로 확인해야 해요. 문법이 올바르고 오류 없이 끝났더라도 출력 순서나 문구가 의도와 다를 수 있기 때문입니다. 아래처럼 기대한 순서를 미리 정하면 결과를 비교하기 쉬워집니다."],"code":{"source":"print(\"시작\")\nprint(\"확인\")\nprint(\"끝\")","kind":"python","output":"시작\n확인\n끝","error":null,"caption":"오류 없이 끝나는지만 보지 말고, 기대한 세 줄이 이 순서로 나오는지도 확인합니다."}}],"worked":{"question":"준비 다음에 출발을 출력하려고 했는데, 두 번째 줄을 prnit(\"출발\")이라고 썼습니다. 준비만 출력된 뒤 NameError가 나왔다면 무엇을 확인해야 할까요?","code":{"source":"print(\"준비\")\nprint(\"출발\")","kind":"python","output":"준비\n출발","error":null,"caption":"명령 이름의 철자를 print로 바로잡아 저장한 수정본입니다."},"steps":["준비가 출력됐으므로 파일은 실행을 시작했고, 그 뒤의 동작에서 멈췄다는 사실을 확인합니다.","NameError는 찾으려는 이름을 알 수 없을 때 나타납니다. 두 번째 줄의 prnit를 앞에서 사용한 print와 비교하면 철자가 바뀐 것을 찾을 수 있습니다.","prnit를 print로 고친 뒤 저장하고 다시 실행합니다. 메시지가 사라졌는지뿐 아니라 준비와 출발이 차례로 출력되는지도 비교합니다."],"answer":"오류 종류와 실행된 위치를 근거로 철자 한 곳을 수정하면, 두 출력이 의도한 순서대로 실행됩니다."},"misconception":{"question":"오류가 난 줄보다 위의 코드는 언제나 이미 실행됐을까요?","answer":"그렇지 않습니다. 이 레슨처럼 .py 파일 전체에 문법 오류가 있으면 그 파일의 실행을 시작하지 못하므로 위의 print도 실행되지 않습니다. 문법을 통과한 뒤 실행 중 오류로 멈춘 경우에는 그 전에 완료한 출력이 남습니다. 대화형 창에서 이미 실행한 이전 입력은 이후 입력의 문법 오류가 생겨도 지워지지 않습니다."},"keypoints":["문법 오류는 코드를 읽는 단계의 문제이고, 실행 중 오류는 실제 동작 중 생긴 문제입니다.","파일·줄 번호·오류 종류를 함께 읽고, 표시 위치 주변의 괄호·따옴표·철자도 확인합니다.","근거가 있는 부분을 작게 고쳐 저장하고, 오류 유무와 기대한 결과를 각각 확인합니다."],"examples":[{"question":"아래 두 줄을 practice.py 하나의 파일에 저장해 실행하세요. 시작이 출력되는지와 오류 종류를 확인하세요. 빠진 괄호를 보충한 뒤 저장하고 다시 실행해 두 출력이 나타나는지 비교하세요.","skill":"파일의 문법 오류 수정","solution":{"answer":"수정 전에는 SyntaxError가 나고 시작도 출력되지 않습니다. 마지막에 닫는 괄호를 넣으면 시작과 끝이 차례로 출력됩니다.","code":{"source":"print(\"시작\")\nprint(\"끝\")","kind":"python","output":"시작\n끝","error":null}},"explanation":"파일은 실행을 시작하기 전에 문법을 확인합니다. 두 번째 줄에 문법 오류가 있으면 그 파일의 첫 번째 줄도 실행되지 않습니다.","code":"print(\"시작\")\nprint(\"끝\"","codeKind":"python"},{"question":"아래 파일을 실행하기 전에 일반 출력이 어디까지 나올지 적으세요. 실행 후 오류 종류를 확인하고, 두 번째 줄을 print(\"계산 확인\")으로 바꾸어 다시 실행하세요. 변경 전과 후의 결과를 비교해 보세요.","skill":"실행 중 오류와 이전 출력","solution":{"answer":"원래 파일은 A를 출력한 뒤 ZeroDivisionError로 멈춥니다. 두 번째 줄을 바꾸면 A, 계산 확인, B가 차례로 출력됩니다.","code":{"source":"print(\"A\")\nprint(\"계산 확인\")\nprint(\"B\")","kind":"python","output":"A\n계산 확인\nB","error":null}},"explanation":"0으로 나누는 식은 문법상 읽을 수 있지만 실행할 수 없습니다. 처리하지 않은 오류가 생기기 전의 출력은 남고 그 뒤의 줄은 실행되지 않습니다.","code":"print(\"A\")\nprint(6 / 0)\nprint(\"B\")","codeKind":"python"},{"question":"아래 코드를 practice.py에 저장하고 실행하세요. 오류 메시지에서 파일 이름, 줄 번호, 오류 종류를 찾아 적으세요. 철자가 다른 곳 한 군데를 고친 뒤 준비와 출발이 차례로 출력되는지 확인하세요.","skill":"오류 위치와 이름 확인","solution":{"answer":"확인할 파일은 practice.py, 줄 번호는 2, 오류 종류는 NameError입니다. prnit를 print로 고치면 준비 다음에 출발이 출력됩니다.","code":{"source":"print(\"준비\")\nprint(\"출발\")","kind":"python","output":"준비\n출발","error":null}},"explanation":"파이썬이 prnit라는 이름을 찾지 못해 멈춥니다. 메시지가 가리킨 줄을 앞의 print와 비교하면 철자가 뒤바뀐 것을 확인할 수 있습니다. 수정 후에는 저장하고 같은 파일을 다시 실행합니다.","code":"print(\"준비\")\nprnit(\"출발\")","codeKind":"python"},{"question":"아래 코드로 Ready라는 글자를 출력하려고 합니다. 따옴표와 괄호의 짝을 확인해 필요한 부분만 고친 뒤 실행하세요. 무엇이 빠져 있었는지도 설명하세요.","skill":"작은 문법 수정","solution":{"answer":"Ready 뒤의 닫는 큰따옴표가 빠졌습니다. 괄호 앞에 큰따옴표를 넣으면 Ready가 출력됩니다.","code":{"source":"print(\"Ready\")","kind":"python","output":"Ready","error":null}},"explanation":"문자열의 끝을 표시하는 따옴표와 print의 괄호는 각각 필요합니다. 오류 메시지가 없어진 것과 원하는 글자가 출력되는 것을 함께 확인합니다.","code":"print(\"Ready)","codeKind":"python"},{"question":"파이썬 대화형 창에서 아래 기록처럼 한 줄씩 입력하세요. >>>는 직접 입력하지 않습니다. A가 나온 뒤 두 번째 입력에 오류가 나도 A가 남는지 확인하세요. 이어서 두 번째 입력의 괄호를 고쳐 B를 출력해 보세요. 두 줄을 하나의 파일로 실행하는 실습과 구분하세요.","skill":"파일과 대화형의 차이","solution":{"answer":"A는 이미 실행된 이전 입력의 출력이므로 남습니다. 두 번째 입력에는 닫는 괄호가 하나 더 있어 SyntaxError가 납니다. print(\"B\")를 새로 입력하면 B가 추가로 출력됩니다.","code":{"source":"print(\"B\")","kind":"python","output":"B","error":null,"caption":"오류가 난 대화형 창에 새로 입력할 코드입니다. 앞서 나온 A는 그대로 남습니다."}},"explanation":"대화형 창의 이전 입력과 새 입력은 구분됩니다. 새 입력의 문법 오류가 이미 끝낸 출력을 되돌리지 않습니다. 하나의 파일 전체에 문법 오류가 있어 실행을 시작하지 못하는 경우와 다릅니다.","code":">>> print(\"A\")\nA\n>>> print(\"B\"))","codeKind":"console","codeLabel":"대화형 창에서 순서대로 입력할 기록"}]}],"review":[{"question":"3과 4를 더한 값을 화면에 출력하는 한 줄 프로그램을 직접 작성하고 실행하세요. 이 프로그램의 입력 자료, 처리, 출력을 각각 한 문장으로 설명해 보세요.","skill":"실행 흐름 · 입력과 결과","solution":{"answer":"예시 답: 입력 자료는 코드에 적힌 3과 4이고, 처리는 두 수를 더하는 계산입니다. 출력은 화면에 나타나는 7입니다.","code":{"source":"print(3 + 4)","kind":"python","output":"7","error":null,"caption":"숫자 7을 코드에 바로 적는 대신, 덧셈의 결과를 출력하는 예시입니다."}},"explanation":"프로그램에 적어 둔 값도 처리할 자료가 될 수 있으므로 키보드로 값을 물어보는 단계가 꼭 필요한 것은 아닙니다. 먼저 3 + 4를 계산하고 print가 그 결과를 화면에 보여 줍니다.","related":["python-l001","python-l003"]},{"question":"아래 코드를 실행하기 전에 화면에 나올 내용을 줄 순서대로 적어 보세요. 그다음 직접 타이핑하여 한 파일로 실행하고, 주석이 출력에 포함되는지 확인하세요.","code":"print(\"준비\")\n# 다음에는 시작을 알립니다.\nprint(\"시작\")\nprint(\"완료\")","codeKind":"python","codeLabel":"실행 순서를 예측할 코드","skill":"실행 흐름 · 순서와 주석","solution":{"answer":"예시 답: 준비, 시작, 완료가 각각 한 줄씩 이 순서로 출력됩니다. 두 번째 줄의 주석은 출력되지 않습니다.","code":{"source":"print(\"준비\")\n# 다음에는 시작을 알립니다.\nprint(\"시작\")\nprint(\"완료\")","kind":"python","output":"준비\n시작\n완료","error":null,"caption":"예측한 세 줄과 실제 실행 결과를 비교하세요."}},"explanation":"이 순차 프로그램은 위에서 아래로 출력 명령을 실행합니다. 따옴표 밖의 #로 시작한 주석은 코드를 읽는 사람을 위한 설명이므로 출력 명령처럼 실행하지 않습니다.","related":["python-l001","python-l004"]},{"question":"아래 코드를 한 파일로 실행하면 어디까지 출력될지 먼저 적어 보세요. 직접 실행한 뒤, 멈춘 줄과 오류 종류를 확인하고 마지막 단계가 출력되지 않는 이유를 설명하세요.","code":"print(\"첫 단계\")\nprint(8 / 0)\nprint(\"마지막 단계\")","codeKind":"python","codeLabel":"실행 중 오류가 있는 코드","skill":"실행 흐름 · 오류 이후의 동작","solution":{"answer":"예시 답: 첫 단계만 출력됩니다. 두 번째 줄에서 0으로 나누려 하여 ZeroDivisionError가 발생하고, 세 번째 줄은 실행하지 못합니다.","code":{"source":"print(\"첫 단계\")\nprint(8 / 0)\nprint(\"마지막 단계\")","kind":"python","output":"첫 단계","error":"ZeroDivisionError","caption":"수정본이 아니라, 오류 전에 남는 출력을 확인하는 코드입니다."}},"explanation":"이 파일은 문법을 읽는 단계는 통과하지만 두 번째 줄을 계산하는 도중 오류가 납니다. 앞에서 완료한 출력은 남고, 여기서는 오류를 따로 처리하지 않으므로 뒤의 명령으로 넘어가지 못합니다.","related":["python-l004","python-l005"]},{"question":"아래 코드가 출력할 내용을 #과 공백까지 포함해 적은 뒤 직접 실행하세요. 두 개의 # 중 어느 것이 문자열의 글자이고 어느 것이 주석의 시작인지 설명해 보세요.","code":"print(\"# 안내\")  # 화면에 안내를 표시합니다.","codeKind":"python","codeLabel":"문자열과 주석을 구별할 코드","skill":"코드 읽기 · 문자열과 주석","solution":{"answer":"예시 답: # 뒤에 공백 한 칸을 두고 안내가 출력됩니다. 따옴표 안의 첫 번째 #은 글자이고, 닫는 괄호 뒤의 두 번째 #이 주석을 시작합니다.","code":{"source":"print(\"# 안내\")  # 화면에 안내를 표시합니다.","kind":"python","output":"# 안내","error":null,"caption":"문자열 경계를 표시하는 따옴표는 출력에 포함되지 않습니다."}},"explanation":"같은 #이라도 코드에서 놓인 위치에 따라 역할이 달라집니다. 따옴표 안은 문자열의 내용이며, 따옴표 밖의 #부터 줄 끝까지는 설명인 주석입니다.","related":["python-l003","python-l004"]},{"question":"아래는 대화형 창의 실행 기록입니다. 이 기록에서 실행할 코드만 골라 hello.py에 직접 작성하고 저장한 뒤 파일로 실행하세요. 두 줄의 출력이 원래 기록과 같은지 확인해 보세요.","code":">>> print(\"안녕\")\n안녕\n>>> print(2 + 5)\n7","codeKind":"console","codeLabel":"대화형 창의 기록 — 코드 파일에 그대로 옮기지 마세요","skill":"코드 읽기 · 입력 표시와 코드 파일","solution":{"answer":"예시 답: hello.py에는 두 개의 print 명령만 저장합니다. >>> 표시와 그 아래에 나온 실행 결과는 파일 내용에 넣지 않습니다.","code":{"source":"print(\"안녕\")\nprint(2 + 5)","kind":"python","output":"안녕\n7","error":null,"caption":"이 두 줄을 hello.py의 내용으로 작성해 실행할 수 있습니다."}},"explanation":">>>는 대화형 창이 입력을 기다린다는 표시이고, 안녕과 7은 실행 결과입니다. 코드 파일에는 파이썬이 실행할 명령을 적으며, 저장한 두 명령을 실행하면 같은 순서의 결과를 얻습니다.","related":["python-l002","python-l003"]},{"question":"아래에서 if True: 아래의 블록은 실행되는 것으로 주어졌습니다. 그 블록 안에 속한 print가 어느 줄인지 적고, 세 print의 출력 순서를 예측하세요. 들여쓰기를 그대로 타이핑하여 결과를 확인해 보세요.","code":"print(\"밖의 첫 줄\")\nif True:\n    print(\"안쪽\")\nprint(\"밖의 마지막 줄\")","codeKind":"python","codeLabel":"블록의 범위를 읽을 코드","skill":"코드 읽기 · 블록의 범위","solution":{"answer":"예시 답: 세 번째 줄의 들여쓴 print(\"안쪽\")만 해당 블록 안에 속합니다. 출력 순서는 밖의 첫 줄, 안쪽, 밖의 마지막 줄입니다.","code":{"source":"print(\"밖의 첫 줄\")\nif True:\n    print(\"안쪽\")\nprint(\"밖의 마지막 줄\")","kind":"python","output":"밖의 첫 줄\n안쪽\n밖의 마지막 줄","error":null,"caption":"안쪽 줄은 공백 네 칸으로 들여썼고, 마지막 줄은 들여쓰기를 되돌렸습니다."}},"explanation":"들여쓰기는 명령이 어느 블록에 속하는지 나타냅니다. 마지막 print는 들여쓰기를 되돌렸으므로 블록 밖입니다. 여기서는 주어진 블록이 실행되므로 세 출력 명령 모두 위에서 아래 순서로 실행됩니다.","related":["python-l004"]},{"question":"아래 내용을 practice.py에 저장하여 실행하세요. 오류 메시지에서 파일 이름, 줄 번호, 오류 종류를 찾아 적고, 그 줄의 어떤 철자를 먼저 확인해야 하는지 설명해 보세요.","code":"print(\"점검 시작\")\n# 다음 줄에서 점검 완료를 알립니다.\nprnit(\"점검 완료\")","codeKind":"python","codeLabel":"오류 위치를 찾을 코드","skill":"오류 위치 · 줄 번호와 종류","solution":{"answer":"예시 답: 파일은 practice.py, 위치는 3번째 줄, 오류 종류는 NameError입니다. 세 번째 줄의 prnit가 배운 명령 이름인 print와 같은 철자인지 확인합니다.","code":{"source":"print(\"점검 시작\")\n# 다음 줄에서 점검 완료를 알립니다.\nprnit(\"점검 완료\")","kind":"python","output":"점검 시작","error":"NameError","caption":"오류 위치를 확인하는 원본입니다. 파일 경로와 메시지의 자세한 모양은 환경에 따라 다를 수 있습니다."}},"explanation":"파일과 줄 번호는 살펴볼 위치를 알려 주며 주석도 파일의 한 줄로 셉니다. NameError는 찾으려는 이름을 알 수 없다는 뜻입니다. 이 코드에서는 print의 철자를 prnit로 잘못 적은 것이 원인입니다.","related":["python-l004","python-l005"]},{"question":"아래 두 줄 전체를 한 .py 파일에 작성하세요. 준비가 출력될지 먼저 예측한 뒤 파일로 실행하고, 오류 종류와 빠진 기호가 있는 줄을 찾아 적으세요. 대화형 창에 한 줄씩 입력했을 때와 혼동하지 마세요.","code":"print(\"준비\")\nprint(\"출발\"","codeKind":"python","codeLabel":"파일 전체의 문법을 확인할 코드","skill":"오류 위치 · 파일의 문법 검사","solution":{"answer":"예시 답: 준비도 출력되지 않습니다. 두 번째 줄에 닫는 괄호 )가 빠져 있어 SyntaxError가 발생합니다.","code":{"source":"print(\"준비\")\nprint(\"출발\"","kind":"python","output":"","error":"SyntaxError","caption":"한 파일로 실행하면 첫 번째 출력도 시작되지 않는 것을 확인하는 코드입니다."}},"explanation":"파일을 실행하기 전에 전체 문법을 읽는 단계에서 닫히지 않은 괄호를 발견합니다. 따라서 첫 번째 명령도 실행되지 않습니다. 실행 중 오류 전에 완료한 출력이 남는 3번 문제와 이 점이 다릅니다.","related":["python-l002","python-l005"]},{"question":"아래 코드는 Start 다음 줄에 End를 출력하려는 프로그램입니다. 두 출력 명령을 모두 유지하고 순서도 바꾸지 않은 채, 빠진 기호를 넣어 수정하세요. 저장하고 실행하여 두 줄의 출력을 확인해 보세요.","code":"print(\"Start\")\nprint(\"End)","codeKind":"python","codeLabel":"수정할 코드","skill":"작은 수정 · 의도를 유지하며 고치기","solution":{"answer":"예시 답: 두 번째 줄의 End 뒤에 닫는 따옴표를 넣습니다. 실행 결과가 Start, End 두 줄인지 확인합니다.","code":{"source":"print(\"Start\")\nprint(\"End\")","kind":"python","output":"Start\nEnd","error":null,"caption":"빠진 따옴표를 넣어 의도한 두 출력을 유지한 수정 예시입니다."}},"explanation":"문자열을 나타내는 따옴표는 여는 것과 닫는 것이 짝을 이루어야 합니다. 오류가 난 줄을 지우면 End가 사라지므로 원래 목표를 이루지 못합니다. 오류가 없어졌는지와 원하는 결과가 나오는지를 함께 확인하세요.","related":["python-l003","python-l004","python-l005"]},{"question":"작업용 hello.py에 아래 코드를 작성하고 저장하여 실행하세요. 그다음 출력할 글자를 수정으로 바꾸고 다시 저장하여 같은 파일을 실행하세요. 여전히 처음이 나온다면 무엇을 확인할지 두 가지를 적어 보세요.","code":"print(\"처음\")","codeKind":"python","codeLabel":"먼저 저장하여 실행할 코드","skill":"작은 수정 · 저장과 재실행","solution":{"answer":"예시 답: print(\"수정\")으로 바꾸고 저장한 뒤 같은 hello.py를 다시 실행합니다. 결과가 바뀌지 않으면 편집한 내용을 저장했는지, 실행한 파일의 위치와 이름이 편집 중인 파일과 같은지 확인합니다.","code":{"source":"print(\"수정\")","kind":"python","output":"수정","error":null,"caption":"수정 후 저장할 파일의 내용과 다시 실행했을 때의 예상 결과입니다."}},"explanation":"파일 실행은 편집기에 보이는 저장 전 내용이 아니라 저장된 파일 내용을 기준으로 합니다. 오류 메시지가 없더라도 예전 파일이나 다른 위치의 파일을 실행했을 수 있으므로 코드와 실행 대상을 함께 확인해야 합니다.","related":["python-l002","python-l005"]}]},{"id":"python-ch02","slug":"ch02","number":2,"title":"값·이름·연산","description":"값에 이름을 붙이고, 알맞은 연산과 변환을 골라 입력을 결과로 연결합니다.","prerequisite":"선행 학습: 챕터 1 · 프로그램을 읽고 실행하기","runtime":"Python 3","testedVersion":"3.12.14","lessons":[{"id":"python-l006","order":1,"title":"변수는 값에 붙이는 이름","subtitle":"이름이 지금 가리키는 값을 따라가면, 값이 바뀌는 코드가 읽힙니다.","minutes":10,"goal":"대입의 오른쪽을 먼저 계산한 뒤 이름에 연결하고, 재대입 전후에 각 이름이 가리키는 값을 설명한다.","intro":"앞 챕터에서는 print 안에 숫자와 글자를 바로 적었습니다. 그런데 같은 가격을 여러 곳에서 사용하거나 계산한 결과를 다음 줄에서 다시 쓰려면, 매번 값을 새로 적는 일이 불편해집니다. 값에 의미 있는 이름을 붙이면 무엇을 다루는지 드러나고, 그 이름으로 현재 값을 다시 사용할 수 있습니다.","sections":[{"title":"이름을 붙이면 값의 역할이 보입니다.","body":["price = 1200은 숫자 1200에 price라는 이름을 연결하는 대입입니다. 이처럼 값에 연결해 사용하는 이름을 변수라고 부릅니다. price라는 철자가 원래부터 가격을 계산하는 기능을 가진 것은 아닙니다. 사람이 코드의 뜻을 읽기 좋도록 붙인 이름입니다.","그다음 줄에서 price를 쓰면 그 이름에 연결된 현재 값을 사용합니다. print(price)는 1200을 출력하지만, print(\"price\")는 따옴표 안의 글자를 출력합니다. 앞 챕터에서 배운 문자열의 경계가 이름과 문자 값을 구분할 때도 중요합니다."],"code":{"source":"price = 1200\nprint(price)\nprint(\"price\")","kind":"python","output":"1200\nprice","error":null,"caption":"대입은 이름과 값을 연결합니다. 대입문 자체가 값을 화면에 출력하지는 않습니다."}},{"title":"대입은 오른쪽 값을 먼저 구한 뒤 연결합니다.","body":["count = count + 1을 수학의 등식으로 읽으면 같은 수가 자신보다 1 커야 하므로 이상해 보입니다. 하지만 파이썬의 =는 양쪽이 같다고 주장하는 기호가 아닙니다. 오른쪽의 값을 구한 뒤 왼쪽 이름이 그 값을 가리키도록 하는 동작입니다.","아래에서는 count가 먼저 2에 연결되어 있습니다. 두 번째 대입의 오른쪽 count + 1은 현재 값 2를 사용하여 3이 됩니다. 그 계산이 끝난 뒤 count를 3에 다시 연결합니다. 같은 이름에 다시 대입하는 일을 재대입이라고 하며, 이후의 count는 새 값을 사용합니다."],"code":{"source":"count = 2\nprint(count)\ncount = count + 1\nprint(count)","kind":"python","output":"2\n3","error":null,"caption":"오른쪽에서 이전 값 2를 읽고, 계산 결과 3을 왼쪽 이름에 다시 연결합니다."}},{"title":"다른 이름에 대입해도 두 이름이 계속 함께 바뀌지는 않습니다.","body":["saved_price = price는 price라는 이름 자체를 saved_price에 묶는 명령이 아닙니다. 그 시점에 price가 가리키는 값을 구하고, saved_price도 그 값에 연결합니다. 아래에서는 두 이름이 모두 숫자 1000을 가리키는 순간이 생깁니다.","이후 price = 1200을 실행하면 price가 가리키는 값만 달라집니다. 이미 있던 숫자 1000 자체를 1200으로 고치는 것이 아니므로 saved_price는 여전히 1000을 가리킵니다. 지금 다루는 숫자의 재대입에서는 이름마다 현재 연결을 따로 따라가면 됩니다.","계산 결과를 대입할 때도 같습니다. total = price + 500은 그 순간의 덧셈 결과에 total을 연결합니다. 계산 공식을 계속 보관하며 price를 감시하는 기능이 아니므로, 나중에 price가 바뀌었을 때 새 합계가 필요하면 다시 계산해야 합니다."],"code":{"source":"price = 1000\nsaved_price = price\nprice = 1200\nprint(price)\nprint(saved_price)","kind":"python","output":"1200\n1000","error":null,"caption":"price를 새 숫자에 연결해도 saved_price의 기존 연결은 남아 있습니다."}},{"title":"이름은 사용하기 전에 연결하고, 뜻이 드러나게 적습니다.","body":["파이썬이 이름의 현재 값을 찾으려면 그 이름에 먼저 값이 연결되어 있어야 합니다. 아래 파일은 total_price를 출력하는 줄이 대입보다 앞에 있습니다. 이 파일을 새로 실행하면 첫 줄에서 NameError가 나고 다음 대입까지 진행하지 못합니다. 대화형 창에서 예전에 만든 이름이 남아 있는 상황과 새 파일 실행을 구분하세요.","이 과정에서는 영문 소문자와 숫자, 밑줄을 사용해 total_price처럼 이름을 적습니다. 숫자로 시작하거나 이름 중간에 공백을 넣을 수 없으며, if처럼 문법에 이미 쓰이는 단어는 변수 이름으로 사용할 수 없습니다. price와 Price는 서로 다른 이름이므로 철자와 대소문자도 맞춰야 합니다.","의미를 알 수 있는 이름은 메모 역할도 합니다. a보다 total_price가 계산값의 쓰임을 드러냅니다. 이미 출력에 쓰는 print 같은 이름을 다른 값에 대입하면 원래 기능을 쓰기 어려워지므로 새 변수 이름으로 덮어쓰지 않습니다."],"code":{"source":"print(total_price)\ntotal_price = 1200","kind":"python","output":"","error":"NameError","caption":"먼저 이름을 사용한 뒤 나중에 대입해도 첫 줄의 오류가 해결되지는 않습니다. 대입 줄을 위로 옮겨야 합니다."}}],"worked":{"question":"기본 요금에 500을 더해 합계를 구한 뒤 기본 요금이 달라졌습니다. 아래 두 출력이 왜 다른지, 각 대입이 실행되는 시점의 값을 따라가 보세요.","code":{"source":"base_price = 1000\ntotal = base_price + 500\nbase_price = 1200\nprint(total)\ntotal = base_price + 500\nprint(total)","kind":"python","output":"1500\n1700","error":null,"caption":"계산한 값을 보관하는 것과 현재 값을 사용해 다시 계산하는 것을 비교합니다."},"steps":["base_price가 1000일 때 첫 덧셈을 계산하므로 total은 1500에 연결됩니다.","base_price를 1200에 다시 연결해도 total의 기존 값은 1500입니다. 첫 print가 그 값을 보여 줍니다.","두 번째 total 대입에서 현재 base_price인 1200을 읽고 500을 더합니다. 이제 total이 1700에 연결되어 두 번째 출력이 달라집니다."],"answer":"출력은 1500과 1700입니다. total은 계산식을 자동으로 다시 계산하는 이름이 아니라, 대입할 때 구한 값에 연결되는 이름입니다."},"misconception":{"question":"b = a를 한 뒤 a를 바꾸면 b도 자동으로 바뀌나요?","answer":"숫자에 연결된 a를 다른 숫자로 재대입해도 b의 연결은 자동으로 바뀌지 않습니다. b = a는 그때 a가 가리키던 값에 b를 연결합니다. 여기서는 숫자 값 자체의 변경과 이름의 재연결을 구분하는 것이 핵심입니다. 나중에 리스트처럼 내용을 바꿀 수 있는 값을 배울 때는 같은 값을 함께 사용하는 상황을 따로 살펴봅니다."},"keypoints":["변수는 값에 붙이는 이름입니다. 따옴표 없는 이름은 현재 값을 읽고, 따옴표 안의 이름 모양은 문자 값입니다.","대입은 오른쪽 값을 먼저 구한 뒤 왼쪽 이름에 연결합니다. 재대입한 뒤에는 새 값을 읽습니다.","다른 이름의 재대입이나 원래 재료의 변경이 이미 계산한 숫자를 자동으로 갱신하지는 않습니다."],"examples":[{"question":"book_price에 800을 대입하고, 다음 두 줄에 그 값과 book_price라는 글자를 각각 출력하세요. 파일을 실행해 두 출력이 왜 다른지도 설명해 보세요.","skill":"이름과 문자 값 구분","solution":{"answer":"첫 줄에는 800, 둘째 줄에는 book_price가 나타납니다.","code":{"source":"book_price = 800\nprint(book_price)\nprint(\"book_price\")","kind":"python","output":"800\nbook_price","error":null}},"explanation":"따옴표 없는 book_price는 연결된 값 800을 읽습니다. 따옴표로 감싼 표현은 이름을 찾지 않고 그 글자 자체를 사용합니다."},{"question":"아래 코드를 직접 입력하고, 실행 전에 두 번째 대입의 오른쪽과 실행 후 count의 값을 적어 보세요. 이어서 실행해 예상과 비교하세요.","skill":"이전 값으로 재대입","solution":{"answer":"오른쪽 count + 2는 4 + 2이므로 6입니다. 계산한 뒤 count가 6에 연결되어 6을 출력합니다.","code":{"source":"count = 4\ncount = count + 2\nprint(count)","kind":"python","output":"6","error":null}},"explanation":"왼쪽 이름을 먼저 지우는 것이 아닙니다. 오른쪽에서 현재 값을 읽어 계산한 다음, 왼쪽 이름이 계산 결과를 가리키도록 합니다.","code":"count = 4\ncount = count + 2\nprint(count)","codeKind":"python"},{"question":"아래 파일의 두 출력을 먼저 적어 보고 실행하세요. price를 1100에 다시 대입해도 saved_price가 어떻게 되는지 자신의 말로 설명하세요.","skill":"두 이름의 현재 값 추적","solution":{"answer":"saved_price는 900, price는 1100을 출력합니다.","code":{"source":"price = 900\nsaved_price = price\nprice = 1100\nprint(saved_price)\nprint(price)","kind":"python","output":"900\n1100","error":null}},"explanation":"saved_price에는 대입 당시의 값 900이 연결되어 있습니다. price라는 이름에 대한 재대입은 saved_price의 연결을 바꾸지 않습니다.","code":"price = 900\nsaved_price = price\nprice = 1100\nprint(saved_price)\nprint(price)","codeKind":"python"},{"question":"아래 파일을 새로 실행하면 이름을 찾지 못하는 오류가 납니다. 두 줄의 순서만 바꾸어 20을 출력하게 고치고, 왜 대입이 먼저 필요한지 설명하세요.","skill":"이름을 사용하기 전 대입","solution":{"answer":"points = 20을 먼저 실행하고 print(points)를 실행하면 20이 출력됩니다.","code":{"source":"points = 20\nprint(points)","kind":"python","output":"20","error":null}},"explanation":"기존 파일은 아직 points에 값이 연결되지 않은 상태에서 그 이름을 읽으려 합니다. 출력할 시점에 값을 찾을 수 있도록 대입이 앞에 있어야 합니다.","code":"print(points)\npoints = 20","codeKind":"python"},{"question":"아래 코드는 기본값을 1400으로 바꾼 뒤에도 이전 합계를 출력합니다. base를 바꾼 다음 total을 다시 계산하는 한 줄을 추가하여 1600을 출력하세요. 숫자 1600을 print에 직접 적지 마세요.","skill":"계산 결과 다시 구하기","solution":{"answer":"base = 1400 다음에 total = base + 200을 추가하면 현재 기본값으로 합계를 다시 계산합니다.","code":{"source":"base = 1000\ntotal = base + 200\nbase = 1400\ntotal = base + 200\nprint(total)","kind":"python","output":"1600","error":null}},"explanation":"원래 total의 값은 1200입니다. base에 새 값을 대입하는 일과 total을 다시 계산하는 일은 별개이므로, 새 합계가 필요할 때 계산을 다시 실행합니다.","code":"base = 1000\ntotal = base + 200\nbase = 1400\nprint(total)","codeKind":"python"}]},{"id":"python-l007","order":2,"title":"정수와 실수의 계산","subtitle":"원하는 결과가 전체 몫인지, 묶음 수인지, 남은 양인지에 따라 연산을 고릅니다.","minutes":12,"goal":"정수와 실수의 기본 연산, 나눗셈의 세 종류, 괄호와 우선순위에 따른 결과를 설명한다.","intro":"이제 계산할 값에 이름을 붙일 수 있습니다. 다음으로 중요한 일은 원하는 계산을 정확히 고르는 것입니다. 사탕을 똑같이 나눌 때 한 사람의 양을 알고 싶은지, 완성되는 묶음 수를 알고 싶은지, 남는 사탕 수를 알고 싶은지에 따라 필요한 연산이 달라집니다.","sections":[{"title":"정수와 실수는 숫자를 다루는 방식이 다릅니다.","body":["7, 0, -3처럼 정수를 나타내는 값은 int형입니다. 7.0, 0.5처럼 소수점을 사용해 적는 수는 float형으로, 실수의 계산에 사용합니다. 자료형은 값이 어떤 종류이고 어떤 규칙으로 다뤄지는지 구분하는 기준입니다. 7과 7.0은 같은 크기를 나타내지만 서로 같은 종류의 값은 아닙니다.","기본 덧셈은 +, 뺄셈은 -, 곱셈은 *를 사용합니다. 파이썬 코드에서는 곱하기를 수학의 × 대신 *로 적습니다. 정수끼리 이 연산들을 하면 정수 결과를 얻으며, 아래의 7 + 0.5처럼 float가 함께 들어간 계산에서는 float 결과를 얻습니다.","앞 레슨의 대입을 함께 사용해도 계산 원리는 같습니다. price * count는 각 이름의 현재 값을 읽어 곱합니다. 단위를 Python이 자동으로 알아내지는 않으므로, 무엇을 계산한 숫자인지는 이름과 설명으로 드러내야 합니다."],"code":{"source":"print(7)\nprint(7.0)\nprice = 1200\ncount = 3\nprint(price * count)\nprint(7 + 0.5)","kind":"python","output":"7\n7.0\n3600\n7.5","error":null,"caption":"정수 7과 float 7.0의 표기를 비교하고, 이름에 연결된 값으로 계산합니다."}},{"title":"나눗셈은 전체 몫, 내린 몫, 나머지를 나누어 생각합니다.","body":["17을 5로 나눈 값 전체가 필요하면 /를 사용하여 3.4를 얻습니다. /는 정수끼리 계산해 나누어떨어지더라도 float 결과를 만듭니다. 따라서 10 / 5의 결과는 2.0입니다.","17개를 5개씩 완전한 묶음으로 나눌 때는 17 // 5로 묶음 수 3을 구하고, 17 % 5로 남은 수 2를 구할 수 있습니다. //는 나눈 값을 그 값보다 크지 않은 가장 가까운 정수 방향으로 내리는 연산이며, %는 그 몫과 맞는 나머지를 구하는 연산입니다. 여기서는 정수끼리 계산하므로 결과도 정수입니다.","음수에서는 ‘소수점 아래를 그냥 지운다’고 생각하면 틀립니다. -7 / 3은 약 -2.333이므로 아래쪽 정수로 내리면 -3입니다. 따라서 -7 // 3은 -3, -7 % 3은 2입니다. -3에 3을 곱한 -9에 나머지 2를 더하면 원래 수 -7로 돌아옵니다.","정수 a와 0이 아닌 정수 b에서는 a가 (a // b) * b + a % b와 같아집니다. 나머지는 0이 아니면 나누는 수 b와 같은 부호를 가집니다. 나누는 수가 0이면 /, //, % 모두 계산할 수 없으며 앞 챕터에서 본 ZeroDivisionError가 납니다."],"code":{"source":"print(17 / 5)\nprint(17 // 5)\nprint(17 % 5)\nprint(-7 // 3)\nprint(-7 % 3)","kind":"python","output":"3.4\n3\n2\n-3\n2","error":null,"caption":"양수 묶음의 뜻으로 이해한 뒤, 음수에서는 아래쪽 정수로 내리는 규칙을 확인합니다."}},{"title":"괄호는 먼저 계산할 범위를 분명히 보여 줍니다.","body":["파이썬은 식에 적힌 모든 연산을 무조건 왼쪽부터 처리하지 않습니다. **는 거듭제곱으로, 2 ** 3은 2를 세 번 곱한 8입니다. 기본적으로 거듭제곱을 곱셈·나눗셈보다 먼저, 곱셈·나눗셈을 덧셈·뺄셈보다 먼저 계산합니다. 같은 단계의 +와 -끼리, 또는 *와 /·//·%끼리는 왼쪽에서 오른쪽으로 계산합니다.","2 + 3 * 4에서는 3 * 4를 먼저 계산하므로 결과는 14입니다. 두 수를 먼저 더하고 싶다면 (2 + 3) * 4처럼 괄호로 묶어 20을 만듭니다. 괄호는 우선순위를 외우지 못한 표시가 아니라, 계산할 의미를 읽는 사람에게 드러내는 도구이기도 합니다.","음수의 거듭제곱은 밑이 어디까지인지 확인해야 합니다. -2 ** 2는 2 ** 2를 먼저 계산한 뒤 앞의 음수 부호를 적용하여 -4가 됩니다. (-2) ** 2는 음수 -2 전체를 밑으로 하므로 4입니다. 이처럼 헷갈리는 식은 괄호로 의도를 적는 편이 좋습니다."],"code":{"source":"print(2 ** 3)\nprint(2 + 3 * 4)\nprint((2 + 3) * 4)\nprint(-2 ** 2)\nprint((-2) ** 2)","kind":"python","output":"8\n14\n20\n-4\n4","error":null,"caption":"괄호가 어떤 계산을 묶는지 먼저 찾고, 그다음 남은 연산을 읽습니다."}},{"title":"float는 일부 소수를 가까운 값으로 표현합니다.","body":["수학에서 0.1 + 0.2는 0.3입니다. 그런데 Python의 일반적인 float는 수를 내부에서 2진 방식의 제한된 자릿수로 저장합니다. 0.1과 0.2처럼 그 방식으로 정확히 표현할 수 없는 값은 가까운 값으로 저장되므로, 계산 결과에 작은 차이가 드러날 수 있습니다.","아래 첫 출력의 긴 끝자리는 코드의 덧셈 순서가 잘못된 것이 아닙니다. 반면 0.5와 0.25처럼 정확히 표현되는 값도 있으므로 모든 소수 계산에서 눈에 보이는 차이가 생기는 것은 아닙니다. 여기서는 float가 수학의 모든 실수를 무한한 정확도로 저장하지 않는다는 경계만 기억하면 됩니다.","물건 개수나 원 단위 금액처럼 정수로 다룰 수 있는 데이터는 정수로 계산하면 이런 소수 표현 문제를 피할 수 있습니다. 소수의 정밀한 비교·반올림 방식은 그 기능이 필요한 단계에서 배우고, 지금은 출력 끝자리를 보며 곧바로 문법 오류라고 판단하지 않습니다."],"code":{"source":"print(0.1 + 0.2)\nprint(0.5 + 0.25)","kind":"python","output":"0.30000000000000004\n0.75","error":null,"caption":"float의 작은 표현 차이와 정확히 표현되는 소수를 함께 관찰합니다."}}],"worked":{"question":"연필 23자루를 5자루씩 봉투에 넣습니다. 완성되는 봉투 수와 남은 연필 수를 구하고, 두 결과로 원래 연필 수를 다시 확인해 보세요.","code":{"source":"pencils = 23\nbag_size = 5\nfull_bags = pencils // bag_size\nleftover = pencils % bag_size\nprint(full_bags)\nprint(leftover)\nprint(full_bags * bag_size + leftover)","kind":"python","output":"4\n3\n23","error":null,"caption":"완성된 묶음 수와 남은 양을 구한 뒤, 다시 합쳐 원래 개수를 확인합니다."},"steps":["pencils와 bag_size는 개수를 나타내는 정수입니다. 23개 중 5개짜리 완전한 묶음은 4개이므로 //로 full_bags를 구합니다.","완전한 묶음에 넣고 남은 연필은 3자루입니다. %로 이 나머지를 구하여 leftover에 연결합니다.","봉투 4개에 든 4 * 5 = 20자루와 남은 3자루를 합치면 23입니다. 곱셈이 덧셈보다 먼저 계산되어 원래 개수를 복원합니다."],"answer":"완성되는 봉투는 4개이고 남은 연필은 3자루입니다. 4 * 5 + 3 = 23으로 나눈 결과를 확인할 수 있습니다."},"misconception":{"question":"//는 /의 결과에서 소수점 아래만 지우는 연산인가요?","answer":"//는 나눈 값을 음의 무한대 방향으로 내립니다. 양수에서는 소수 부분을 버린 것처럼 보이지만, 음수에서는 결과가 달라집니다. 예를 들어 -7 / 3은 약 -2.333이고 -7 // 3은 -3입니다. //가 언제나 int형을 만드는 것도 아닙니다. 정수끼리 계산하면 int 결과이고, float가 들어간 7.0 // 3 같은 계산은 2.0이라는 float 결과입니다."},"keypoints":["int는 정수, float는 실수 계산에 쓰이는 자료형입니다. /는 정수끼리 나누어도 float 결과를 만듭니다.","//는 나눈 값을 아래쪽 정수 방향으로 내리고, %는 그 몫에 맞는 나머지를 구합니다. 음수에서도 같은 규칙을 적용합니다.","괄호와 연산 우선순위가 계산 순서를 결정합니다. float는 일부 소수를 가까운 값으로 저장할 수 있습니다."],"examples":[{"question":"1000을 4로 나눈 값을 /와 //로 각각 계산하여 한 줄씩 출력하세요. 나누어떨어지는데도 두 결과의 표기가 어떻게 다른지 설명해 보세요.","skill":"나눗셈 결과의 자료형","solution":{"answer":"/의 출력은 250.0이고 //의 출력은 250입니다.","code":{"source":"print(1000 / 4)\nprint(1000 // 4)","kind":"python","output":"250.0\n250","error":null}},"explanation":"정수끼리 계산해도 /는 float 결과를 만듭니다. 이 예의 //는 정수 두 개를 사용한 내림 나눗셈이므로 int 결과를 만듭니다."},{"question":"사탕 29개를 6개씩 봉투에 담으려고 합니다. candies와 bag_size에 값을 대입하고, 완성되는 봉투 수와 남은 사탕 수를 각각 구해 출력하세요. 마지막에는 묶음과 나머지를 합쳐 29가 되는지도 출력해 확인하세요.","skill":"묶음 수와 나머지 구하기","solution":{"answer":"완성되는 봉투는 4개, 남은 사탕은 5개입니다. 4 * 6 + 5는 29입니다.","code":{"source":"candies = 29\nbag_size = 6\nfull_bags = candies // bag_size\nleftover = candies % bag_size\nprint(full_bags)\nprint(leftover)\nprint(full_bags * bag_size + leftover)","kind":"python","output":"4\n5\n29","error":null}},"explanation":"사탕 개수는 정수입니다. 완전한 묶음 수는 //로, 묶고 남은 양은 %로 구하면 나눗셈의 서로 다른 목적을 분리할 수 있습니다."},{"question":"아래 식은 2와 3을 먼저 더한 값을 제곱하려던 코드입니다. 현재 출력부터 예상하고 실행한 뒤, 괄호를 추가해 원하는 결과 25가 나오도록 고치세요. **의 의미와 괄호의 역할도 설명하세요.","skill":"거듭제곱과 괄호로 의도 표현","solution":{"answer":"원래 코드는 3 ** 2를 먼저 계산하여 11을 출력합니다. (2 + 3) ** 2로 고치면 5를 제곱한 25가 됩니다.","code":{"source":"print((2 + 3) ** 2)","kind":"python","output":"25","error":null}},"explanation":"**는 거듭제곱이고 덧셈보다 먼저 계산합니다. 원하는 밑이 두 수의 합 전체라면 그 범위를 괄호로 분명하게 표시해야 합니다.","code":"print(2 + 3 ** 2)","codeKind":"python"},{"question":"-10을 3으로 나누는 //와 %를 각각 실행해 보세요. quotient와 remainder에 결과를 대입하고 두 값을 출력한 뒤, quotient * 3 + remainder도 출력하세요. 왜 몫이 -3이 아닌지 설명하세요.","skill":"음수의 내림 나눗셈","solution":{"answer":"몫은 -4, 나머지는 2이고, -4 * 3 + 2는 원래 수 -10입니다.","code":{"source":"quotient = -10 // 3\nremainder = -10 % 3\nprint(quotient)\nprint(remainder)\nprint(quotient * 3 + remainder)","kind":"python","output":"-4\n2\n-10","error":null}},"explanation":"나눈 값 약 -3.333보다 크지 않은 가장 가까운 정수는 -4입니다. //는 0 쪽으로 소수 부분을 지우는 연산이 아니며, %의 결과는 이 몫과 함께 원래 수를 복원합니다."},{"question":"0.1 + 0.2와 0.5 + 0.25를 각각 출력하는 코드를 작성해 실행하세요. 수학에서 기대하는 값과 출력을 비교한 뒤, 첫 결과의 긴 끝자리가 왜 나타나는지 한 문장으로 적어 보세요.","skill":"실수 근사의 경계 관찰","solution":{"answer":"출력은 0.30000000000000004와 0.75입니다. float가 일부 소수를 정확히 저장하지 못하고 가까운 값으로 표현하기 때문에 작은 차이가 보일 수 있습니다.","code":{"source":"print(0.1 + 0.2)\nprint(0.5 + 0.25)","kind":"python","output":"0.30000000000000004\n0.75","error":null}},"explanation":"소수점을 썼다는 이유만으로 계산이 항상 정확하거나 항상 눈에 띄게 어긋나는 것은 아닙니다. 0.5와 0.25는 이 표현 방식으로 정확히 나타낼 수 있으므로 두 사례를 구분합니다."}]},{"id":"python-l008","order":3,"title":"문자열과 숫자 변환","subtitle":"같아 보이는 값도 맡길 일에 따라 필요한 타입이 다릅니다.","minutes":11,"goal":"문자열과 숫자의 타입을 확인하고, 계산이나 표시 목적에 맞게 변환하며 실패와 정보 손실을 설명한다.","intro":"화면에 12가 보인다고 해서 언제나 숫자 12를 가지고 있는 것은 아닙니다. 글자로 적힌 수량은 계산하기 전에 숫자로 읽어야 하고, 계산한 수량을 문장에 붙이려면 다시 글자로 나타낼 필요가 있습니다. 변환은 따옴표를 눈으로 지우는 요령이 아니라, 값에 어떤 일을 맡길지 정하는 과정입니다.","sections":[{"title":"타입은 값이 어떤 종류인지 알려 줍니다.","body":["앞에서 숫자와 문자열을 변수 이름에 연결했습니다. 이제 그 값의 종류를 타입이라고 부릅니다. 정수의 타입 이름은 int, 소수를 표현하는 부동소수점 수는 float, 문자열은 str입니다. 타입은 어떤 연산을 할 수 있고 그 연산을 어떻게 해석할지에 관계됩니다.","print만 보면 문자열 \"12\"와 정수 12가 모두 12로 보일 수 있습니다. type(...)은 전달한 값의 타입을 알려 줍니다. print(type(text))처럼 결과를 출력했을 때 <class 'str'>가 나오면 문자열이라는 뜻입니다. 여기서는 class라는 단어의 세부 의미보다 안쪽 타입 이름을 읽으면 됩니다."],"code":{"source":"text = \"12\"\nnumber = 12\nprint(text)\nprint(number)\nprint(type(text))\nprint(type(number))\nprint(type(12.0))","kind":"python","output":"12\n12\n<class 'str'>\n<class 'int'>\n<class 'float'>","error":null,"caption":"출력 모양이 같아도 type으로 확인한 값의 종류는 다를 수 있습니다."}},{"title":"계산하려면 문자열을 숫자로 읽습니다.","body":["int(\"12\")는 정수를 나타내는 문자열을 읽어 정수 12를 만듭니다. float(\"2.5\")는 소수를 나타내는 문자열을 읽어 float 값 2.5를 만듭니다. int와 float는 타입의 이름이면서, 괄호에 전달한 값을 해당 타입으로 변환할 때도 사용합니다.","변환 결과를 다른 이름에 연결하면 원래 문자열과 변환한 숫자를 각각 사용할 수 있습니다. int(text_count)를 실행했다고 text_count의 값이 저절로 바뀌지는 않습니다. 변환한 결과를 무엇에 사용할지, 어느 이름에 연결할지도 코드로 적어야 합니다.","변환 뒤에는 숫자끼리 덧셈이나 곱셈을 할 수 있습니다. 문자열이 숫자처럼 보인다는 이유만으로 Python이 계산 목적을 추측해 자동으로 변환하지는 않습니다."],"code":{"source":"text_count = \"12\"\ncount = int(text_count)\nweight = float(\"2.5\")\nprint(count + 3)\nprint(weight + 0.5)\nprint(type(text_count))","kind":"python","output":"15\n3.0\n<class 'str'>","error":null,"caption":"숫자로 변환한 값으로 계산해도 text_count는 원래 문자열을 가리킵니다."}},{"title":"문장에 붙일 때는 숫자를 문자열로 나타냅니다.","body":["문자열끼리 +를 쓰면 글자를 이어 붙입니다. 예를 들어 \"개수: \" + \"12\"는 \"개수: 12\"가 됩니다. 반면 \"개수: \" + 12처럼 문자열과 정수를 바로 연결하면 TypeError가 납니다. 문자열 연결에 맞지 않는 종류의 값이 함께 전달됐기 때문입니다.","str(12)는 숫자 12를 나타내는 문자열 \"12\"를 만듭니다. 따라서 \"개수: \" + str(count)처럼 각 부분을 문자열로 맞추어 연결할 수 있습니다. 계산할 때는 숫자, 문장을 만들 때는 문자열이라는 목적을 구분하세요. str(count) 역시 count에 연결된 원래 숫자를 바꾸지 않습니다."],"code":{"source":"count = 12\nmessage = \"개수: \" + str(count)\nprint(message)\nprint(type(count))","kind":"python","output":"개수: 12\n<class 'int'>","error":null,"caption":"표시에 쓸 문자열을 만들고도 원래 count로는 계속 숫자 계산을 할 수 있습니다."}},{"title":"변환에는 받아들일 수 있는 형태와 잃는 정보가 있습니다.","body":["int(\"3.5\")는 ValueError를 일으킵니다. int가 정수로 읽을 문자열에 소수점이 있기 때문입니다. 3.5를 그대로 사용하려는 목적이라면 float(\"3.5\")가 맞습니다. int(\"세 개\")처럼 숫자로 해석할 수 없는 글도 변환되지 않습니다. Python이 필요한 숫자만 알아서 골라내는 기능은 아닙니다.","이미 float인 수를 int에 전달하는 것은 다릅니다. int(3.9)는 3, int(-3.9)는 -3처럼 소수 부분을 없애고 0 쪽으로 정수를 만듭니다. 반올림도 아니고 음수를 더 작은 정수로 내리는 것도 아닙니다. int(float(\"3.5\"))는 실행되지만 결과가 3이므로, 소수 부분을 버려도 되는 목적일 때만 사용합니다.","형태의 정보도 달라질 수 있습니다. int(\"003\")은 3이고, 이를 str로 다시 바꿔도 원래의 003 모양이 돌아오지는 않습니다. 개수를 계산할 값인지, 앞의 0까지 보존할 번호표인지 먼저 구분해야 하는 이유입니다."],"code":{"source":"print(float(\"3.5\"))\nprint(int(3.9))\nprint(int(-3.9))\nprint(int(float(\"3.5\")))","kind":"python","output":"3.5\n3\n-3\n3","error":null,"caption":"첫 줄은 소수를 유지하고, int로 바꾼 값에서는 소수 부분이 사라집니다."}}],"worked":{"question":"가격 \"1250\"과 수량 \"3\"이 문자열로 주어졌습니다. 총액을 계산하고 총액: 3750원이라는 문장으로 보여 주려면 어떤 변환이 필요할까요?","code":{"source":"price_text = \"1250\"\nquantity_text = \"3\"\nprice = int(price_text)\nquantity = int(quantity_text)\ntotal = price * quantity\nprint(total)\nprint(\"총액: \" + str(total) + \"원\")","kind":"python","output":"3750\n총액: 3750원","error":null,"caption":"코드에 미리 적어 둔 문자열로 계산합니다. 키보드 입력을 받는 프로그램은 아닙니다."},"steps":["처음 두 값은 따옴표로 적힌 문자열입니다. 가격과 수량을 계산에 쓰려고 각각 int로 읽어 정수를 만듭니다.","두 정수를 곱한 total은 정수 3750입니다. print(total)로 계산 결과를 먼저 확인합니다.","출력 문장을 만들 때는 str(total)로 숫자를 문자열로 나타냅니다. 문장 앞뒤의 문자열과 +로 연결하여 총액: 3750원을 만듭니다."],"answer":"계산 전에 int로 숫자를 만들고, 문장과 연결할 때 str로 나타냅니다. 각 변환의 방향은 다음에 할 일에 따라 달라집니다."},"misconception":{"question":"변환이 성공하면 원래 정보도 모두 유지된 건가요?","answer":"그렇지 않습니다. int(3.9)는 오류 없이 3을 만들지만 소수 부분이 사라집니다. int(\"003\")도 3을 만들지만 앞의 0 두 개를 보존하지 않습니다. 또 변환 결과를 다른 이름에 연결했다면 원래 변수의 문자열은 그대로 남습니다. 변환 성공 여부와 필요한 정보가 유지됐는지, 어떤 이름에 결과를 연결했는지를 각각 확인해야 합니다."},"keypoints":["type으로 값의 종류를 확인합니다. 출력 모양이 같아도 문자열과 숫자는 다를 수 있습니다.","계산용 문자열은 int·float로 읽고, 숫자를 문장에 연결할 때는 str로 나타냅니다. 변환 결과를 사용해야 하며 원래 이름이 자동으로 바뀌지는 않습니다.","int(\"3.5\")는 실패하고 float(\"3.5\")는 소수를 유지합니다. int에 float를 전달하면 0 방향으로 소수 부분을 없애므로 필요한 정보의 손실도 확인합니다."],"examples":[{"question":"아래 코드를 직접 적어 실행하세요. 첫 두 출력은 같은데 뒤의 두 출력은 왜 다른지 설명하세요. 이어서 number를 8.0으로 바꾸었을 때 number의 타입이 어떻게 달라지는지도 확인하세요.","skill":"출력 모양과 타입 구분","solution":{"answer":"처음에는 8과 8이 나오고, 타입은 str과 int입니다. number를 8.0으로 바꾸면 그 값의 출력은 8.0, 타입은 float가 됩니다.","code":{"source":"text = \"8\"\nnumber = 8.0\nprint(text)\nprint(number)\nprint(type(text))\nprint(type(number))","kind":"python","output":"8\n8.0\n<class 'str'>\n<class 'float'>","error":null,"caption":"number를 8.0으로 바꾼 뒤의 코드입니다."}},"explanation":"type은 화면에 그려진 글자의 모양이 아니라 전달한 값의 종류를 확인합니다. text는 변환하거나 다시 대입하지 않았으므로 계속 문자열입니다.","code":"text = \"8\"\nnumber = 8\nprint(text)\nprint(number)\nprint(type(text))\nprint(type(number))","codeKind":"python"},{"question":"아래 코드는 문자열로 적힌 20에 숫자 5를 더하려다 멈춥니다. 오류 종류를 확인한 뒤, 숫자 덧셈 결과 25가 나오도록 고치세요. 원래 value가 여전히 문자열인지도 type으로 확인하세요.","skill":"타입에 맞는 변환으로 오류 수정","solution":{"answer":"원래 코드는 TypeError가 납니다. int(value) + 5로 계산하면 25가 나오며, value의 타입은 여전히 str입니다.","code":{"source":"value = \"20\"\nprint(int(value) + 5)\nprint(type(value))","kind":"python","output":"25\n<class 'str'>","error":null}},"explanation":"문자열과 정수를 바로 +로 더할 수 없습니다. int로 만든 정수와 5를 더하면 숫자 덧셈을 수행합니다. 원래 value에 변환 결과를 다시 대입하지 않았으므로 원래 문자열은 유지됩니다.","code":"value = \"20\"\nprint(value + 5)","codeKind":"python","codeLabel":"수정할 코드"},{"question":"아래 파일을 실행해 오류 종류를 확인하세요. 소수 3.5를 유지한 채 1을 더해 4.5를 출력하도록 변환 한 곳을 고치세요. int(float(text))로 바꾸는 것이 이번 목표에 맞지 않는 이유도 적으세요.","skill":"문자열의 형태와 변환 목적","solution":{"answer":"int(text)에서 ValueError가 납니다. float(text)로 고치면 4.5가 출력됩니다. int(float(text))는 3을 만들므로 1을 더해도 4가 되어 목표와 다릅니다.","code":{"source":"text = \"3.5\"\nvalue = float(text)\nprint(value + 1)","kind":"python","output":"4.5","error":null}},"explanation":"int는 문자열 \"3.5\"를 정수의 표기로 받아들이지 않습니다. 소수를 보존하려는 요구에는 float 변환이 맞으며, 오류만 없애고 소수 부분을 버리면 원래 요구를 만족하지 못합니다.","code":"text = \"3.5\"\nvalue = int(text)\nprint(value + 1)","codeKind":"python","codeLabel":"소수 부분을 유지하도록 고칠 코드"},{"question":"int(4.9)와 int(-4.9)를 각각 출력하는 코드를 작성하세요. 결과를 먼저 예상한 뒤 실행하고, 반올림이나 음수 쪽으로 내리는 계산과 어떻게 다른지 설명하세요.","skill":"float를 정수로 바꿀 때의 손실","solution":{"answer":"결과는 4와 -4입니다. 양수와 음수 모두 소수 부분을 없애며 0 쪽의 정수가 됩니다.","code":{"source":"print(int(4.9))\nprint(int(-4.9))","kind":"python","output":"4\n-4","error":null}},"explanation":"4.9를 반올림하면 5이지만 int(4.9)는 4입니다. -4.9보다 작은 정수로 내리면 -5이지만 int(-4.9)는 -4입니다. 변환의 규칙을 계산 목적과 구분해야 합니다."},{"question":"아래 두 문자열은 끝낸 레슨 수와 남은 레슨 수입니다. 두 수를 더해 전체 6개라는 한 줄을 출력하세요. 숫자 계산과 문자열 연결에 각각 어떤 변환을 사용했는지 적으세요.","skill":"계산과 표시를 위한 변환 조합","solution":{"answer":"두 문자열을 정수로 바꾸어 더한 뒤, 합을 str로 나타내어 문장에 연결합니다. 아래는 가능한 풀이의 한 가지입니다.","code":{"source":"completed_text = \"4\"\nremaining_text = \"2\"\ncompleted = int(completed_text)\nremaining = int(remaining_text)\ntotal = completed + remaining\nprint(\"전체 \" + str(total) + \"개\")","kind":"python","output":"전체 6개","error":null}},"explanation":"문자열 \"4\"와 \"2\"를 그대로 +로 연결하면 \"42\"가 됩니다. 합계가 필요하므로 먼저 숫자로 읽고, 마지막에 출력할 문장을 만들 때 다시 문자열로 나타냅니다.","code":"completed_text = \"4\"\nremaining_text = \"2\"","codeKind":"python"}]},{"id":"python-l009","order":4,"title":"비교·불리언·논리 연산","subtitle":"값을 비교해 얻은 참과 거짓으로 여러 조건을 정확히 표현합니다.","minutes":11,"goal":"비교 결과를 불리언 값으로 다루고 and·or·not과 괄호로 요구에 맞는 조건을 표현한다.","intro":"점수가 기준에 도달했는지, 두 가지 준비가 모두 끝났는지처럼 계산 결과에 질문을 던질 때가 있습니다. 이런 질문의 답도 프로그램이 다룰 수 있는 값입니다. 이번 레슨에서는 참과 거짓을 만들고 결합하는 데 집중합니다. 그 결과에 따라 실행할 일을 나누는 조건문은 뒤에서 배우며, 지금은 print로 판단 결과를 확인합니다.","sections":[{"title":"비교의 답도 하나의 값입니다.","body":["두 값을 비교한 결과는 참을 나타내는 True 또는 거짓을 나타내는 False입니다. 이 두 값의 타입을 bool, 불리언이라고 부릅니다. 첫 글자를 대문자로 쓰고 따옴표로 감싸지 않습니다. \"False\"는 글자가 들어 있는 문자열이므로 불리언 False와 구분합니다.","==는 같은지, !=는 다른지 확인합니다. >와 <는 큰지와 작은지, >=와 <=는 크거나 같은지와 작거나 같은지 확인합니다. 특히 >=와 <=는 두 값이 같을 때도 True입니다. 같은 값일 때의 결과가 경계를 포함하는지 결정합니다.","한 개의 =는 오른쪽 값을 이름에 연결하는 대입입니다. 두 개인 ==는 값을 비교하는 연산입니다. score = 80으로 값을 연결한 뒤 score == 80을 확인해도 score에 연결된 값 자체를 바꾸지는 않습니다."],"code":{"source":"score = 80\nprint(score == 80)\nprint(score != 80)\nprint(score > 80)\nprint(score >= 80)\nprint(score < 90)\nprint(score <= 80)\nprint(type(score == 80))","kind":"python","output":"True\nFalse\nFalse\nTrue\nTrue\nTrue\n<class 'bool'>","error":null,"caption":"각 비교의 결과가 불리언 값이며, 그 값을 출력해 확인할 수 있습니다."}},{"title":"and와 or는 서로 다른 요구를 표현합니다.","body":["불리언 값 둘을 and로 연결하면 두 값이 모두 True일 때만 True입니다. 준비 두 가지가 모두 끝나야 하는 상황에 어울립니다. or로 연결하면 하나라도 True일 때 True이며, 둘 다 True인 경우도 포함합니다. 둘 다 False일 때만 False입니다.","아래에서는 표가 있다는 값은 True이고 초대장이 있다는 값은 False입니다. 둘을 모두 가지고 있다는 판단과 하나 이상 가지고 있다는 판단은 서로 다른 결과를 만듭니다. 단어를 외우기보다 질문이 ‘모두’인지 ‘하나 이상’인지 먼저 읽어 보세요.","이 레슨에서는 and와 or 양쪽에 불리언 값이나 비교 결과만 놓습니다. 이 범위에서는 결과도 불리언입니다. 일반 숫자나 문자열에 적용한 and와 or가 언제나 True 또는 False를 돌려주는 것으로 확대해서 생각하지는 않습니다."],"code":{"source":"has_ticket = True\nhas_invitation = False\nprint(has_ticket and has_invitation)\nprint(has_ticket or has_invitation)\nprint(False or False)","kind":"python","output":"False\nTrue\nFalse","error":null,"caption":"둘 모두 필요한 경우와 하나 이상이면 되는 경우를 같은 값으로 비교합니다."}},{"title":"not은 참과 거짓을 뒤집습니다.","body":["불리언 값 앞의 not은 True를 False로, False를 True로 바꿉니다. 예를 들어 is_closed가 휴장 여부라면 not is_closed는 휴장이 아니라는 판단입니다. 질문을 반대로 읽어야 할 때 사용합니다.","비교 전체의 결과를 뒤집고 싶다면 not (age >= 18)처럼 괄호로 묶어 읽을 수 있습니다. age가 15일 때 age >= 18은 False이고, 그 결과를 not으로 뒤집으면 True입니다. 먼저 비교가 답하는 질문과 그 반대 질문을 각각 말로 풀어 보세요."],"code":{"source":"is_closed = False\nprint(not is_closed)\nage = 15\nprint(not (age >= 18))","kind":"python","output":"True\nTrue","error":null,"caption":"첫 줄의 판단은 휴장이 아니라는 뜻, 두 번째 판단은 18 이상이 아니라는 뜻입니다."}},{"title":"괄호로 어떤 조건들을 먼저 묶는지 드러냅니다.","body":["배운 연산을 함께 쓰면 산술 연산과 비교를 먼저 묶고, 논리 연산은 not, and, or 순으로 묶습니다. 우선순위는 식의 묶음을 정하는 규칙입니다. 예를 들어 True or False and False는 True or (False and False)로 읽습니다. 왼쪽 True만으로도 하나 이상이 참이라는 요구를 만족하므로 전체 결과는 True입니다.","반면 (True or False) and False는 괄호로 묶은 결과 True와 마지막 False를 and로 연결하므로 False입니다. 기호가 같아도 묶음이 다르면 질문이 달라질 수 있습니다. 여러 조건을 적을 때는 읽는 사람이 의도를 바로 알 수 있도록 필요한 묶음을 괄호로 표시하세요.","비교 두 개를 연결할 때도 (age >= 7) and (age <= 12)처럼 각 비교를 분명히 적을 수 있습니다. 이렇게 쓰면 7 이상이면서 12 이하라는 범위를 읽기 쉽습니다. 비교식 안의 =와 논리 연결에 필요한 단어를 빠뜨리지 않았는지 확인하세요."],"code":{"source":"print(True or False and False)\nprint((True or False) and False)\nprint(not (3 < 5))","kind":"python","output":"True\nFalse\nFalse","error":null,"caption":"첫 두 줄은 묶음의 차이, 마지막 줄은 비교 결과를 뒤집는 동작을 확인합니다."}}],"worked":{"question":"체험에 참여하려면 나이가 7세 이상 12세 이하이고, 표가 있으며, 휴장이 아니어야 합니다. 12세이고 표가 있으며 휴장이 아니라면 참여 조건을 만족할까요?","code":{"source":"age = 12\nhas_ticket = True\nis_closed = False\nin_range = (age >= 7) and (age <= 12)\ncan_enter = in_range and has_ticket and (not is_closed)\nprint(in_range)\nprint(can_enter)","kind":"python","output":"True\nTrue","error":null,"caption":"실행을 나누는 조건문 없이, 조건이 맞는지를 불리언 값으로 계산합니다."},"steps":["age >= 7과 age <= 12가 모두 True입니다. 같은 값도 허용하는 <=를 사용하므로 12세는 범위에 들어갑니다. 두 비교를 and로 연결한 in_range는 True입니다.","has_ticket은 True이고 is_closed는 False입니다. not is_closed는 휴장이 아니라는 뜻의 True가 됩니다.","세 조건을 and로 연결하면 모두 True일 때 참여 조건이 만족됩니다. can_enter는 True이며, print로 그 판단을 확인합니다."],"answer":"나이 범위, 표 보유, 휴장이 아님이라는 세 조건이 모두 맞으므로 can_enter는 True입니다."},"misconception":{"question":"조건들을 or로 연결하면 둘 중 정확히 하나만 참이어야 하나요?","answer":"아닙니다. 불리언 값끼리의 or는 하나 이상이 True이면 True입니다. True or True도 True입니다. 둘 다 필요한 요구는 and로, 하나 이상이면 되는 요구는 or로 표현합니다. 일상에서 쓰는 ‘또는’이라는 말만 보고 고르지 말고 두 조건이 모두 참인 경우도 허용하는지 확인하세요."},"keypoints":["비교는 True 또는 False를 만듭니다. =는 대입, ==는 같은지 비교이며 >=와 <=는 경계의 같은 값도 포함합니다.","불리언끼리 and는 모두 참, or는 하나 이상 참을 확인합니다. not은 참과 거짓을 뒤집습니다.","논리 연산의 우선순위는 not, and, or이며, 괄호로 묶음을 바꾸면 의미도 달라질 수 있습니다. 요구하는 조건을 먼저 말로 풀어 봅니다."],"examples":[{"question":"아래 여섯 비교의 출력을 먼저 예상하고 직접 실행하세요. >와 >=가 서로 다른 결과를 내는 이유를 설명하세요. 마지막에 출력한 score가 비교 때문에 바뀌었는지도 확인하세요.","skill":"비교 기호와 경계 읽기","solution":{"answer":"비교 결과는 True, False, False, True, True, True 순서이고, 마지막 score는 70입니다. >는 같을 때 False지만 >=는 같을 때도 True입니다.","code":{"source":"score = 70\nprint(score == 70)\nprint(score != 70)\nprint(score > 70)\nprint(score >= 70)\nprint(score < 80)\nprint(score <= 70)\nprint(score)","kind":"python","output":"True\nFalse\nFalse\nTrue\nTrue\nTrue\n70","error":null}},"explanation":"각 비교는 불리언 값을 계산할 뿐 score를 다시 대입하지 않습니다. 기호에 =가 붙은 >=와 <=는 경계값도 포함합니다.","code":"score = 70\nprint(score == 70)\nprint(score != 70)\nprint(score > 70)\nprint(score >= 70)\nprint(score < 80)\nprint(score <= 70)\nprint(score)","codeKind":"python"},{"question":"count에 정수 3을 대입한 뒤, count가 3과 같은지 비교한 결과를 same이라는 이름에 연결하세요. same, same의 타입, count를 각각 출력하세요. 값을 연결할 때와 비교할 때 어떤 기호를 썼는지 설명하세요.","skill":"대입과 비교·불리언 구분","solution":{"answer":"same은 True, 타입은 bool, count는 3입니다. 대입에는 =, 같은지 비교하는 식에는 ==를 사용합니다.","code":{"source":"count = 3\nsame = count == 3\nprint(same)\nprint(type(same))\nprint(count)","kind":"python","output":"True\n<class 'bool'>\n3","error":null}},"explanation":"same = count == 3은 오른쪽의 비교 결과를 계산한 뒤 그 불리언 값을 same에 연결합니다. count에 연결된 숫자 3은 그대로 유지됩니다."},{"question":"아래 값으로 표와 초대장을 모두 가지고 있는지, 하나 이상 가지고 있는지를 각각 출력하세요. 이어서 두 값을 모두 False로 바꾸어 같은 두 판단을 다시 출력하세요.","skill":"and와 or의 요구 차이","solution":{"answer":"처음 두 판단은 False, True입니다. 두 값이 모두 False이면 두 판단 모두 False가 됩니다. 아래는 두 경우를 이어서 확인하는 예시입니다.","code":{"source":"has_ticket = True\nhas_invitation = False\nprint(has_ticket and has_invitation)\nprint(has_ticket or has_invitation)\nhas_ticket = False\nhas_invitation = False\nprint(has_ticket and has_invitation)\nprint(has_ticket or has_invitation)","kind":"python","output":"False\nTrue\nFalse\nFalse","error":null}},"explanation":"모두 필요하다는 요구는 and, 하나 이상이면 된다는 요구는 or로 표현합니다. 두 값이 모두 False이면 어느 요구도 만족하지 못합니다.","code":"has_ticket = True\nhas_invitation = False","codeKind":"python"},{"question":"age가 17일 때 18 이상이 아니라는 판단을 not과 >=를 사용해 출력하세요. 이어서 age를 18로 바꾸어 같은 판단을 다시 출력하세요. 두 결과가 다른 이유를 경계값과 연결해 설명하세요.","skill":"not과 경계값 확인","solution":{"answer":"17일 때는 True, 18일 때는 False입니다. 18은 18 이상에 포함되므로 그 결과를 뒤집으면 False가 됩니다.","code":{"source":"age = 17\nprint(not (age >= 18))\nage = 18\nprint(not (age >= 18))","kind":"python","output":"True\nFalse","error":null}},"explanation":"not (age >= 18)은 먼저 18 이상인지 비교하고 그 결과를 뒤집습니다. not이 있다고 해서 >=가 경계값을 포함하는 규칙이 사라지는 것은 아닙니다."},{"question":"회원이거나 쿠폰이 있고, 동시에 영업 중이어야 이용 가능하다고 정했습니다. 아래 코드는 영업 중이 아닌데도 True를 출력합니다. 회원 여부와 쿠폰 여부를 먼저 묶도록 괄호를 넣어 고치고, 원래 결과와 비교하세요.","skill":"조건 묶음과 우선순위 수정","solution":{"answer":"원래 코드는 True이지만, (is_member or has_coupon) and is_open으로 묶으면 False입니다. 영업 중이어야 한다는 조건이 전체에 적용됩니다.","code":{"source":"is_member = True\nhas_coupon = False\nis_open = False\nprint((is_member or has_coupon) and is_open)","kind":"python","output":"False","error":null}},"explanation":"원래 식은 is_member or (has_coupon and is_open)으로 묶입니다. is_member가 True이므로 전체 결과가 True가 됩니다. 괄호로 회원 또는 쿠폰이라는 판단을 먼저 묶어야 영업 여부까지 함께 요구할 수 있습니다.","code":"is_member = True\nhas_coupon = False\nis_open = False\nprint(is_member or has_coupon and is_open)","codeKind":"python","codeLabel":"괄호를 추가할 코드"}]},{"id":"python-l010","order":5,"title":"입력받아 계산하고 출력하기","subtitle":"읽은 문자열을 목적에 맞는 숫자로 바꾸어 계산 결과까지 연결합니다.","minutes":12,"goal":"입력받기, 숫자로 변환하기, 계산하기, 출력하기를 연결한 작은 프로그램을 작성한다.","intro":"지금까지는 코드에 적힌 값을 바꾸어 계산했습니다. 프로그램을 실행할 때마다 사용자가 다른 값을 넣을 수 있다면 코드를 고치지 않고도 여러 계산을 할 수 있습니다. 앞에서 배운 변수와 숫자 변환을 input에 연결해, 입력한 값이 결과로 바뀌는 과정을 따라가 봅시다.","sections":[{"title":"input은 한 줄을 읽어 문자열로 돌려줍니다.","body":["input()은 실행 중에 입력 한 줄을 읽는 기능입니다. PC에서 아래 파일을 실행한 뒤 입력을 기다리는 창에 수학이라고 타이핑하고 Enter를 누르세요. 이 예시에서는 안내 문장을 출력하지 않으므로 입력 전에는 아무것도 보이지 않을 수 있습니다. Enter를 누르면 그 한 줄을 읽고 다음 명령으로 넘어갑니다.","읽은 결과는 문자열입니다. text = input()은 그 문자열에 text라는 이름을 연결합니다. input은 줄 끝의 줄바꿈을 제외한 내용을 돌려주므로, 그다음 print(text)가 읽은 글자를 한 줄로 출력합니다. 숫자처럼 보이는 25를 입력해도 이 단계에서는 문자열 \"25\"입니다.","이 페이지의 입력 예시는 코드를 적는 자리가 아니라 실행 중에 넣을 값을 보여 줍니다. 따옴표를 덧붙이지 않고 각 줄을 입력한 뒤 Enter를 누릅니다. 터미널이나 IDLE 창에는 타이핑한 글자도 보일 수 있지만, 여기의 예상 출력에는 프로그램이 print로 내보낸 내용만 적습니다."],"code":{"source":"text = input()\nprint(text)","kind":"python","output":"수학","error":null,"input":"수학\n","caption":"PC에서 파일을 실행하고 수학을 입력한 뒤 Enter를 누르세요. 입력 예시와 예상 출력은 역할이 다릅니다."}},{"title":"계산하기 전에 숫자라는 뜻을 정합니다.","body":["수량을 입력받아 10을 더하려면, 읽은 문자열을 먼저 정수로 바꿔야 합니다. input이 숫자 모양을 보고 자동으로 int를 선택하지는 않습니다. 사용자가 입력한 내용이 글자인지 정수인지 실수인지는 프로그램을 만드는 사람이 목적에 맞게 정합니다.","아래에서는 number_text로 문자열을 받고 int(number_text)로 정수를 만듭니다. 그 결과에 number라는 이름을 붙인 뒤 덧셈을 합니다. 이름을 나누면 읽은 원본과 계산할 값을 구별하기 쉽습니다. 익숙해지면 number = int(input())처럼 한 줄로 쓸 수도 있으며, 이때도 먼저 input()이 끝난 뒤 int가 그 결과를 변환합니다."],"code":{"source":"number_text = input()\nnumber = int(number_text)\nresult = number + 10\nprint(result)","kind":"python","output":"17","error":null,"input":"7\n","caption":"7을 입력하면 문자열 \"7\"을 정수 7로 바꾸고 10을 더합니다."}},{"title":"여러 입력은 적힌 순서대로 한 줄씩 받습니다.","body":["두 값을 읽으려면 input을 두 번 사용합니다. 아래 코드는 첫 번째 줄을 읽어 first_text에 연결한 다음 두 번째 줄을 기다립니다. 8을 입력하고 Enter를 누른 뒤, 5를 입력하고 다시 Enter를 누르세요. 두 번째 입력까지 받으면 두 값을 변환하고 계산합니다.","한 번의 input은 한 줄 전체를 문자열 하나로 읽습니다. 따라서 이 예시에 8 5를 한 줄로 넣으면 두 값으로 자동 분리되지 않습니다. 지금은 값 하나마다 한 줄을 입력하는 약속으로 연습합니다. 어떤 순서로 무엇을 넣을지도 프로그램의 사용 방법에 포함됩니다."],"code":{"source":"first_text = input()\nsecond_text = input()\nfirst = int(first_text)\nsecond = int(second_text)\ntotal = first + second\nprint(total)","kind":"python","output":"13","error":null,"input":"8\n5\n","caption":"첫 줄에는 8, 둘째 줄에는 5를 입력합니다. 각각의 input이 한 줄씩 읽습니다."}},{"title":"입력의 의미에 맞는 변환을 선택합니다.","body":["개수처럼 정수로 다룰 값에는 int를 쓰고, 1.5처럼 소수 부분이 필요한 길이에는 float를 쓸 수 있습니다. 아래 코드는 입력한 길이의 두 배를 계산하므로 float로 변환합니다. 변환을 생략하거나 소수 부분을 버리면 의도한 계산과 달라질 수 있습니다.","이 레슨의 입력은 문제에서 정한 숫자 형식에 맞는다고 가정합니다. 예를 들어 float로 바꿀 입력은 1.5처럼 적고, 1.5m처럼 단위 글자를 함께 넣지 않습니다. 숫자로 읽을 수 없는 글자나 빈 줄은 변환할 때 ValueError를 낼 수 있습니다. 입력을 다시 요청하거나 오류를 처리하는 방법은 뒤 챕터에서 배우고, 지금은 어떤 값과 형식을 기대하는지 먼저 확인합니다."],"code":{"source":"length_text = input()\nlength = float(length_text)\ndoubled = length * 2\nprint(doubled)","kind":"python","output":"3.0","error":null,"input":"1.5\n","caption":"1.5를 입력합니다. float로 계산한 결과 3.0은 수로는 3과 같지만 실수 값의 출력입니다."}}],"worked":{"question":"공책 한 권의 가격과 권수를 두 줄로 입력받아 총금액을 출력해 봅시다. 첫 줄은 가격 1200, 둘째 줄은 권수 3입니다. 두 값은 단위 글자나 쉼표 없는 정수로 입력합니다.","code":{"source":"price_text = input()\ncount_text = input()\nprice = int(price_text)\ncount = int(count_text)\ntotal = price * count\nprint(total)","kind":"python","output":"3600","error":null,"input":"1200\n3\n","caption":"1200을 입력하고 Enter, 이어서 3을 입력하고 Enter를 누릅니다. 결과로 3600이 출력됩니다."},"steps":["첫 번째 input은 문자열 \"1200\"을, 두 번째 input은 문자열 \"3\"을 읽습니다. 아직 두 값 모두 문자열입니다.","int로 각각 변환하여 price는 정수 1200, count는 정수 3에 연결합니다. 계산에 쓰기 전에 필요한 종류의 값으로 바꾼 것입니다.","price * count로 3600을 계산하고 그 값에 total이라는 이름을 연결합니다. print(total)이 화면에 총금액을 보여 줍니다.","같은 파일을 다시 실행하여 가격과 권수를 새로 입력하면 그 입력으로 다시 계산합니다. 코드를 고치지 않아도 입력이 달라지면 결과가 달라질 수 있습니다."],"answer":"입력은 1200과 3 두 줄이고, 프로그램의 출력은 3600 한 줄입니다. 읽기 → 변환 → 계산 → 출력의 각 단계가 서로 다른 역할을 합니다."},"misconception":{"question":"입력할 때 따옴표 없이 25를 적었으니 input도 숫자 25를 돌려주나요?","answer":"아닙니다. 코드에 적은 숫자 리터럴과 실행 중 입력한 글자는 읽는 방식이 다릅니다. input()은 25라는 글자를 문자열 \"25\"로 돌려줍니다. 정수 덧셈을 하려면 int로 변환해야 합니다. print로 보이는 모양이 같아도 문자열과 숫자는 서로 다른 값의 종류입니다."},"keypoints":["input()은 실행 중 한 줄을 읽어, 줄 끝의 줄바꿈을 뺀 문자열을 돌려줍니다.","계산할 입력은 목적에 맞게 int 또는 float로 변환한 다음 사용합니다.","입력 순서와 형식을 정하고, 읽기 → 변환 → 계산 → 출력 순서로 결과를 확인합니다."],"examples":[{"question":"아래 파일을 실행하고 25를 입력한 뒤 Enter를 누르세요. 먼저 출력 두 줄을 예상하고, text의 값 종류와 마지막 줄이 덧셈 결과가 아닌 이유를 설명해 보세요.","code":"text = input()\nprint(type(text))\nprint(text + \"0\")","codeKind":"python","codeLabel":"입력값의 종류를 확인할 코드","skill":"입력 문자열의 의미","solution":{"answer":"예시 답: 첫 줄에는 <class 'str'>, 둘째 줄에는 250이 출력됩니다. text는 문자열 \"25\"이고 \"0\"도 문자열이므로 두 글자 묶음을 이어 붙입니다.","code":{"source":"text = input()\nprint(type(text))\nprint(text + \"0\")","kind":"python","output":"<class 'str'>\n250","error":null,"input":"25\n","caption":"type으로 값 종류를 확인하면 출력 모양만 보고 숫자로 오해하는 일을 줄일 수 있습니다."}},"explanation":"input은 숫자 모양의 입력도 문자열로 읽습니다. 문자열끼리의 +는 글자를 이어 붙이므로 정수 25에 0을 더한 것과 다릅니다."},{"question":"하루 공부 시간(분)과 공부할 일수를 각각 정수로 입력받아 총 공부 시간을 분 단위로 출력하는 프로그램을 작성하세요. 첫 줄에는 20, 둘째 줄에는 3을 입력해 결과를 확인하세요.","skill":"두 정수 입력의 계산","solution":{"answer":"예시 답: 두 입력을 int로 바꾸고 곱하면 60이 출력됩니다. 변수 이름이나 변환을 나누어 쓰는 방식은 달라도 됩니다.","code":{"source":"minutes_per_day = int(input())\ndays = int(input())\ntotal_minutes = minutes_per_day * days\nprint(total_minutes)","kind":"python","output":"60","error":null,"input":"20\n3\n","caption":"20과 3을 서로 다른 줄로 입력하는 한 가지 풀이입니다."}},"explanation":"input을 두 번 호출하므로 두 줄이 필요합니다. 먼저 각 문자열을 정수로 바꾸면 *가 공부 시간과 일수를 수로 곱하는 계산이 됩니다."},{"question":"아래 코드는 입력한 개수에 1을 더하려 하지만 4를 입력하면 TypeError가 납니다. 입력을 정수로 바꾸도록 수정한 뒤, 4를 넣었을 때 5가 출력되는지 확인하세요.","code":"count = input()\nnext_count = count + 1\nprint(next_count)","codeKind":"python","codeLabel":"숫자 변환이 빠진 코드","skill":"입력 변환 누락 수정","solution":{"answer":"예시 답: 첫 줄을 count = int(input())으로 바꿀 수 있습니다. 그러면 정수 4에 정수 1을 더해 5를 출력합니다.","code":{"source":"count = int(input())\nnext_count = count + 1\nprint(next_count)","kind":"python","output":"5","error":null,"input":"4\n","caption":"입력 후 계산 전에 정수로 변환한 수정 예시입니다."}},"explanation":"원래 코드의 count는 문자열이어서 정수 1과 바로 더할 수 없습니다. 1을 문자열 \"1\"로 바꾸면 41이 되므로, 개수를 하나 늘리려는 목표에는 입력값을 숫자로 바꾸는 편이 맞습니다."},{"question":"리본의 길이를 미터 단위로 입력받아 절반 길이를 출력하는 프로그램을 작성하세요. 소수 부분을 유지해야 하며, 실행할 때 단위 글자 없이 3.5를 입력하세요.","skill":"소수 입력에 맞는 변환","solution":{"answer":"예시 답: 입력을 float로 바꾸고 2로 나누면 1.75가 출력됩니다.","code":{"source":"length = float(input())\nhalf = length / 2\nprint(half)","kind":"python","output":"1.75","error":null,"input":"3.5\n","caption":"3.5미터의 절반을 계산하는 예시이며 입력에는 숫자만 적습니다."}},"explanation":"문자열 \"3.5\"는 소수 형태이므로 float로 읽어 소수 부분을 유지합니다. int(\"3.5\")는 소수 문자열을 정수로 바로 바꾸지 못해 ValueError가 납니다."},{"question":"남은 좌석 수를 정수로 입력받고, 4명이 모두 앉을 수 있는지를 True 또는 False로 출력하는 프로그램을 작성하세요. 한 번은 4, 다시 실행해서는 3을 입력하고 결과를 비교하세요.","skill":"입력값과 비교 결과 연결","solution":{"answer":"예시 답: 좌석 수가 4 이상인지 비교하여 출력합니다. 4를 입력하면 True, 파일을 다시 실행해 3을 입력하면 False가 나옵니다.","code":{"source":"seats = int(input())\nenough = seats >= 4\nprint(enough)","kind":"python","output":"True","error":null,"input":"4\n","caption":"좌석 수 4로 실행한 예시입니다. 3으로 확인할 때는 파일을 새로 실행합니다."}},"explanation":"입력을 정수로 바꾸면 좌석 수를 숫자로 비교할 수 있습니다. >=는 같은 값도 포함하므로 딱 4석일 때도 True입니다. 조건문 없이 비교 결과인 불리언 자체를 print로 보여 줄 수 있습니다."}]}],"review":[{"question":"아래 코드의 마지막 두 줄이 출력할 값을 순서대로 적은 뒤 실행하세요. original을 다시 대입한 것이 saved에도 영향을 주는지, 두 이름이 가리키는 값으로 설명해 보세요.","code":"original = 8\nsaved = original\noriginal = 11\nprint(original)\nprint(saved)","codeKind":"python","skill":"값과 이름 · 재대입 뒤의 값","solution":{"answer":"예시 답: 11 다음 줄에 8이 출력됩니다. saved는 대입 당시의 값 8에 연결되었고, original만 나중에 11로 바뀝니다.","code":{"source":"original = 8\nsaved = original\noriginal = 11\nprint(original)\nprint(saved)","kind":"python","output":"11\n8","error":null}},"explanation":"saved = original은 두 이름을 영구히 묶는 규칙이 아닙니다. 그 줄을 실행할 때 original이 가리키던 값을 saved에도 연결합니다. 이후 original의 재대입은 saved의 연결을 바꾸지 않습니다.","related":["python-l006"]},{"question":"공책 한 권의 가격이 900일 때 아래 코드를 읽고 total과 count의 최종 값을 예상하세요. 실행 후, count를 3으로 바꿨는데 total이 자동으로 2700이 되지 않는 이유를 적어 보세요.","code":"unit_price = 900\ncount = 2\ntotal = unit_price * count\ncount = 3\nprint(total)\nprint(count)","codeKind":"python","skill":"값과 이름 · 계산한 값의 연결","solution":{"answer":"예시 답: total은 1800, count는 3입니다. total에 연결된 것은 당시 계산한 값 1800이므로, count를 바꾼 것만으로 다시 계산되지는 않습니다.","code":{"source":"unit_price = 900\ncount = 2\ntotal = unit_price * count\ncount = 3\nprint(total)\nprint(count)","kind":"python","output":"1800\n3","error":null}},"explanation":"대입은 오른쪽 식을 그 순간의 값으로 계산한 뒤 결과를 이름에 연결합니다. 나중에 count가 달라졌다면 total = unit_price * count를 다시 실행해야 새 개수로 계산한 값이 연결됩니다.","related":["python-l006","python-l007"]},{"question":"아래 코드는 score를 7에서 10으로 바꾸려는 의도입니다. 실제 출력을 먼저 예상하고, 잘못 쓴 한 줄을 고쳐 10이 출력되게 하세요. =와 ==의 역할 차이도 설명해 보세요.","code":"score = 7\nscore == 10\nprint(score)","codeKind":"python","codeLabel":"대입과 비교를 확인할 코드","skill":"값과 이름 · 대입과 비교 구분","solution":{"answer":"예시 답: 원래 코드는 7을 출력합니다. 두 번째 줄을 score = 10으로 바꾸면 score가 10에 연결되어 10을 출력합니다.","code":{"source":"score = 7\nscore = 10\nprint(score)","kind":"python","output":"10","error":null,"caption":"값을 바꾸려는 의도에 맞게 대입으로 수정한 예시입니다."}},"explanation":"==는 양쪽 값이 같은지 비교할 뿐 왼쪽 이름의 값을 바꾸지 않습니다. 원래 두 번째 줄의 비교 결과는 False이지만 저장하거나 print하지 않았으므로 파일 실행 화면에는 나타나지 않습니다.","related":["python-l006","python-l009"]},{"question":"아래 두 출력값을 먼저 계산하고 실행해 확인하세요. 가격 3인 물건과 가격 5인 물건을 한 개씩 묶어 같은 묶음 4개를 산다면, 어느 식이 총금액을 나타내는지 이유를 적으세요.","code":"print(3 + 5 * 4)\nprint((3 + 5) * 4)","codeKind":"python","skill":"연산 예측 · 괄호와 계산 순서","solution":{"answer":"예시 답: 첫 줄은 23, 둘째 줄은 32입니다. 묶음 하나의 가격 3 + 5를 먼저 계산해야 하므로 둘째 식이 요구한 총금액입니다.","code":{"source":"print(3 + 5 * 4)\nprint((3 + 5) * 4)","kind":"python","output":"23\n32","error":null}},"explanation":"괄호가 없으면 곱셈 5 * 4가 덧셈보다 먼저 계산됩니다. (3 + 5)는 한 묶음의 가격을 먼저 구하라는 뜻을 코드에 분명히 나타냅니다.","related":["python-l007"]},{"question":"공 27개를 상자당 6개씩 담습니다. 아래 세 출력값을 예상하고, 그중 가득 채울 수 있는 상자 수와 남는 공 수를 나타내는 값이 무엇인지 설명하세요. 코드를 실행해 확인해 보세요.","code":"balls = 27\ncapacity = 6\nprint(balls / capacity)\nprint(balls // capacity)\nprint(balls % capacity)","codeKind":"python","skill":"연산 예측 · 나눗셈과 몫과 나머지","solution":{"answer":"예시 답: 차례로 4.5, 4, 3이 출력됩니다. 가득 채운 상자는 4개이고 남는 공은 3개입니다.","code":{"source":"balls = 27\ncapacity = 6\nprint(balls / capacity)\nprint(balls // capacity)\nprint(balls % capacity)","kind":"python","output":"4.5\n4\n3","error":null}},"explanation":"/는 이 나눗셈의 실수 결과를 구합니다. 양의 정수인 이 사례에서 //는 가득 묶을 수 있는 개수를, %는 묶은 뒤 남는 개수를 나타냅니다. 27 = 6 * 4 + 3으로도 확인할 수 있습니다.","related":["python-l006","python-l007"]},{"question":"야외 학습은 기온이 18 이상 26 이하이고 비가 오지 않을 때 가능하다고 정했습니다. 아래 두 줄의 출력을 예상한 뒤 실행하세요. 첫 번째 식에서 기온 26이 범위에 포함되는 이유도 설명하세요.","code":"temperature = 26\nraining = False\nprint(temperature >= 18 and temperature <= 26 and not raining)\nprint(temperature == 25 or raining)","codeKind":"python","skill":"연산 예측 · 비교와 불리언 연결","solution":{"answer":"예시 답: 첫 줄은 True, 둘째 줄은 False입니다. 26은 18 이상이면서 26 이하이고, raining이 False이므로 not raining은 True입니다.","code":{"source":"temperature = 26\nraining = False\nprint(temperature >= 18 and temperature <= 26 and not raining)\nprint(temperature == 25 or raining)","kind":"python","output":"True\nFalse","error":null}},"explanation":">=와 <=는 경계값이 같은 경우도 포함합니다. 첫 줄의 and로 묶인 불리언 세 값은 모두 True입니다. 둘째 줄은 26 == 25와 raining이 모두 False라서 or의 결과도 False입니다.","related":["python-l009"]},{"question":"아래 코드는 문자열로 적힌 컵 개수 \"8\"에 2개를 더하려 합니다. 실행했을 때의 오류 종류를 확인하고, 숫자 덧셈 결과 10이 나오도록 고치세요. 글자 82가 나오게 바꾸는 것은 목표가 아닙니다.","code":"cups = \"8\"\nprint(cups + 2)","codeKind":"python","codeLabel":"값의 종류가 맞지 않는 코드","skill":"변환 오류 · 문자열과 숫자의 덧셈","solution":{"answer":"예시 답: 원본은 TypeError가 납니다. cups를 int로 바꾸어 정수끼리 더하면 10이 출력됩니다.","code":{"source":"cups = \"8\"\nprint(int(cups) + 2)","kind":"python","output":"10","error":null,"caption":"컵 개수를 정수로 바꾼 뒤 계산하는 수정 예시입니다."}},"explanation":"문자열과 정수는 +로 바로 더할 수 없습니다. int(\"8\")은 정수 8을 만들고, 그때부터 + 2가 숫자 덧셈이 됩니다. 변환은 어떤 의미의 계산을 원하는지에 맞게 선택합니다.","related":["python-l007","python-l008"]},{"question":"높이 2.5를 두 배로 계산하려는 아래 코드에서 오류가 나는 줄과 오류 종류를 확인하세요. 소수 부분을 유지하면서 5.0을 출력하도록 변환을 고쳐 보세요.","code":"height_text = \"2.5\"\nheight = int(height_text)\nprint(height * 2)","codeKind":"python","codeLabel":"소수 문자열의 변환을 고칠 코드","skill":"변환 오류 · 정수와 실수 변환 선택","solution":{"answer":"예시 답: 두 번째 줄의 int(height_text)에서 ValueError가 납니다. float(height_text)로 바꾸면 2.5의 소수 부분을 유지하여 5.0을 출력합니다.","code":{"source":"height_text = \"2.5\"\nheight = float(height_text)\nprint(height * 2)","kind":"python","output":"5.0","error":null,"caption":"소수 형태의 문자열을 float로 변환한 수정 예시입니다."}},"explanation":"int는 \"2.5\"처럼 소수점이 있는 문자열을 정수 형식으로 바로 읽지 못합니다. 먼저 float로 바꾼 뒤 다시 int를 적용하면 소수 부분을 버리므로, 이 문제에서는 float 값을 그대로 계산에 씁니다.","related":["python-l007","python-l008"]},{"question":"낸 돈, 물건 한 개의 가격, 살 개수를 이 순서로 세 줄 입력받아 거스름돈을 출력하는 프로그램을 작성하세요. 모두 정수이며 낸 돈은 총금액 이상입니다. 10000, 1200, 3을 따옴표나 쉼표 없이 각각 한 줄씩 입력해 결과를 확인하세요.","skill":"입출력 적용 · 여러 입력의 계산 연결","solution":{"answer":"예시 답: 세 입력을 각각 int로 바꾸고, 낸 돈에서 가격과 개수를 곱한 값을 뺍니다. 주어진 입력에서는 6400이 출력됩니다.","code":{"source":"paid = int(input())\nprice = int(input())\ncount = int(input())\nchange = paid - price * count\nprint(change)","kind":"python","output":"6400","error":null,"input":"10000\n1200\n3\n","caption":"첫 줄은 낸 돈, 둘째 줄은 가격, 셋째 줄은 개수입니다."}},"explanation":"input을 적은 순서와 값을 넣는 순서가 맞아야 각 이름이 의도한 수에 연결됩니다. 가격 1200과 개수 3을 먼저 곱한 뒤 10000에서 빼므로 6400이 남습니다.","related":["python-l006","python-l007","python-l008","python-l010"]},{"question":"직사각형의 가로와 세로를 미터 단위로 두 줄 입력받으세요. 소수 입력을 허용하며 먼저 넓이를 출력하고, 다음 줄에는 넓이가 6.0제곱미터 이상인지 True 또는 False로 출력하는 프로그램을 작성하세요. 첫 줄 3.5, 둘째 줄 2를 입력해 확인하세요.","skill":"입출력 적용 · 실수 계산과 불리언 출력","solution":{"answer":"예시 답: 가로와 세로를 float로 바꾸어 곱하면 7.0입니다. 이 값은 6.0 이상이므로 다음 줄에는 True가 출력됩니다.","code":{"source":"width = float(input())\nheight = float(input())\narea = width * height\nprint(area)\nprint(area >= 6.0)","kind":"python","output":"7.0\nTrue","error":null,"input":"3.5\n2\n","caption":"2도 float로 변환하므로 2.0으로 계산에 참여합니다."}},"explanation":"읽은 문자열을 float로 바꾸면 소수 부분을 유지한 채 넓이를 계산할 수 있습니다. area >= 6.0은 값을 바꾸는 대입이 아니라 비교이며, 그 결과인 불리언을 별도의 줄에 출력합니다.","related":["python-l007","python-l008","python-l009","python-l010"]}]},{"id":"python-ch03","slug":"ch03","number":3,"title":"문자열을 다루는 기본 도구","description":"문자의 위치와 범위를 읽고, 문자열을 정리하고 나누고 합쳐 읽기 좋은 결과를 만듭니다.","prerequisite":"선행 학습: 챕터 2 · 값·이름·연산","runtime":"Python 3","testedVersion":"3.12.14","lessons":[{"id":"python-l011","order":1,"title":"인덱스와 음수 인덱스","subtitle":"문자열의 길이와 위치를 구분하면 앞에서도 뒤에서도 필요한 문자를 찾을 수 있습니다.","minutes":11,"goal":"문자열의 길이를 확인하고, 같은 문자의 위치를 0부터 세는 인덱스와 음수 인덱스로 나타내며 유효한 범위를 설명한다.","intro":"앞 챕터에서는 문자열 전체를 출력하거나 숫자로 바꾸었습니다. 그런데 상품 번호의 맨 앞 글자나 파일 이름의 마지막 글자처럼 일부만 읽고 싶을 때도 있습니다. 문자열 안에서 각 문자가 놓인 위치에 번호를 붙이면 전체를 다시 쓰지 않고 필요한 한 문자를 찾을 수 있습니다.","sections":[{"title":"위치 번호는 0에서 시작합니다.","body":["문자열은 문자들이 순서대로 이어진 값입니다. 각 위치를 가리키는 정수 번호를 인덱스라고 합니다. word[0]처럼 문자열 뒤의 대괄호 안에 인덱스를 쓰면 그 위치의 한 문자를 읽습니다. 첫 위치는 1이 아니라 0이며, 다음 위치가 1입니다.","word가 \"PYTHON\"이면 P, Y, T, H, O, N의 인덱스는 차례로 0, 1, 2, 3, 4, 5입니다. 인덱스 2는 세 번째 문자 T를 뜻합니다. 인덱스를 첫 위치에서 얼마나 떨어졌는지로 읽으면 0부터 시작하는 이유를 이해하기 쉽습니다.","한 문자를 읽어도 결과의 타입은 str입니다. Python은 이 경우에 별도의 한 글자 타입을 만들지 않습니다. 대괄호는 위치를 읽는 표시이고, print의 괄호는 전달한 값을 출력하는 호출이라는 차이도 살펴보세요."],"code":{"source":"word = \"PYTHON\"\nprint(word[0])\nprint(word[2])\nprint(type(word[2]))","kind":"python","output":"P\nT\n<class 'str'>","error":null,"caption":"위치 번호 2와 세 번째 문자는 같은 위치를 가리킵니다."}},{"title":"길이와 마지막 위치는 1만큼 다릅니다.","body":["len(word)는 문자열의 길이를 정수로 알려 줍니다. \"PYTHON\"의 길이는 6이지만 0부터 세는 마지막 인덱스는 5입니다. 비어 있지 않은 문자열에서 마지막 위치는 len(word) - 1로 구합니다.","공백도 문자열에 들어 있는 문자이므로 길이와 위치에 포함됩니다. \"A B\"의 길이는 3이고 인덱스 1에는 공백이 있습니다. 공백을 읽어 출력하면 눈으로 구분하기 어려워서 아래에서는 양쪽에 대괄호 문자를 붙여 보여 줍니다.","정확히 말하면 Python 문자열의 길이와 인덱스는 유니코드 코드 포인트라는 문자 단위를 셉니다. 이 레슨의 영문과 미리 조합된 한글은 눈에 보이는 한 글자와 한 단위가 대응합니다. 일부 이모지나 조합 문자는 여러 단위로 표현될 수 있으므로 len이 언제나 화면에 보이는 글자 수나 폭을 뜻한다고 생각하지는 마세요."],"code":{"source":"word = \"PYTHON\"\nprint(len(word))\nprint(word[len(word) - 1])\ntext = \"A B\"\nprint(len(text))\nprint(\"[\" + text[1] + \"]\")","kind":"python","output":"6\nN\n3\n[ ]","error":null,"caption":"길이는 개수이고, 인덱스는 0부터 시작하는 위치 번호입니다."}},{"title":"뒤에서는 -1부터 셉니다.","body":["문자열의 끝을 기준으로 읽고 싶으면 음수 인덱스를 사용합니다. -1은 마지막 문자, -2는 뒤에서 두 번째 문자입니다. 문자열 길이를 미리 숫자로 적지 않아도 끝의 위치를 표현할 수 있습니다.","길이가 6인 \"PYTHON\"에서 -1은 5, -2는 4와 같은 위치입니다. 일반적으로 길이 n인 문자열에서 유효한 음수 인덱스 i는 n + i 위치를 가리킵니다. 따라서 -6은 0과 같아서 첫 문자 P를 읽습니다.","-0은 정수 0과 같은 값이므로 마지막 위치를 나타내는 새로운 번호가 아닙니다. 음수 인덱스의 시작은 -1이라는 점을 기억하세요. 문자열 길이가 바뀌어도 마지막 문자를 읽겠다는 의도를 표현할 때 -1이 편리합니다."],"code":{"source":"word = \"PYTHON\"\nprint(word[-1])\nprint(word[-2])\nprint(word[-6])\nprint(word[-0])","kind":"python","output":"N\nO\nP\nP","error":null,"caption":"양수와 음수 인덱스는 같은 문자열의 위치를 앞과 뒤에서 나타내는 두 방법입니다."}},{"title":"없는 위치를 읽으면 IndexError가 납니다.","body":["길이가 n인 비어 있지 않은 문자열에서 0부터 세는 유효한 인덱스는 0부터 n - 1까지, 음수 인덱스는 -n부터 -1까지입니다. 이 범위를 벗어나면 IndexError가 납니다. 없는 문자를 빈 문자열로 대신 주거나 첫 문자부터 다시 돌아서 읽지 않습니다.","아래 문자열의 길이는 3이므로 인덱스 3은 없습니다. 마지막 문자를 읽으려면 2 또는 -1을 사용해야 합니다. 오류 때문에 실행이 멈추면 앞에서 배운 것처럼 오류 종류와 해당 줄을 읽고 요구한 위치를 다시 확인합니다.","빈 문자열 \"\"의 길이는 0이며 읽을 문자가 하나도 없습니다. 따라서 빈 문자열에서는 [0]도 [-1]도 IndexError입니다. -1이 언제나 안전한 것은 아닙니다. 이번 실습은 값이 주어진 문자열로 진행하며, 빈 값에 따라 실행을 나누는 방법은 조건문 챕터에서 배웁니다."],"code":{"source":"code = \"A27\"\nprint(len(code))\nprint(code[3])","kind":"python","output":"3","error":"IndexError","caption":"길이 3을 출력한 뒤 없는 인덱스 3에서 멈춥니다. 오류 메시지 전체의 모양은 실행 환경에 따라 다를 수 있습니다."}}],"worked":{"question":"물품 코드 \"BOX-7\"의 첫 문자와 마지막 문자를 연결해 \"B7\"을 만들고 싶습니다. 어느 위치를 읽어야 할까요?","code":{"source":"code = \"BOX-7\"\nfirst = code[0]\nlast = code[-1]\nlabel = first + last\nprint(len(code))\nprint(label)\nprint(code)","kind":"python","output":"5\nB7\nBOX-7","error":null,"caption":"문자를 읽고 새 문자열을 연결해도 원래 code의 내용은 그대로입니다."},"steps":["code의 길이는 5이고 앞에서 센 위치는 0부터 4까지입니다. code[0]은 첫 문자 B를 읽습니다.","code[-1]은 마지막 문자 7을 읽습니다. code[4] 또는 code[len(code) - 1]도 같은 위치를 읽습니다.","두 결과는 각각 길이 1인 문자열이므로 +로 연결하면 B7이 됩니다. code에는 다시 대입하지 않았으므로 원래 문자열 BOX-7이 그대로 남습니다."],"answer":"첫 위치 0과 마지막 위치 -1을 읽어 연결하면 B7을 얻습니다. 인덱스로 읽은 7은 정수 7이 아니라 문자열 \"7\"입니다."},"misconception":{"question":"문자열 길이가 6이면 word[6]이 마지막 문자인가요?","answer":"아닙니다. 길이는 문자의 개수이고 인덱스는 0부터 시작합니다. 여섯 문자의 위치는 0부터 5까지이므로 word[5]나 word[-1]이 마지막 문자입니다. word[6]은 없는 위치라 IndexError가 납니다. 빈 문자열은 길이가 0이므로 마지막 문자 자체가 없습니다."},"keypoints":["문자열[인덱스]는 한 위치의 문자를 읽으며 결과는 길이 1인 문자열입니다. 첫 인덱스는 0입니다.","길이 n인 비어 있지 않은 문자열의 마지막 위치는 n - 1 또는 -1입니다. 음수 인덱스는 끝에서부터 위치를 나타냅니다.","범위를 벗어난 인덱스는 IndexError를 일으킵니다. 빈 문자열에는 유효한 인덱스가 없으며 공백도 길이에 포함됩니다."],"examples":[{"question":"word = \"LEARN\"을 직접 입력하고 문자열의 길이와 첫 문자를 각각 출력하세요. 길이와 첫 인덱스가 서로 무엇을 나타내는지도 적어 보세요.","skill":"길이와 위치 구분","solution":{"answer":"길이는 5이며 첫 문자는 L입니다. 첫 인덱스는 0입니다.","code":{"source":"word = \"LEARN\"\nprint(len(word))\nprint(word[0])","kind":"python","output":"5\nL","error":null}},"explanation":"len은 문자의 개수를 셉니다. word[0]은 개수를 구하는 것이 아니라 첫 위치의 문자를 읽습니다."},{"question":"아래 세 출력과 각 문자의 앞쪽 인덱스를 먼저 적은 뒤 실행해 비교하세요.","skill":"양수와 음수 위치 대응","solution":{"answer":"차례로 D, E, C가 출력됩니다. 앞쪽 인덱스는 각각 2, 3, 0입니다.","code":{"source":"word = \"CODE\"\nprint(word[2])\nprint(word[-1])\nprint(word[-4])","kind":"python","output":"D\nE\nC","error":null}},"explanation":"길이가 4이므로 -1은 4 - 1인 3, -4는 4 - 4인 0 위치를 읽습니다. 두 번호 체계는 같은 네 문자 안의 위치를 가리킵니다.","code":"word = \"CODE\"\nprint(word[2])\nprint(word[-1])\nprint(word[-4])","codeKind":"python"},{"question":"아래 파일을 실행해 오류 종류를 확인하세요. 마지막 문자 Z를 출력하도록 대괄호 안을 고치고, len(tag)가 마지막 인덱스가 아닌 이유를 설명하세요.","skill":"범위 밖 인덱스 수정","solution":{"answer":"원래 코드는 IndexError가 납니다. len(tag) - 1을 사용하면 마지막 문자 Z를 출력합니다. -1도 가능합니다.","code":{"source":"tag = \"ABZ\"\nprint(tag[len(tag) - 1])","kind":"python","output":"Z","error":null}},"explanation":"길이는 3이지만 위치 번호는 0, 1, 2입니다. 개수를 그대로 위치로 사용하면 마지막 문자 다음의 없는 위치를 요구하게 됩니다.","code":"tag = \"ABZ\"\nprint(tag[len(tag)])","codeKind":"python"},{"question":"text = \"가 나\"에서 가운데 공백만 읽어 대괄호 문자 사이에 출력하세요. 결과가 [ ]가 되는지 확인하고, len(text)도 출력하세요.","skill":"공백도 포함하는 위치","solution":{"answer":"가운데 공백은 인덱스 1에 있습니다. 출력은 [ ]와 3입니다.","code":{"source":"text = \"가 나\"\nprint(\"[\" + text[1] + \"]\")\nprint(len(text))","kind":"python","output":"[ ]\n3","error":null}},"explanation":"이 문자열은 가, 공백, 나의 세 단위로 이루어져 있습니다. 공백을 읽은 결과도 문자열이므로 양쪽 표시와 연결해 눈으로 확인할 수 있습니다."},{"question":"아래 코드를 먼저 실행한 뒤 text를 빈 문자열 \"\"로 바꾸어 별도로 다시 실행하세요. 두 실행의 출력과 오류를 비교하고, -1이 항상 안전한 위치인지 설명하세요.","skill":"빈 문자열의 경계","solution":{"answer":"원래 코드는 길이 1과 문자 Q를 출력합니다. 빈 문자열로 바꾸면 0을 출력한 뒤 IndexError가 납니다.","code":{"source":"text = \"\"\nprint(len(text))\nprint(text[-1])","kind":"python","output":"0","error":"IndexError"}},"explanation":"음수 인덱스는 실제로 있는 문자만 뒤에서 셉니다. 빈 문자열에는 마지막 문자가 없으므로 -1도 읽을 수 없습니다. 예시 코드는 요구한 두 번째 실행입니다.","code":"text = \"Q\"\nprint(len(text))\nprint(text[-1])","codeKind":"python"}]},{"id":"python-l012","order":2,"title":"슬라이싱과 범위","subtitle":"한 위치 대신 시작과 끝의 경계를 정해 문자열의 필요한 부분을 읽습니다.","minutes":13,"goal":"슬라이싱의 시작·끝·간격과 생략한 경계를 읽고, 선택되는 위치와 결과를 인덱스 접근과 구분해 설명한다.","intro":"이전 레슨에서는 인덱스로 한 문자를 읽었습니다. 날짜에서 연도 부분을 얻거나 코드의 앞쪽 세 글자를 읽으려면 여러 문자를 한꺼번에 선택하는 방법이 필요합니다. 슬라이싱은 어디서 시작하고 어디에서 멈출지 정해 문자열의 부분을 읽는 연산입니다.","sections":[{"title":"시작 위치는 포함하고 끝 위치는 제외합니다.","body":["text[start:stop]처럼 대괄호 안에 콜론을 넣으면 슬라이싱입니다. start 위치에서 시작하여 stop 위치에 도착하기 전까지의 문자를 선택합니다. 간격을 따로 적지 않으면 인덱스가 1씩 커지는 방향으로 읽습니다.","text가 \"PYTHON\"일 때 text[1:4]는 인덱스 1, 2, 3의 Y, T, H를 선택해 \"YTH\"를 만듭니다. 인덱스 4의 O는 포함하지 않습니다. 끝값을 제외하므로 text[0:3] 다음에 text[3:6]을 붙이면 경계의 문자를 겹치거나 빠뜨리지 않고 전체를 나눌 수 있습니다.","시작과 끝을 0 이상인 위치로 나타내고 두 경계가 0부터 문자열 길이 사이에 있을 때, 간격이 1이고 시작이 끝보다 작다면 선택한 길이는 stop - start입니다. 음수 경계는 앞에서 세는 위치로 바꾸어 생각합니다. 문자 하나를 읽는 text[1]과 달리 슬라이싱은 길이 0 이상인 부분 문자열을 얻습니다. 콜론이 있는지 살펴보면 두 연산을 구별할 수 있습니다."],"code":{"source":"text = \"PYTHON\"\nprint(text[1:4])\nprint(text[0:3])\nprint(text[3:6])","kind":"python","output":"YTH\nPYT\nHON","error":null,"caption":"1:4는 위치 1부터 4까지가 아니라, 위치 4에 도착하기 전까지입니다."}},{"title":"경계를 생략하거나 음수로 나타낼 수 있습니다.","body":["간격이 양수일 때 시작을 생략하면 문자열의 처음, 끝을 생략하면 문자열의 끝까지 선택합니다. text[:3]은 앞의 세 문자, text[3:]은 인덱스 3부터 마지막 문자까지입니다. text[:]는 전체 문자열과 같은 내용의 결과를 얻습니다.","음수 경계도 앞 레슨의 위치 기준을 사용합니다. text[-3:]은 뒤에서 세 번째 위치부터 끝까지, text[:-1]은 마지막 문자 위치 직전까지 선택합니다. 음수 경계라고 자동으로 뒤집어 읽지는 않으며 간격을 생략하면 여전히 앞에서 뒤로 읽습니다.","슬라이싱은 원래 문자열의 일부를 지우는 명령이 아닙니다. 결과를 다른 이름에 연결하면 원래 문자열과 나눈 결과를 함께 사용할 수 있습니다. 문자열이 불변이라는 성질은 다음 레슨에서 더 자세히 살펴봅니다."],"code":{"source":"date = \"2026-11-09\"\nyear = date[:4]\nmonth = date[5:7]\nday = date[-2:]\nprint(year)\nprint(month)\nprint(day)\nprint(date)","kind":"python","output":"2026\n11\n09\n2026-11-09","error":null,"caption":"날짜의 구분 기호도 인덱스에 포함됩니다. 원본의 정해진 위치를 기준으로 부분을 읽습니다."}},{"title":"간격의 크기는 이동할 칸 수, 부호는 방향입니다.","body":["text[start:stop:step]의 세 번째 값은 인덱스를 얼마나 바꾸며 읽을지 정하는 간격입니다. step이 2면 시작에서 2칸씩 앞으로 갑니다. \"ABCDEF\"의 [0:6:2]는 인덱스 0, 2, 4를 선택해 \"ACE\"가 됩니다. 끝 위치는 이때도 제외합니다.","step이 음수이면 인덱스가 줄어드는 방향으로 읽습니다. [4:1:-1]은 4, 3, 2를 선택해 \"EDC\"가 됩니다. 뒤로 읽을 때도 stop 위치에 도착하기 전에 멈추므로 인덱스 1은 포함하지 않습니다.","간격이 음수일 때 생략한 시작은 마지막 문자 쪽이며, 끝을 생략하면 첫 문자까지 읽습니다. 그래서 text[::-1]은 전체를 거꾸로 읽습니다. 여기서 생략한 끝을 숫자 -1로 채우면 같지 않습니다. -1은 마지막 문자의 실제 위치이므로 text[:-1:-1]은 시작 위치에서 이미 멈출 경계를 만나 빈 문자열을 얻습니다.","간격 0은 어느 방향으로도 이동하지 않으므로 허용하지 않으며 ValueError가 납니다. 음수 간격을 처음 읽을 때는 선택되는 인덱스를 하나씩 적어 결과와 비교해 보세요."],"code":{"source":"text = \"ABCDEF\"\nprint(text[0:6:2])\nprint(text[4:1:-1])\nprint(text[::-1])\nprint(\"[\" + text[:-1:-1] + \"]\")","kind":"python","output":"ACE\nEDC\nFEDCBA\n[]","error":null,"caption":"간격의 부호에 따라 생략한 경계가 달라집니다. 생략과 명시한 -1을 같은 뜻으로 바꾸면 안 됩니다."}},{"title":"범위 경계는 잘리지만 없는 한 위치는 읽을 수 없습니다.","body":["슬라이싱의 경계가 문자열 바깥까지 나가면 실제 문자열 범위에 맞추어 선택합니다. \"CAT\"의 [0:20]은 \"CAT\"이고 [20:30]은 빈 문자열입니다. 존재하지 않는 글자를 채우거나 IndexError를 내지 않습니다. 반면 [20]은 한 위치의 문자를 요구하므로 IndexError입니다.","간격이 양수인데 시작이 끝과 같거나 뒤에 있으면 선택할 위치가 없어 빈 문자열을 얻습니다. \"CAT\"의 [2:2]와 [2:1]이 그런 경우입니다. 빈 문자열에 [:]를 적용해도 결과는 빈 문자열입니다. 아래에서는 양쪽에 표시를 붙여 빈 결과를 []로 보여 줍니다.","슬라이싱이 범위 밖 경계를 받아들인다고 모든 잘못된 코드가 허용되는 것은 아닙니다. 간격 0은 여전히 ValueError입니다. 기대보다 짧거나 빈 결과가 나왔다면 시작·끝·방향이 요구한 범위를 가리키는지 확인하세요."],"code":{"source":"text = \"CAT\"\nprint(text[:20])\nprint(\"[\" + text[20:30] + \"]\")\nprint(\"[\" + text[2:1] + \"]\")\nempty = \"\"\nprint(\"[\" + empty[:] + \"]\")","kind":"python","output":"CAT\n[]\n[]\n[]","error":null,"caption":"빈 문자열은 오류와 다릅니다. 선택할 문자가 없다는 결과입니다."}}],"worked":{"question":"고정된 형식의 기록 \"2026-11-09\"에서 \"11/09\"라는 월/일 표시를 만들려면 어떤 범위를 읽어야 할까요?","code":{"source":"record = \"2026-11-09\"\nmonth = record[5:7]\nday = record[8:10]\nlabel = month + \"/\" + day\nprint(label)\nprint(record)","kind":"python","output":"11/09\n2026-11-09","error":null,"caption":"이 예시는 연도 4자리·월 2자리·일 2자리인 고정 형식의 문자열을 전제로 합니다."},"steps":["앞의 연도는 인덱스 0부터 3, 첫 하이픈은 4입니다. 월은 인덱스 5와 6이므로 [5:7]로 선택합니다.","두 번째 하이픈은 인덱스 7입니다. 일은 8과 9이므로 [8:10]으로 선택합니다. 끝 경계 10은 마지막 문자 다음 위치라서 인덱스 9까지 포함합니다.","두 부분 문자열 사이에 /를 연결하여 11/09를 만듭니다. record 자체는 바꾸지 않았습니다. 자릿수가 다른 날짜까지 이 위치로 처리할 수 있다고 가정하지는 않습니다."],"answer":"월은 [5:7], 일은 [8:10]으로 읽어 연결합니다. 고정된 위치를 활용한 풀이이며, 각 범위의 끝은 포함하지 않습니다."},"misconception":{"question":"끝 경계가 마지막 인덱스를 넘으면 슬라이싱도 IndexError가 나나요?","answer":"슬라이싱은 선택 범위를 실제 문자열 경계에 맞추므로 \"CAT\"[:20]은 \"CAT\"입니다. 같은 문자열의 [20]은 없는 한 문자를 요구해서 IndexError가 납니다. 또 슬라이스의 끝 경계는 포함하지 않으므로 [0:3]은 길이 3인 문자열 전체를 읽는 올바른 범위입니다."},"keypoints":["text[start:stop:step]은 시작 위치를 포함하고 끝 위치는 제외합니다. step을 생략하면 1씩 앞으로 읽습니다.","음수 경계는 뒤쪽 위치를 나타내고 음수 간격은 읽는 방향을 뒤집습니다. [::-1]은 전체 역순이며 생략한 경계는 간격의 방향에 따라 정해집니다.","슬라이싱의 경계는 문자열 범위에 맞춰 잘리며 선택할 문자가 없으면 빈 문자열을 얻습니다. 간격 0은 ValueError이고 없는 한 위치의 인덱스 접근은 IndexError입니다."],"examples":[{"question":"아래 결과를 예상하고 선택되는 인덱스를 적으세요. 이어서 코드를 실행한 뒤 끝 경계만 바꾸어 HIJKL이 나오도록 다시 실행하세요.","skill":"끝을 포함하지 않는 범위","solution":{"answer":"원래 출력은 HIJ입니다. 1:6으로 바꾸면 인덱스 1~5를 읽어 HIJKL이 됩니다. 예시 코드는 원래 결과와 변경 결과를 순서대로 보여 줍니다.","code":{"source":"text = \"GHIJKL\"\nprint(text[1:4])\nprint(text[1:6])","kind":"python","output":"HIJ\nHIJKL","error":null}},"explanation":"원래 범위는 1, 2, 3만 선택합니다. 마지막 인덱스 5를 포함하려면 끝 경계를 그 다음인 6으로 둡니다.","code":"text = \"GHIJKL\"\nprint(text[1:4])","codeKind":"python"},{"question":"code = \"ITEM-042\"에서 앞의 ITEM과 뒤의 042를 각각 출력하세요. 처음에는 시작 경계 생략을, 두 번째에는 음수 시작과 끝 경계 생략을 사용하세요.","skill":"생략한 경계와 음수 위치","solution":{"answer":"code[:4]는 ITEM, code[-3:]은 042를 얻습니다.","code":{"source":"code = \"ITEM-042\"\nprint(code[:4])\nprint(code[-3:])","kind":"python","output":"ITEM\n042","error":null}},"explanation":"앞 네 문자는 위치 0~3입니다. -3은 뒤에서 세 번째 문자 0의 위치이므로 끝까지 읽으면 042가 됩니다. 문자열을 숫자로 변환하지 않아 앞의 0도 유지됩니다."},{"question":"아래 세 결과가 빈 문자열인지, 문자들이 있는 문자열인지 먼저 구분하고 실행하세요. 결과가 다른 이유를 경계와 방향으로 설명하세요.","skill":"범위 잘림과 빈 선택","solution":{"answer":"각각 [DOG], [], []가 출력됩니다. 첫 범위만 실제 문자를 포함합니다.","code":{"source":"text = \"DOG\"\nprint(\"[\" + text[:99] + \"]\")\nprint(\"[\" + text[9:] + \"]\")\nprint(\"[\" + text[2:1] + \"]\")","kind":"python","output":"[DOG]\n[]\n[]","error":null}},"explanation":"끝 99는 실제 끝에 맞추어 잘립니다. 시작 9는 문자열 바깥이어서 선택할 문자가 없습니다. 2:1은 기본 간격 +1로 이동하면서 끝 1 전에 읽을 위치가 없으므로 빈 결과입니다.","code":"text = \"DOG\"\nprint(\"[\" + text[:99] + \"]\")\nprint(\"[\" + text[9:] + \"]\")\nprint(\"[\" + text[2:1] + \"]\")","codeKind":"python"},{"question":"text = \"01234567\"에서 짝수 위치의 문자들을 읽어 0246을 출력하고, 전체를 뒤집어 76543210도 출력하세요. 두 슬라이스의 간격을 설명하세요.","skill":"간격과 역방향 적용","solution":{"answer":"text[::2]는 0, 2, 4, 6 위치를 고르고 text[::-1]은 7부터 0까지 역순으로 읽습니다.","code":{"source":"text = \"01234567\"\nprint(text[::2])\nprint(text[::-1])","kind":"python","output":"0246\n76543210","error":null}},"explanation":"간격 2는 선택한 인덱스를 두 칸씩 늘립니다. 간격 -1은 한 칸씩 줄이며, 경계를 모두 생략했으므로 마지막부터 첫 문자까지 선택합니다."},{"question":"아래 파일을 실행해 오류 종류를 확인하세요. 간격 한 곳만 고쳐 EDC가 나오게 하고, 왜 마지막에 B가 포함되지 않는지 설명하세요.","skill":"잘못된 간격과 끝 경계","solution":{"answer":"간격 0은 ValueError를 일으킵니다. -1로 바꾸면 인덱스 4, 3, 2의 EDC가 출력됩니다.","code":{"source":"text = \"ABCDEF\"\nprint(text[4:1:-1])","kind":"python","output":"EDC","error":null}},"explanation":"뒤로 읽어야 하므로 음수 간격이 필요합니다. 끝 경계 1은 음수 방향에서도 제외되므로 인덱스 1의 B는 들어가지 않습니다.","code":"text = \"ABCDEF\"\nprint(text[4:1:0])","codeKind":"python"}]},{"id":"python-l013","order":3,"title":"문자열 메서드와 반환값","subtitle":"문자열에 작업을 요청하고, 돌려받은 값을 다음 작업에 사용합니다.","minutes":13,"goal":"문자열 메서드의 반환값을 출력하거나 이름에 연결하고, 원래 문자열과 새 결과를 구분한다.","intro":"이름 앞뒤의 빈칸을 정리하거나 영문 표기를 통일하려면 글자를 하나씩 다시 적기보다 문자열이 제공하는 도구를 쓰면 편리합니다. 앞에서 배운 변수와 대입을 떠올려 보세요. 작업을 요청했다는 사실과 그 결과를 어느 이름에 연결했는지는 다른 문제입니다. 이번에는 문자열의 도구를 호출하고 결과를 이어 쓰는 흐름을 살펴봅니다.","sections":[{"title":"점과 괄호로 문자열에 작업을 요청합니다.","body":["text.upper()에서 점 앞의 text는 작업할 문자열이고, upper는 사용할 도구의 이름입니다. 이렇게 값에 연결된 도구를 메서드라고 부릅니다. 뒤의 괄호까지 써야 작업을 실행하는 호출이 됩니다. upper는 대문자로 바꿀 수 있는 문자를 대문자로 나타낸 문자열을 돌려줍니다.","작업이 돌려준 값을 반환값이라고 합니다. result = text.upper()는 반환값을 result라는 이름에 연결하고, print(result)는 그 값을 화면에 보여 줍니다. 반환과 출력은 서로 다른 동작이므로 코드 파일에서 text.upper()만 적으면 결과가 화면에 저절로 나오지 않습니다.","대화형 창에서는 식의 결과를 자동으로 보여 주기도 합니다. 여기서는 저장한 코드 파일을 실행하므로, 화면에서 확인할 값은 print에 전달합니다. 메서드를 호출할 때의 괄호와 print를 호출할 때의 괄호를 각각 구분해 읽으세요."],"code":{"source":"text = \"Hello\"\nresult = text.upper()\nprint(result)\nprint(text)","kind":"python","output":"HELLO\nHello","error":null,"caption":"upper가 돌려준 값은 result에 연결되고, text의 문자열은 그대로 남습니다."}},{"title":"strip은 문자열 양 끝의 공백을 정리합니다.","body":["text.strip()은 양 끝에 연속된 공백 문자를 제거한 결과를 돌려줍니다. 여기서 공백 문자에는 일반 빈칸뿐 아니라 탭과 줄바꿈 등도 포함됩니다. 괄호 안을 비우면 이 기본 동작을 사용합니다.","가운데의 빈칸은 그대로 둡니다. \"  서울 역  \"을 strip으로 정리하면 \"서울 역\"이 됩니다. 이름이나 문장의 일부인 안쪽 빈칸까지 지우는 작업과 구분해야 합니다. 출력 앞뒤에 |를 붙이면 보이지 않는 끝 공백이 어디까지 남았는지 비교하기 쉽습니다.","빈 문자열이나 공백만 있는 문자열에도 호출할 수 있습니다. 공백만 있던 문자열의 결과는 빈 문자열이며, 이것도 정상적인 반환값입니다. 이 레슨에서는 strip의 괄호 안에 별도 값을 넣는 방식은 다루지 않습니다."],"code":{"source":"text = \"  서울 역  \"\nclean = text.strip()\nprint(\"|\" + text + \"|\")\nprint(\"|\" + clean + \"|\")\nprint(\"|\" + \"   \".strip() + \"|\")","kind":"python","output":"|  서울 역  |\n|서울 역|\n||","error":null,"caption":"세로선은 공백 위치를 보기 위해 덧붙인 표시입니다. strip의 결과에 포함되는 문자는 아닙니다."}},{"title":"lower·upper·replace는 각각 다른 규칙으로 결과를 만듭니다.","body":["lower()는 소문자로 바꿀 수 있는 문자를 소문자로, upper()는 대문자로 바꿀 수 있는 문자를 대문자로 나타냅니다. 예를 들어 \"PyThOn\"의 lower 결과는 \"python\"입니다. 숫자나 한글처럼 대소문자 구분이 없는 문자는 이 변환으로 달라지지 않습니다.","replace(old, new)는 괄호 안에 바꿀 문자열과 새 문자열을 쉼표로 구분해 받습니다. 이번처럼 두 값만 전달하면 일치하는 부분을 모두 바꾼 결과를 돌려줍니다. \"red-red\".replace(\"red\", \"blue\")는 \"blue-blue\"입니다.","replace는 대소문자를 구별하고, 저절로 단어 경계를 판단하지 않습니다. \"cat catalog\".replace(\"cat\", \"dog\")는 \"dog dogalog\"가 됩니다. 요구가 특정 단어 전체인지, 일치하는 부분 전부인지 먼저 살펴보세요. 해당 부분이 없으면 내용이 같은 문자열이 결과로 나옵니다."],"code":{"source":"label = \"PyThOn 3\"\nprint(label.lower())\nprint(label.upper())\nprint(\"red-red\".replace(\"red\", \"blue\"))\nprint(\"Red-red\".replace(\"red\", \"blue\"))","kind":"python","output":"python 3\nPYTHON 3\nblue-blue\nRed-blue","error":null,"caption":"replace에 전달한 red와 정확히 일치하는 부분만 바뀝니다."}},{"title":"문자열을 바꾸는 대신 반환값을 다시 연결합니다.","body":["문자열은 만들어진 뒤 그 안의 문자를 직접 바꿀 수 없는 값입니다. 이를 불변이라고 합니다. text[0] = \"P\"처럼 한 위치에 새 문자를 대입하면 TypeError가 납니다. 앞 레슨의 인덱스는 문자를 읽는 데 사용할 수 있지만 문자열의 일부를 덮어쓰는 데는 사용할 수 없습니다.","지금 배운 strip·lower·upper·replace도 원래 문자열을 직접 수정하지 않습니다. text.upper()를 호출하고 반환값을 사용하지 않으면 text는 계속 원래 문자열을 가리킵니다. 이후에 새 결과를 쓰고 싶다면 text = text.upper()처럼 다시 대입합니다.","같은 이름에 다시 대입할 수 있다는 사실은 문자열 내부가 변경된다는 뜻이 아닙니다. 오른쪽의 작업 결과를 먼저 구하고, 그 다음 이름을 그 결과에 연결합니다. 다른 이름에 원래 문자열을 연결해 두었다면 그 이름은 원래 값을 계속 가리킵니다.","반환값이 문자열이면 그 결과에 다시 문자열 메서드를 호출할 수 있습니다. raw.strip().lower()는 먼저 strip의 결과를 얻고, 그 결과를 대상으로 lower를 호출한다는 뜻입니다. 처음에는 중간 결과를 이름에 연결해 한 단계씩 확인한 뒤 이어 쓰면 흐름을 읽기 쉽습니다."],"code":{"source":"text = \"draft\"\noriginal = text\ntext = text.upper()\nprint(text)\nprint(original)","kind":"python","output":"DRAFT\ndraft","error":null,"caption":"text의 재대입은 original이 가리키는 원래 문자열을 고치지 않습니다."}}],"worked":{"question":"입력된 표시 이름이 \"  JiHoon  \"입니다. 원본은 보존하고 양 끝의 공백을 정리한 소문자 이름을 만들어 보세요.","code":{"source":"raw_name = \"  JiHoon  \"\ntrimmed = raw_name.strip()\nname = trimmed.lower()\nprint(\"|\" + raw_name + \"|\")\nprint(name)","kind":"python","output":"|  JiHoon  |\njihoon","error":null,"caption":"단계를 나누어 각 작업의 반환값을 다음 이름에 연결합니다."},"steps":["raw_name은 양 끝 공백과 대소문자가 섞인 원본 문자열을 가리킵니다. strip의 반환값 \"JiHoon\"을 trimmed에 연결합니다.","trimmed.lower()는 \"jihoon\"을 돌려주고, 이 결과를 name에 연결합니다. 앞 단계의 결과가 다음 단계의 작업 대상입니다.","raw_name을 다시 대입하지 않았으므로 원래 공백과 글자 모양이 유지됩니다. name에는 정리된 값이 있습니다."],"answer":"원본과 처리 결과를 다른 이름에 연결하면 두 값을 함께 보존할 수 있습니다. 각 메서드의 반환값을 다음 작업에 사용했기 때문에 공백 정리와 소문자 변환이 모두 반영됩니다."},"misconception":{"question":"문자열이 불변이면 text = text.upper()도 할 수 없는 것 아닌가요?","answer":"불변은 문자열 값 내부를 직접 고칠 수 없다는 뜻입니다. 변수 이름에 다른 결과를 다시 연결하는 대입은 가능합니다. text.upper()의 결과를 구한 뒤 text라는 이름을 그 결과에 연결하므로 원래 문자열을 고친 것이 아닙니다. 원래 문자열을 가리키던 다른 이름에는 변화가 없습니다."},"keypoints":["문자열.메서드(...)는 작업을 호출하고 반환값을 돌려줍니다. 결과를 화면에서 보려면 print에 전달하고, 나중에 쓰려면 이름에 연결합니다.","strip은 양 끝 공백, lower·upper는 대소문자, replace는 지정한 부분을 다룹니다. 각 도구가 무엇을 바꾸고 무엇을 유지하는지 구분합니다.","문자열 내부는 직접 수정할 수 없습니다. 반환값을 같은 이름에 다시 대입하거나 다른 이름에 연결해야 처리 결과를 이어 쓸 수 있습니다."],"examples":[{"question":"아래 코드를 파일로 저장해 실행하세요. 출력이 없는 이유를 설명하고, 원래 text는 유지하면서 대문자 결과를 result에 연결해 출력하도록 코드를 추가하세요.","skill":"반환과 화면 출력 구분","solution":{"answer":"원래 파일에는 print가 없어 출력이 없습니다. result에 반환값을 연결한 뒤 출력하면 START, 원래 text를 출력하면 start입니다.","code":{"source":"text = \"start\"\nresult = text.upper()\nprint(result)\nprint(text)","kind":"python","output":"START\nstart","error":null}},"explanation":"upper 호출은 값을 반환하지만 파일 실행 중 화면에 출력하는 명령은 아닙니다. 반환값을 이름에 연결하고 print에 전달하면 이후에도 사용할 수 있습니다.","code":"text = \"start\"\ntext.upper()","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드의 출력을 먼저 예상하고 실행하세요. 공백을 없애려 했는데 왜 그대로인지 설명하고, 마지막 출력이 |책 읽기|가 되도록 한 줄을 고치세요. 단어 사이 공백은 남겨야 합니다.","skill":"사용하지 않은 반환값 수정","solution":{"answer":"원래 출력은 |  책 읽기  |입니다. text = text.strip()으로 바꾸면 양 끝 공백만 제거되어 |책 읽기|가 됩니다.","code":{"source":"text = \"  책 읽기  \"\ntext = text.strip()\nprint(\"|\" + text + \"|\")","kind":"python","output":"|책 읽기|","error":null}},"explanation":"strip의 결과를 버리면 text가 가리키는 값은 유지됩니다. 다시 대입하면 정리한 결과를 이어 쓰며, 안쪽 공백은 strip의 제거 대상이 아닙니다.","code":"text = \"  책 읽기  \"\ntext.strip()\nprint(\"|\" + text + \"|\")","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"text가 \"red Red red\"일 때 replace로 소문자 red만 blue로 바꾼 결과를 출력하세요. 이어서 모든 글자를 소문자로 만든 결과에 replace를 적용해 세 부분을 모두 바꾸세요. 원래 text도 마지막에 출력하세요.","skill":"변환 순서와 대소문자","solution":{"answer":"첫 결과는 blue Red blue, 두 번째는 blue blue blue이며 원래 text는 red Red red입니다.","code":{"source":"text = \"red Red red\"\nprint(text.replace(\"red\", \"blue\"))\nlowered = text.lower()\nprint(lowered.replace(\"red\", \"blue\"))\nprint(text)","kind":"python","output":"blue Red blue\nblue blue blue\nred Red red","error":null}},"explanation":"replace는 대소문자를 구분합니다. lower의 반환값에서는 세 부분이 모두 red이므로 모두 바뀝니다. 어떤 단계에서도 text에 다시 대입하지 않아 원본은 유지됩니다."},{"question":"아래 코드가 내는 오류 종류를 확인하세요. word 내부를 직접 바꾸는 대신, 첫 글자를 대문자로 한 새 문자열을 만들고 word에 다시 대입해 Python을 출력하도록 고치세요. 앞 레슨에서 배운 슬라이싱을 사용해 보세요.","skill":"불변 문자열의 일부 바꾸기","solution":{"answer":"word[0]에 대입하면 TypeError가 납니다. \"P\"와 word[1:]를 연결한 결과를 word에 대입하면 Python이 됩니다.","code":{"source":"word = \"python\"\nword = \"P\" + word[1:]\nprint(word)","kind":"python","output":"Python","error":null}},"explanation":"문자열의 특정 위치는 읽을 수 있지만 덮어쓸 수 없습니다. word[1:]의 ython 앞에 P를 연결한 문자열을 만들고 이름을 다시 연결합니다. 이처럼 새로운 값을 만드는 다른 풀이도 가능합니다.","code":"word = \"python\"\nword[0] = \"P\"\nprint(word)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드의 두 출력을 예상하고 실행하세요. saved도 대문자로 바뀔지 설명하세요. 이어서 text 대신 \"   \"을 원본으로 삼아 strip한 결과를 별도 이름에 연결하고, 원본과 결과를 |로 감싸 출력하는 코드를 작성하세요.","skill":"재대입과 빈 결과의 경계","solution":{"answer":"첫 코드는 PY와 py를 출력합니다. 공백만 있는 값에 strip을 쓰면 결과는 빈 문자열이고, 원본은 세 공백을 유지합니다.","code":{"source":"text = \"py\"\nsaved = text\ntext = text.upper()\nprint(text)\nprint(saved)\nraw = \"   \"\nclean = raw.strip()\nprint(\"|\" + raw + \"|\")\nprint(\"|\" + clean + \"|\")","kind":"python","output":"PY\npy\n|   |\n||","error":null}},"explanation":"text의 재대입은 saved의 연결을 바꾸지 않습니다. strip이 빈 문자열을 돌려줘도 정상적인 결과이며, raw를 다시 대입하지 않았으므로 원본 공백은 그대로입니다.","code":"text = \"py\"\nsaved = text\ntext = text.upper()\nprint(text)\nprint(saved)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"}]},{"id":"python-l014","order":4,"title":"나누기·합치기·검색하기","subtitle":"문자열을 조각으로 나누고 다시 연결하며, 필요한 글이 있는지 확인합니다.","minutes":15,"goal":"split·join·find·in의 결과를 구분하여 텍스트를 나누고 결합하거나 포함 여부와 위치를 확인한다.","intro":"쉼표로 적힌 항목을 보기 좋은 한 줄로 바꾸거나, 긴 제목에 원하는 말이 있는지 찾을 때가 있습니다. 앞 레슨의 메서드 호출과 반환값을 이용하면 이런 처리를 작은 단계로 나눌 수 있습니다. 이때 결과가 문자열인지, 여러 조각의 묶음인지, 위치 숫자인지 구분해야 다음 도구를 알맞게 연결할 수 있습니다.","sections":[{"title":"split은 기준 문자열에서 나누어 조각을 돌려줍니다.","body":["text.split(\",\")는 쉼표를 구분자로 삼아 문자열을 나눕니다. 구분자는 조각에 포함되지 않고, 나온 문자열들이 원래 순서대로 리스트라는 묶음에 담깁니다. 리스트는 여러 값을 순서대로 담는 자료형입니다. 자세한 생성과 변경은 뒤 챕터에서 배우며, 여기서는 split의 결과를 이름에 연결해 다음 작업에 전달하는 데 사용합니다.","print로 리스트를 보면 바깥 대괄호 안에 문자열들이 따옴표와 쉼표로 구분되어 보입니다. ['사과', '배']는 문자열 두 개가 담긴 리스트의 표시이지, 대괄호까지 들어 있는 문자열 한 개가 아닙니다. 문자열 자체를 print했을 때와 표시 모양이 다른 이유입니다. parts[0]처럼 인덱스로 한 항목을 읽을 수도 있습니다. 위치는 앞에서 0부터 세지만, 문자열 인덱스가 문자 하나를 읽는 것과 달리 여기서는 리스트에 담긴 문자열 조각 하나를 읽습니다.","구분자를 직접 지정하면 연속된 구분자 사이나 끝부분에서 빈 조각이 생길 수 있습니다. \"사과,,배,\"를 쉼표로 나누면 빈 문자열도 남습니다. 지정한 구분자가 원문에 없으면 원래 문자열 하나를 담은 리스트가 됩니다. 빈 문자열을 구분자로 지정하는 split(\"\")는 사용할 수 없고 ValueError가 납니다."],"code":{"source":"text = \"사과,,배,\"\nparts = text.split(\",\")\nprint(parts)\nprint(type(parts))\nprint(\"사과\".split(\",\"))","kind":"python","output":"['사과', '', '배', '']\n<class 'list'>\n['사과']","error":null,"caption":"리스트 안의 빈 따옴표는 길이 0인 문자열 조각을 뜻합니다."}},{"title":"구분자를 생략한 split은 공백 묶음을 기준으로 나눕니다.","body":["text.split()처럼 괄호 안을 비우면 연속된 공백 문자를 하나의 구분 구간으로 다루고, 양 끝의 공백 때문에 빈 조각을 만들지 않습니다. 일반 빈칸뿐 아니라 탭과 줄바꿈도 구분 기준에 포함됩니다. 공백이 여러 개여도 단어들만 차례로 얻고 싶을 때 어울립니다.","반면 text.split(\" \")은 정확히 한 칸짜리 빈칸을 구분자로 지정한 호출입니다. 연속된 빈칸이나 양 끝 빈칸에 대해 빈 문자열 조각을 남깁니다. 괄호를 비운 호출과 빈칸 하나를 전달한 호출은 같은 뜻이 아닙니다.","빈 문자열의 split() 결과는 아무 조각도 없는 빈 리스트 []입니다. 빈 문자열이라도 split(\",\")처럼 구분자를 지정하면 빈 문자열 하나가 든 ['']가 됩니다. 화면에는 비슷하게 비어 보여도 조각의 개수와 다음 결합 결과에 영향을 줄 수 있습니다."],"code":{"source":"text = \"  읽고   쓰기  \"\nprint(text.split())\nprint(text.split(\" \"))\nprint(\"\".split())\nprint(\"\".split(\",\"))","kind":"python","output":"['읽고', '쓰기']\n['', '', '읽고', '', '', '쓰기', '', '']\n[]\n['']","error":null,"caption":"공백을 묶어서 처리할지, 지정한 구분자 사이의 빈 조각까지 보존할지 먼저 정합니다."}},{"title":"join은 조각 사이에 구분자를 넣어 문자열로 합칩니다.","body":["\" / \".join(parts)는 parts에 들어 있는 문자열들을 차례로 연결하면서 사이마다 \" / \"를 넣습니다. 점 앞에는 결합에 사용할 구분자 문자열을, 괄호 안에는 합칠 문자열들의 묶음을 씁니다. parts.join(...)처럼 리스트 쪽에서 호출하는 방식이 아닙니다.","join의 반환값은 하나의 문자열입니다. 구분자는 조각 사이에만 들어가므로 첫 조각 앞이나 마지막 조각 뒤에 자동으로 붙지 않습니다. \"\".join(parts)처럼 빈 구분자를 쓰면 조각을 그대로 이어 붙입니다. 묶음 안에 숫자처럼 문자열이 아닌 값이 있으면 join은 자동 변환하지 않고 TypeError를 냅니다.","나누고 합친다고 언제나 원문이 복원되는 것은 아닙니다. 구분자를 생략한 split은 원래 공백의 개수와 종류를 보존하지 않고, 다른 구분자로 join하면 표시도 달라집니다. 원본이 필요하면 따로 유지하고 처리 결과를 새로운 이름에 연결하세요."],"code":{"source":"raw = \"기초,연습,복습\"\nparts = raw.split(\",\")\nresult = \" / \".join(parts)\nprint(parts)\nprint(result)\nprint(raw)","kind":"python","output":"['기초', '연습', '복습']\n기초 / 연습 / 복습\n기초,연습,복습","error":null,"caption":"split의 리스트 반환값을 join에 전달하면 하나의 새 문자열이 됩니다."}},{"title":"있는지는 in, 처음 나타난 위치는 find로 확인합니다.","body":["\"기초\" in text는 text 안에 \"기초\"라는 연속된 문자열이 포함되어 있는지 True 또는 False로 알려 줍니다. text.find(\"기초\")는 처음 나타난 위치의 인덱스를 정수로 돌려주고, 없으면 -1을 돌려줍니다. 포함 여부만 필요하면 in을 쓰고 실제 위치가 필요하면 find의 결과를 확인합니다.","검색도 대소문자를 구분합니다. \"Python\"과 \"python\"은 다른 문자열이므로 같은 결과를 기대할 수 없습니다. 영문 대소문자를 무시하려는 이번 입문 예제에서는 검색할 문자열을 lower로 맞춘 뒤 같은 소문자를 찾을 수 있습니다.","find가 돌려준 0은 맨 앞에서 찾았다는 뜻이며, -1은 못 찾았다는 뜻입니다. 그런데 인덱스로 쓰는 -1은 마지막 문자를 가리킵니다. 따라서 못 찾은 결과를 그대로 text[position]에 넣으면 마지막 문자가 나와 엉뚱한 성공처럼 보일 수 있습니다. 지금은 위치와 포함 여부를 출력해 구분하고, 결과에 따라 실행을 나누는 방법은 다음 챕터에서 배웁니다."],"code":{"source":"text = \"기초 Python 기초\"\nprint(\"기초\" in text)\nprint(text.find(\"기초\"))\nprint(\"python\" in text)\nprint(text.find(\"python\"))\nprint(\"python\" in text.lower())","kind":"python","output":"True\n0\nFalse\n-1\nTrue","error":null,"caption":"find는 첫 위치를 알려 주며, 찾지 못한 -1을 마지막 위치라는 뜻으로 해석하면 안 됩니다."}}],"worked":{"question":"\"  읽기   쓰기  복습 \"을 단어 사이에 /가 하나씩 들어간 문장으로 정리하고, 복습이 포함되어 있는지도 확인해 보세요.","code":{"source":"raw = \"  읽기   쓰기  복습 \"\nparts = raw.split()\nmessage = \"/\".join(parts)\nprint(parts)\nprint(message)\nprint(\"복습\" in message)\nprint(message.find(\"복습\"))","kind":"python","output":"['읽기', '쓰기', '복습']\n읽기/쓰기/복습\nTrue\n6","error":null,"caption":"공백 정리, 문자열 결합, 포함 여부와 위치 확인을 순서대로 수행합니다."},"steps":["split()은 연속된 공백을 구분 구간으로 사용해 읽기·쓰기·복습이라는 세 문자열을 리스트에 담습니다. 원래 공백 개수는 이 결과에 남지 않습니다.","\"/\".join(parts)는 세 문자열 사이 두 곳에 /를 넣어 읽기/쓰기/복습이라는 새 문자열을 만듭니다.","in으로 확인한 결과는 True입니다. find의 6은 합쳐진 문자열에서 복습의 첫 글자가 0부터 센 위치 6에 있다는 뜻입니다."],"answer":"조각을 얻는 split, 문자열을 만드는 join, 불리언을 만드는 in, 위치를 만드는 find의 결과 종류를 구분하면 작은 처리 흐름을 연결할 수 있습니다."},"misconception":{"question":"find가 -1을 돌려주면 text[-1]로 찾은 문자를 확인하면 되나요?","answer":"아닙니다. find의 -1은 해당 문자열을 찾지 못했다는 표시입니다. text[-1]은 별개의 인덱스 규칙에 따라 마지막 문자를 읽습니다. 마지막 문자가 출력되더라도 검색에 성공했다는 증거가 아닙니다. 포함 여부만 필요하면 in을 사용하고, 위치를 사용하기 전에는 못 찾은 결과인지 구분해야 합니다."},"keypoints":["split은 문자열 조각들의 리스트를 반환합니다. 구분자 생략은 연속 공백을 묶지만, 구분자 지정은 사이의 빈 조각도 보존합니다.","구분자.join(문자열 묶음)은 조각 사이를 연결한 문자열을 반환합니다. 원본은 유지되며, 공백을 없앤 뒤 합친 결과가 원문과 같으리라고 가정하지 않습니다.","in은 포함 여부, find는 처음 나타난 위치를 알려 줍니다. 위치 0은 찾은 결과이고 -1은 못 찾은 표시이므로 그대로 인덱스에 사용하지 않습니다."],"examples":[{"question":"아래 문자열을 쉼표로 나눈 parts를 출력하고, 조각 사이를 세로선 |로 합친 결과도 출력하세요. 연속된 쉼표와 맨 끝 쉼표가 결합 결과에 어떻게 남는지 설명하세요.","skill":"구분자와 빈 조각 해석","solution":{"answer":"parts는 ['봄', '', '가을', '']이며 결합 결과는 봄||가을|입니다.","code":{"source":"text = \"봄,,가을,\"\nparts = text.split(\",\")\nprint(parts)\nprint(\"|\".join(parts))","kind":"python","output":"['봄', '', '가을', '']\n봄||가을|","error":null}},"explanation":"명시한 구분자 사이에 글자가 없으면 빈 문자열 조각이 남습니다. join은 빈 조각도 포함한 네 조각 사이 세 곳에 |를 넣으므로 끝에도 |가 보입니다.","code":"text = \"봄,,가을,\"","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 문자열에 split()과 split(\" \")을 각각 적용해 결과를 출력하세요. 이어서 단어 사이 빈칸이 하나이고 양 끝에 빈칸이 없는 문자열을 만들어 |로 감싸 출력하세요.","skill":"공백 묶음과 지정 구분자 비교","solution":{"answer":"split()은 ['배움', '기록']이고, split(\" \")은 양 끝과 연속 공백 사이에 빈 조각을 남깁니다. split()의 결과를 \" \".join으로 연결하면 |배움 기록|입니다.","code":{"source":"text = \" 배움  기록 \"\nprint(text.split())\nprint(text.split(\" \"))\nwords = text.split()\nresult = \" \".join(words)\nprint(\"|\" + result + \"|\")","kind":"python","output":"['배움', '기록']\n['', '배움', '', '기록', '']\n|배움 기록|","error":null}},"explanation":"split()은 연속 공백을 묶어 단어만 얻습니다. 지정 구분자 split(\" \")는 각 한 칸에서 나누므로 빈 조각이 남습니다. 정리한 단어 사이를 한 칸으로 연결하면 요구한 결과가 됩니다.","code":"text = \" 배움  기록 \"","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드는 없는 쉼표의 위치를 읽고 마지막 글자를 출력합니다. 실행 결과를 확인하고 잘못된 해석을 설명하세요. 마지막 줄을 쉼표가 포함되는지 출력하는 코드로 바꾸세요.","skill":"못 찾은 위치와 음수 인덱스 구분","solution":{"answer":"원래 출력은 -1과 n입니다. 수정한 출력은 -1과 False입니다. n은 검색 결과가 아니라 text[-1]로 읽은 마지막 문자입니다.","code":{"source":"text = \"Python\"\nposition = text.find(\",\")\nprint(position)\nprint(\",\" in text)","kind":"python","output":"-1\nFalse","error":null}},"explanation":"쉼표가 없어 find는 -1을 반환합니다. 이 숫자를 그대로 인덱스로 쓰면 음수 인덱스 규칙이 적용됩니다. 포함 여부를 묻는 요구에는 in의 불리언 결과가 맞습니다.","code":"text = \"Python\"\nposition = text.find(\",\")\nprint(position)\nprint(text[position])","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"text가 \"code code\"일 때 \"code\"의 포함 여부와 처음 나타난 위치를 출력하세요. 이어서 \"Code\"에 대해서도 같은 두 결과를 출력하고, 위치 0과 못 찾았다는 결과의 차이를 설명하세요.","skill":"첫 위치와 검색의 대소문자","solution":{"answer":"code는 True와 0, Code는 False와 -1을 얻습니다. 0은 맨 앞에서 찾았다는 뜻입니다.","code":{"source":"text = \"code code\"\nprint(\"code\" in text)\nprint(text.find(\"code\"))\nprint(\"Code\" in text)\nprint(text.find(\"Code\"))","kind":"python","output":"True\n0\nFalse\n-1","error":null}},"explanation":"find는 일치하는 여러 부분 중 가장 앞선 위치를 반환합니다. 대소문자를 구분하므로 Code는 포함되지 않습니다. 숫자 0과 -1을 각각 발견 위치와 실패 표시로 구분합니다."},{"question":"\"  Python   기초  \"를 공백 기준으로 나누고, 단어 사이를 -로 합친 뒤 소문자로 표시하세요. 완성된 결과에 \"python\"이 포함되는지와 원본 문자열을 |로 감싼 값도 출력하세요.","skill":"반환값을 연결한 텍스트 처리","solution":{"answer":"완성 문자열은 python-기초, 포함 여부는 True입니다. 원본은 공백과 대문자 P를 그대로 유지합니다.","code":{"source":"raw = \"  Python   기초  \"\nparts = raw.split()\njoined = \"-\".join(parts)\nresult = joined.lower()\nprint(result)\nprint(\"python\" in result)\nprint(\"|\" + raw + \"|\")","kind":"python","output":"python-기초\nTrue\n|  Python   기초  |","error":null}},"explanation":"split의 리스트 결과는 join의 입력이고, join의 문자열 결과는 lower의 작업 대상입니다. 결과를 별도 이름에 연결했으므로 raw의 원래 공백과 대소문자는 유지됩니다."}]},{"id":"python-l015","order":5,"title":"형식에 맞춰 출력하기","subtitle":"계산에 쓰는 값은 유지하고, 읽는 사람에게 필요한 모양으로 보여 줍니다.","minutes":12,"goal":"f-string으로 값과 설명을 결합하고, 소수 자릿수와 정수의 최소 표시 폭을 정하되 원래 값과 표시 문자열을 구분한다.","intro":"7.5라는 숫자만 보면 시간인지 길이인지 알기 어렵습니다. 앞에서 문자열을 자르고 정리했다면, 이제 그 결과와 숫자를 한 문장으로 묶어 봅시다. 숫자를 계산하기 좋은 값으로 보관하는 일과 사람이 읽기 좋은 글자로 보여 주는 일은 서로 다릅니다. f-string은 문장 안에서 값이 들어갈 자리와 표시 방법을 함께 적게 해 줍니다.","sections":[{"title":"문자열 앞의 f와 중괄호가 값의 자리를 만듭니다.","body":["챕터 2에서는 \"개수: \" + str(count)처럼 숫자를 문자열로 바꾸어 이어 붙였습니다. f-string은 따옴표 바로 앞에 f를 쓰고, 값을 넣을 자리에 {count}처럼 중괄호를 씁니다. 중괄호 밖의 설명은 그대로 두고 안의 식을 계산해 문자열에 넣습니다.","f\"개수: {count}개\"는 문자열 값 하나를 만듭니다. 그 결과를 message 같은 이름에 저장하거나 print로 출력할 수 있습니다. f가 없는 보통 문자열에서는 {count}도 글자 그대로입니다. 변수 이름을 따옴표 안에 썼다는 이유만으로 값이 자동으로 들어가지는 않습니다.","문장을 만드는 f-string과 화면에 보여 주는 print의 역할도 구별하세요. message = f\"개수: {count}개\"만 실행하면 파일 실행 화면에는 아무것도 출력되지 않습니다."],"code":{"source":"count = 4\nmessage = f\"개수: {count}개\"\nprint(\"개수: {count}개\")\nprint(message)\nprint(type(message))","kind":"python","output":"개수: {count}개\n개수: 4개\n<class 'str'>","error":null}},{"title":"중괄호 안의 식은 문자열을 만드는 순간 계산합니다.","body":["중괄호에는 이름 하나뿐 아니라 price * count처럼 이미 배운 계산식도 넣을 수 있습니다. f-string을 실행하는 시점에 곱셈을 하고 그 결과를 문장에 넣습니다. 긴 처리는 먼저 변수에 나누어 담으면 읽기 쉽습니다.","한 번 만든 문자열이 나중의 변수 변화를 계속 따라가지는 않습니다. count가 2일 때 만든 안내 문구는 count를 3으로 바꿔도 그대로입니다. 최신 값의 문장이 필요하면 f-string을 다시 실행해야 합니다.","f-string의 중괄호 안에서는 식으로 값을 구합니다. 값이 아직 정의되지 않은 이름을 쓰면 NameError가 납니다. 식과 표시를 연결하는 도구이지, 빠진 값을 알아서 만드는 도구는 아닙니다."],"code":{"source":"price = 1200\ncount = 2\nmessage = f\"총액: {price * count}원\"\ncount = 3\nprint(message)\nprint(f\"총액: {price * count}원\")","kind":"python","output":"총액: 2400원\n총액: 3600원","error":null}},{"title":"소수 자릿수는 계산값이 아니라 표시 방법입니다.","body":["f\"{distance:.2f}\"에서 콜론 앞의 distance는 표시할 값이고, 콜론 뒤의 .2f는 소수점 아래 두 자리까지 고정된 소수 형태로 나타내라는 형식입니다. 1.2는 1.20으로 보이고, 1.236은 두 자리로 반올림되어 1.24로 보입니다. 여기서 따옴표 앞의 f와 형식 끝의 f는 서로 다른 위치에서 다른 역할을 합니다.","결과는 표시용 문자열입니다. .2f를 썼다고 distance에 저장된 숫자의 소수 부분이 바뀌지는 않습니다. 원래 값으로 계속 계산할 수 있고, 표시에 쓸 글자만 따로 얻습니다.","float는 이진수로 저장되어 모든 십진 소수를 정확히 나타내지는 못합니다. 반올림 경계에서는 손으로 생각한 결과와 표시가 다를 수 있습니다. 이 레슨의 자릿수 지정은 읽기 좋은 표시를 위한 것이며, 정확한 금액 계산이나 측정 정밀도를 보장하는 기능은 아닙니다."],"code":{"source":"distance = 1.236\nlabel = f\"거리: {distance:.2f} km\"\nprint(label)\nprint(distance)\nprint(f\"거리: {1.2:.2f} km\")","kind":"python","output":"거리: 1.24 km\n1.236\n거리: 1.20 km","error":null}},{"title":"정수의 표시 폭을 정해 번호를 읽기 쉽게 만듭니다.","body":["시간이나 번호에 앞자리 0이 필요할 때 정수에 02d 형식을 쓸 수 있습니다. f\"{number:02d}\"에서 d는 십진 정수 표시, 2는 최소 두 칸, 앞의 0은 빈 자리를 0으로 채우라는 뜻입니다. 정수 7은 문자열 \"07\"로 표시됩니다.","2는 최대 길이가 아닙니다. 정수 123을 02d로 표시해도 123 전체가 나옵니다. 긴 숫자를 자르지 않고, 짧을 때만 폭을 채웁니다. 원래 number는 여전히 정수이므로 다음 번호를 계산할 수도 있습니다.","형식은 값의 종류에 맞게 선택합니다. 02d는 정수용이며 문자열 \"7\"을 정수로 변환하는 명령이 아닙니다. 숫자로 받은 입력을 정수 형식으로 표시할 목적이면 먼저 int로 변환합니다. 반면 이미 \"007\"처럼 앞의 0에 뜻이 있는 식별 문자열은 그대로 보존할 수도 있습니다."],"code":{"source":"number = 7\nprint(f\"번호 {number:02d}\")\nprint(f\"다음 번호 {number + 1:02d}\")\nprint(f\"큰 번호 {123:02d}\")\nprint(number)","kind":"python","output":"번호 07\n다음 번호 08\n큰 번호 123\n7","error":null}}],"worked":{"question":"이름 \"  하린  \", 참가 번호 4, 이동 거리 3.456을 받아 \"04번 하린 · 3.46 km\"로 표시하려면 정리와 표시를 어떻게 나눌까요?","code":{"source":"raw_name = \"  하린  \"\nnumber = 4\ndistance = 3.456\nname = raw_name.strip()\nmessage = f\"{number:02d}번 {name} · {distance:.2f} km\"\nprint(message)\nprint(distance)","kind":"python","output":"04번 하린 · 3.46 km\n3.456","error":null},"steps":["strip의 반환값을 name에 연결해 이름 양끝의 공백을 뺍니다. 이 단계는 원래 입력 문자열을 바꾸는 것이 아니라 정리한 문자열을 얻는 과정입니다.","number는 정수이므로 02d로 최소 두 자리를 맞춥니다. name은 값 그대로, distance는 .2f로 소수점 아래 두 자리까지 문장에 넣습니다.","완성한 문자열을 print로 출력합니다. distance를 따로 출력하면 3.456이 남아 있어 표시 형식이 원래 계산값을 바꾸지 않았다는 점을 확인할 수 있습니다."],"answer":"문자열 정리, 숫자 계산, 표시 형식을 구분합니다. 결과 문장은 04번 하린 · 3.46 km이고, distance는 계속 3.456입니다."},"misconception":{"question":"f-string으로 두 자리 소수나 두 칸 정수를 만들면 원래 값도 그 모양으로 바뀌나요?","answer":"아닙니다. f\"{value:.2f}\"나 f\"{number:02d}\"는 표시용 문자열을 만듭니다. 원래 값에 다시 대입하지 않는 한 value와 number는 그대로입니다. 또 02d의 두 칸은 최소 폭이어서 123을 23으로 자르지 않습니다. 계산할 숫자와 표시 문자열, 최소 폭과 최대 길이를 각각 구별하세요."},"keypoints":["f-string은 따옴표 앞의 f와 중괄호 안의 식으로 값과 설명을 한 문자열에 결합합니다.",":.2f는 소수점 아래 두 자리 표시, :02d는 정수를 최소 두 칸에 0으로 채운 표시입니다. 형식은 값 종류와 목적에 맞춥니다.","표시 문자열을 만들어도 원래 숫자는 변하지 않으며, 이미 만든 문장은 이후 변수 변화에 맞춰 자동 갱신되지 않습니다."],"examples":[{"question":"아래 코드는 이름 대신 {name}을 출력합니다. 지우님, 안녕하세요가 나오도록 한 곳을 고쳐 실행하고, f가 하는 일을 설명하세요.","skill":"값의 자리와 보통 문자열","solution":{"answer":"따옴표 앞에 f를 붙이면 {name} 자리에 변수 값 지우가 들어갑니다.","code":{"source":"name = \"지우\"\nprint(f\"{name}님, 안녕하세요\")","kind":"python","output":"지우님, 안녕하세요","error":null}},"explanation":"보통 문자열의 중괄호는 글자 자체입니다. f-string은 중괄호 안의 식을 계산하고 그 값을 문장에 넣습니다.","code":"name = \"지우\"\nprint(\"{name}님, 안녕하세요\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"공책 가격 price = 800, 개수 count = 3을 이용해 총액: 2400원이라는 문장을 출력하세요. 중괄호 안에서 곱하는 식을 사용하고, count를 4로 바꿔 다시 실행한 결과도 적으세요.","skill":"식과 문장 연결","solution":{"answer":"price * count를 중괄호 안에 넣습니다. 3개면 총액: 2400원, 4개로 바꿔 실행하면 총액: 3200원입니다.","code":{"source":"price = 800\ncount = 3\nprint(f\"총액: {price * count}원\")\ncount = 4\nprint(f\"총액: {price * count}원\")","kind":"python","output":"총액: 2400원\n총액: 3200원","error":null}},"explanation":"f-string이 만들어질 때 곱셈을 계산합니다. 개수를 바꾼 새 결과를 표시하려면 f-string을 다시 실행해야 합니다."},{"question":"아래 출력 두 줄을 먼저 예상하고 실행하세요. 첫째 줄에 보이는 2.38을 이유로 value도 2.38로 바뀌었다고 할 수 있는지 설명하세요.","skill":"표시 정밀도와 원래 값","solution":{"answer":"첫 줄은 2.38, 둘째 줄은 2.375입니다. .2f는 표시 문자열을 만들 뿐 value를 다시 대입하지 않습니다.","code":{"source":"value = 2.375\nprint(f\"{value:.2f}\")\nprint(value)","kind":"python","output":"2.38\n2.375","error":null}},"explanation":"이 값은 두 소수 자리로 표시할 때 2.38이 됩니다. 계산용 숫자와 출력에 쓸 문자열이 별개이므로 다음 print에서는 원래 값이 보입니다.","code":"value = 2.375\nprint(f\"{value:.2f}\")\nprint(value)","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"정수 9와 108을 각각 번호 09, 번호 108로 출력하는 코드를 작성하세요. 두 값 모두 같은 02d 형식을 쓰고, 108이 두 자리로 잘리지 않는 이유를 설명하세요.","skill":"최소 표시 폭의 경계","solution":{"answer":"9는 09로 채우고 108은 그대로 표시합니다. 2는 최소 폭이지 최대 길이가 아닙니다.","code":{"source":"small = 9\nlarge = 108\nprint(f\"번호 {small:02d}\")\nprint(f\"번호 {large:02d}\")","kind":"python","output":"번호 09\n번호 108","error":null}},"explanation":"앞의 0은 부족한 폭을 채울 때 쓰입니다. 이미 필요한 폭보다 긴 정수는 원래 자릿수를 유지합니다."},{"question":"소수로 된 리본 길이 한 줄을 입력받아 절반 길이를 소수점 아래 두 자리로 출력하세요. 5를 입력하면 절반: 2.50 m가 나와야 합니다. 원래 길이를 숫자로 바꾸는 단계와 표시 단계를 구분하세요.","skill":"입력과 계산에서 형식 출력으로 전이","solution":{"answer":"입력을 float로 읽고 2로 나눈 값을 .2f로 표시합니다. 5를 입력하면 절반: 2.50 m입니다.","code":{"source":"length = float(input())\nhalf = length / 2\nprint(f\"절반: {half:.2f} m\")","kind":"python","output":"절반: 2.50 m","error":null,"input":"5\n"}},"explanation":"input은 문자열을 반환하므로 먼저 계산 가능한 float로 변환합니다. 계산 후 표시할 때만 f-string의 .2f를 적용하면 소수 두 자리와 단위를 붙일 수 있습니다."}]}],"review":[{"question":"안내판 코드 label = \"ROOM-204\"에서 마지막 세 글자 204와 마지막 글자 4를 각각 출력하세요. 두 결과를 구할 때 음수 인덱스와 슬라이스를 쓰고, 마지막 글자의 양수 인덱스도 len을 이용해 확인하세요.","skill":"범위 해석 · 위치와 구간 연결","solution":{"answer":"label[-3:]은 204, label[-1]과 label[len(label) - 1]은 모두 4입니다.","code":{"source":"label = \"ROOM-204\"\nprint(label[-3:])\nprint(label[-1])\nprint(label[len(label) - 1])","kind":"python","output":"204\n4\n4","error":null}},"explanation":"길이가 8이므로 마지막 위치는 7입니다. -1은 마지막 한 위치이고, -3:은 뒤에서 세 번째부터 끝까지의 구간입니다.","related":["python-l011","python-l012"]},{"question":"아래 코드가 오류를 내는 이유와 오류 종류를 확인하세요. 이어서 마지막 print를 print(f\"[{text[5:9]}]\")로 고쳐 실행하세요. 한 위치 조회와 범위 조회의 결과가 왜 다른지 설명하세요.","skill":"범위 해석 · 범위 밖 조회의 차이","solution":{"answer":"원래 text[5]는 IndexError입니다. 슬라이스로 고친 코드는 []를 출력하며, 대괄호 사이에는 빈 문자열이 있습니다.","code":{"source":"text = \"ABCDE\"\nprint(f\"[{text[5:9]}]\")","kind":"python","output":"[]","error":null}},"explanation":"길이 5인 문자열의 인덱스는 0부터 4까지입니다. 인덱싱은 존재하는 한 위치가 필요하지만 슬라이싱은 범위를 문자열 길이에 맞추고, 선택한 문자가 없으면 빈 문자열을 만듭니다. f-string의 바깥 대괄호는 빈 결과를 눈으로 확인하기 위한 표시입니다.","related":["python-l011","python-l012","python-l015"],"code":"text = \"ABCDE\"\nprint(text[5])","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"아래 두 슬라이스의 결과와 선택한 양수 인덱스를 각각 적은 뒤 실행하세요. 두 번째 슬라이스가 끝 인덱스 0의 문자까지 포함하는지 설명하세요.","skill":"범위 해석 · 간격과 역방향 끝 경계","solution":{"answer":"첫 줄은 1357로 인덱스 1, 3, 5, 7을 선택합니다. 둘째 줄은 7531로 인덱스 7, 5, 3, 1을 선택하며 0은 포함하지 않습니다.","code":{"source":"digits = \"0123456789\"\nprint(digits[1:8:2])\nprint(digits[7:0:-2])","kind":"python","output":"1357\n7531","error":null}},"explanation":"양의 간격 2는 오른쪽으로, 음의 간격 -2는 왼쪽으로 이동합니다. 두 방향 모두 끝 경계는 포함하지 않습니다. 두 번째는 0에 도달하기 전의 위치까지만 고릅니다.","related":["python-l012"],"code":"digits = \"0123456789\"\nprint(digits[1:8:2])\nprint(digits[7:0:-2])","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"아래 코드의 출력 세 줄을 예상하고 실행하세요. find의 반환값을 문자열 위치로 사용할 때 마지막 결과 -1을 그대로 쓰면 왜 위험한지도 설명하세요.","skill":"결과 예측 · 정리한 문자열에서 검색","solution":{"answer":"clean은 tea입니다. 출력은 True, 0, -1입니다. -1은 찾지 못했다는 신호인데 clean[-1]은 마지막 글자 a를 가리키므로 검색 성공으로 해석하면 안 됩니다.","code":{"source":"raw = \" Tea \"\nclean = raw.strip().lower()\nprint(\"ea\" in clean)\nprint(clean.find(\"t\"))\nprint(clean.find(\"T\"))","kind":"python","output":"True\n0\n-1","error":null}},"explanation":"strip이 양끝 공백을 없애고 lower가 영문을 소문자로 만듭니다. in은 포함 여부, find는 첫 위치 또는 없을 때 -1을 반환합니다. 원래 문자열의 대문자 T가 정리 뒤에는 남아 있지 않습니다.","related":["python-l011","python-l013","python-l014"],"code":"raw = \" Tea \"\nclean = raw.strip().lower()\nprint(\"ea\" in clean)\nprint(clean.find(\"t\"))\nprint(clean.find(\"T\"))","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"아래 두 출력이 서로 다른 이유를 예상한 뒤 실행하세요. 연속된 공백을 한 구분으로 읽는 방식과 공백 한 글자를 정확한 구분자로 쓰는 방식에서, split의 결과 사이에 빈 문자열이 생기는지 설명하세요.","skill":"결과 예측 · split과 join의 경계","solution":{"answer":"첫 줄은 red|blue, 둘째 줄은 red||blue입니다. split()은 연속 공백을 묶어 나누고, split(\" \")은 사이의 빈 문자열도 결과에 남깁니다.","code":{"source":"text = \"red  blue\"\nprint(\"|\".join(text.split()))\nprint(\"|\".join(text.split(\" \")))","kind":"python","output":"red|blue\nred||blue","error":null}},"explanation":"join은 문자열 목록의 각 항목 사이에 구분자 |를 넣습니다. 두 번째 목록은 red, 빈 문자열, blue의 세 항목이므로 구분자가 두 번 들어갑니다. 원래 연속 공백을 어떻게 해석하려는지에 맞춰 분리 방법을 고릅니다.","related":["python-l014"],"code":"text = \"red  blue\"\nprint(\"|\".join(text.split()))\nprint(\"|\".join(text.split(\" \")))","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"아래 두 출력 문장을 예상한 뒤 실행하세요. 이미 만들어진 message와 마지막 줄에서 새로 만드는 f-string이 서로 다른 값을 보여 주는 이유를 설명하세요.","skill":"결과 예측 · 문자열을 만든 시점","solution":{"answer":"첫 줄은 거리 1.50 km, 둘째 줄은 거리 2.00 km입니다. message에는 distance가 1.5였을 때 만든 문자열이 남아 있습니다.","code":{"source":"distance = 1.5\nmessage = f\"거리 {distance:.2f} km\"\ndistance = 2\nprint(message)\nprint(f\"거리 {distance:.2f} km\")","kind":"python","output":"거리 1.50 km\n거리 2.00 km","error":null}},"explanation":"f-string은 실행할 때의 식 값을 읽어 문자열을 만듭니다. 변수와 영구히 연결된 안내판이 아니므로 이후 distance의 재대입이 message를 자동으로 갱신하지 않습니다.","related":["python-l015"],"code":"distance = 1.5\nmessage = f\"거리 {distance:.2f} km\"\ndistance = 2\nprint(message)\nprint(f\"거리 {distance:.2f} km\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"사용자가 한 줄로 입력한 \"  TEAM-07  \"을 양끝 공백 없는 소문자 표기 team/07로 바꾸어 출력하세요. strip, lower, split, join을 연결하되 번호의 앞자리 0은 그대로 보존하세요. 입력할 때 따옴표는 쓰지 않습니다.","skill":"변환 조합 · 텍스트 표기 통일","solution":{"answer":"입력의 양끝 공백과 대문자를 정리한 뒤 -로 나누고 /로 합치면 team/07이 됩니다.","code":{"source":"raw = input()\nclean = raw.strip().lower()\nparts = clean.split(\"-\")\nlabel = \"/\".join(parts)\nprint(label)","kind":"python","output":"team/07","error":null,"input":"  TEAM-07  \n"}},"explanation":"번호 부분은 계산할 개수가 아니라 표기의 일부이므로 문자열로 유지합니다. int로 바꾸면 앞의 0이 사라질 수 있습니다. 각 메서드의 반환값을 다음 단계에 전달하는 것이 처리 흐름입니다.","related":["python-l013","python-l014"]},{"question":"record = \"모임:3.5\"는 이름과 한 번의 활동 시간이며 :가 한 번 들어 있습니다. split으로 분리한 결과에서 시간 문자열을 꺼내 숫자로 바꾸고, 같은 활동 두 번의 시간을 합계: 7.00시간으로 출력하세요.","skill":"변환 조합 · 분리한 숫자와 표시","solution":{"answer":"parts[1]은 문자열 3.5입니다. float로 변환해 2를 곱한 다음 .2f 형식으로 합계: 7.00시간을 출력합니다.","code":{"source":"record = \"모임:3.5\"\nparts = record.split(\":\")\nhours = float(parts[1])\ntotal = hours * 2\nprint(f\"합계: {total:.2f}시간\")","kind":"python","output":"합계: 7.00시간","error":null}},"explanation":"split의 결과는 순서가 있는 리스트이며 첫 항목은 0, 두 번째 항목은 1로 조회합니다. 계산할 시간은 float로 읽고, 계산한 결과에 마지막으로 단위와 표시 형식을 붙입니다. 이 입력은 이름과 시간 두 부분이 있다는 전제를 사용합니다.","related":["python-l014","python-l015"]},{"question":"filename = \"report.txt\"에는 점이 한 번 있습니다. find로 점의 위치를 찾고, 점 앞부분만 대문자로 만들어 REPORT.txt를 출력하세요. 점부터 끝까지는 슬라이싱으로 그대로 유지하고, 처리 순서를 설명하세요.","skill":"변환 조합 · 검색 위치로 범위 나누기","solution":{"answer":"점의 위치는 6입니다. filename[:6]에 upper를 적용하고 filename[6:]을 이어 붙이면 REPORT.txt가 됩니다.","code":{"source":"filename = \"report.txt\"\nposition = filename.find(\".\")\nbase = filename[:position].upper()\nsuffix = filename[position:]\nprint(base + suffix)","kind":"python","output":"REPORT.txt","error":null}},"explanation":"find가 돌려준 위치를 두 범위의 경계로 사용합니다. 앞 슬라이스는 점을 포함하지 않고, 뒤 슬라이스는 점부터 포함합니다. 이 문제는 점이 있다는 전제가 있으므로 찾은 위치를 사용할 수 있습니다. 점이 없을 때의 -1을 같은 뜻으로 사용하면 안 됩니다.","related":["python-l012","python-l013","python-l014"]},{"question":"아래 코드는 문자열의 첫 글자를 직접 바꾸려 합니다. 실행해 오류 종류를 확인하세요. 이어서 text[0]에 대입하는 줄을 새 문자열 \"R\"과 text[1:]을 이어 text에 다시 대입하는 줄로 고치고, text와 saved의 값을 각각 출력하세요.","skill":"불변성 오개념 · 문자열 변경과 재대입","solution":{"answer":"원본은 TypeError입니다. text = \"R\" + text[1:]로 고치면 text는 R02, saved는 A02입니다.","code":{"source":"text = \"A02\"\nsaved = text\ntext = \"R\" + text[1:]\nprint(text)\nprint(saved)","kind":"python","output":"R02\nA02","error":null}},"explanation":"문자열의 한 위치를 대입으로 바꿀 수는 없습니다. 슬라이싱과 연결로 다른 문자열을 만들고 text라는 이름을 그 결과에 다시 연결합니다. saved는 원래 문자열 A02를 계속 가리키므로 바뀌지 않습니다.","related":["python-l011","python-l012","python-l013"],"code":"text = \"A02\"\nsaved = text\ntext[0] = \"R\"\nprint(text)\nprint(saved)","codeKind":"python","codeLabel":"읽거나 수정할 코드"}]},{"id":"python-ch04","slug":"ch04","number":4,"title":"조건에 따라 흐름 바꾸기","description":"조건으로 실행할 블록을 나누고, 빈 값과 경계값에서도 의도한 흐름인지 확인합니다.","prerequisite":"선행 학습: 챕터 2 · 값·이름·연산","runtime":"Python 3","testedVersion":"3.12.14","lessons":[{"id":"python-l016","order":1,"title":"if와 들여쓰기 블록","subtitle":"조건의 참·거짓에 따라 실행할 줄을 고르고, 들여쓰기로 그 범위를 나타냅니다.","minutes":12,"goal":"if의 조건과 들여쓰기 블록을 읽고, 참일 때 실행하는 줄과 조건과 관계없이 이어지는 줄을 구분한다.","intro":"챕터 2에서는 비교식이 True나 False를 만든다는 것을 배웠습니다. 그런데 비가 올 때만 우산 안내를 출력하거나 재고가 있을 때만 수량을 줄이려면, 비교 결과에 따라 실제 실행도 달라져야 합니다. if는 조건이 참일 때 실행할 명령들을 묶어 이런 선택을 표현합니다.","sections":[{"title":"if는 조건이 참일 때만 다음 블록을 실행합니다.","body":["if temperature >= 28:은 temperature가 28 이상인지 먼저 확인하고, 참이면 그 아래에 들여쓴 줄을 실행하라는 뜻입니다. 조건의 끝에는 콜론 :을 적습니다. 비교식 자체를 출력하는 print와 달리 if는 실행 여부를 결정합니다.","아래 예시에서는 temperature >= 28이 True이므로 더위를 조심하세요.가 출력됩니다. temperature를 22로 바꾸면 비교 결과가 False가 되어 들여쓴 출력 줄을 건너뜁니다. 그다음 들여쓰지 않은 확인을 마쳤습니다.는 두 경우 모두 출력합니다.","True와 False를 직접 쓰거나, 앞에서 만든 불리언 변수로도 조건을 나타낼 수 있습니다. 예를 들어 raining = True 다음의 if raining:은 raining이 가리키는 불리언을 확인합니다. 여기서는 비교식과 불리언을 사용하고, 다른 종류의 값을 조건에 넣는 규칙은 뒤 레슨에서 배웁니다."],"code":{"source":"temperature = 30\nprint(temperature >= 28)\nif temperature >= 28:\n    print(\"더위를 조심하세요.\")\nprint(\"확인을 마쳤습니다.\")","kind":"python","output":"True\n더위를 조심하세요.\n확인을 마쳤습니다.","error":null,"caption":"조건식의 결과를 보는 것과 그 결과로 실행을 고르는 것을 함께 비교합니다."}},{"title":"들여쓴 여러 줄이 하나의 실행 범위입니다.","body":["조건에 묶여 함께 실행되는 명령들의 범위를 블록이라고 합니다. 이 과정에서는 블록 안의 줄 앞에 공백 네 칸을 넣습니다. 같은 블록의 줄은 같은 깊이로 맞추고, 탭 문자와 공백을 섞지 않습니다.","아래에서는 할인 안내와 금액 차감이 둘 다 if 아래에 들어 있습니다. 조건이 참이면 두 줄을 위에서 아래로 실행하고, 거짓이면 두 줄을 모두 건너뜁니다. 마지막 print(total)은 다시 왼쪽으로 돌아와 있으므로 조건 블록 밖에 있습니다.","들여쓰기는 보기 좋게 꾸미는 여백이 아니라 문법입니다. if 다음에 실행문을 들여쓰지 않으면 IndentationError가 납니다. 반대로 조건에 넣어야 할 줄을 밖에 두면 문법상 실행되더라도 원한 동작과 달라질 수 있습니다. 콜론과 함께 어느 줄까지 같은 조건에 속하는지 확인하세요."],"code":{"source":"total = 12000\nif total >= 10000:\n    print(\"1000원 할인합니다.\")\n    total = total - 1000\nprint(total)","kind":"python","output":"1000원 할인합니다.\n11000","error":null,"caption":"total이 8000이면 할인 블록의 두 줄을 모두 건너뛰고 8000만 출력합니다."}},{"title":"조건을 비교하는 ==와 값을 대입하는 =는 다릅니다.","body":["챕터 2에서 배운 =는 오른쪽 값을 왼쪽 이름에 연결하는 대입입니다. ==는 두 값이 같은지를 비교하여 True 또는 False를 만드는 연산입니다. if 안에서 개수가 3인지 확인하려면 count == 3이라고 적습니다.","if count = 3:처럼 일반 대입을 조건 자리에 적으면 SyntaxError가 납니다. count를 3으로 바꾼 뒤 검사하는 의미가 아닙니다. if 줄 끝의 콜론이 빠져도 문법 오류이므로, 오류 종류와 표시된 줄을 읽고 대입·비교·블록 표시를 각각 확인하세요.","아래에서는 count에 3을 대입한 다음 같은 값인지 비교합니다. if가 비교식을 읽는다고 count 자체를 바꾸지는 않습니다. 조건 검사와 블록 안에서의 값 변경은 별개의 동작입니다."],"code":{"source":"count = 3\nif count == 3:\n    print(\"세 개가 준비됐습니다.\")\nprint(count)","kind":"python","output":"세 개가 준비됐습니다.\n3","error":null,"caption":"=로 값을 준비하고 ==로 조건을 확인합니다."}},{"title":"독립된 if는 차례로 각각 조건을 확인합니다.","body":["if를 두 개 적으면 두 번째 if도 자신의 조건을 확인합니다. 앞의 if가 참이었다는 이유로 다음 if를 건너뛰지 않습니다. 서로 독립된 검사라 조건이 모두 참이면 두 블록이 모두 실행될 수 있습니다.","조건은 그 줄을 만났을 때의 현재 값을 사용합니다. 아래에서는 처음 stock이 1이라 첫 조건이 참입니다. 블록에서 1을 빼면 stock은 0이 되고, 이어지는 두 번째 if가 그 새 값으로 stock == 0을 확인합니다.","if는 조건이 바뀔 때까지 기다리거나 같은 블록을 계속 반복하는 명령이 아닙니다. 이 파일을 한 번 실행하면 적힌 순서대로 각 if를 만나 한 번씩 판단하고 다음 줄로 진행합니다. 여러 경우 중 하나만 고르는 구조는 다음 레슨의 elif와 else로 이어집니다."],"code":{"source":"stock = 1\nif stock > 0:\n    print(\"한 개를 판매합니다.\")\n    stock = stock - 1\nif stock == 0:\n    print(\"재고가 없습니다.\")\nprint(stock)","kind":"python","output":"한 개를 판매합니다.\n재고가 없습니다.\n0","error":null,"caption":"두 번째 조건은 첫 블록을 실행한 뒤의 현재 재고를 읽습니다."}}],"worked":{"question":"상품 금액이 20000원 이상이면 배송비가 0원이고, 그보다 작으면 3000원입니다. 기본 배송비를 먼저 정한 뒤 if로 필요한 경우만 바꾸어, 상품 금액 25000원의 결제 금액을 구해 봅시다.","code":{"source":"amount = 25000\ndelivery = 3000\nif amount >= 20000:\n    delivery = 0\ntotal = amount + delivery\nprint(delivery)\nprint(total)","kind":"python","output":"0\n25000","error":null,"caption":"상품 금액은 0 이상의 정수라고 가정합니다. 기본값을 먼저 정하면 조건이 거짓인 경우에도 delivery를 사용할 수 있습니다."},"steps":["amount는 상품 금액 25000, delivery는 기본 배송비 3000에 연결합니다. 아직 조건을 검사하지 않았습니다.","25000 >= 20000은 True이므로 들여쓴 delivery = 0을 실행합니다. 배송비 이름이 0을 가리키도록 바뀝니다.","total 계산은 블록 밖에 있으므로 조건 검사 뒤에 실행합니다. 현재 배송비 0을 더하여 결제 금액은 25000입니다.","amount를 15000으로 바꾸어 파일을 새로 실행하면 조건이 False라 배송비 변경을 건너뜁니다. 기본값 3000이 유지되어 결제 금액은 18000입니다."],"answer":"25000원을 주문한 실행에서는 배송비 0과 결제 금액 25000을 출력합니다. 기본 배송비 설정, 조건에 따른 변경, 최종 계산의 역할을 나누면 두 경우를 같은 코드로 다룰 수 있습니다."},"misconception":{"question":"if 조건이 거짓이면 그 아래에 적힌 나머지 코드도 모두 멈추나요?","answer":"거짓일 때 건너뛰는 범위는 그 if에 속한 들여쓰기 블록입니다. 블록 밖으로 돌아온 다음 명령은 계속 실행합니다. 조건이 거짓인 것 자체는 오류가 아니며 프로그램 전체를 끝내지도 않습니다. 반대로 블록 안에 넣은 줄은 조건이 참일 때만 실행되므로 들여쓰기 범위를 먼저 읽어야 합니다."},"keypoints":["if는 조건이 참일 때 들여쓴 블록을 실행하고, 거짓이면 그 블록을 건너뜁니다. 블록 밖의 다음 명령은 이어서 실행합니다.","조건 끝에 콜론을 쓰고 같은 블록은 공백 네 칸으로 맞춥니다. =는 대입, ==는 같은 값인지 비교하는 연산입니다.","독립된 if는 각각 현재 값으로 조건을 검사합니다. 앞의 if가 실행되어도 다음 if를 건너뛰지 않으며, if 자체가 반복을 만들지는 않습니다."],"examples":[{"question":"아래 파일을 실행하기 전에 어떤 문장이 나올지 적으세요. 실행해 확인한 뒤 raining을 True로 바꾸어 다시 실행하고, 두 결과에서 공통으로 나오는 문장을 설명하세요.","skill":"불리언 조건과 실행 선택","solution":{"answer":"False일 때는 출발 준비 완료만 출력합니다. True로 바꾸면 우산을 챙기세요. 다음에 출발 준비 완료를 출력합니다. 예시 코드는 바꾼 뒤의 실행입니다.","code":{"source":"raining = True\nif raining:\n    print(\"우산을 챙기세요.\")\nprint(\"출발 준비 완료\")","kind":"python","output":"우산을 챙기세요.\n출발 준비 완료","error":null}},"explanation":"마지막 출력은 if 블록 밖에 있으므로 조건과 관계없이 실행됩니다. if가 True나 False라는 글자를 자동으로 출력하는 것은 아닙니다.","code":"raining = False\nif raining:\n    print(\"우산을 챙기세요.\")\nprint(\"출발 준비 완료\")","codeKind":"python"},{"question":"아래 코드의 출력 순서와 마지막 total을 예상한 뒤 실행하세요. total을 12000으로 바꾸어 새로 실행했을 때의 결과도 비교하고, 어느 두 줄이 함께 실행되거나 생략되는지 적으세요.","skill":"여러 줄로 이루어진 블록","solution":{"answer":"처음에는 9000 한 줄만 나옵니다. 12000으로 바꾸면 할인 적용과 11000이 차례로 나옵니다. 예시 코드는 처음 값의 실행입니다.","code":{"source":"total = 9000\nif total >= 10000:\n    print(\"할인 적용\")\n    total = total - 1000\nprint(total)","kind":"python","output":"9000","error":null}},"explanation":"안내 출력과 금액 차감은 같은 블록이므로 조건이 거짓이면 둘 다 생략됩니다. 마지막 total 출력은 밖에 있어 9000인 경우에도 실행됩니다.","code":"total = 9000\nif total >= 10000:\n    print(\"할인 적용\")\n    total = total - 1000\nprint(total)","codeKind":"python"},{"question":"아래 파일은 if 다음 줄의 들여쓰기가 빠져 실행되지 않습니다. 오류 종류를 확인한 뒤, 앞의 두 print는 조건 안에 넣고 마지막 print는 조건 밖에 두도록 고치세요. ready를 False로 바꾸었을 때는 점검 종료만 나와야 합니다.","skill":"들여쓰기로 실행 범위 수정","solution":{"answer":"처음 파일은 IndentationError가 납니다. 앞의 두 print를 네 칸 들여쓰면 준비 완료와 시작하세요.를 함께 출력한 뒤 점검 종료를 출력합니다.","code":{"source":"ready = True\nif ready:\n    print(\"준비 완료\")\n    print(\"시작하세요.\")\nprint(\"점검 종료\")","kind":"python","output":"준비 완료\n시작하세요.\n점검 종료","error":null}},"explanation":"if 뒤에는 들여쓴 실행문이 필요합니다. 두 줄을 같은 깊이로 맞추면 함께 선택되는 블록이 되고, 왼쪽으로 돌아온 마지막 줄은 어느 경우에도 실행됩니다.","code":"ready = True\nif ready:\nprint(\"준비 완료\")\nprint(\"시작하세요.\")\nprint(\"점검 종료\")","codeKind":"python"},{"question":"아래 코드를 파일로 실행해 오류 종류를 확인하세요. count의 값을 바꾸지 않고 3과 같은지 검사하도록 기호 한 곳을 고치고, count를 2로 바꾸면 어떤 출력이 남는지도 확인하세요.","skill":"대입과 비교 구분","solution":{"answer":"if 줄의 = 때문에 SyntaxError가 납니다. ==로 바꾸면 count가 3일 때 세 개와 3을 출력하고, 2일 때는 2만 출력합니다.","code":{"source":"count = 3\nif count == 3:\n    print(\"세 개\")\nprint(count)","kind":"python","output":"세 개\n3","error":null}},"explanation":"=는 이름에 값을 연결하는 대입이고 ==는 두 값의 비교입니다. 비교 결과가 참일 때만 세 개를 출력하며, 조건 검사는 count에 다른 값을 대입하지 않습니다.","code":"count = 3\nif count = 3:\n    print(\"세 개\")\nprint(count)","codeKind":"python"},{"question":"재고가 양수이면 한 개를 판매해 stock을 1 줄이고 판매 완료를 출력하세요. 이어서 독립된 if로 현재 stock이 0인지 검사하여 품절도 출력하세요. stock을 처음에 1과 2로 각각 설정해 별도로 실행하고 결과를 비교하세요.","skill":"독립된 조건과 현재 값 추적","solution":{"answer":"초기 재고가 1이면 판매 완료와 품절을 출력합니다. 2이면 판매 완료만 출력하며 남은 재고는 1입니다. 예시 코드는 재고 1의 실행입니다.","code":{"source":"stock = 1\nif stock > 0:\n    stock = stock - 1\n    print(\"판매 완료\")\nif stock == 0:\n    print(\"품절\")","kind":"python","output":"판매 완료\n품절","error":null}},"explanation":"두 번째 if는 차감이 끝난 stock을 읽습니다. 처음 값이 1이면 0이 되어 참이고, 처음 값이 2이면 1이 되어 거짓입니다. 두 조건은 각각 확인하므로 첫 블록 실행이 두 번째 검사를 막지 않습니다."}]},{"id":"python-l017","order":2,"title":"elif와 else로 경우 나누기","subtitle":"위에서부터 조건을 확인하고, 처음 맞는 경우 하나를 실행합니다.","minutes":13,"goal":"if·elif·else의 검사 순서를 추적하고, 겹치는 조건에서도 원하는 경우 하나가 선택되도록 분기를 배치한다.","intro":"앞 레슨의 if는 조건이 맞을 때 할 일을 골랐습니다. 이제 재고가 있으면 판매 가능, 없으면 품절처럼 어느 쪽이든 결과를 알려 주고 싶습니다. 또 여러 단계의 안내 중 하나를 고를 때는 독립된 if를 나열하는 것과 다른 구조가 필요합니다. elif와 else를 연결하면 한 번의 선택 안에서 경우를 나눌 수 있습니다.","sections":[{"title":"else는 앞 조건이 거짓인 경우를 맡습니다.","body":["if 아래에 else:를 연결하면 조건이 거짓일 때 실행할 블록을 정할 수 있습니다. if 조건이 참이면 if 블록을, 거짓이면 else 블록을 실행합니다. 한 번의 선택에서 두 블록이 모두 실행되지는 않습니다.","else에는 별도의 조건식을 적지 않습니다. 앞의 if 조건이 거짓이었다는 사실이 이미 선택 기준입니다. if와 else는 같은 깊이로 맞추고, 각 블록의 실행문만 네 칸 들여씁니다. 두 블록 다음의 바깥 코드는 어느 쪽을 선택해도 이어집니다.","아래 실습은 재고를 0 이상의 정수로 정합니다. stock > 0이 거짓인 입력은 이 범위에서 0이므로 품절 안내를 할 수 있습니다. 음수도 허용하는 프로그램이라면 거짓이라는 사실만으로 재고가 정확히 0이라고 말할 수 없으므로 입력의 범위와 조건을 함께 확인해야 합니다."],"code":{"source":"stock = 0\nif stock > 0:\n    print(\"판매 가능\")\nelse:\n    print(\"품절\")\nprint(\"조회 완료\")","kind":"python","output":"품절\n조회 완료","error":null,"caption":"else는 if와 같은 위치에 놓고, 각 경우의 실행문을 들여씁니다."}},{"title":"elif는 앞에서 선택되지 않았을 때 다음 조건을 검사합니다.","body":["세 가지 이상의 경우를 나누려면 if와 else 사이에 elif 조건:을 넣습니다. 위에서부터 조건을 검사하다가 처음 참인 조건을 만나면 그 블록을 실행하고, 같은 if 묶음의 나머지 elif와 else는 건너뜁니다.","아래 코드는 양수, 음수, 0을 구분합니다. number가 -4이므로 첫 number > 0은 거짓이고 다음 number < 0은 참입니다. 따라서 음수를 출력하며 마지막 else에는 들어가지 않습니다.","elif는 필요한 만큼 이어 붙일 수 있고, else는 선택 사항입니다. else가 없고 모든 조건이 거짓이면 어떤 블록도 실행하지 않은 채 뒤로 진행합니다. else가 있으면 앞의 조건이 모두 거짓일 때 그 마지막 블록을 실행합니다. 조건식 없는 else는 이 묶음의 맨 뒤에 둡니다."],"code":{"source":"number = -4\nif number > 0:\n    print(\"양수\")\nelif number < 0:\n    print(\"음수\")\nelse:\n    print(\"0\")\nprint(\"분류 완료\")","kind":"python","output":"음수\n분류 완료","error":null,"caption":"number를 0으로 바꾸면 앞의 두 조건이 모두 거짓이어서 else가 실행됩니다."}},{"title":"조건이 겹치면 검사 순서가 결과를 바꿉니다.","body":["80점 이상이면 우수, 60점 이상 80점 미만이면 통과, 그보다 낮으면 다시 연습이라는 규칙을 생각해 봅시다. 85는 score >= 80과 score >= 60을 모두 만족합니다. if 묶음은 더 알맞은 조건을 자동으로 고르지 않고 먼저 참인 조건 하나를 고릅니다.","따라서 큰 기준인 80을 먼저 확인하고, 그 조건이 거짓일 때 60을 확인합니다. elif score >= 60에 도달했다는 사실 자체가 이미 80 미만임을 알려 줍니다. 그래서 두 번째 조건에는 score < 80을 다시 적지 않아도 60 이상 80 미만의 경우가 됩니다.","반대로 score >= 60을 앞에 놓으면 85도 첫 블록에서 통과로 분류되어 뒤의 우수 블록을 검사하지 않습니다. 조건 순서를 정할 때는 각각의 식만 보지 말고, 그 줄에 도착하기 전에 어떤 조건이 거짓이었는지 함께 읽으세요. 여기서는 점수가 0부터 100까지의 정수라고 가정합니다."],"code":{"source":"score = 85\nif score >= 80:\n    print(\"우수\")\nelif score >= 60:\n    print(\"통과\")\nelse:\n    print(\"다시 연습\")","kind":"python","output":"우수","error":null,"caption":"위에서부터 큰 기준을 확인하면 겹치는 조건에서도 요구한 분류가 선택됩니다."}},{"title":"독립된 if와 연결된 elif는 다른 질문에 답합니다.","body":["독립된 if 두 개는 각 조건을 모두 확인합니다. 85점에 대해 60점 이상인지와 80점 이상인지 각각 알리고 싶다면 두 if가 맞습니다. 두 조건이 모두 참이므로 안내도 두 번 나옵니다.","반면 여러 분류 중 하나의 이름만 정하려면 if·elif·else로 연결합니다. 처음 참인 경우를 선택한 뒤 같은 묶음의 남은 조건을 검사하지 않는 것이 핵심입니다. 앞 블록이 실행되었다는 사실과 별개로 계속 확인할 조건이라면 elif로 묶지 않습니다.","if·elif·else의 한 묶음이 끝나도 프로그램 전체가 끝나는 것은 아닙니다. 바깥에 있는 다음 명령이나 또 다른 if는 계속 실행합니다. 들여쓰기와 if/elif라는 단어를 함께 읽어 하나의 선택인지 여러 개의 독립 검사인지 구분하세요."],"code":{"source":"score = 85\nif score >= 60:\n    print(\"60점 이상\")\nif score >= 80:\n    print(\"80점 이상\")\nprint(\"검사 완료\")","kind":"python","output":"60점 이상\n80점 이상\n검사 완료","error":null,"caption":"이 코드는 등급 하나를 고르는 문제가 아니라 두 사실을 각각 확인하는 코드입니다."}}],"worked":{"question":"0 이상의 정수인 주문 수량에 따라 안내 하나를 표시합니다. 10개 이상은 대량 주문, 5개 이상 10개 미만은 묶음 주문, 나머지는 일반 주문입니다. 수량 12에서는 어떤 순서로 판단해야 할까요?","code":{"source":"quantity = 12\nif quantity >= 10:\n    message = \"대량 주문\"\nelif quantity >= 5:\n    message = \"묶음 주문\"\nelse:\n    message = \"일반 주문\"\nprint(message)","kind":"python","output":"대량 주문","error":null,"caption":"세 경우 중 하나에서 message를 정한 뒤 공통 출력은 블록 밖에 둡니다."},"steps":["12 >= 10이 True이므로 첫 블록에서 message에 대량 주문을 연결합니다.","첫 블록을 선택했으므로 quantity >= 5는 검사하지 않고 else도 건너뜁니다. 두 기준을 모두 만족해도 안내는 하나만 정해집니다.","블록 밖의 print(message)가 선택된 문장을 출력합니다. 어떤 경우를 선택해도 message를 먼저 정하므로 출력 줄에서 그 값을 사용할 수 있습니다.","quantity를 7로 바꾸어 다시 실행하면 첫 조건은 거짓이고 다음 조건이 참이라 묶음 주문을 고릅니다. 3이면 두 조건이 모두 거짓이라 일반 주문을 고릅니다."],"answer":"기준 10을 먼저, 그다음 5를 검사하면 요구한 세 범위로 나뉩니다. 12개의 결과는 대량 주문이며, 처음 참인 블록 하나만 실행합니다."},"misconception":{"question":"elif 조건도 참이면 앞의 if 블록 다음에 함께 실행되나요?","answer":"같은 if·elif·else 묶음에서는 처음 참인 조건의 블록만 실행합니다. 앞의 if가 참이었다면 뒤의 elif 조건은 검사하지도 않습니다. 두 조건을 각각 확인해서 두 동작을 모두 수행하려면 독립된 if를 사용합니다. 반대로 하나의 분류만 원한다면 조건이 겹치는 값에서 어느 조건을 먼저 만나야 하는지 정해야 합니다."},"keypoints":["if·elif·else는 위에서부터 확인해 처음 참인 조건의 블록 하나를 실행합니다. 그 뒤의 같은 묶음은 건너뜁니다.","else는 조건식 없이 앞 조건이 모두 거짓인 경우를 맡습니다. else가 없으면 어떤 블록도 선택되지 않을 수 있습니다.","겹치는 조건의 순서는 결과를 바꿉니다. 독립된 if는 여러 사실을 각각 확인하고, elif로 연결한 묶음은 여러 경우 중 하나를 고릅니다."],"examples":[{"question":"아래 파일의 출력 두 줄을 예상하고 실행하세요. stock을 2로 바꾸어 다시 실행한 뒤, else에 조건식을 적지 않아도 되는 이유를 설명하세요. stock은 0 이상의 정수입니다.","skill":"else가 맡는 나머지 경우","solution":{"answer":"stock이 0이면 품절과 조회 완료, 2이면 판매 가능과 조회 완료를 출력합니다. 예시 코드는 stock이 0인 실행입니다.","code":{"source":"stock = 0\nif stock > 0:\n    print(\"판매 가능\")\nelse:\n    print(\"품절\")\nprint(\"조회 완료\")","kind":"python","output":"품절\n조회 완료","error":null}},"explanation":"else는 앞 조건이 거짓인 경우를 맡으므로 새 조건을 쓰지 않습니다. 정해진 입력 범위에서는 양수가 아닌 재고가 0이며, 마지막 출력은 선택한 블록과 관계없이 이어집니다.","code":"stock = 0\nif stock > 0:\n    print(\"판매 가능\")\nelse:\n    print(\"품절\")\nprint(\"조회 완료\")","codeKind":"python"},{"question":"정수 한 줄을 입력받아 양수, 음수, 0 중 하나를 출력하는 코드를 if·elif·else로 작성하세요. PC에서 파일을 각각 새로 실행해 4, -2, 0을 한 번씩 입력하고 결과를 비교하세요.","skill":"세 경우의 순차 검사","solution":{"answer":"4는 양수, -2는 음수, 0은 0을 출력합니다. 예시 입력 -2에서는 두 번째 조건을 선택합니다.","code":{"source":"number = int(input())\nif number > 0:\n    print(\"양수\")\nelif number < 0:\n    print(\"음수\")\nelse:\n    print(\"0\")","kind":"python","output":"음수","error":null,"input":"-2\n"}},"explanation":"먼저 양수인지 보고, 그 조건이 거짓일 때만 음수인지 봅니다. 정수가 두 조건을 모두 만족하지 않으면 0이므로 else에 그 결과를 둡니다. 입력은 단위 글자 없는 정수라고 가정합니다."},{"question":"아래 코드는 85점을 통과라고 잘못 분류합니다. 실행해 확인하고, 80점 이상은 우수·60점 이상 80점 미만은 통과·60점 미만은 다시 연습이 되도록 앞의 두 조건과 그 블록의 순서를 바꾸세요. 점수는 0~100의 정수입니다.","skill":"겹치는 조건의 검사 순서 수정","solution":{"answer":"score >= 80과 우수 출력을 앞에, score >= 60과 통과 출력을 뒤에 놓으면 85의 결과가 우수가 됩니다.","code":{"source":"score = 85\nif score >= 80:\n    print(\"우수\")\nelif score >= 60:\n    print(\"통과\")\nelse:\n    print(\"다시 연습\")","kind":"python","output":"우수","error":null}},"explanation":"원래 순서에서는 85가 첫 조건을 만족해 뒤의 조건을 검사하지 않습니다. 더 높은 기준을 먼저 두면 두 번째 블록에 도달한 점수는 이미 80 미만이어서 원하는 범위를 나눌 수 있습니다.","code":"score = 85\nif score >= 60:\n    print(\"통과\")\nelif score >= 80:\n    print(\"우수\")\nelse:\n    print(\"다시 연습\")","codeKind":"python"},{"question":"아래 코드가 몇 줄을 출력하는지 예상하고 실행하세요. 여러 안내 대신 높은 기준의 안내 하나만 남기려면 어떻게 연결해야 할까요? 두 번째 if를 elif로 고친 뒤 결과를 비교하세요.","skill":"독립된 if와 한 묶음의 차이","solution":{"answer":"원래는 우수 대상과 통과 대상 두 줄이 나옵니다. 두 번째 if를 elif로 바꾸면 우수 대상 한 줄만 나옵니다.","code":{"source":"score = 90\nif score >= 80:\n    print(\"우수 대상\")\nelif score >= 60:\n    print(\"통과 대상\")","kind":"python","output":"우수 대상","error":null}},"explanation":"두 개의 독립된 if는 각 조건을 확인하므로 둘 다 실행합니다. elif로 연결하면 앞 조건이 참이었던 실행에서 두 번째 검사를 건너뜁니다. 두 안내가 모두 필요하다면 원래의 독립 if가 맞습니다.","code":"score = 90\nif score >= 80:\n    print(\"우수 대상\")\nif score >= 60:\n    print(\"통과 대상\")","codeKind":"python"},{"question":"주문 수량이 10개 이상이면 대량, 5개 이상 10개 미만이면 묶음, 나머지는 일반을 출력하세요. 수량은 0 이상의 정수입니다. quantity를 4, 5, 10으로 바꾸어 각각 새로 실행하고 5와 10이 어느 경우에 속하는지 확인하세요.","skill":"포함하는 기준값과 분류 확인","solution":{"answer":"4는 일반, 5는 묶음, 10은 대량을 출력합니다. 예시 코드는 수량 5를 확인합니다.","code":{"source":"quantity = 5\nif quantity >= 10:\n    print(\"대량\")\nelif quantity >= 5:\n    print(\"묶음\")\nelse:\n    print(\"일반\")","kind":"python","output":"묶음","error":null}},"explanation":">=는 기준값 자체도 포함합니다. 10은 첫 조건에서 선택되고, 5는 첫 조건을 지나 두 번째에서 선택됩니다. >로 잘못 쓰면 기준값 5나 10이 아래 단계로 내려가므로 값을 바꾸어 경계를 확인합니다."}]},{"id":"python-l018","order":3,"title":"여러 조건을 연결하기","subtitle":"필요한 조건을 말로 나누고, 그 관계를 코드의 묶음과 검사 순서로 표현합니다.","minutes":14,"goal":"and·or·not으로 분기 조건을 구성하고, 괄호와 단락 평가가 실행 결과에 미치는 영향을 설명한다.","intro":"표가 있더라도 휴장 중이면 들어갈 수 없고, 회원이 아니어도 초대장이 있으면 참여할 수 있는 경우가 있습니다. 실제 요구는 한 번의 숫자 비교만으로 표현되지 않을 때가 많습니다. 챕터 2에서 배운 불리언 연산과 앞 레슨의 if를 연결해, 어떤 조건을 모두 요구하고 어떤 조건을 대신 허용하는지 코드에 드러내 봅시다.","sections":[{"title":"모두 필요한지, 하나 이상이면 되는지부터 정합니다.","body":["불리언 조건 둘을 and로 연결하면 둘 다 참이어야 전체가 참입니다. or로 연결하면 하나 이상이 참이면 되고, 둘 다 참인 경우도 포함합니다. not은 뒤 조건의 참과 거짓을 뒤집습니다. 이용 가능 여부처럼 하나의 판단을 만들려면 요구를 먼저 작은 질문으로 나누세요.","예를 들어 표가 있고 휴장이 아니어야 한다면 has_ticket and (not is_closed)로 표현합니다. 회원이거나 초대장이 있으면 되는 조건은 is_member or has_invitation입니다. 두 조건 모두 필요한 상황에 or를 쓰면 하나만 만족해도 통과하므로 요구가 달라집니다.","if는 이렇게 만든 전체 조건으로 실행할 블록을 정합니다. 비교와 논리 연산을 한 줄로 적어도, 각 이름이 어떤 질문의 답인지 분명히 하면 흐름을 따라가기 쉽습니다."],"code":{"source":"has_ticket = True\nis_closed = False\nif has_ticket and (not is_closed):\n    print(\"입장 가능\")\nelse:\n    print(\"입장 불가\")","kind":"python","output":"입장 가능","error":null,"caption":"표가 있다는 조건과 휴장이 아니라는 조건을 모두 만족합니다."}},{"title":"괄호는 어느 조건에 공통 요구를 적용할지 보여 줍니다.","body":["논리 연산은 not, and, or 순서로 묶입니다. 예를 들어 is_member or has_coupon and is_open은 is_member or (has_coupon and is_open)으로 읽습니다. 회원이 참이면 영업 중이 아니어도 전체 조건이 참이 될 수 있습니다.","회원이거나 쿠폰이 있어야 하고 누구나 영업 중일 때만 이용할 수 있다면, (is_member or has_coupon) and is_open으로 적습니다. 먼저 이용 자격을 묶고, 그 전체에 영업 조건을 적용한 것입니다. 괄호는 꾸밈이 아니라 요구의 적용 범위를 바꿀 수 있습니다.","not도 적용 범위를 살펴야 합니다. not (is_member or has_coupon)은 회원도 아니고 쿠폰도 없다는 판단입니다. not is_member or has_coupon은 회원이 아니거나 쿠폰이 있다는 다른 판단입니다. 복잡해지면 묶은 조건을 별도 이름에 연결해 읽어도 됩니다."],"code":{"source":"is_member = True\nhas_coupon = False\nis_open = False\nprint(is_member or has_coupon and is_open)\nprint((is_member or has_coupon) and is_open)\nif (is_member or has_coupon) and is_open:\n    print(\"이용 가능\")\nelse:\n    print(\"이용 불가\")","kind":"python","output":"True\nFalse\n이용 불가","error":null,"caption":"괄호로 자격 조건을 묶어야 영업 중이라는 공통 요구가 회원에게도 적용됩니다."}},{"title":"각 경우를 비교하는 식은 끝까지 적습니다.","body":["level이 \"A\" 또는 \"B\"인지를 묻고 싶다면 (level == \"A\") or (level == \"B\")로 적습니다. level == \"A\" or \"B\"라고 줄여 쓰면 Python이 생략된 level ==를 보충해 주지 않습니다. 왼쪽에는 비교 결과가 있지만 오른쪽에는 문자열 자체가 놓입니다.","비어 있지 않은 문자열 \"B\"는 조건 자리에서 참으로 판정됩니다. 따라서 level이 \"C\"여도 잘못 줄인 조건의 블록이 실행됩니다. 문자열의 참 거짓 판정은 다음 레슨에서 자세히 배우며, 지금은 다른 두 값과 비교하려면 비교식을 두 번 써야 한다는 점을 확인하세요.","숫자 범위도 (age >= 7) and (age <= 12)처럼 각 비교가 묻는 질문을 완성해 적을 수 있습니다. 두 비교에 같은 이름을 쓴다는 이유만으로 오른쪽 비교의 이름이나 기호를 생략하지 않습니다."],"code":{"source":"level = \"C\"\nif level == \"A\" or \"B\":\n    print(\"잘못된 조건: 통과\")\nif (level == \"A\") or (level == \"B\"):\n    print(\"올바른 조건: 통과\")\nelse:\n    print(\"올바른 조건: 제외\")","kind":"python","output":"잘못된 조건: 통과\n올바른 조건: 제외","error":null,"caption":"첫 조건은 문자열 B 자체를 오른쪽 값으로 사용해서 의도와 다르게 동작합니다."}},{"title":"단락 평가는 필요 없는 오른쪽 검사를 건너뜁니다.","body":["and는 왼쪽이 거짓이면 전체가 참일 수 없으므로 오른쪽을 평가하지 않습니다. or는 왼쪽이 참이면 이미 하나 이상 참이므로 오른쪽을 평가하지 않습니다. 결과를 정하는 데 필요 없는 검사를 생략하는 이 동작을 단락 평가라고 합니다. 여기서 평가는 식의 값을 구하는 일을 뜻합니다.","나누기 전에 분모가 0이 아닌지 확인할 때 이 순서가 중요합니다. count != 0 and total / count >= 5는 먼저 0 여부를 확인합니다. count가 0이면 오른쪽 나눗셈까지 가지 않습니다. 반대로 total / count >= 5 and count != 0은 위험한 나눗셈을 먼저 평가하므로 뒤의 검사가 오류를 막지 못합니다.","and와 or는 일반적으로 True나 False로 변환해서 반환하는 연산자가 아닙니다. and는 왼쪽이 거짓으로 판정되면 그 왼쪽 값을, 그렇지 않으면 오른쪽 값을 반환합니다. or는 왼쪽이 참으로 판정되면 그 왼쪽 값을, 그렇지 않으면 오른쪽 값을 반환합니다. 예를 들어 False or \"재확인\"의 결과는 문자열 \"재확인\"입니다. 비교 결과나 불리언끼리 연결한 이번 조건들은 결과도 불리언이지만 이 규칙을 다른 값 전체로 확대하지 마세요. not은 항상 불리언을 반환합니다."],"code":{"source":"total = 20\ncount = 0\nif (count != 0) and (total / count >= 5):\n    print(\"평균이 5 이상\")\nelse:\n    print(\"계산 조건을 만족하지 않음\")\nprint((count == 0) or (total / count < 5))\nprint(False or \"재확인\")","kind":"python","output":"계산 조건을 만족하지 않음\nTrue\n재확인","error":null,"caption":"두 논리식 모두 왼쪽에서 결과가 결정되어 0으로 나누는 오른쪽 식을 평가하지 않습니다."}}],"worked":{"question":"체험에 참여하려면 나이가 7세 이상 12세 이하이고, 표 또는 초대장 중 하나 이상이 있으며, 휴장이 아니어야 합니다. 조건을 이름으로 나누고 12세·표 없음·초대장 있음·휴장 아님인 경우를 확인해 보세요.","code":{"source":"age = 12\nhas_ticket = False\nhas_invitation = True\nis_closed = False\nin_range = (age >= 7) and (age <= 12)\nhas_entry = has_ticket or has_invitation\nif in_range and has_entry and (not is_closed):\n    print(\"참여 가능\")\nelse:\n    print(\"참여 불가\")","kind":"python","output":"참여 가능","error":null,"caption":"각 이름은 하나의 작은 질문을 맡고, 마지막 if가 세 요구를 모두 확인합니다."},"steps":["7 이상과 12 이하라는 두 비교가 모두 참이므로 in_range는 True입니다. <=를 사용해 12세도 허용합니다.","표가 없더라도 초대장이 있으므로 has_entry는 True입니다. or는 둘 중 하나 이상이면 참이며 둘 다 있어도 참입니다.","휴장이 아니므로 not is_closed도 True입니다. 세 조건을 and로 연결한 전체가 참이어서 참여 가능을 출력합니다."],"answer":"나이 범위·입장 자격·휴장 여부라는 세 요구를 모두 만족합니다. 자격 안에서는 표와 초대장이 대안이고, 자격과 다른 두 요구 사이에는 모두 필요하다는 관계가 있습니다."},"misconception":{"question":"and 양쪽의 조건을 바꿔 써도 항상 같은 프로그램인가요?","answer":"불리언 값들의 참 거짓 조합만 보면 순서를 바꿔도 같은 판단이 나옵니다. 하지만 실제 식은 왼쪽부터 평가되며 오른쪽을 건너뛸 수 있습니다. count != 0을 먼저 확인하면 0으로 나누는 식을 건너뛸 수 있지만, 나눗셈을 먼저 두면 그 전에 오류가 납니다. 조건의 의미뿐 아니라 안전하게 평가할 수 있는 순서도 확인해야 합니다."},"keypoints":["and는 모두, or는 하나 이상, not은 반대 판단을 표현합니다. if는 이 전체 조건으로 실행할 블록을 고릅니다.","논리 연산은 not·and·or 순서로 묶입니다. 괄호로 의도를 드러내고, 값이 A 또는 B인지 비교할 때는 각 비교식을 완성해서 씁니다.","and의 왼쪽이 거짓이거나 or의 왼쪽이 참이면 오른쪽을 평가하지 않습니다. 검사 순서로 오류를 피할 수 있으며 and·or의 반환값이 항상 불리언인 것은 아닙니다."],"examples":[{"question":"도서관 자료를 빌리려면 회원이고 연체 중이 아니어야 합니다. is_member = True, is_overdue = False에서 대출 가능을, 그렇지 않으면 대출 불가를 출력하는 if·else를 작성하세요. 연체 여부를 True로 바꾸어 다시 확인하세요.","skill":"모두 필요한 조건과 부정","solution":{"answer":"처음에는 대출 가능, 연체 중이면 대출 불가입니다. is_member and (not is_overdue)로 두 요구를 연결합니다.","code":{"source":"is_member = True\nis_overdue = False\nif is_member and (not is_overdue):\n    print(\"대출 가능\")\nelse:\n    print(\"대출 불가\")\nis_overdue = True\nif is_member and (not is_overdue):\n    print(\"대출 가능\")\nelse:\n    print(\"대출 불가\")","kind":"python","output":"대출 가능\n대출 불가","error":null}},"explanation":"회원이라는 사실만으로 대출 조건이 충분하지 않습니다. not으로 연체 중이 아니라는 조건을 만들고 and로 둘 다 요구합니다."},{"question":"아래 코드는 정기권 또는 초대장이 있고, 동시에 행사 중일 때만 입장시키려는 코드입니다. 지금은 행사가 끝났는데도 입장됩니다. 괄호를 넣어 요구에 맞게 고치고 출력 변화를 확인하세요.","skill":"공통 조건의 적용 범위","solution":{"answer":"원래는 입장 허용, 수정 뒤에는 입장 불가입니다. (has_pass or has_invitation) and event_open으로 묶습니다.","code":{"source":"has_pass = True\nhas_invitation = False\nevent_open = False\nif (has_pass or has_invitation) and event_open:\n    print(\"입장 허용\")\nelse:\n    print(\"입장 불가\")","kind":"python","output":"입장 불가","error":null}},"explanation":"괄호가 없으면 and가 먼저 묶여 행사 조건이 초대장 쪽에만 적용됩니다. 두 자격을 묶은 전체에 행사 조건을 적용해야 정기권이 있어도 행사가 끝났으면 입장할 수 없습니다.","code":"has_pass = True\nhas_invitation = False\nevent_open = False\nif has_pass or has_invitation and event_open:\n    print(\"입장 허용\")\nelse:\n    print(\"입장 불가\")","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드는 command가 \"start\" 또는 \"resume\"일 때만 실행을 허용하려고 합니다. \"stop\"에서도 실행이 출력되는 이유를 설명하고, 두 비교를 완성해 멈춤이 출력되도록 고치세요.","skill":"or 오른쪽의 생략된 비교 수정","solution":{"answer":"원래 조건의 오른쪽은 비교 결과가 아니라 비어 있지 않은 문자열입니다. (command == \"start\") or (command == \"resume\")로 고치면 멈춤입니다.","code":{"source":"command = \"stop\"\nif (command == \"start\") or (command == \"resume\"):\n    print(\"실행\")\nelse:\n    print(\"멈춤\")","kind":"python","output":"멈춤","error":null}},"explanation":"or는 앞의 비교 대상을 오른쪽에 자동으로 보충하지 않습니다. 오른쪽에서도 command를 원하는 문자열과 비교해야 합니다.","code":"command = \"stop\"\nif command == \"start\" or \"resume\":\n    print(\"실행\")\nelse:\n    print(\"멈춤\")","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드의 오류 종류를 확인하세요. count가 0일 때 나눗셈을 하지 않도록 and 양쪽의 순서를 고치세요. 수정 후 count가 0이면 계산 조건 불충족, 2이면 평균 기준 충족이 나오는지도 확인하세요.","skill":"단락 평가로 나눗셈 보호","solution":{"answer":"원래 코드는 ZeroDivisionError입니다. count != 0을 먼저 확인하면 0일 때 나눗셈을 건너뛰고, 2일 때는 평균 6이 기준을 만족합니다.","code":{"source":"total = 12\ncount = 0\nif (count != 0) and (total / count >= 5):\n    print(\"평균 기준 충족\")\nelse:\n    print(\"계산 조건 불충족\")\ncount = 2\nif (count != 0) and (total / count >= 5):\n    print(\"평균 기준 충족\")\nelse:\n    print(\"계산 조건 불충족\")","kind":"python","output":"계산 조건 불충족\n평균 기준 충족","error":null}},"explanation":"0인지 확인하는 왼쪽 비교가 거짓이면 and는 오른쪽을 평가하지 않습니다. 안전 검사를 나눗셈 뒤에 두면 이미 오류가 발생했기 때문에 보호할 수 없습니다.","code":"total = 12\ncount = 0\nif (total / count >= 5) and (count != 0):\n    print(\"평균 기준 충족\")\nelse:\n    print(\"계산 조건 불충족\")","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 두 줄이 0으로 나누는 오류 없이 어떤 값을 출력할지 예상하고 실행하세요. 이어서 False or \"안내\"의 결과와 그 타입을 출력하여 or가 항상 불리언을 만드는지 확인하세요.","skill":"건너뛴 평가와 실제 반환값","solution":{"answer":"첫 두 출력은 True와 False입니다. 추가한 식은 안내와 <class 'str'>를 출력합니다. or는 선택된 값 자체를 반환할 수 있습니다.","code":{"source":"print(True or (1 / 0 > 1))\nprint(False and (1 / 0 > 1))\nresult = False or \"안내\"\nprint(result)\nprint(type(result))","kind":"python","output":"True\nFalse\n안내\n<class 'str'>","error":null}},"explanation":"첫 줄은 or의 왼쪽이 참, 둘째 줄은 and의 왼쪽이 거짓이어서 모두 오른쪽 나눗셈을 건너뜁니다. False or \"안내\"는 왼쪽이 거짓이므로 오른쪽 문자열을 반환하며, 문자열을 불리언으로 변환하지 않습니다.","code":"print(True or (1 / 0 > 1))\nprint(False and (1 / 0 > 1))","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"}]},{"id":"python-l019","order":4,"title":"빈 값·None·참 거짓 판정","subtitle":"값이 비었는지, 아직 없는지, 숫자가 양수인지는 서로 다른 질문입니다.","minutes":14,"goal":"bool과 if의 참 거짓 판정, None 여부, 숫자 비교를 구분해 의도에 맞는 조건을 선택한다.","intro":"0점을 입력했는데 미입력으로 표시되거나, \"False\"를 읽었는데 참인 분기로 들어가는 일이 생길 수 있습니다. if에 전달하는 값이 어떤 의미인지와 Python이 그 값을 참 또는 거짓으로 판정하는 방식은 같지 않을 수 있기 때문입니다. 이번에는 빈 문자열, 숫자 0, 아직 값이 없다는 표시를 구분해 정확한 질문을 만들어 봅시다.","sections":[{"title":"bool은 조건에서 어떻게 판정되는지 보여 줍니다.","body":["if의 조건에는 비교식뿐 아니라 값 자체를 쓸 수도 있습니다. Python은 그 값을 참 또는 거짓으로 판정해 실행할 블록을 정합니다. bool(value)는 같은 판정 결과를 True나 False라는 불리언 값으로 만들어 주므로, 낯선 값이 조건에서 어떻게 읽히는지 출력해 확인할 수 있습니다.","지금까지 배운 값 중 False, 숫자 0과 0.0, 빈 문자열 \"\"는 거짓으로 판정됩니다. 0이 아닌 숫자와 비어 있지 않은 문자열은 참으로 판정됩니다. 음수도 0이 아니므로 참입니다. 이 판정은 값이 올바른 입력인지, 숫자가 양수인지를 검사한 결과가 아닙니다.","예를 들어 count가 -2이면 if count:의 블록은 실행되지만 count > 0은 False입니다. 수량이 양수인지가 요구라면 양수 비교를 직접 써야 합니다. bool은 참 거짓 판정을 보여 줄 뿐 원래 변수의 값을 바꾸지 않습니다."],"code":{"source":"print(bool(False))\nprint(bool(0))\nprint(bool(0.0))\nprint(bool(\"\"))\ncount = -2\nprint(bool(count))\nprint(count > 0)\nif count:\n    print(\"0이 아닌 수\")","kind":"python","output":"False\nFalse\nFalse\nFalse\nTrue\nFalse\n0이 아닌 수","error":null,"caption":"음수도 조건에서는 참일 수 있으므로 양수 요구는 별도 비교로 적습니다."}},{"title":"문자열의 내용은 자동으로 불리언 문법이 되지 않습니다.","body":["문자열 \"0\"은 숫자 0과 다르고, 문자열 \"False\"는 불리언 False와 다릅니다. 문자열 자체의 참 거짓은 내용이 무슨 뜻처럼 보이는지가 아니라 비어 있는지로 판정됩니다. 따라서 \"0\", \"False\", 빈칸 하나가 든 \" \"는 모두 참입니다.","input()의 반환값도 문자열입니다. 아무 글자 없이 Enter만 누르면 빈 문자열이고, 빈칸 한 개를 입력한 뒤 Enter를 누르면 빈칸이 들어 있는 문자열입니다. if text:는 빈 문자열인지만 구별하므로, 사람이 보기에 빈칸뿐인 입력까지 잘못된 입력으로 자동 판정하지는 않습니다.","입력 글자가 정확히 \"yes\"일 때만 동의로 처리하려면 text == \"yes\"처럼 명시적으로 비교합니다. bool(text)는 단어를 해석하는 변환기가 아니므로 \"False\"를 불리언 False로 읽어 주지 않습니다. 대소문자와 다른 입력을 어떻게 받을지도 프로그램의 요구로 정해야 합니다."],"code":{"source":"print(bool(\"0\"))\nprint(bool(\"False\"))\nprint(bool(\" \"))\ntext = \"False\"\nif text:\n    print(\"문자열이 비어 있지 않음\")\nprint(text == \"yes\")","kind":"python","output":"True\nTrue\nTrue\n문자열이 비어 있지 않음\nFalse","error":null,"caption":"문자열이 있는지 확인하는 조건과 특정 동의 표현인지를 비교하는 조건은 다릅니다."}},{"title":"None은 아직 값이 없다는 뜻으로 정해 사용할 수 있습니다.","body":["None은 아직 결과가 없거나 값이 주어지지 않았다는 상태를 나타낼 때 쓰는 특별한 값입니다. 첫 글자는 대문자이며 따옴표를 붙이지 않습니다. 예를 들어 score = None으로 아직 점수를 입력하지 않았음을 나타내고, score = 0으로 실제 0점을 나타내면 두 상태를 구별할 수 있습니다.","score is None은 score가 None인지를 확인하고, score is not None은 None이 아닌지를 확인합니다. None 확인에는 이 표현을 사용합니다. 이것을 일반 숫자나 문자열의 값 비교까지 확대하지 마세요. 두 숫자나 문자열의 값이 같은지는 앞에서 배운 ==로 비교하며, is와 ==는 서로 바꿔 쓰는 기호가 아닙니다.","None도 거짓으로 판정되지만 0이나 빈 문자열과 같은 값은 아닙니다. 또 score = None을 쓴 뒤에는 score라는 이름이 이미 존재하고 None에 연결되어 있습니다. 아직 대입하지 않은 이름을 읽어서 생기는 NameError와도 다릅니다. \"None\"처럼 따옴표를 붙이면 네 글자의 문자열이며 None 확인은 거짓이 됩니다."],"code":{"source":"score = None\nprint(bool(score))\nprint(score is None)\nif score is None:\n    print(\"점수 미입력\")\nscore = 0\nprint(score is not None)\nif score is not None:\n    print(\"입력한 점수:\", score)\ntext = \"None\"\nprint(text is None)","kind":"python","output":"False\nTrue\n점수 미입력\nTrue\n입력한 점수: 0\nFalse","error":null,"caption":"0점은 입력된 값이므로 None 여부를 확인하면 미입력 상태와 구분됩니다."}},{"title":"값의 존재와 그 값이 요구에 맞는지는 나누어 확인합니다.","body":["이번 예제에서 temperature는 숫자 또는 None만 갖는다고 정합니다. None이 아니면 측정값이 있다는 뜻이고, 그 숫자가 0보다 큰지는 영상인지를 묻는 다른 조건입니다. 0도와 음수 온도도 정상적인 측정값이므로 if temperature:만으로 측정 여부를 정하면 0도를 놓칩니다.","if temperature is None:에서 미측정 상태를 먼저 나누고, elif temperature > 0:에서 숫자를 비교할 수 있습니다. 앞 조건이 거짓인 경우에만 elif로 진행하므로 이 전제에서는 None을 숫자와 크기 비교하지 않습니다. None > 0은 허용되지 않아 TypeError가 나므로 비교 전에 값의 상태를 구분하는 이유이기도 합니다.","여기서 is not None은 숫자라는 검사가 아닙니다. 문자열도 None은 아니므로, 값을 숫자 또는 None으로만 정한 전제가 있어야 뒤의 숫자 비교가 맞습니다. 여러 종류의 잘못된 입력을 모두 처리하는 방법까지 이 조건 하나로 해결했다고 생각하지 않습니다."],"code":{"source":"temperature = 0\nif temperature is None:\n    print(\"미측정\")\nelif temperature > 0:\n    print(\"영상\")\nelse:\n    print(\"측정됨: 0도 이하\")\nprint(temperature is not None)\nprint(bool(temperature))","kind":"python","output":"측정됨: 0도 이하\nTrue\nFalse","error":null,"caption":"같은 값 0에 대해 측정값 존재는 참이고 참 거짓 판정은 거짓입니다."}}],"worked":{"question":"아직 작성하지 않은 점수는 None, 입력한 점수는 0~100의 정수로 저장한다고 정했습니다. 0점은 미입력이 아니라 입력된 점수로 보여 주려면 어떤 조건을 써야 할까요?","code":{"source":"score = None\nif score is None:\n    print(\"점수를 입력하세요\")\nelse:\n    print(\"입력한 점수:\", score)\nscore = 0\nif score is None:\n    print(\"점수를 입력하세요\")\nelse:\n    print(\"입력한 점수:\", score)","kind":"python","output":"점수를 입력하세요\n입력한 점수: 0","error":null,"caption":"두 번의 확인은 미입력과 실제 0점이라는 서로 다른 상태를 비교합니다."},"steps":["처음에는 score가 None이므로 score is None이 True입니다. 미입력 안내를 출력합니다.","score에 0을 대입한 뒤에는 score is None이 False입니다. else로 가서 실제 입력한 0점을 출력합니다.","if score:를 썼다면 None과 0이 둘 다 거짓이어서 구별되지 않습니다. 요구는 참으로 판정되는 값인지가 아니라 미입력 표시인 None인지 확인하는 것입니다."],"answer":"미입력을 None으로 정했다면 is None으로 확인합니다. 0도 유효한 입력값이라는 요구를 보존하려면 일반적인 참 거짓 판정과 구분해야 합니다."},"misconception":{"question":"if value:가 거짓이면 값이 없거나 잘못된 입력이라는 뜻인가요?","answer":"그렇게 단정할 수 없습니다. 0점이나 빈 문자열이 정상적인 값인 상황도 있습니다. 반대로 \"False\"나 빈칸 하나는 조건에서 참이지만 사용자가 요구한 동의나 이름이 아닐 수 있습니다. None을 미입력 표시로 정했다면 is None, 양수인지라면 > 0, 특정 문자열인지라면 ==처럼 프로그램이 실제로 묻는 질문을 적어야 합니다."},"keypoints":["bool과 if의 참 거짓 판정에서 False·0·0.0·빈 문자열·None은 거짓입니다. 0이 아닌 음수와 비어 있지 않은 문자열은 참입니다.","\"0\"·\"False\"·\" \"는 모두 비어 있지 않은 문자열입니다. bool은 글자의 의미를 해석하지 않으므로 특정 입력 요구는 명시적으로 비교합니다.","None을 값이 없는 상태로 정했다면 is None 또는 is not None으로 확인합니다. 존재 여부·양수 여부·입력의 유효성은 서로 다른 질문입니다."],"examples":[{"question":"아래 다섯 값의 bool 결과를 먼저 예상하고 실행하세요. 마지막 값 -3이 참으로 판정되는 것이 양수라는 뜻은 아닌 이유를 설명하고, -3 > 0의 결과도 출력하세요.","skill":"참 거짓 판정과 숫자 부호","solution":{"answer":"순서대로 False, False, False, False, True이며 -3 > 0은 False입니다. 0이 아닌 수는 음수라도 참입니다.","code":{"source":"print(bool(False))\nprint(bool(0))\nprint(bool(0.0))\nprint(bool(\"\"))\nprint(bool(-3))\nprint(-3 > 0)","kind":"python","output":"False\nFalse\nFalse\nFalse\nTrue\nFalse","error":null}},"explanation":"bool은 숫자의 양수 여부를 묻지 않습니다. 0인지가 참 거짓 판정에 영향을 주며, 양수 요구에는 > 0이라는 비교가 필요합니다.","code":"print(bool(False))\nprint(bool(0))\nprint(bool(0.0))\nprint(bool(\"\"))\nprint(bool(-3))","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"text를 \"0\", \"False\", 빈칸 하나인 \" \"로 각각 바꾸어 bool 결과를 확인하세요. 아래 시작 코드가 동의를 출력하는 이유를 설명하고, 정확히 \"yes\"일 때만 동의를 출력하도록 if 조건을 고치세요.","skill":"문자열의 존재와 의미 구분","solution":{"answer":"세 문자열의 bool 결과는 모두 True입니다. 조건을 text == \"yes\"로 바꾸면 주어진 \"False\"에서는 동의 아님을 출력합니다.","code":{"source":"print(bool(\"0\"))\nprint(bool(\"False\"))\nprint(bool(\" \"))\ntext = \"False\"\nif text == \"yes\":\n    print(\"동의\")\nelse:\n    print(\"동의 아님\")","kind":"python","output":"True\nTrue\nTrue\n동의 아님","error":null}},"explanation":"비어 있지 않은 문자열은 내용과 관계없이 참으로 판정됩니다. 특정 동의 표현을 확인하는 요구에는 문자열 값 비교가 맞습니다.","code":"text = \"False\"\nif text:\n    print(\"동의\")\nelse:\n    print(\"동의 아님\")","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"값을 아직 받지 못했으면 None, 받았다면 정수를 저장한다고 정했습니다. 아래 코드는 실제 값 0을 미입력으로 잘못 표시합니다. 0을 값: 0으로 출력하고 None은 미입력으로 출력하도록 고친 뒤 두 경우를 확인하세요.","skill":"None과 유효한 0 구분","solution":{"answer":"value is None으로 미입력을 확인합니다. 0은 값: 0, None은 미입력입니다.","code":{"source":"value = 0\nif value is None:\n    print(\"미입력\")\nelse:\n    print(\"값:\", value)\nvalue = None\nif value is None:\n    print(\"미입력\")\nelse:\n    print(\"값:\", value)","kind":"python","output":"값: 0\n미입력","error":null}},"explanation":"if value는 0과 None을 모두 거짓으로 판정합니다. 미입력 표시를 None으로 정했다면 None 여부를 확인해야 0을 보존할 수 있습니다.","code":"value = 0\nif value:\n    print(\"값:\", value)\nelse:\n    print(\"미입력\")","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"reading은 숫자 또는 None만 갖는다고 정했습니다. 아래 코드의 오류 종류를 확인하고, None이면 미측정, 양수면 영상, 그 밖의 숫자면 0도 이하를 출력하도록 고치세요. reading이 None일 때와 -2일 때를 확인하세요.","skill":"존재 확인 뒤 숫자 비교","solution":{"answer":"원래 None > 0에서 TypeError가 납니다. None 여부를 먼저 나눈 뒤 비교하면 None은 미측정, -2는 0도 이하입니다.","code":{"source":"reading = None\nif reading is None:\n    print(\"미측정\")\nelif reading > 0:\n    print(\"영상\")\nelse:\n    print(\"0도 이하\")\nreading = -2\nif reading is None:\n    print(\"미측정\")\nelif reading > 0:\n    print(\"영상\")\nelse:\n    print(\"0도 이하\")","kind":"python","output":"미측정\n0도 이하","error":null}},"explanation":"None은 0의 다른 표기가 아니며 숫자와 크기 비교를 할 수 없습니다. 앞의 None 분기를 통과하지 않은 경우만 숫자 비교를 하므로 정해 둔 입력 범위에서 안전하게 상태를 나눕니다.","code":"reading = None\nif reading > 0:\n    print(\"영상\")\nelse:\n    print(\"0도 이하\")","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드가 출력할 bool 결과와 None 확인 결과를 예상하고 실행하세요. 같은 두 확인을 실제 None으로도 수행하고, 따옴표가 값의 종류와 판정을 어떻게 바꾸는지 설명하세요.","skill":"None 표시와 문자열 구별","solution":{"answer":"문자열 \"None\"은 True와 False, 실제 None은 False와 True입니다. 따옴표가 있으면 값이 없다는 표시가 아니라 네 글자의 문자열입니다.","code":{"source":"value = \"None\"\nprint(bool(value))\nprint(value is None)\nvalue = None\nprint(bool(value))\nprint(value is None)","kind":"python","output":"True\nFalse\nFalse\nTrue","error":null}},"explanation":"문자열은 비어 있지 않아서 참으로 판정되고 None과는 별개입니다. 실제 None은 거짓으로 판정되며 is None 확인에서 참입니다. None인지 확인하는 is를 일반 문자열 내용 비교 대신 사용하지 않습니다.","code":"value = \"None\"\nprint(bool(value))\nprint(value is None)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"}]},{"id":"python-l020","order":5,"title":"경계값과 중첩 조건","subtitle":"조건이 바뀌는 지점과 안쪽 분기에 도달하는 경로를 확인합니다.","minutes":13,"goal":"허용 범위의 경계와 그 주변 값을 골라 분기를 검증하고, 중첩된 if의 검사 순서와 else의 소속을 설명한다.","intro":"평범한 값 하나에서 원하는 문장이 나왔다고 모든 경우가 맞는 것은 아닙니다. 최소 인원에 딱 맞는 팀이나 한도를 조금 넘는 입력은 다른 경로를 드러냅니다. 앞에서 배운 if·elif·else와 논리 연산을 사용해, 어떤 값이 어느 경우에 들어가야 하는지 먼저 정하고 실제 코드와 대조해 봅시다.","sections":[{"title":"경계를 포함하는지는 요구 문장으로 결정합니다.","body":["인원이 2명 이상 6명 이하일 때 신청할 수 있다고 정했다면 2와 6도 허용됩니다. 조건 count >= 2 and count <= 6은 두 경계를 포함합니다. >나 <로 바꾸면 같은 값은 빠집니다. 조건식을 쓰기 전에 이상·초과·이하·미만을 구별하세요.","경계값은 결과가 바뀌는 기준값입니다. 정수 인원이라면 최소 2의 주변인 1, 2, 3과 최대 6의 주변인 5, 6, 7을 확인할 수 있습니다. 4만 확인하면 등호가 빠진 실수를 놓치기 쉽습니다.","if·elif로 범위를 나눌 때는 앞 조건에서 제외된 값이 무엇인지도 생각합니다. count < 2가 거짓인 뒤 count <= 6을 검사하면, 그 분기에 도달한 값은 이미 2 이상입니다. 마지막 else는 6보다 큰 경우입니다."],"code":{"source":"count = 6\nif count < 2:\n    print(\"인원 부족\")\nelif count <= 6:\n    print(\"신청 가능\")\nelse:\n    print(\"인원 초과\")","kind":"python","output":"신청 가능","error":null}},{"title":"검사할 값은 정수인지 소수인지에 맞춰 고릅니다.","body":["정수만 허용하는 인원에서는 2 바로 아래로 1을 고르면 됩니다. 소수를 허용하는 길이나 온도에서는 기준보다 1 작은 값만으로 충분하지 않을 수 있습니다. 예를 들어 20.0 이상 25.0 이하를 허용한다면 19.9, 20.0, 20.1과 24.9, 25.0, 25.1로 경계 양쪽을 확인할 수 있습니다.","이 값들은 확인을 위한 대표 예시입니다. 모든 float 사이에 0.1 간격이 있다는 뜻은 아닙니다. 입력 규칙에 따라 더 가까운 값을 확인할 수도 있습니다. 정수 기준의 조건을 소수 입력에 그대로 옮기며 temperature <= 19와 temperature >= 20으로 나누면 19.5 같은 값이 빠집니다.","먼저 입력과 기대 결과를 작은 표로 적고, 코드의 값을 하나씩 바꾸어 새로 실행해 대조합니다. 틀린 결과가 나오면 어떤 비교가 True였는지, 어떤 분기에 도달했는지 순서대로 추적합니다. 대표값 확인은 도움이 되지만 모든 입력에 대한 완전한 증명은 아닙니다."],"code":{"kind":"text","source":"입력 온도 | 기대 결과\n19.9      | 범위 밖\n20.0      | 범위 안\n20.1      | 범위 안\n24.9      | 범위 안\n25.0      | 범위 안\n25.1      | 범위 밖","caption":"20.0 이상 25.0 이하라는 규칙을 먼저 적은 점검표입니다. 아래 예제에서는 값을 바꿔 실행하며 이런 표와 비교합니다."}},{"title":"안쪽 조건은 바깥 조건을 통과해야 검사합니다.","body":["한 경우 안에서 다시 나누는 것을 중첩 조건이라고 합니다. 시설이 열려 있을 때만 입장권을 확인한다면, 바깥 if opened: 안에 if has_ticket:을 넣을 수 있습니다. 바깥 조건이 거짓이면 안쪽 조건은 검사하지 않습니다.","바깥 블록은 공백 네 칸, 그 안쪽 블록은 다시 네 칸을 더 들여씁니다. else는 같은 들여쓰기 깊이에서 연결되는 if의 거짓인 경우를 담당합니다. 아래 안쪽 else는 입장권이 없는 경우이고, 바깥 else는 시설이 닫힌 경우입니다.","열림·입장권 두 값이 각각 True 또는 False이므로 네 조합을 살펴볼 수 있습니다. 시설이 닫혀 있다면 입장권이 있어도 닫힘 안내가 맞아야 합니다. 모든 조건을 한 줄로 합치기보다, 먼저 충족되어야 하는 단계가 있는지 살펴보세요."],"code":{"source":"opened = True\nhas_ticket = False\nif opened:\n    if has_ticket:\n        print(\"입장하세요\")\n    else:\n        print(\"입장권을 확인하세요\")\nelse:\n    print(\"시설이 닫혔습니다\")","kind":"python","output":"입장권을 확인하세요","error":null}},{"title":"정상 범위를 벗어난 값은 먼저 따로 다룹니다.","body":["입력을 숫자로 읽을 수 있다는 사실과 그 수가 문제의 허용 범위에 있다는 사실은 다릅니다. 충전량 -3은 int로 변환할 수 있지만 0부터 100까지라는 규칙에는 맞지 않습니다. 이런 값은 정상·충전 필요 같은 분류에 섞기 전에 따로 안내합니다.","아래 코드에서는 음수 또는 100 초과를 먼저 검사합니다. 그 경우가 아니라는 것이 확인된 뒤에 20 미만인지 판단합니다. 순서를 바꾸어 charge < 20부터 검사하면 -3도 충전 필요로 잘못 분류됩니다.","이 레슨의 입력 예시는 정수나 소수로 변환할 수 있는 글자를 전제로 합니다. int(input())에 \"세 개\" 같은 글을 넣으면 조건문에 도달하기 전에 ValueError가 납니다. 숫자의 허용 범위를 나누는 것과 변환 오류를 처리하는 것은 다른 작업이며, 오류 처리 문법은 뒤에서 배웁니다."],"code":{"source":"charge = int(input())\nif charge < 0 or charge > 100:\n    print(\"충전량 범위를 확인하세요\")\nelif charge < 20:\n    print(\"충전이 필요합니다\")\nelse:\n    print(\"사용할 수 있습니다\")","kind":"python","output":"충전량 범위를 확인하세요","error":null,"input":"-3\n"}}],"worked":{"question":"연습용 배송 규칙은 무게가 0보다 크고 5kg 이하일 때만 접수하며, 2kg 이하는 소형, 2kg 초과는 일반입니다. 입력 2가 어느 경로를 지나는지 설명하고 다른 경계도 점검해 봅시다.","code":{"source":"weight = float(input())\nif weight <= 0 or weight > 5:\n    print(\"접수할 수 없는 무게입니다\")\nelse:\n    if weight <= 2:\n        print(\"소형 접수\")\n    else:\n        print(\"일반 접수\")","kind":"python","output":"소형 접수","error":null,"input":"2\n"},"steps":["먼저 입력을 float로 읽습니다. 2.0은 0 이하도 5 초과도 아니므로 바깥 if가 거짓이고 바깥 else 안으로 들어갑니다.","안쪽 if는 허용된 무게에 대해서만 검사합니다. 2.0 <= 2가 True이므로 소형 접수만 출력합니다. 안쪽 else는 실행하지 않습니다.","0은 접수 불가, 0.1과 2는 소형, 2.1과 5는 일반, 5.1은 접수 불가여야 합니다. 한 번에 한 값을 입력해 실행 결과를 적으면 양끝과 소형·일반 사이의 경계를 함께 확인할 수 있습니다."],"answer":"허용 범위 확인 뒤 그 안에서 크기를 나눕니다. 2kg은 소형에 포함되고, 5kg은 일반에 포함되지만 0kg은 제외됩니다."},"misconception":{"question":"else가 있으니 잘못된 입력까지 자동으로 올바르게 처리되나요?","answer":"else는 앞 조건들이 거짓인 나머지 경우를 실행할 뿐, 그 값이 올바른 입력인지 알아서 판단하지 않습니다. 음수 충전량이 정상 범주로 들어가지 않도록 범위 규칙을 직접 적어야 합니다. 중첩된 코드의 else도 같은 깊이에서 연결된 if만 기준으로 하므로 들여쓰기와 앞에서 제외한 경우를 함께 읽어야 합니다."},"keypoints":["이상·이하에는 경계값을 포함하고 초과·미만에는 포함하지 않습니다. 경계 자체와 양쪽의 대표 입력을 기대 결과와 비교합니다.","중첩 조건은 바깥 경로에 들어가야 안쪽 조건을 검사합니다. else의 소속은 들여쓰기 깊이로 구별합니다.","입력의 종류와 허용 범위를 먼저 정합니다. 범위를 벗어난 숫자와 숫자로 바꿀 수 없는 입력은 서로 다른 문제입니다."],"examples":[{"question":"정수 인원이 2명 이상 5명 이하이면 참여 가능, 나머지는 참여 불가를 출력하는 코드를 작성하세요. count를 1, 2, 3, 4, 5, 6으로 각각 바꾸어 실행하고 기대 결과를 표로 적으세요.","skill":"경계 포함과 제외","solution":{"answer":"1과 6은 참여 불가이고 2, 3, 4, 5는 참여 가능입니다. >=와 <=로 두 경계를 포함합니다.","code":{"source":"count = 2\nif count >= 2 and count <= 5:\n    print(\"참여 가능\")\nelse:\n    print(\"참여 불가\")","kind":"python","output":"참여 가능","error":null}},"explanation":"최솟값 2와 최댓값 5뿐 아니라 양쪽의 1과 6도 확인하면 등호 누락이나 범위 밖 허용을 발견할 수 있습니다. 같은 규칙을 만족하는 if·elif 구조도 가능합니다."},{"question":"아래 코드는 온도가 20 미만이면 낮음, 20 이상이면 높음을 출력하려고 합니다. 19.5에서 무엇이 출력되는지 확인하고, 소수 입력 사이에 빈 구간이 생기지 않게 수정하세요. 19.9, 20.0, 20.1도 대조하세요.","skill":"소수 입력에서 빠진 구간","solution":{"answer":"원본은 19.5에서 아무것도 출력하지 않습니다. temperature < 20과 그 나머지를 나누면 19.5와 19.9는 낮음, 20.0과 20.1은 높음입니다.","code":{"source":"temperature = 19.5\nif temperature < 20:\n    print(\"낮음\")\nelse:\n    print(\"높음\")","kind":"python","output":"낮음","error":null}},"explanation":"정수만 생각해 <= 19와 >= 20으로 나누면 두 값 사이의 소수가 어느 조건에도 들어가지 않습니다. < 20의 거짓인 나머지는 20 이상이므로 else로 전체 경우를 나눌 수 있습니다.","code":"temperature = 19.5\nif temperature <= 19:\n    print(\"낮음\")\nelif temperature >= 20:\n    print(\"높음\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"아래 코드에서 마지막 else는 어느 if에 연결되나요? 처음 상태와 has_ticket만 True로 바꾼 상태를 각각 실행하세요. opened가 False이면 어떤 상태에서도 시설 닫힘이 나오는 이유를 설명하세요.","skill":"중첩 경로와 else 소속","solution":{"answer":"마지막 else는 opened를 검사하는 바깥 if에 연결됩니다. 두 경우 모두 시설 닫힘이 나오며 안쪽 입장권 검사는 건너뜁니다.","code":{"source":"opened = False\nhas_ticket = False\nif opened:\n    if has_ticket:\n        print(\"입장 가능\")\n    else:\n        print(\"입장권 필요\")\nelse:\n    print(\"시설 닫힘\")","kind":"python","output":"시설 닫힘","error":null}},"explanation":"else의 깊이가 바깥 if와 같으므로 시설이 닫힌 경우를 담당합니다. 안쪽 조건은 열린 경우에만 검사하므로 입장권 값만 바꿔도 닫힌 시설의 결과는 달라지지 않습니다.","code":"opened = False\nhas_ticket = False\nif opened:\n    if has_ticket:\n        print(\"입장 가능\")\n    else:\n        print(\"입장권 필요\")\nelse:\n    print(\"시설 닫힘\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"점수는 0부터 100까지의 정수이고 60 이상이면 통과입니다. 아래 코드는 -1도 다시 연습으로 분류합니다. 범위를 벗어나면 점수 오류, 허용된 점수가 60 미만이면 다시 연습, 그 외에는 통과를 출력하게 고치세요. -1, 0, 59, 60, 100, 101을 확인하세요.","skill":"허용 범위 검사 우선","solution":{"answer":"-1과 101은 점수 오류, 0과 59는 다시 연습, 60과 100은 통과입니다. 범위를 벗어나는 조건을 먼저 검사합니다.","code":{"source":"score = -1\nif score < 0 or score > 100:\n    print(\"점수 오류\")\nelif score < 60:\n    print(\"다시 연습\")\nelse:\n    print(\"통과\")","kind":"python","output":"점수 오류","error":null}},"explanation":"통과 여부를 판단하기 전에 유효한 점수인지 나누면 잘못된 값이 정상 분류에 섞이지 않습니다. 0과 100은 허용 범위의 경계이며 60은 통과 규칙의 경계입니다.","code":"score = -1\nif score < 60:\n    print(\"다시 연습\")\nelse:\n    print(\"통과\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"물품을 빌릴 수 있는 나이는 정수로 12세 이상이며, 그중 16세 미만은 보호자 동의가 필요합니다. age = 15, consent = False로 시작해 중첩 if를 작성하세요. 11세·동의 있음, 12세·동의 없음, 12세·동의 있음, 16세·동의 없음도 각각 확인하세요. 음수 나이는 입력되지 않는다고 가정합니다.","skill":"규칙이 바뀌는 경계에 중첩 조건 적용","solution":{"answer":"15세·동의 없음과 12세·동의 없음은 동의 필요입니다. 11세·동의 있음은 대여 불가, 12세·동의 있음과 16세·동의 없음은 대여 가능입니다.","code":{"source":"age = 15\nconsent = False\nif age < 12:\n    print(\"대여 불가\")\nelif age < 16:\n    if consent:\n        print(\"대여 가능\")\n    else:\n        print(\"동의 필요\")\nelse:\n    print(\"대여 가능\")","kind":"python","output":"동의 필요","error":null}},"explanation":"먼저 나이 12 미만을 제외하고, 남은 12세 이상 중 16 미만에서만 동의를 확인합니다. 16세 이상은 동의 값과 관계없이 대여 가능하므로 모든 나이에 동의를 요구하지 않습니다."}]}],"review":[{"question":"아래 코드가 출력할 줄을 순서대로 적고 실행하세요. seats가 1에서 0으로 바뀐 뒤 두 번째 if도 검사하는지, 마지막 안내가 블록 밖에 있다는 점을 설명하세요.","skill":"분기 추적 · 독립 조건과 상태 변화","solution":{"answer":"예약 완료, 매진, 확인 끝이 차례로 출력됩니다. 두 번째 if는 첫 번째 if와 별개여서 바뀐 seats가 0인지 다시 검사합니다.","code":{"source":"seats = 1\nif seats > 0:\n    seats = seats - 1\n    print(\"예약 완료\")\nif seats == 0:\n    print(\"매진\")\nprint(\"확인 끝\")","kind":"python","output":"예약 완료\n매진\n확인 끝","error":null}},"explanation":"첫 블록에서 좌석을 하나 줄인 뒤 다음 독립 if에 도달합니다. elif였다면 같은 분기 묶음에서 첫 블록이 실행된 뒤 건너뛰지만, 여기서는 새 검사입니다. 마지막 print는 들여쓰기 밖에 있어 이 흐름에서 항상 실행됩니다.","related":["python-l016","python-l017"],"code":"seats = 1\nif seats > 0:\n    seats = seats - 1\n    print(\"예약 완료\")\nif seats == 0:\n    print(\"매진\")\nprint(\"확인 끝\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"아래 코드의 출력과 실제 검사 순서를 적은 뒤 실행하세요. opened만 False로 바꿨을 때 출력도 확인하고, 그때 안쪽 paid 조건은 검사되는지 설명하세요.","skill":"분기 추적 · 바깥 경우 안의 재분류","solution":{"answer":"원래는 현장 결제, opened가 False이면 운영 종료입니다. 닫힌 경우에는 paid를 검사하지 않습니다.","code":{"source":"opened = True\npaid = False\nif opened:\n    if paid:\n        print(\"바로 입장\")\n    else:\n        print(\"현장 결제\")\nelse:\n    print(\"운영 종료\")","kind":"python","output":"현장 결제","error":null}},"explanation":"바깥 if가 True일 때만 안쪽 분기에 도달합니다. 안쪽 else는 미결제, 바깥 else는 운영 종료라는 서로 다른 경우를 담당합니다.","related":["python-l016","python-l020"],"code":"opened = True\npaid = False\nif opened:\n    if paid:\n        print(\"바로 입장\")\n    else:\n        print(\"현장 결제\")\nelse:\n    print(\"운영 종료\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"아래 코드에서 count가 0일 때 나눗셈이 실행되는지 예상하고 실행하세요. count를 2와 4로 각각 바꿨을 때 결과도 적으세요. 논리식의 두 비교를 반대 순서로 쓰면 0에서 무엇이 달라질까요?","skill":"분기 추적 · 단락 평가와 나눗셈","solution":{"answer":"0에서는 평균 조건 불충족이며 나눗셈은 생략됩니다. 2에서는 평균 5 이상, 4에서는 평균 조건 불충족입니다. 나눗셈을 먼저 검사하면 0에서 ZeroDivisionError가 납니다.","code":{"source":"total = 12\ncount = 0\nif count > 0 and total / count >= 5:\n    print(\"평균 5 이상\")\nelse:\n    print(\"평균 조건 불충족\")","kind":"python","output":"평균 조건 불충족","error":null}},"explanation":"and는 왼쪽이 거짓이면 오른쪽을 계산하지 않습니다. count > 0을 먼저 확인하여 나눌 수 있는 경로에서만 평균을 계산합니다. 12 / 2는 6.0, 12 / 4는 3.0입니다.","related":["python-l018"],"code":"total = 12\ncount = 0\nif count > 0 and total / count >= 5:\n    print(\"평균 5 이상\")\nelse:\n    print(\"평균 조건 불충족\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"행사장은 예약자 또는 초대받은 사람만 들어갈 수 있고, 운영 중이어야 합니다. reserved, invited, opened는 불리언입니다. reserved = False, invited = True, opened = True로 입장 가능 여부를 출력하세요. 같은 상태에서 opened만 False로 바꾸어 운영 종료 조건이 우선되는지도 확인하세요.","skill":"조건 설계 · 두 자격 중 하나와 공통 조건","solution":{"answer":"운영 중이고 예약 또는 초대가 있을 때 입장 가능합니다. 처음에는 입장 가능, opened가 False이면 입장 불가입니다.","code":{"source":"reserved = False\ninvited = True\nopened = True\nif opened and (reserved or invited):\n    print(\"입장 가능\")\nelse:\n    print(\"입장 불가\")","kind":"python","output":"입장 가능","error":null}},"explanation":"예약 여부와 초대 여부는 or로 묶고, 묶음 전체에 opened라는 공통 조건을 and로 붙입니다. 괄호는 운영 중이어야 한다는 요구가 두 자격 모두에 적용됨을 드러냅니다.","related":["python-l018"]},{"question":"숫자로 변환 가능한 정수 입력 한 줄을 받아 음수이면 음수, 0이면 영, 나머지는 양수를 딱 한 줄 출력하세요. -2, 0, 3으로 각각 실행하고, 어떤 정수도 빠지지 않는 이유를 설명하세요.","skill":"조건 설계 · 겹치지 않는 세 경우","solution":{"answer":"-2는 음수, 0은 영, 3은 양수입니다. if·elif·else 한 묶음으로 세 경우를 나눌 수 있습니다.","code":{"source":"number = int(input())\nif number < 0:\n    print(\"음수\")\nelif number == 0:\n    print(\"영\")\nelse:\n    print(\"양수\")","kind":"python","output":"영","error":null,"input":"0\n"}},"explanation":"0보다 작은 정수를 먼저 제외하고 0과 같은지 검사합니다. 두 조건이 모두 거짓인 나머지 정수는 양수입니다. 한 묶음이므로 세 안내가 동시에 나오지 않습니다.","related":["python-l017"]},{"question":"이름 name이 빈 문자열이면 이름 필요, 이름이 있고 agreed가 False이면 동의 필요, 두 조건을 충족하면 신청 완료를 출력하세요. name = \"민서\", agreed = False로 시작해 name을 빈 문자열로 바꾼 경우와 agreed를 True로 바꾼 경우도 따로 확인하세요. 이름은 공백만으로 입력되지 않는다고 가정합니다.","skill":"조건 설계 · 빈 문자열과 불리언","solution":{"answer":"처음은 동의 필요입니다. 이름이 빈 문자열이면 동의 값과 관계없이 이름 필요이며, 이름 민서와 agreed = True이면 신청 완료입니다.","code":{"source":"name = \"민서\"\nagreed = False\nif not name:\n    print(\"이름 필요\")\nelif not agreed:\n    print(\"동의 필요\")\nelse:\n    print(\"신청 완료\")","kind":"python","output":"동의 필요","error":null}},"explanation":"빈 문자열은 거짓으로 판정되므로 not name으로 비어 있는 경우를 먼저 구분합니다. elif에 도달했다면 이름이 있다는 조건은 이미 확인했으므로 동의 여부만 검사합니다. 공백이 있는 문자열은 빈 문자열과 다르다는 전제도 유지합니다.","related":["python-l017","python-l018","python-l019"]},{"question":"배송비는 주문 금액이 정수로 30000원 이상이면 무료이며 그 미만이면 2500원입니다. 금액은 음수가 아니라고 가정합니다. 아래 코드의 경계 오류를 고치고 29999, 30000, 30001에서 배송비를 확인하세요.","skill":"경계값 · 이상 조건의 등호","solution":{"answer":"조건을 amount >= 30000으로 바꿉니다. 배송비는 순서대로 2500, 0, 0입니다. 원본은 30000에서 2500을 출력합니다.","code":{"source":"amount = 30000\nif amount >= 30000:\n    print(0)\nelse:\n    print(2500)","kind":"python","output":"0","error":null}},"explanation":"이상이라는 요구에는 같은 값도 포함됩니다. 임의의 큰 금액만 검사하면 >와 >=가 같은 결과를 내므로 경계 자체인 30000을 꼭 확인해야 합니다.","related":["python-l016","python-l020"],"code":"amount = 30000\nif amount > 30000:\n    print(0)\nelse:\n    print(2500)","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"연습용 센서는 0.0 이상 10.0 미만을 정상 범위로 정했습니다. 소수 값을 숫자로 변환해 입력받아 정상 또는 범위 밖을 출력하세요. -0.1, 0.0, 0.1, 9.9, 10.0, 10.1의 기대 결과를 먼저 표로 적고 각각 확인하세요.","skill":"경계값 · 포함하는 최소와 제외하는 최대","solution":{"answer":"-0.1, 10.0, 10.1은 범위 밖이고 0.0, 0.1, 9.9는 정상입니다. 최소에는 >=, 최대에는 <를 씁니다.","code":{"source":"value = float(input())\nif value >= 0.0 and value < 10.0:\n    print(\"정상\")\nelse:\n    print(\"범위 밖\")","kind":"python","output":"범위 밖","error":null,"input":"10.0\n"}},"explanation":"양끝이 항상 같은 방식으로 포함되는 것은 아닙니다. 이 규칙에서는 0.0을 허용하고 10.0은 제외합니다. 소수 입력이므로 경계 바로 양쪽의 대표값으로도 확인합니다.","related":["python-l018","python-l020"]},{"question":"예약할 좌석 수는 1~4의 정수만 허용합니다. 남은 좌석 available = 2일 때 요청 wanted가 허용 범위를 벗어나면 요청 오류, 허용 범위 안이지만 남은 좌석보다 많으면 좌석 부족, 나머지는 예약 가능을 출력하세요. wanted를 0, 1, 2, 3, 4, 5로 바꿔 확인하세요.","skill":"경계값 · 입력 범위와 현재 상태 비교","solution":{"answer":"0과 5는 요청 오류, 1과 2는 예약 가능, 3과 4는 좌석 부족입니다. 먼저 요청 범위를 검사한 뒤 그 안에서 남은 좌석과 비교합니다.","code":{"source":"available = 2\nwanted = 5\nif wanted < 1 or wanted > 4:\n    print(\"요청 오류\")\nelse:\n    if wanted > available:\n        print(\"좌석 부족\")\n    else:\n        print(\"예약 가능\")","kind":"python","output":"요청 오류","error":null}},"explanation":"좌석 부족과 잘못된 요청은 다른 경우입니다. 두 조건의 순서가 뒤바뀌면 5를 요청 오류 대신 좌석 부족으로 분류할 수 있습니다. available과 같은 2는 남은 좌석에 딱 맞으므로 예약 가능합니다.","related":["python-l018","python-l020"]},{"question":"관측값 reading은 아직 측정하지 않았으면 None, 측정했다면 숫자이며 0도 유효합니다. 아래 코드를 실행한 뒤 None에서만 미측정, 0을 포함한 숫자에서는 측정값과 값을 두 줄로 출력하게 고치세요. reading을 None, 0, -2로 각각 확인하세요.","skill":"None 오개념 · 값 없음과 숫자 0","solution":{"answer":"원본은 유효한 0에도 미측정을 출력합니다. reading is None으로 검사하면 None은 미측정이고, 0과 -2는 각각 측정값 다음 줄에 해당 숫자가 출력됩니다.","code":{"source":"reading = 0\nif reading is None:\n    print(\"미측정\")\nelse:\n    print(\"측정값\")\n    print(reading)","kind":"python","output":"측정값\n0","error":null}},"explanation":"None과 0은 둘 다 조건에서 거짓으로 판정되지만 의미는 다릅니다. 측정 여부라는 요구에는 참 거짓 판정보다 None인지 확인하는 검사가 맞습니다. 숫자 비교 전에 값이 없는 경우를 나누는 데에도 이 구분을 사용합니다.","related":["python-l019"],"code":"reading = 0\nif reading:\n    print(\"측정값\")\n    print(reading)\nelse:\n    print(\"미측정\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"}]},{"id":"python-ch05","slug":"ch05","number":5,"title":"반복으로 같은 규칙 적용하기","description":"반복 대상과 종료 조건을 읽고, 합계·개수·최댓값을 갱신하며 반복 흐름을 조절합니다.","prerequisite":"선행 학습: 챕터 4 · 조건에 따라 흐름 바꾸기","runtime":"Python 3","testedVersion":"3.12.14","lessons":[{"id":"python-l021","order":1,"title":"for와 반복 대상","subtitle":"값을 하나씩 꺼내 같은 블록에 전달하면, 같은 규칙을 여러 대상에 적용할 수 있습니다.","minutes":12,"goal":"for가 반복 대상의 값을 순서대로 변수에 연결하는 흐름을 추적하고, 블록의 실행 횟수와 빈 대상의 동작을 설명한다.","intro":"여러 숫자에 10을 더하거나 여러 글자를 한 줄씩 보여 주려면 같은 모양의 명령이 필요합니다. 값을 바꿔 가며 print를 여러 번 적을 수도 있지만 대상이 늘 때마다 코드도 늘어납니다. for는 대상에서 값을 하나씩 받아 같은 명령 블록을 실행하도록 만들어, 바뀌는 값과 반복할 규칙을 분리합니다.","sections":[{"title":"for는 다음 값을 받아 블록을 다시 실행합니다.","body":["for letter in \"CAT\":은 문자열 \"CAT\"의 문자를 앞에서부터 하나씩 받아 letter라는 이름에 연결합니다. 첫 번째에는 \"C\", 다음에는 \"A\", 마지막에는 \"T\"가 letter의 값입니다. 이처럼 반복할 때마다 현재 값을 받는 이름을 반복 변수라고 부릅니다.","각 값을 받은 뒤에는 들여쓴 블록을 실행합니다. 블록 끝에 도착하면 for가 다음 값을 받아 같은 블록의 처음으로 돌아갑니다. 더 받을 값이 없으면 반복을 마치고 블록 밖의 다음 명령으로 진행합니다.","if와 마찬가지로 for 줄 끝에 콜론을 쓰고 블록 안은 공백 네 칸으로 들여씁니다. 여기의 in은 값을 차례로 받을 대상을 연결하는 for 문법입니다. 전체 문자열을 매번 받는 것이 아니라, 이 영문 문자열에서는 한 글자씩 받습니다."],"code":{"source":"for letter in \"CAT\":\n    print(letter)\nprint(\"끝\")","kind":"python","output":"C\nA\nT\n끝","error":null,"caption":"들여쓴 print는 세 번, 블록 밖의 print는 반복을 마친 뒤 한 번 실행됩니다."}},{"title":"숫자 목록도 값의 순서를 따라 반복합니다.","body":["[3, 7, -2]는 대괄호 안에 값을 쉼표로 구분하여 적은 리스트입니다. 여러 값을 순서대로 담은 묶음이라고 생각하면 됩니다. 여러 값을 함께 담는 구조를 컬렉션이라고도 부르며, 지금은 이미 적힌 목록을 읽는 데만 사용합니다. 리스트의 조회·추가·변경은 다음 챕터에서 배웁니다.","for number in [3, 7, -2]:는 number에 3, 7, -2를 차례로 연결합니다. number는 몇 번째 반복인지 세는 번호가 아니라 지금 받은 값입니다. 첫 번째 값이 3이라는 이유로 세 번 반복하거나, -2를 받았다고 뒤로 돌아가지 않습니다.","아래 블록은 현재 값에 10을 더하여 출력합니다. 목록의 항목 세 개를 한 번씩 처리하므로 출력도 세 줄입니다. 같은 값이 목록에 두 번 있으면 두 위치를 각각 처리하며, 값의 크기와 반복 횟수를 구분해야 합니다."],"code":{"source":"for number in [3, 7, -2]:\n    print(number + 10)","kind":"python","output":"13\n17\n8","error":null,"caption":"각 값에 같은 계산을 적용합니다. 더한 결과를 원래 목록에 저장하는 코드는 아닙니다."}},{"title":"반복 변수는 다음 값을 받을 때 다시 연결됩니다.","body":["반복 변수 이름은 for가 현재 값을 연결하므로 반복 전에 같은 이름을 미리 대입하지 않아도 됩니다. 블록 안에서 그 이름에 다른 값을 대입할 수는 있지만, 다음 반복이 시작되면 대상의 다음 값으로 다시 연결됩니다.","아래에서 number는 처음 2를 받고 102에 다시 연결됩니다. 다음 반복에서는 앞의 102에 1을 더하는 것이 아니라 목록의 다음 값 5를 새로 받아 105를 계산합니다. number = number + 100은 반복 변수의 연결을 바꾸며, 이 숫자 목록 안의 2와 5를 교체하는 명령은 아닙니다.","반복이 한 번 이상 실행되면 반복 변수의 마지막 값은 이후에도 남습니다. 하지만 항상 반복이 한 번 이상이라고 가정해서 밖에서 그 값을 사용하면 빈 대상에서 문제가 생길 수 있습니다. 각 항목의 처리는 우선 반복 블록 안에서 마치는 습관을 들이세요."],"code":{"source":"values = [2, 5]\nfor number in values:\n    number = number + 100\n    print(number)\nprint(values)","kind":"python","output":"102\n105\n[2, 5]","error":null,"caption":"마지막 줄은 리스트 전체를 대괄호와 쉼표가 있는 형태로 보여 줍니다. 원래 두 숫자는 바뀌지 않았습니다."}},{"title":"빈 대상은 블록을 한 번도 실행하지 않습니다.","body":["[]는 들어 있는 값이 없는 빈 리스트입니다. \"\"도 문자가 없는 빈 문자열입니다. for는 다음 값이 있어야 블록에 들어가므로 이런 대상에서는 블록이 0번 실행됩니다. 한 번 실행한 뒤 끝나는 것이 아닙니다.","반복을 시작하는 문장에 문제가 없다면, 빈 대상 자체는 오류가 아닙니다. 아래에서는 안쪽 print를 건너뛰고 바깥의 처리 완료만 출력합니다. 반복 횟수는 대상에 있는 값의 개수로 결정된다는 뜻입니다.","for가 빈 대상을 읽으면 반복 변수에 새 값을 대입하지도 않습니다. 이전에 그 이름을 만든 적이 없다면 반복 뒤에 그 이름을 읽을 때 NameError가 날 수 있습니다. 또한 정수 3은 순서대로 값을 꺼낼 수 있는 대상이 아니므로 for number in 3:은 TypeError입니다. 횟수만 정해 반복하는 방법은 다음 레슨에서 배웁니다."],"code":{"source":"for number in []:\n    print(number)\nprint(\"처리 완료\")","kind":"python","output":"처리 완료","error":null,"caption":"처리할 값이 없으면 블록 전체가 0회 실행되고 다음 명령으로 넘어갑니다."}}],"worked":{"question":"목록 [3, 7, -2]의 값마다 양수인지 검사하여 양수인 값만 출력하려고 합니다. 앞 챕터의 if를 반복 블록 안에 넣으면 어떻게 실행될까요?","code":{"source":"for number in [3, 7, -2]:\n    if number > 0:\n        print(number)\nprint(\"검사 완료\")","kind":"python","output":"3\n7\n검사 완료","error":null,"caption":"for 블록은 네 칸, 그 안의 if 블록은 한 단계 더 들어가 여덟 칸입니다."},"steps":["첫 값 3을 number에 연결하고 for 블록에 들어갑니다. 3 > 0은 참이므로 if 안에서 3을 출력합니다.","블록 끝에서 다음 값 7을 받아 같은 검사를 다시 합니다. 이번에도 참이므로 7을 출력합니다.","마지막 값 -2는 조건이 거짓이라 안쪽 print만 건너뜁니다. for 블록은 이 값에 대해서도 한 번 실행된 것입니다.","다음 값이 없으면 반복을 마칩니다. 바깥의 검사 완료는 마지막에 한 번 출력합니다. 반복은 세 번이지만 조건을 만족하는 출력은 두 번입니다."],"answer":"3과 7을 차례로 출력한 뒤 검사 완료를 출력합니다. for는 모든 항목을 받고, if는 각 항목에 대해 실행할 일을 고릅니다."},"misconception":{"question":"for number in [3, 7, -2]에서 number는 0, 1, 2라는 순서 번호가 되나요?","answer":"아닙니다. number는 목록에서 받은 실제 값 3, 7, -2를 차례로 가리킵니다. 반복 변수의 이름은 원하는 대로 붙일 수 있지만 그 이름이 자동으로 위치 번호를 뜻하지는 않습니다. 각 반복에서 어떤 값을 받는지와 몇 번 반복하는지를 따로 읽어야 합니다."},"keypoints":["for는 반복 대상에서 다음 값을 받아 변수에 연결하고 들여쓴 블록을 실행합니다. 더 받을 값이 없으면 밖으로 나갑니다.","문자열은 문자를, 숫자 리스트는 적힌 숫자를 순서대로 제공합니다. 반복 변수는 횟수나 위치가 아니라 현재 값입니다.","빈 리스트와 빈 문자열은 블록을 0번 실행합니다. 반복 변수만 재대입해도 원래 숫자 목록의 항목은 바뀌지 않습니다."],"examples":[{"question":"문자열 \"SUN\"의 문자를 for로 한 줄에 하나씩 출력하고, 반복이 끝난 뒤 완료를 한 번 출력하세요. 어느 print가 몇 번 실행되는지도 적으세요.","skill":"반복 대상과 블록 구분","solution":{"answer":"S, U, N을 한 줄씩 출력한 뒤 완료를 출력합니다. 안쪽 print는 세 번이고 바깥 print는 한 번입니다.","code":{"source":"for letter in \"SUN\":\n    print(letter)\nprint(\"완료\")","kind":"python","output":"S\nU\nN\n완료","error":null}},"explanation":"문자열의 세 문자가 순서대로 letter에 연결됩니다. 완료 출력은 들여쓰지 않아 반복 블록 밖에 있습니다."},{"question":"아래 코드의 출력 순서를 예상한 뒤 실행하세요. number가 반복 횟수가 아니라 현재 값이라는 점으로 결과를 설명하세요.","skill":"현재 값으로 계산하기","solution":{"answer":"8, 8, -2가 출력됩니다. 값 4가 두 위치에 있으므로 각각 처리합니다.","code":{"source":"for number in [4, 4, -1]:\n    print(number * 2)","kind":"python","output":"8\n8\n-2","error":null}},"explanation":"세 항목을 차례로 받아 각각 두 배를 계산합니다. 값이 중복돼도 항목을 자동으로 합치지 않고, 음수도 하나의 값으로 처리합니다.","code":"for number in [4, 4, -1]:\n    print(number * 2)","codeKind":"python"},{"question":"아래 파일을 실행해 오류 종류를 확인하세요. 정수 3이라는 값 하나를 한 번 출력하려는 요구에 맞게 반복 대상을 고치세요. 세 번 출력하는 문제는 아닙니다.","skill":"반복할 값과 횟수의 차이","solution":{"answer":"원래 정수 3은 반복 대상이 될 수 없어 TypeError가 납니다. [3]으로 감싸면 항목 한 개짜리 리스트가 되어 3을 한 번 출력합니다.","code":{"source":"for number in [3]:\n    print(number)","kind":"python","output":"3","error":null}},"explanation":"리스트 [3]은 꺼낼 값이 하나 있고 그 값이 3입니다. 항목 수와 항목의 숫자는 다르며, 반복 대상을 숫자 하나와 혼동하면 안 됩니다.","code":"for number in 3:\n    print(number)","codeKind":"python"},{"question":"아래 코드의 세 출력 결과를 먼저 예상한 뒤 실행하세요. number를 0으로 대입하는데도 다음 반복에서 8을 받는 이유와 원래 목록이 바뀌는지 설명하세요.","skill":"반복 변수의 재대입","solution":{"answer":"6, 8, [6, 8]이 차례로 출력됩니다. number에 0을 대입해도 다음 항목을 받으면 8에 다시 연결됩니다.","code":{"source":"values = [6, 8]\nfor number in values:\n    print(number)\n    number = 0\nprint(values)","kind":"python","output":"6\n8\n[6, 8]","error":null}},"explanation":"for는 각 반복 시작에 대상의 다음 값을 변수에 연결합니다. 반복 변수에 대한 대입은 여기의 숫자 리스트 항목을 바꾸지 않으므로 원래 목록은 [6, 8]입니다.","code":"values = [6, 8]\nfor number in values:\n    print(number)\n    number = 0\nprint(values)","codeKind":"python"},{"question":"아래 코드에서 반복 대상을 []로 바꾸어 실행하고, 다시 [0]으로 바꾸어 별도로 실행하세요. 두 경우에 어떤 출력이 나오는지 비교하고 0이라는 값과 값이 없는 상태를 구분하세요.","skill":"빈 대상과 값 0의 구분","solution":{"answer":"[]에서는 끝만 출력합니다. [0]에서는 0과 끝을 출력합니다. 예시 코드는 빈 목록을 확인합니다.","code":{"source":"for number in []:\n    print(number)\nprint(\"끝\")","kind":"python","output":"끝","error":null}},"explanation":"빈 목록에는 받을 값이 없어 블록이 0회 실행됩니다. [0]에는 값 0 한 개가 있으므로 블록이 한 번 실행됩니다. for는 항목을 조건의 참·거짓으로 거르는 명령이 아닙니다.","code":"for number in [2]:\n    print(number)\nprint(\"끝\")","codeKind":"python"}]},{"id":"python-l022","order":2,"title":"range와 횟수·범위","subtitle":"끝값을 제외한 정수 범위를 만들면 횟수와 번호를 직접 늘리지 않고 반복할 수 있습니다.","minutes":12,"goal":"range의 시작·끝·간격이 만드는 정수들을 읽고, 빈 범위와 반복 횟수 및 마지막 값을 구분한다.","intro":"앞 레슨에서는 문자열이나 숫자 목록의 값을 차례로 읽었습니다. 인사말을 다섯 번 출력하거나 1번부터 10번까지 번호를 붙이려면 숫자를 전부 목록에 적는 대신 일정한 규칙으로 받을 수 있으면 편리합니다. range는 정수의 시작·끝·간격을 나타내어 for에 필요한 값을 제공합니다.","sections":[{"title":"range(n)은 0부터 n 직전까지의 정수를 제공합니다.","body":["range(4)는 0, 1, 2, 3을 순서대로 제공하는 범위를 만듭니다. 괄호 안의 4는 포함하지 않는 끝값입니다. 0부터 시작하기 때문에 끝값이 양의 정수 n일 때 range(n)으로 반복하는 횟수는 n번이 됩니다.","for index in range(4):에서는 index가 각 정수를 받아 같은 블록을 실행합니다. 반복 변수에 직접 1을 더하는 줄이 없어도 for가 range의 다음 값을 연결합니다. 변수 이름이 index여서 증가하는 것이 아니라 반복 대상이 이 정수들을 제공하기 때문입니다.","range는 모든 정수를 미리 담은 리스트와는 다른 값입니다. 범위의 규칙을 보관하고 필요한 정수를 제공하므로 print(range(4))는 항목 네 개가 아니라 range(0, 4)라는 표현을 보여 줍니다. 실제 값들을 하나씩 보려면 아래처럼 for로 읽습니다."],"code":{"source":"print(range(4))\nfor index in range(4):\n    print(index)","kind":"python","output":"range(0, 4)\n0\n1\n2\n3","error":null,"caption":"출력할 횟수 네 번과 마지막으로 받는 숫자 3은 서로 다른 정보입니다."}},{"title":"시작을 적어도 끝값은 포함하지 않습니다.","body":["range(start, stop)은 start부터 시작해 stop보다 작은 정수를 1씩 증가시키며 제공합니다. range(2, 5)는 2, 3, 4를 제공하므로 세 번 반복합니다. stop이 5라는 이유로 다섯 번 반복하는 것은 아닙니다.","1부터 5까지 모두 포함하려면 range(1, 6)이라고 적습니다. 마지막으로 필요한 값보다 1 큰 경계를 두는 것입니다. 간격이 양수이면 끝 경계 자체를 선택하지 않는다는 규칙이 일관되게 적용됩니다.","반복 횟수와 표시할 번호를 구분하세요. 세 번 반복하면서 1, 2, 3을 번호로 쓰고 싶다면 range(1, 4)를 고르면 됩니다. 몇 번 처리할 것인지와 각 반복에서 필요한 값이 무엇인지 먼저 적으면 하나 차이 오류를 줄일 수 있습니다."],"code":{"source":"for number in range(2, 5):\n    print(number)\nprint(\"끝\")","kind":"python","output":"2\n3\n4\n끝","error":null,"caption":"시작 2는 포함하지만 끝 경계 5는 포함하지 않습니다."}},{"title":"간격의 부호가 진행 방향을 정합니다.","body":["range(start, stop, step)의 세 번째 정수는 다음 값으로 이동할 간격입니다. range(1, 8, 2)는 1, 3, 5, 7을 제공합니다. 매번 2를 더하며 stop보다 작은 값만 제공하고, 끝 경계 8을 넘는 다음 값 9는 제공하지 않습니다.","step이 음수이면 값이 작아집니다. range(5, 0, -2)는 5, 3, 1을 제공합니다. 이 방향에서는 stop보다 큰 동안 값을 제공하므로 0은 포함하지 않고, 다음 값 -1도 범위를 벗어나 제공하지 않습니다.","시작값이 끝보다 크다고 자동으로 감소하지 않습니다. range(5, 0)은 간격이 기본값 1이라 앞으로 갈 값이 없습니다. 감소하는 범위에는 음수 간격을 명시하세요. 간격 0은 다음 값으로 진행할 수 없어 ValueError가 납니다."],"code":{"source":"for number in range(1, 8, 2):\n    print(number)\nprint(\"거꾸로\")\nfor number in range(5, 0, -2):\n    print(number)","kind":"python","output":"1\n3\n5\n7\n거꾸로\n5\n3\n1","error":null,"caption":"간격에 맞는 값만 선택합니다. 끝 경계 가까이의 모든 정수를 반드시 방문하는 것은 아닙니다."}},{"title":"빈 범위와 항목 수를 함께 확인합니다.","body":["range(0)처럼 0에서 시작해 0 전에 멈추는 범위는 비어 있습니다. 기본 양수 간격에서 시작이 끝과 같거나 크면 받을 값이 없어서 for 블록은 0번 실행됩니다. 음수 간격에서는 시작이 끝보다 커야 값을 받을 수 있습니다.","len은 값 묶음의 항목 수를 정수로 알려 주는 기능입니다. len(range(2, 9, 3))은 2, 5, 8이라는 정수 세 개를 제공하므로 3입니다. 범위를 숫자로 출력한 모양이나 마지막 값 대신 실제 항목 수를 확인할 수 있습니다.","아래 range(5, 0)은 비어 있어서 아무 숫자도 출력하지 않습니다. 마지막 확인 완료는 블록 밖이므로 실행됩니다. range의 인수에는 여기서 사용하는 정수를 넣으며, 2.5 같은 실수 간격으로 반복하는 기능은 아닙니다."],"code":{"source":"print(len(range(2, 9, 3)))\nprint(len(range(5, 0)))\nfor number in range(5, 0):\n    print(number)\nprint(\"확인 완료\")","kind":"python","output":"3\n0\n확인 완료","error":null,"caption":"len은 마지막 정수가 아니라 범위에 들어 있는 정수의 개수를 알려 줍니다."}}],"worked":{"question":"접수 번호 1부터 4까지를 한 줄씩 출력하고 마지막에 접수 준비 완료를 한 번 알리려면 어떤 range가 필요할까요?","code":{"source":"for ticket in range(1, 5):\n    print(\"접수 \" + str(ticket))\nprint(\"접수 준비 완료\")","kind":"python","output":"접수 1\n접수 2\n접수 3\n접수 4\n접수 준비 완료","error":null,"caption":"숫자를 문장에 붙일 때는 챕터 2에서 배운 str 변환을 사용합니다."},"steps":["첫 번호가 1이므로 시작값을 1로 둡니다. 마지막 번호 4를 포함하려면 끝 경계는 5로 둡니다.","range(1, 5)는 1, 2, 3, 4를 제공하고 ticket은 각 값을 받습니다. str(ticket)으로 숫자를 문자열로 나타내 안내 문장에 붙입니다.","받을 번호가 모두 끝나면 for 밖으로 나갑니다. 마지막 안내는 들여쓰지 않았으므로 네 번이 아니라 한 번 출력됩니다."],"answer":"range(1, 5)를 사용하면 시작 번호 1부터 마지막 번호 4까지 네 번 처리합니다. 끝 경계 5는 출력하지 않습니다."},"misconception":{"question":"range(2, 5)는 2부터 5까지라서 네 번 반복하나요?","answer":"아닙니다. range는 끝 경계를 포함하지 않으므로 2, 3, 4의 세 값입니다. 5도 필요하다면 간격 1에서는 range(2, 6)을 사용합니다. 끝값, 마지막으로 제공하는 값, 항목 수는 서로 다를 수 있으므로 각각 구분해야 합니다."},"keypoints":["range(stop)은 0부터, range(start, stop)은 지정한 시작부터 정수를 제공합니다. 끝 경계 stop은 포함하지 않습니다.","step은 다음 정수까지의 간격이며 음수이면 감소합니다. 방향이 맞지 않으면 빈 범위이고, 간격 0은 ValueError입니다.","range는 리스트와 다른 범위 값입니다. for로 정수를 차례로 받고 len으로 항목 수를 확인할 수 있습니다."],"examples":[{"question":"for와 range를 사용해 준비라는 글자를 정확히 세 번 출력하세요. 반복 변수에 연결되는 세 숫자를 설명하고, 화면에 숫자도 자동으로 나오는지 확인하세요.","skill":"횟수와 출력 내용 구분","solution":{"answer":"준비가 세 줄 출력됩니다. 반복 변수는 0, 1, 2를 받지만 print에 그 변수를 적지 않아 숫자는 출력되지 않습니다.","code":{"source":"for count in range(3):\n    print(\"준비\")","kind":"python","output":"준비\n준비\n준비","error":null}},"explanation":"range(3)은 세 항목을 제공하므로 블록이 세 번 실행됩니다. 반복 변수가 값을 받는 것과 그 값을 화면에 출력하는 것은 별개입니다."},{"question":"아래 코드의 출력과 반복 횟수를 먼저 적고 실행하세요. 이어서 4도 출력되도록 끝 경계 한 곳만 고치세요.","skill":"끝을 제외하는 범위 수정","solution":{"answer":"처음에는 1, 2, 3이 세 줄 나옵니다. 끝 경계를 5로 바꾸면 1부터 4까지 네 줄을 출력합니다.","code":{"source":"for number in range(1, 5):\n    print(number)","kind":"python","output":"1\n2\n3\n4","error":null}},"explanation":"끝 경계는 제공하지 않으므로 4를 포함하려면 4 다음의 5를 경계로 둡니다. 시작값은 그대로 1입니다.","code":"for number in range(1, 4):\n    print(number)","codeKind":"python"},{"question":"아래 파일은 끝만 출력합니다. 4, 3, 2, 1을 한 줄씩 출력한 뒤 끝이 나오도록 range에 간격을 추가하고, 왜 원래 범위가 비어 있는지 설명하세요.","skill":"감소 방향과 빈 범위","solution":{"answer":"range(4, 0, -1)로 고치면 4부터 1까지 출력합니다. 원래는 간격이 +1이라 시작 4에서 0보다 작은 값으로 진행할 수 없습니다.","code":{"source":"for number in range(4, 0, -1):\n    print(number)\nprint(\"끝\")","kind":"python","output":"4\n3\n2\n1\n끝","error":null}},"explanation":"음수 간격은 값을 줄이며 끝 경계 0보다 큰 값들을 제공합니다. 시작과 끝만 적는다고 Python이 방향을 추측해서 바꾸지 않습니다.","code":"for number in range(4, 0):\n    print(number)\nprint(\"끝\")","codeKind":"python"},{"question":"아래 코드를 실행해 오류 종류를 확인하세요. 간격 한 곳만 고쳐 2, 4, 6을 차례로 출력하고, 왜 8은 포함하지 않는지도 설명하세요.","skill":"허용되지 않는 간격 수정","solution":{"answer":"간격 0은 ValueError를 일으킵니다. 2로 바꾸면 2, 4, 6을 출력합니다.","code":{"source":"for number in range(2, 8, 2):\n    print(number)","kind":"python","output":"2\n4\n6","error":null}},"explanation":"간격 0은 같은 값에서 이동하지 않으므로 range가 허용하지 않습니다. 간격 2를 사용하면 두 칸씩 진행하며 끝 경계 8 직전까지의 값만 제공합니다.","code":"for number in range(2, 8, 0):\n    print(number)","codeKind":"python"},{"question":"numbers = range(3, 11, 3)을 만들고 len(numbers)와 각 값을 한 줄씩 출력하세요. 끝 경계를 9로 바꾸어 다시 실행하면 항목 수가 왜 줄어드는지도 확인하세요.","skill":"간격이 있는 범위의 개수","solution":{"answer":"끝이 11이면 항목 수 3 다음에 3, 6, 9가 출력됩니다. 끝이 9이면 항목 수 2 다음에 3, 6만 출력됩니다.","code":{"source":"numbers = range(3, 11, 3)\nprint(len(numbers))\nfor number in numbers:\n    print(number)","kind":"python","output":"3\n3\n6\n9","error":null}},"explanation":"간격 3으로 진행하므로 3, 6, 9를 제공합니다. 끝 경계를 9로 옮기면 그 값 자체를 제외하여 9가 사라지고 항목 수도 하나 줄어듭니다."}]},{"id":"python-l023","order":3,"title":"while과 종료 조건","subtitle":"조건을 다시 검사할 때마다 달라지는 상태를 따라가면 반복이 끝나는 이유가 보입니다.","minutes":13,"goal":"while의 조건 검사·블록 실행·상태 갱신 순서를 추적하고, 최초 거짓과 종료되지 않는 반복의 원인을 구분한다.","intro":"for는 받을 값이 정해진 대상을 차례로 처리했습니다. 반면 남은 수량이 있을 동안 한 개씩 처리하는 상황에서는 지금 상태가 계속할 조건을 만족하는지 다시 확인해야 합니다. while은 조건을 먼저 검사하고, 블록을 실행한 뒤 같은 조건으로 돌아오는 반복입니다. 무엇이 달라져서 언제 거짓이 되는지가 핵심입니다.","sections":[{"title":"while은 블록 앞에서 조건을 매번 다시 검사합니다.","body":["while remaining > 0:은 현재 remaining이 0보다 큰지 확인합니다. 참이면 들여쓴 블록을 실행하고, 블록 끝에 도착하면 다시 while의 조건으로 돌아갑니다. 거짓이면 블록에 들어가지 않고 반복 다음 줄로 나갑니다.","아래에서 처음 remaining은 3입니다. 3을 출력한 뒤 1을 빼면 2가 됩니다. 다음 조건 검사는 이 새 값 2로 이루어지고, 이어서 1을 처리합니다. 마지막에 0이 되면 조건이 거짓이라 더는 블록을 실행하지 않습니다.","if도 조건을 검사하지만 블록이 끝났다고 스스로 같은 조건으로 돌아가지는 않습니다. while은 다시 검사하는 경로가 있으므로 반복합니다. 반복 상태를 바꾸는 대입이 없다면 같은 조건 결과가 계속 나올 수 있습니다."],"code":{"source":"remaining = 3\nwhile remaining > 0:\n    print(remaining)\n    remaining = remaining - 1\nprint(\"완료\")","kind":"python","output":"3\n2\n1\n완료","error":null,"caption":"조건 검사 → 블록 실행 → 상태 갱신 → 다시 조건 검사 순서로 읽습니다."}},{"title":"상태 갱신은 다음 검사에 쓸 값을 바꿉니다.","body":["while은 for의 다음 값 받기처럼 반복 변수를 자동으로 증가시키지 않습니다. 어떤 상태를 어떻게 바꿀지는 블록에 직접 적어야 합니다. 아래에서는 number = number + 1이 다음 검사에서 사용할 number를 바꿉니다.","number가 1, 2, 3일 때는 number <= 3이 참입니다. 각 값을 출력한 뒤 1을 더하고, number가 4인 상태로 조건에 돌아오면 거짓이 됩니다. 조건이 거짓이 되어 나갈 때의 값은 마지막으로 출력한 값보다 클 수 있습니다.","갱신과 출력의 순서도 결과에 영향을 줍니다. 1을 먼저 더한 뒤 출력하면 첫 출력부터 달라집니다. 조건은 블록 중간에서 계속 감시되는 것이 아니라 블록 앞에서 검사합니다. 블록 안에서 값이 바뀌어도 남은 문장은 순서대로 실행한 뒤 다음 검사를 합니다."],"code":{"source":"number = 1\nwhile number <= 3:\n    print(number)\n    number = number + 1\nprint(\"종료 시 값\")\nprint(number)","kind":"python","output":"1\n2\n3\n종료 시 값\n4","error":null,"caption":"마지막으로 블록에 들어간 값은 3이고, 조건이 거짓이 되어 나갈 때의 값은 4입니다."}},{"title":"처음부터 거짓이면 한 번도 실행하지 않습니다.","body":["while은 먼저 조건을 검사하므로 블록을 적어도 한 번 실행한다고 보장하지 않습니다. remaining이 처음부터 0이면 remaining > 0은 거짓이라 출력과 차감이 모두 생략됩니다.","이 성질 때문에 상태의 초기값도 종료 조건과 함께 확인해야 합니다. 처리할 일이 0개일 때 없는 일을 한 번 처리하지 않도록 할 수 있습니다. 반복이 끝난 뒤 필요한 안내는 블록 밖에 두면 0회인 경우에도 실행됩니다.","횟수가 분명히 정해져 있으면 range를 사용한 for가 의도를 드러내기 쉽습니다. 현재 상태가 어떤 조건을 만족하는 동안 계속할지는 while로 나타낼 수 있습니다. 어느 문법을 쓰든 처음 상태, 반복마다 할 일, 끝나는 이유가 맞아야 합니다."],"code":{"source":"remaining = 0\nwhile remaining > 0:\n    print(\"한 개 처리\")\n    remaining = remaining - 1\nprint(\"남은 작업 없음\")","kind":"python","output":"남은 작업 없음","error":null,"caption":"조건이 처음부터 거짓이라 안쪽 명령은 0회 실행됩니다."}},{"title":"언젠가 거짓이 되도록 상태와 조건을 함께 정합니다.","body":["조건에 영향을 주는 값이 그대로라서 계속 참이면 반복이 끝나지 않습니다. 이를 무한 반복이라고 합니다. 예를 들어 remaining이 3인데 while remaining > 0 안에서 remaining을 줄이지 않으면 같은 상태로 계속 돌아옵니다. 이런 코드는 실행하기 전에 읽고 고칩니다.","값을 바꾼다는 사실만으로도 충분하지 않습니다. level이 0에서 2씩 증가하면 0, 2, 4, 6처럼 바뀌어 5와 같아지지 않습니다. 이때 level != 5를 계속할 조건으로 사용하면 5를 지나쳐도 멈추지 않습니다. 목표 이상에서 끝낼 목적이면 level < 5처럼 범위를 사용해야 합니다.","아래에서는 0, 2, 4를 출력하고 갱신 후 6이 되면 조건이 거짓이라 종료합니다. 목표값 5에 정확히 도착하는 코드가 아니라 5 이상이 되면 끝내는 코드입니다. 실행 전 몇 번의 상태 변화를 적어 종료에 가까워지는지 확인하세요. 실수로 끝나지 않는 파일을 실행했다면 터미널에서는 Ctrl+C, IDLE에서는 Shell의 Interrupt Execution으로 중단할 수 있습니다."],"code":{"source":"level = 0\nwhile level < 5:\n    print(level)\n    level = level + 2\nprint(\"도달한 값\")\nprint(level)","kind":"python","output":"0\n2\n4\n도달한 값\n6","error":null,"caption":"5와 정확히 같은 순간을 기다리지 않고 5 이상이 되면 종료합니다."}}],"worked":{"question":"남은 작업량이 7이고 한 번 처리할 때마다 2씩 줄어듭니다. 남은 양이 양수인 동안 처리한 뒤 최종 값을 출력하려면 어떻게 종료를 판단해야 할까요? 음수 결과는 마지막 처리량이 남은 양을 넘어선 뜻으로 허용합니다.","code":{"source":"remaining = 7\nwhile remaining > 0:\n    print(\"처리 전: \" + str(remaining))\n    remaining = remaining - 2\nprint(\"최종: \" + str(remaining))","kind":"python","output":"처리 전: 7\n처리 전: 5\n처리 전: 3\n처리 전: 1\n최종: -1","error":null,"caption":"남은 양을 0에 정확히 맞추는 규칙이 아니라, 양수인 동안 2씩 처리하는 규칙입니다."},"steps":["remaining이 7일 때 조건이 참입니다. 현재 값을 출력한 뒤 2를 빼서 5로 갱신합니다.","다시 조건을 검사하면 5도 양수입니다. 같은 방식으로 5, 3, 1인 상태에서 블록을 실행합니다.","1에서 2를 빼면 -1이 됩니다. 다음 검사의 -1 > 0은 거짓이라 반복을 끝냅니다. remaining != 0이었다면 0을 건너뛰어서 이 규칙으로는 멈추지 않습니다.","블록 밖의 마지막 출력은 최종 상태 -1을 보여 줍니다. 몇 번 반복했는지는 실제로 조건이 참이었던 네 상태를 세어 확인합니다."],"answer":"while remaining > 0과 remaining = remaining - 2를 연결합니다. 7, 5, 3, 1에서 네 번 실행하고 최종 상태 -1에서 종료합니다."},"misconception":{"question":"while 안에서 변수를 쓰면 Python이 자동으로 1씩 바꾸나요?","answer":"아닙니다. while은 조건을 다시 검사할 뿐 상태를 자동으로 갱신하지 않습니다. 갱신 대입이나 다른 상태 변화가 있어야 다음 조건 결과가 달라질 수 있습니다. for가 반복 대상의 다음 값을 변수에 연결하는 동작과 구분하세요. 또한 값이 변하더라도 종료할 상태에 도달하지 못하면 계속 반복할 수 있습니다."},"keypoints":["while은 조건을 먼저 검사하고 참이면 블록을 실행한 뒤 다시 조건으로 돌아갑니다. 처음부터 거짓이면 블록은 0회 실행됩니다.","while은 상태를 자동으로 갱신하지 않습니다. 갱신할 값과 시점을 직접 적고, 마지막 출력값과 종료할 때의 상태를 구분합니다.","종료 조건은 실제 상태 변화로 도달할 수 있어야 합니다. 값을 건너뛸 수 있다면 정확한 일치만 기다리는 조건에 주의합니다."],"examples":[{"question":"아래 코드에서 조건을 검사할 때의 number를 순서대로 적고, 출력도 예상한 뒤 실행하세요. 마지막 조건 검사에서는 블록이 실행되는지 설명하세요.","skill":"조건 재검사와 종료 상태","solution":{"answer":"검사할 때의 값은 0, 1, 2, 3입니다. 0, 1, 2를 출력하고 3에서는 거짓이므로 종료를 출력합니다.","code":{"source":"number = 0\nwhile number < 3:\n    print(number)\n    number = number + 1\nprint(\"종료\")","kind":"python","output":"0\n1\n2\n종료","error":null}},"explanation":"세 번의 블록 실행 뒤 number가 3이 됩니다. 네 번째 검사는 종료 여부를 확인하지만 블록을 네 번째로 실행하지는 않습니다.","code":"number = 0\nwhile number < 3:\n    print(number)\n    number = number + 1\nprint(\"종료\")","codeKind":"python"},{"question":"아래 코드의 출력을 예상하고 실행하세요. number를 0에서 시작하는데 첫 출력은 왜 1이며 마지막에는 왜 3이 나오는지, 갱신과 검사 시점으로 설명하세요.","skill":"블록 안에서의 갱신 순서","solution":{"answer":"1, 2, 3이 차례로 출력됩니다. 조건 검사 때는 0, 1, 2였고 블록에 들어간 뒤 각각 1을 더해 출력했습니다.","code":{"source":"number = 0\nwhile number < 3:\n    number = number + 1\n    print(number)","kind":"python","output":"1\n2\n3","error":null}},"explanation":"조건은 블록 앞에서 검사합니다. number가 2인 상태로 들어온 마지막 블록에서 3으로 바꿔도 남은 print는 실행하고, 그다음 조건에 돌아와 종료합니다.","code":"number = 0\nwhile number < 3:\n    number = number + 1\n    print(number)","codeKind":"python"},{"question":"아래 파일에서 remaining이 0일 때의 결과를 확인하고, 1로 바꾸어 새로 실행하세요. 블록이 적어도 한 번은 실행된다는 생각이 왜 틀리는지 두 결과를 비교해 설명하세요.","skill":"처음 거짓일 때 0회 실행","solution":{"answer":"0일 때는 완료만 출력합니다. 1일 때는 처리 중과 완료를 출력합니다. 예시 코드는 0인 실행입니다.","code":{"source":"remaining = 0\nwhile remaining > 0:\n    print(\"처리 중\")\n    remaining = remaining - 1\nprint(\"완료\")","kind":"python","output":"완료","error":null}},"explanation":"조건 검사가 블록보다 먼저라서 처음부터 거짓이면 바로 밖으로 나갑니다. 초기값 1은 한 번 처리한 뒤 0이 되어 끝납니다.","code":"remaining = 0\nwhile remaining > 0:\n    print(\"처리 중\")\n    remaining = remaining - 1\nprint(\"완료\")","codeKind":"python"},{"question":"아래 코드는 그대로 실행하지 마세요. 현재 값이 바뀌지 않아 끝나지 않는 이유를 읽고 설명한 뒤, 블록 안에 갱신 한 줄을 넣어 3, 2, 1을 출력하고 끝나도록 고치세요. 고친 코드만 실행하세요.","skill":"갱신 누락으로 끝나지 않는 반복 수정","solution":{"answer":"remaining을 1 줄이는 줄을 블록 안에 추가하면 3, 2, 1을 출력하고 0에서 종료합니다.","code":{"source":"remaining = 3\nwhile remaining > 0:\n    print(remaining)\n    remaining = remaining - 1","kind":"python","output":"3\n2\n1","error":null}},"explanation":"원래 코드는 remaining이 계속 3이므로 조건도 계속 참입니다. 블록 안에서 갱신해야 다음 조건 검사에 2, 1, 0이 전달됩니다. 갱신을 블록 밖에 두면 반복을 끝내기 전에는 그 줄에 도달하지 못합니다.","code":"remaining = 3\nwhile remaining > 0:\n    print(remaining)","codeKind":"python","codeLabel":"그대로 실행하지 말고 읽고 고칠 코드"},{"question":"아래 코드는 그대로 실행하지 마세요. level의 처음 네 값을 적고 왜 5와 같아지지 않는지 설명하세요. 5 이상이 되는 순간 반복을 끝내려는 요구에 맞게 조건만 고친 뒤, 고친 코드만 실행하세요.","skill":"건너뛴 값과 도달 가능한 종료 조건","solution":{"answer":"처음 네 상태는 0, 2, 4, 6입니다. 조건을 level < 5로 바꾸면 0, 2, 4를 출력하고 6에서 종료합니다.","code":{"source":"level = 0\nwhile level < 5:\n    print(level)\n    level = level + 2","kind":"python","output":"0\n2\n4","error":null}},"explanation":"0에 2를 계속 더하면 짝수만 되어 5와 같아지지 않습니다. == 여부만 기다리는 대신 요구한 범위의 조건을 쓰면 목표를 지나쳤을 때에도 종료합니다.","code":"level = 0\nwhile level != 5:\n    print(level)\n    level = level + 2","codeKind":"python","codeLabel":"그대로 실행하지 말고 읽고 고칠 코드"}]},{"id":"python-l024","order":4,"title":"누적값과 개수 세기","subtitle":"지금까지 처리한 결과를 한 값에 모으고, 다음 값으로 갱신합니다.","minutes":13,"goal":"합계·개수·최댓값에 알맞은 초기 상태와 갱신 규칙을 정하고, 음수만 있거나 반복 대상이 비어 있을 때도 결과를 설명한다.","intro":"값을 한 번씩 출력하는 것에서 한 걸음 더 나아가 봅시다. 며칠 동안의 사용량 합계나 기준을 넘긴 횟수는 이전까지 처리한 결과를 기억해야 구할 수 있습니다. 반복 대상, 시작값, 한 번의 갱신, 마지막 결과를 나누어 생각하면 긴 목록도 작은 같은 규칙으로 처리할 수 있습니다.","sections":[{"title":"합계는 아직 더한 값이 없는 0에서 시작합니다.","body":["누적은 지금까지 얻은 결과에 새 값의 영향을 차례로 반영하는 것입니다. 합계를 담을 total을 반복 전에 0으로 두고, 항목을 하나 읽을 때마다 total = total + value를 실행합니다. 오른쪽은 이전 합계와 이번 값을 더하고, 왼쪽은 그 결과를 다음 합계로 연결합니다.","total = 0은 반복 밖에 한 번만 둡니다. 안쪽에서 매번 0으로 만들면 이전 항목의 결과를 지우므로 마지막 값만 남습니다. 시작값을 정하는 초기화와 계속 갱신하는 줄은 역할이 다릅니다.","아래 print는 반복 안에 있어 중간 합계를 보여 줍니다. 마지막 합계만 필요하면 print(total)을 반복 밖으로 옮깁니다. 숫자 목록을 모두 처리한 뒤에도 total에는 마지막 결과가 남습니다."],"code":{"source":"total = 0\nfor value in [3, 7, -2]:\n    total = total + value\n    print(total)","kind":"python","output":"3\n10\n8","error":null}},{"title":"개수는 값 자체가 아니라 한 번 처리했음을 더합니다.","body":["합계는 value를 더하지만 개수를 세는 count에는 1을 더합니다. 값이 100이어도 항목 하나를 읽은 것이므로 개수는 1만 늘어납니다. 처음에는 읽은 항목이 없어서 count = 0입니다.","정수 누적에서 count += 1은 count = count + 1을 짧게 쓴 형태입니다. 이 레슨에서는 숫자에 쓰며, 같은 기호가 다른 종류의 값에서 어떻게 동작하는지는 뒤에서 다룹니다. 짧게 쓰더라도 이전 값에 무엇을 더하는지 읽을 수 있어야 합니다.","비어 있는 목록은 []로 나타냅니다. for의 본문이 한 번도 실행되지 않으면 합계나 개수는 초기값 0으로 남습니다. 빈 경우에도 결과가 의미 있는지 초기값을 정할 때 확인합니다."],"code":{"source":"count = 0\nfor value in [100, 4, 4]:\n    count += 1\nprint(count)\nempty_count = 0\nfor value in []:\n    empty_count += 1\nprint(empty_count)","kind":"python","output":"3\n0","error":null}},{"title":"조건에 맞는 항목에만 갱신을 적용합니다.","body":["모든 값을 합칠 필요가 없다면 반복 안에서 if로 고릅니다. 아래 코드는 양수인 기록만 합계에 반영하고, 선택한 항목의 개수도 셉니다. 한 항목을 고를 때 합계와 개수를 함께 갱신해야 두 결과가 같은 대상을 가리킵니다.","value > 0이라는 조건에서는 0도 제외됩니다. 0을 포함하려는 요구라면 >= 0으로 바꾸어야 합니다. 0을 더해도 합계는 같지만 선택한 개수는 달라질 수 있으므로 합계만 보고 조건이 맞다고 판단하지 않습니다.","반복 뒤에는 total에 선택한 값의 합계, count에 선택한 개수가 남습니다. 평균을 구하려면 total / count를 계산할 수 있지만, 선택한 값이 없어 count가 0이면 나눌 수 없으므로 별도 경우로 나눕니다."],"code":{"source":"total = 0\ncount = 0\nfor value in [4, -1, 0, 6]:\n    if value > 0:\n        total = total + value\n        count = count + 1\nprint(total)\nprint(count)","kind":"python","output":"10\n2","error":null}},{"title":"최댓값은 후보가 없는 상태에서 시작할 수 있습니다.","body":["최댓값을 0에서 시작하면 모든 값이 음수일 때 목록에 없는 0이 결과가 됩니다. 처음에는 best = None으로 아직 후보가 없음을 표시하고, 첫 값을 만나면 그 값을 후보로 삼습니다. 이후에는 더 큰 값일 때만 갱신합니다.","best is None or value > best는 후보가 없거나 새 값이 기존 후보보다 클 때 참입니다. or는 왼쪽이 참이면 오른쪽을 검사하지 않으므로, 첫 항목에서 숫자와 None을 크기로 비교하지 않습니다. 앞 챕터의 None 구분과 단락 평가가 여기서 연결됩니다.","반복 대상이 []이면 best는 끝까지 None입니다. 이때는 최댓값 0이라고 꾸며 내지 않고 값 없음으로 안내합니다. None인지 확인한 뒤에만 숫자 최댓값으로 사용합니다."],"code":{"source":"best = None\nfor value in [-8, -3, -11]:\n    if best is None or value > best:\n        best = value\nif best is None:\n    print(\"값 없음\")\nelse:\n    print(best)","kind":"python","output":"-3","error":null}}],"worked":{"question":"연습 기록 [0, 12, 8, -1]에서 0 이상인 값만 유효한 공부 시간으로 봅니다. 유효 기록의 합계·개수·평균을 구할 때 0과 -1은 어떻게 다르게 처리할까요?","code":{"source":"total = 0\ncount = 0\nfor minutes in [0, 12, 8, -1]:\n    if minutes >= 0:\n        total = total + minutes\n        count = count + 1\nprint(total)\nprint(count)\nif count > 0:\n    print(total / count)\nelse:\n    print(\"유효 기록 없음\")","kind":"python","output":"20\n3\n6.666666666666667","error":null},"steps":["아직 처리한 유효 기록이 없으므로 합계와 개수를 모두 0으로 시작합니다. 0분은 유효하여 합계는 0 그대로지만 개수는 1이 됩니다.","12분과 8분을 각각 더하고 개수도 늘립니다. -1은 조건을 통과하지 못하므로 두 누적값 모두 바꾸지 않습니다. 최종 합계는 20, 개수는 3입니다.","count가 0보다 클 때만 나눕니다. 이 경우 평균은 20 / 3이며 float로 표시됩니다. 모든 기록이 제외되거나 목록이 비었다면 나눗셈 대신 유효 기록 없음으로 안내합니다."],"answer":"유효 기록 3개의 합계는 20분입니다. 0분 기록도 개수에 포함하므로 평균은 20 / 3이고, -1은 합계와 개수에서 모두 제외합니다."},"misconception":{"question":"합계나 최댓값은 모두 0으로 시작하면 되는 것 아닌가요?","answer":"합계 0은 아직 아무 값도 더하지 않았다는 뜻으로 쓸 수 있습니다. 하지만 최댓값 0은 0이라는 후보가 이미 있다는 뜻이 되어 음수만 있는 입력에서 틀립니다. 무엇을 기억하는 변수인지에 맞춰 초기값을 고르고, 반복이 한 번도 실행되지 않는 경우에도 그 뜻이 유지되는지 확인해야 합니다."},"keypoints":["누적값은 반복 전에 초기화하고, 반복 안에서 이전 결과와 이번 값으로 갱신합니다.","합계에는 값을, 개수에는 1을 더합니다. 조건으로 고른 대상이 같도록 합계와 개수를 함께 갱신합니다.","최댓값은 None으로 후보 없음에서 시작할 수 있습니다. 음수만 있는 경우와 빈 대상, 평균의 0 나누기를 따로 확인합니다."],"examples":[{"question":"아래 코드를 읽고 total의 변화와 마지막 출력을 예상한 뒤 실행하세요. 초기화 줄이 반복 안에 있어 어떤 기록이 사라지는지 설명하고, 합계 10이 나오도록 고치세요.","skill":"초기화와 갱신 위치","solution":{"answer":"원본은 5를 출력합니다. total = 0을 반복 전에 두면 2, 5, 10으로 누적되어 최종 10이 나옵니다.","code":{"source":"total = 0\nfor value in [2, 3, 5]:\n    total = total + value\nprint(total)","kind":"python","output":"10","error":null}},"explanation":"반복 안의 초기화는 각 항목을 처리하기 전에 이전 합계를 지웁니다. 초기화 한 번과 갱신 세 번을 분리해야 모든 값을 반영합니다.","code":"for value in [2, 3, 5]:\n    total = 0\n    total = total + value\nprint(total)","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"숫자 목록 [5, 5, 20]을 한 번씩 읽으며 합계와 항목 개수를 각각 구해 출력하세요. 같은 값 5가 두 번 있어도 개수에 두 번 반영되는 이유를 설명하세요.","skill":"합계와 개수의 차이","solution":{"answer":"합계는 30, 항목 개수는 3입니다. 같은 숫자도 목록의 별도 항목이므로 각각 한 번 처리합니다.","code":{"source":"total = 0\ncount = 0\nfor value in [5, 5, 20]:\n    total += value\n    count += 1\nprint(total)\nprint(count)","kind":"python","output":"30\n3","error":null}},"explanation":"total에는 이번 숫자를, count에는 항목을 처리했다는 뜻의 1을 더합니다. 서로 다른 숫자의 종류 수를 세는 것이 아닙니다."},{"question":"점수 [60, 49, 80, 60]에서 60 이상인 점수의 개수를 세세요. 처음에는 60 이상, 다음에는 조건만 60 초과로 바꾸어 각각 실행하고 경계값 60의 영향도 적으세요.","skill":"조건을 만족한 횟수 누적","solution":{"answer":"60 이상이면 3개, 60 초과이면 80 하나뿐이므로 1개입니다.","code":{"source":"count = 0\nfor score in [60, 49, 80, 60]:\n    if score >= 60:\n        count += 1\nprint(count)","kind":"python","output":"3","error":null}},"explanation":"목록을 한 항목씩 읽고 해당 조건이 참일 때만 count를 1 늘립니다. 같은 경계값이 두 번 있으므로 등호 한 개의 차이가 개수를 2만큼 바꿉니다."},{"question":"아래 코드는 최댓값을 찾으려 하지만 0을 출력합니다. None을 시작 상태로 사용하도록 고쳐 실제 최댓값 -2를 출력하세요. 목록을 []로 바꾼 경우에는 값 없음이 나오도록 하세요.","skill":"음수와 빈 대상에 맞는 최댓값","solution":{"answer":"후보가 없거나 새 값이 더 큰 때 갱신하면 -2가 나옵니다. 빈 목록에서는 best가 None이므로 값 없음으로 안내합니다.","code":{"source":"best = None\nfor value in [-9, -2, -7]:\n    if best is None or value > best:\n        best = value\nif best is None:\n    print(\"값 없음\")\nelse:\n    print(best)","kind":"python","output":"-2","error":null}},"explanation":"0은 입력 목록에 없는 값인데도 모든 음수보다 큽니다. None은 숫자 후보가 아직 없다는 상태를 구별하며, 첫 숫자를 만나면 그 숫자가 실제 후보가 됩니다.","code":"best = 0\nfor value in [-9, -2, -7]:\n    if value > best:\n        best = value\nprint(best)","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"기록 [4, 0, -3, 8]에서 양수만 골라 평균을 출력하세요. 합계와 선택 개수를 따로 누적하고, 목록을 [0, -3]으로 바꿨을 때는 나눗셈 대신 양수 기록 없음이 나오게 하세요.","skill":"누적 결과를 후속 계산에 사용","solution":{"answer":"처음에는 양수 4와 8의 합계 12를 개수 2로 나누어 6.0을 출력합니다. 두 번째 목록은 선택 개수가 0이라 양수 기록 없음입니다.","code":{"source":"total = 0\ncount = 0\nfor value in [4, 0, -3, 8]:\n    if value > 0:\n        total += value\n        count += 1\nif count > 0:\n    print(total / count)\nelse:\n    print(\"양수 기록 없음\")","kind":"python","output":"6.0","error":null}},"explanation":"평균의 분모는 모든 항목 수가 아니라 선택한 항목 수입니다. 같은 if 안에서 합계와 개수를 늘린 뒤, 반복이 끝나고 개수가 있는지 확인해 나누어야 합니다."}]},{"id":"python-l025","order":5,"title":"break·continue와 중첩 반복","subtitle":"멈출 반복과 건너뛸 한 번을 구별하고, 안쪽·바깥쪽 흐름을 읽습니다.","minutes":14,"goal":"break와 continue가 바꾸는 실행 경로를 추적하고, while의 상태 갱신과 중첩 반복의 종료 범위를 확인한다.","intro":"원하는 값을 찾았는데 남은 항목을 모두 확인할 필요가 있을까요? 처리 대상이 아닌 값 하나 때문에 나머지 기록까지 포기해야 할까요? 반복을 끝낼 때와 이번 항목만 건너뛸 때를 구분하면 목적에 맞게 흐름을 조절할 수 있습니다. 먼저 순서대로 따라 읽고, 중간에서 경로가 바뀌는 위치를 확인해 봅시다.","sections":[{"title":"break는 현재 반복을 바로 끝냅니다.","body":["break에 도달하면 자신을 직접 둘러싼 가장 안쪽 반복문을 끝내고 그 반복문 다음 줄로 이동합니다. 조건을 만족한 첫 항목만 필요할 때, 남은 항목을 처리하지 않도록 사용할 수 있습니다.","아래 코드는 5보다 큰 첫 값을 찾습니다. 4는 조건에 맞지 않아 다음 항목으로 가고, 9에서 출력 뒤 break를 실행합니다. 그 뒤의 2는 읽지 않으며 반복문 밖의 검색 끝은 실행합니다.","break는 프로그램 전체를 끝내는 명령이 아닙니다. 반복문 다음 코드도 실행됩니다. 조건을 만족하는 값이 없어 break가 한 번도 실행되지 않으면, for는 원래처럼 모든 항목을 처리하고 끝납니다."],"code":{"source":"for value in [4, 9, 2]:\n    if value > 5:\n        print(value)\n        break\nprint(\"검색 끝\")","kind":"python","output":"9\n검색 끝","error":null}},{"title":"continue는 이번 반복의 남은 부분만 건너뜁니다.","body":["continue에 도달하면 현재 한 번의 반복에서 남은 코드를 실행하지 않고 다음 반복 단계로 이동합니다. for에서는 다음 항목을 받고, while에서는 조건을 다시 검사합니다. 반복 자체를 끝내는 break와 다릅니다.","아래 코드는 음수만 건너뜁니다. -1에서는 continue 때문에 print에 도달하지 않지만, 뒤의 0과 6은 계속 처리합니다. 0을 제외하려는 것이 아니라면 < 0과 <= 0을 구분해야 합니다.","if value >= 0: 안에 처리 코드를 두어도 같은 목표를 이룰 수 있습니다. continue는 이번 항목을 제외한 뒤 아래 흐름을 진행하지 않겠다는 뜻을 분명히 나타내는 선택지입니다."],"code":{"source":"for value in [4, -1, 0, 6]:\n    if value < 0:\n        continue\n    print(value)","kind":"python","output":"4\n0\n6","error":null}},{"title":"while에서는 continue 경로에서도 상태가 바뀌어야 합니다.","body":["while의 조건이 언젠가 거짓이 되려면 그 조건에 영향을 주는 상태가 바뀌어야 합니다. 상태를 바꾸는 줄보다 앞에 continue를 넣으면 그 갱신을 건너뛰어 같은 값에서 멈추지 않을 수 있습니다.","아래에서는 먼저 number를 1 늘린 뒤 짝수인지 확인합니다. % 2가 0이면 짝수이므로 출력만 건너뜁니다. number는 모든 반복에서 증가하므로 5에 도달한 뒤 조건이 거짓이 되어 끝납니다.","조건을 만족하는 경로뿐 아니라 continue로 빠지는 경로도 따라 읽으세요. for의 다음 항목 이동과 달리 while의 숫자 갱신은 자동으로 일어나지 않습니다. 이 점을 빠뜨리면 반복 대상이 같아 보여도 종료 여부가 달라집니다."],"code":{"source":"number = 0\nwhile number < 5:\n    number = number + 1\n    if number % 2 == 0:\n        continue\n    print(number)","kind":"python","output":"1\n3\n5","error":null}},{"title":"중첩 반복에서는 안쪽 반복이 바깥 값마다 다시 시작합니다.","body":["반복 안에 다른 반복을 넣으면 바깥 항목 하나마다 안쪽 반복을 진행합니다. 아래에서는 row가 1일 때 column을 1부터 검사하고, 다음 row가 2일 때 column도 다시 1부터 시작합니다. print(row, column)은 두 값을 공백으로 구분해 같은 줄에 보여 줍니다.","column이 2일 때 break가 있으므로 각 행에서는 column 1만 출력합니다. break가 끝내는 대상은 안쪽 for뿐입니다. 바깥 for는 다음 row로 계속 이동합니다.","continue도 자신을 직접 둘러싼 반복의 다음 단계로 이동합니다. 안쪽 continue는 다음 column으로, 바깥 반복 본문에 있는 continue는 다음 row로 이동합니다. 들여쓰기와 가장 가까운 반복을 함께 읽으면 영향을 받는 범위를 구별할 수 있습니다."],"code":{"source":"for row in range(1, 3):\n    for column in range(1, 4):\n        if column == 2:\n            break\n        print(row, column)\nprint(\"전체 확인 끝\")","kind":"python","output":"1 1\n2 1\n전체 확인 끝","error":null}}],"worked":{"question":"기록 [3, -2, 4, 0, 9]를 앞에서 읽되 0을 만나면 기록 끝으로 보고 멈춥니다. 음수는 잘못된 기록으로 건너뛰고 양수만 합치려면 어떤 순서가 필요할까요?","code":{"source":"total = 0\nfor value in [3, -2, 4, 0, 9]:\n    if value == 0:\n        break\n    if value < 0:\n        continue\n    total = total + value\nprint(total)","kind":"python","output":"7","error":null},"steps":["합계를 0으로 시작합니다. 3은 종료 표시도 음수도 아니므로 합계에 더합니다.","-2는 continue로 누적 줄을 건너뛰지만 반복을 끝내지는 않습니다. 다음 4는 합계에 반영하여 7이 됩니다.","0에서 break가 실행되므로 나머지 9는 확인하지 않습니다. 반복 뒤 print가 최종 합계 7을 출력합니다. 종료 표시와 제외할 항목을 서로 다른 경로로 처리했습니다."],"answer":"break는 0 이후의 처리를 끝내고, continue는 음수 한 항목만 제외합니다. 결과에는 3과 4만 포함되어 7입니다."},"misconception":{"question":"안쪽 반복에서 break를 쓰면 바깥 반복도 함께 끝나나요?","answer":"아닙니다. break는 자신을 직접 둘러싼 가장 안쪽 반복만 끝냅니다. 바깥 반복을 끝내려면 바깥 반복에서도 종료할 조건과 흐름을 따로 정해야 합니다. continue 역시 그 반복의 다음 단계로 갈 뿐이며, 프로그램 전체나 모든 중첩 반복에 동시에 적용되지 않습니다."},"keypoints":["break는 가장 안쪽 반복을 끝내고 그 다음 줄로 이동합니다. continue는 그 반복의 이번 실행에서 남은 부분만 건너뜁니다.","while에서 continue를 만나도 종료 조건에 필요한 상태 갱신이 이루어지는지 확인합니다.","중첩 반복은 바깥 항목마다 안쪽 반복을 진행합니다. break·continue가 어느 반복에 속하는지 들여쓰기로 추적합니다."],"examples":[{"question":"아래 코드를 실행하면 무엇이 출력되는지 예상하세요. 2만 빼고 1, 3, 4를 출력하려는 의도에 맞게 한 단어를 바꾸고, break와 continue의 차이를 설명하세요.","skill":"전체 종료와 한 항목 제외","solution":{"answer":"원본은 1만 출력합니다. break를 continue로 바꾸면 2에서 출력만 건너뛰고 3과 4를 계속 처리합니다.","code":{"source":"for number in range(1, 5):\n    if number == 2:\n        continue\n    print(number)","kind":"python","output":"1\n3\n4","error":null}},"explanation":"break는 남은 항목을 모두 처리하지 않고 반복을 끝냅니다. 하나의 값만 제외하려면 다음 항목으로 이동하는 continue가 요구에 맞습니다.","code":"for number in range(1, 5):\n    if number == 2:\n        break\n    print(number)","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"숫자 목록 [8, 3, -1, 10]에서 처음 나오는 음수 직전까지만 출력하세요. 음수 자체도 출력하지 않아야 합니다. 검사와 출력의 순서를 정하고, 음수가 맨 처음인 [-1, 8]도 확인하세요.","skill":"종료 검사의 위치","solution":{"answer":"8과 3을 출력하고 -1에서 끝냅니다. [-1, 8]에서는 첫 검사에서 끝나므로 출력이 없습니다.","code":{"source":"for number in [8, 3, -1, 10]:\n    if number < 0:\n        break\n    print(number)","kind":"python","output":"8\n3","error":null}},"explanation":"음수를 발견한 뒤에도 출력하면 요구와 달라집니다. 음수 검사와 break를 출력보다 앞에 두면 종료 표시 자체와 이후 항목을 모두 제외할 수 있습니다."},{"question":"아래 코드는 1부터 4까지 중 2만 제외하려 하지만 멈추지 않습니다. 원본은 실행하지 말고, number가 2가 된 뒤 어떤 줄을 건너뛰는지 읽어 보세요. 갱신을 continue 전에 항상 수행하도록 고친 코드만 실행하세요.","skill":"continue와 while 갱신 누락","solution":{"answer":"원본은 number가 2일 때 갱신 줄을 건너뛰어 계속 2에 머뭅니다. 0에서 시작하여 반복마다 먼저 1 늘린 뒤 2를 제외하면 1, 3, 4가 출력되고 끝납니다.","code":{"source":"number = 0\nwhile number < 4:\n    number = number + 1\n    if number == 2:\n        continue\n    print(number)","kind":"python","output":"1\n3\n4","error":null}},"explanation":"while은 continue 뒤에 조건을 다시 검사할 뿐 number를 자동으로 바꾸지 않습니다. 모든 경로에서 number가 증가하도록 순서를 정하면 반복이 종료 조건 쪽으로 진행합니다.","code":"number = 1\nwhile number <= 4:\n    if number == 2:\n        continue\n    print(number)\n    number = number + 1","codeKind":"python","codeLabel":"실행하지 말고 읽고 고칠 코드"},{"question":"아래 중첩 반복의 출력 순서를 예상하고 실행하세요. 안쪽 break를 continue로 바꾸면 어떤 줄이 추가되는지도 적은 뒤 확인하세요.","skill":"중첩 반복의 제어 범위","solution":{"answer":"원본은 1 1, 2 1을 출력합니다. continue로 바꾸면 각 행에서 열 2만 건너뛰므로 1 1, 1 3, 2 1, 2 3입니다.","code":{"source":"for row in range(1, 3):\n    for column in range(1, 4):\n        if column == 2:\n            continue\n        print(row, column)","kind":"python","output":"1 1\n1 3\n2 1\n2 3","error":null}},"explanation":"break는 각 row의 안쪽 반복을 column 2에서 끝내지만 바깥 row는 이어집니다. continue는 column 2만 건너뛰므로 같은 row의 column 3에도 도달합니다.","code":"for row in range(1, 3):\n    for column in range(1, 4):\n        if column == 2:\n            break\n        print(row, column)","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"기록 [2, 5, -3, 7, 1]에서 음수는 건너뛰며 양수 합계가 10 이상이 되는 순간 멈추세요. 그 기준을 넘게 만든 값은 합계에 포함하고, 마지막 합계를 출력하세요. 누적 전과 후 중 어디에 종료 검사를 둘지도 설명하세요.","skill":"누적한 결과로 종료 결정","solution":{"answer":"2와 5를 더하고 -3을 건너뛴 뒤 7을 더하면 14입니다. 이때 멈추므로 마지막 1은 포함하지 않습니다.","code":{"source":"total = 0\nfor value in [2, 5, -3, 7, 1]:\n    if value < 0:\n        continue\n    total = total + value\n    if total >= 10:\n        break\nprint(total)","kind":"python","output":"14","error":null}},"explanation":"이번 값을 포함한 합계로 멈출지 결정해야 하므로 누적 뒤에 total >= 10을 검사합니다. 음수에서 continue를 만나면 누적과 종료 검사를 함께 건너뛰지만 다음 기록은 계속 확인합니다."}]}],"review":[{"question":"아래 코드를 읽고 출력 순서와 출력 줄 수를 예상한 뒤 실행하세요. 반복 밖의 끝은 몇 번 나오며, word가 빈 문자열이면 무엇이 출력되는지도 확인하세요.","skill":"반복 추적 · 항목과 블록 범위","solution":{"answer":"원본은 시작, A, 확인, B, 확인, 끝의 6줄입니다. word를 빈 문자열로 바꾸면 시작과 끝만 출력합니다.","code":{"source":"word = \"AB\"\nprint(\"시작\")\nfor letter in word:\n    print(letter)\n    print(\"확인\")\nprint(\"끝\")","kind":"python","output":"시작\nA\n확인\nB\n확인\n끝","error":null}},"explanation":"for 본문의 두 print가 문자마다 함께 실행됩니다. 빈 문자열에는 받을 문자가 없어 본문은 한 번도 실행되지 않지만 반복 밖의 두 출력은 남습니다.","related":["python-l021"],"code":"word = \"AB\"\nprint(\"시작\")\nfor letter in word:\n    print(letter)\n    print(\"확인\")\nprint(\"끝\")","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"아래 코드에서 while 조건을 검사할 때의 remaining 값과 출력값을 각각 순서대로 적고 실행하세요. 마지막으로 조건을 검사하지만 본문은 실행하지 않는 값도 포함하세요.","skill":"반복 추적 · 검사 시점과 갱신 시점","solution":{"answer":"조건은 remaining이 5, 3, 1, -1일 때 검사합니다. 출력은 3, 1, -1입니다. 마지막 -1에서는 조건이 거짓이어서 본문이 다시 실행되지 않습니다.","code":{"source":"remaining = 5\nwhile remaining > 0:\n    remaining = remaining - 2\n    print(remaining)","kind":"python","output":"3\n1\n-1","error":null}},"explanation":"조건은 본문에 들어가기 전에 검사하고, 출력은 2를 뺀 뒤 실행합니다. 따라서 마지막 출력이 양수여야 한다고 단정할 수 없습니다. 원하는 출력 범위와 반복 진입 조건을 구분해야 합니다.","related":["python-l023"],"code":"remaining = 5\nwhile remaining > 0:\n    remaining = remaining - 2\n    print(remaining)","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"아래 중첩 반복에서 값이 출력되는 row·column 조합을 순서대로 적은 뒤 실행하세요. column이 2에서 멈추어도 다음 row가 시작되는 이유를 설명하세요.","skill":"반복 추적 · 건너뛰기와 안쪽 종료","solution":{"answer":"1 1 다음에 2 1이 출력됩니다. 각 행에서 column 0은 continue, column 1은 출력, column 2는 break를 실행합니다.","code":{"source":"for row in range(1, 3):\n    for column in range(3):\n        if column == 0:\n            continue\n        if column == 2:\n            break\n        print(row, column)","kind":"python","output":"1 1\n2 1","error":null}},"explanation":"continue는 column 0의 남은 부분만 건너뛰고, break는 column 반복만 끝냅니다. 바깥 row는 계속 진행되며 다음 행에서도 안쪽 range를 새로 순회합니다.","related":["python-l022","python-l025"],"code":"for row in range(1, 3):\n    for column in range(3):\n        if column == 0:\n            continue\n        if column == 2:\n            break\n        print(row, column)","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"문자열 \"AABA\"를 한 글자씩 읽어 A의 개수와 전체 문자 개수를 각각 출력하세요. 문자열을 \"BBB\"와 빈 문자열로 바꾼 경우도 확인하세요. 별도의 문자열 메서드 없이 누적 변수 두 개를 사용하세요.","skill":"누적 처리 · 선택 개수와 전체 개수","solution":{"answer":"AABA에서는 A가 3개, 전체 4개입니다. BBB에서는 0과 3, 빈 문자열에서는 0과 0입니다.","code":{"source":"a_count = 0\ntotal_count = 0\nfor letter in \"AABA\":\n    total_count = total_count + 1\n    if letter == \"A\":\n        a_count = a_count + 1\nprint(a_count)\nprint(total_count)","kind":"python","output":"3\n4","error":null}},"explanation":"전체 개수는 매번 1 늘리고, A 개수는 이번 글자가 A일 때만 늘립니다. 초기화를 반복 밖에 두면 빈 문자열에서도 두 개수가 모두 0으로 남습니다.","related":["python-l021","python-l024"]},{"question":"온도 기록 [-4, 5, -9, 0, -2] 중 0 이하인 기록만 골라 그중 최댓값을 출력하세요. 양수는 후보에 넣지 않고, [3, 5]처럼 선택한 기록이 없으면 해당 기록 없음으로 안내하세요. 조건으로 고르는 단계와 최댓값 갱신 단계를 나누어 작성하세요.","skill":"누적 처리 · 조건으로 고른 최댓값","solution":{"answer":"처음 목록에서는 0 이하인 -4, -9, 0, -2 중 최댓값 0이 나옵니다. [3, 5]에서는 후보가 끝까지 None이므로 해당 기록 없음입니다.","code":{"source":"best = None\nfor temperature in [-4, 5, -9, 0, -2]:\n    if temperature <= 0:\n        if best is None or temperature > best:\n            best = temperature\nif best is None:\n    print(\"해당 기록 없음\")\nelse:\n    print(best)","kind":"python","output":"0","error":null}},"explanation":"전체 목록의 최댓값 5를 찾는 문제가 아닙니다. 바깥 if가 대상을 먼저 고르고, 안쪽 if는 그 대상 안에서만 후보를 갱신합니다. 유효한 0과 후보가 없는 None도 구분해야 합니다.","related":["python-l024"]},{"question":"순서대로 입력하는 세 줄의 작업 시간 중 음수가 아닌 값만 합계와 개수에 반영하세요. 첫 입력 5, 둘째 -1, 셋째 0을 넣어 합계와 유효 개수를 출력하고, 0이 개수에 포함되는 이유를 설명하세요. 입력은 모두 정수로 변환할 수 있다고 가정합니다.","skill":"누적 처리 · 정해진 횟수의 입력 선택","solution":{"answer":"합계는 5이고 유효 개수는 2입니다. 0도 음수가 아닌 기록이므로 개수에 포함됩니다.","code":{"source":"total = 0\ncount = 0\nfor turn in range(3):\n    minutes = int(input())\n    if minutes >= 0:\n        total = total + minutes\n        count = count + 1\nprint(total)\nprint(count)","kind":"python","output":"5\n2","error":null,"input":"5\n-1\n0\n"}},"explanation":"range(3)으로 input을 세 번 실행합니다. 각 입력을 숫자로 바꿔 조건을 확인하고, 유효한 값일 때만 합계와 개수를 함께 갱신합니다. -1은 둘 다 갱신하지 않습니다.","related":["python-l022","python-l024"]},{"question":"아래 코드는 3, 2, 1을 출력하려 하지만 멈추지 않습니다. 원본은 실행하지 말고 count의 값이 바뀌는지 읽어 확인하세요. 종료 조건으로 가까워지도록 한 줄을 추가한 코드만 실행하세요.","skill":"종료 오류 · 상태 갱신 없음","solution":{"answer":"반복 안에서 count를 1 줄이는 줄이 필요합니다. 수정 후 3, 2, 1이 출력되고 count가 0이 되면 종료됩니다.","code":{"source":"count = 3\nwhile count > 0:\n    print(count)\n    count = count - 1","kind":"python","output":"3\n2\n1","error":null}},"explanation":"출력만으로 count의 값은 변하지 않습니다. count > 0을 거짓으로 만들 수 있는 갱신이 있어야 while이 끝납니다. 반복 밖에서 한 번 줄이는 것만으로는 충분하지 않습니다.","related":["python-l023"],"code":"count = 3\nwhile count > 0:\n    print(count)","codeKind":"python","codeLabel":"실행하지 말고 읽고 고칠 코드"},{"question":"아래 코드는 row + column이 3인 첫 조합만 출력하려 하지만 다음 행에서도 검색합니다. 원본 출력을 확인한 뒤, 안쪽 반복이 끝난 자리에서 found를 검사해 바깥 반복도 종료하게 고치세요. 목표 출력은 1 2 다음 줄의 검색 끝입니다.","code":"found = False\nfor row in range(1, 4):\n    for column in range(1, 4):\n        if row + column == 3:\n            print(row, column)\n            found = True\n            break\nprint(\"검색 끝\")","codeKind":"python","codeLabel":"안쪽 반복만 끝내는 코드","skill":"종료 오류 · 중첩 반복의 종료 범위","solution":{"answer":"원본은 1 2, 2 1, 검색 끝을 출력합니다. 안쪽 for 다음이면서 바깥 for 안인 위치에 if found:와 break를 두면 첫 조합 뒤 바깥 반복도 끝납니다.","code":{"source":"found = False\nfor row in range(1, 4):\n    for column in range(1, 4):\n        if row + column == 3:\n            print(row, column)\n            found = True\n            break\n    if found:\n        break\nprint(\"검색 끝\")","kind":"python","output":"1 2\n검색 끝","error":null}},"explanation":"첫 break는 가장 안쪽 column 반복만 끝냅니다. 찾았다는 상태를 found에 남기면 바깥 반복이 이어지는 위치에서도 그 상태를 확인할 수 있습니다. 두 번째 break는 row 반복 안에서 실행되어 그 반복을 끝냅니다.","related":["python-l025"]},{"question":"1부터 n까지 모든 정수의 합계를 구하려고 아래 코드를 작성했습니다. n = 4에서 원본 출력을 확인하고, n도 포함하도록 한 곳을 수정하세요. n을 1과 0으로 바꾼 결과도 설명하세요. n은 0 이상의 정수입니다.","skill":"범위 경계 · 끝값 포함과 빈 반복","solution":{"answer":"원본은 6을 출력합니다. range(1, n + 1)로 고치면 n = 4는 10, n = 1은 1, n = 0은 0입니다.","code":{"source":"n = 4\ntotal = 0\nfor number in range(1, n + 1):\n    total = total + number\nprint(total)","kind":"python","output":"10","error":null}},"explanation":"range의 끝값은 포함하지 않으므로 n까지 처리하려면 끝 경계를 n + 1로 둡니다. n이 0이면 range(1, 1)은 비어 있어 누적값은 초기 0으로 남습니다.","related":["python-l022","python-l024"],"code":"n = 4\ntotal = 0\nfor number in range(1, n):\n    total = total + number\nprint(total)","codeKind":"python","codeLabel":"읽거나 수정할 코드"},{"question":"8, 6, 4, 2를 순서대로 출력하는 range를 작성하세요. 끝값을 2로 쓰면 왜 2가 빠지는지 확인하고, 같은 시작·끝에 간격을 양수 2로 바꿨을 때 출력이 있는지도 설명하세요.","skill":"범위 경계 · 감소 방향과 제외되는 끝","solution":{"answer":"range(8, 1, -2)는 8, 6, 4, 2를 출력합니다. range(8, 2, -2)는 2를 제외하고, range(8, 1, 2)는 방향이 맞지 않아 비어 있습니다.","code":{"source":"for number in range(8, 1, -2):\n    print(number)","kind":"python","output":"8\n6\n4\n2","error":null}},"explanation":"음수 간격으로 줄어들 때도 끝 경계는 포함하지 않습니다. 마지막 2를 포함하려면 2보다 작은 끝 경계를 고릅니다. 시작이 끝보다 큰데 양의 간격이면 처음부터 처리할 값이 없습니다.","related":["python-l022"]}]},{"id":"python-ch06","slug":"ch06","number":6,"title":"여러 값을 담는 방법","description":"목적에 맞게 컬렉션을 고르고, 조회·변경·순회와 별칭·얕은 복사의 차이를 확인합니다.","prerequisite":"선행 학습: 챕터 3 · 문자열을 다루는 기본 도구, 챕터 5 · 반복으로 같은 규칙 적용하기","runtime":"Python 3","testedVersion":"3.12.14","lessons":[{"id":"python-l026","order":1,"title":"리스트의 생성·조회·변경","subtitle":"순서가 있는 여러 값을 하나로 묶고, 필요한 위치를 읽거나 바꿉니다.","minutes":14,"goal":"리스트의 항목을 인덱스로 조회하고, 대입·append·pop·del의 목적과 결과를 구분해 수정한다.","intro":"준비물마다 다른 변수 이름을 만들면 항목이 늘어날 때마다 코드를 다시 적어야 합니다. 여러 값을 순서대로 한 묶음에 담으면 위치로 찾거나 같은 규칙으로 반복할 수 있습니다. 앞에서 split의 결과와 for의 반복 대상으로 만났던 리스트를 이번에는 직접 만들고, 항목을 추가·수정·삭제하며 변화를 추적해 봅시다.","sections":[{"title":"대괄호 안에 항목을 순서대로 적습니다.","body":["리스트는 여러 값을 순서대로 담는 자료형입니다. [\"연필\", \"공책\", \"지우개\"]처럼 대괄호 안에 값을 쉼표로 구분해 적습니다. 각 값을 항목이라고 부르며, 같은 값이 여러 번 들어갈 수도 있습니다. []는 항목이 없는 빈 리스트입니다.","리스트의 항목은 문자열뿐 아니라 숫자 등 다른 값일 수도 있습니다. 한 리스트에 서로 다른 종류를 담을 수 있지만, 모두 점수나 모두 준비물처럼 목적이 일관되면 뒤의 처리를 이해하기 쉽습니다. 여기서는 목록이 맡은 역할을 먼저 정하고 값을 담습니다.","len(items)는 리스트에 담긴 항목 수입니다. print(items)는 대괄호와 쉼표를 포함해 리스트 전체를 보여 주며, 문자열 항목 주위의 따옴표는 항목의 종류를 드러내는 표시입니다. 문자열 하나의 글자 수와 리스트의 항목 수를 구분하세요."],"code":{"source":"items = [\"연필\", \"공책\", \"연필\"]\nprint(items)\nprint(len(items))\nempty = []\nprint(empty)\nprint(len(empty))","kind":"python","output":"['연필', '공책', '연필']\n3\n[]\n0","error":null,"caption":"같은 값이 두 번 있어도 각각 하나의 항목으로 셉니다."}},{"title":"인덱스는 항목의 위치를 가리킵니다.","body":["문자열과 마찬가지로 리스트의 인덱스는 앞에서 0부터 셉니다. items[0]은 첫 항목이고 items[-1]은 마지막 항목입니다. 문자열 인덱스가 문자 하나를 읽었다면 리스트 인덱스는 그 자리에 들어 있는 값 하나를 읽습니다.","항목 수가 n인 리스트에서 앞쪽 인덱스는 0부터 n - 1까지입니다. items[len(items)]는 끝 바로 다음 위치이므로 IndexError가 납니다. 빈 리스트에는 첫 항목이나 마지막 항목이 없어 [0]과 [-1] 모두 사용할 수 없습니다. if items:로 비어 있지 않은지 확인한 뒤 읽을 수 있습니다.","items[1:3]처럼 슬라이싱하면 끝 인덱스 3을 포함하지 않는 구간의 항목들을 담은 리스트를 얻습니다. 범위가 클 때 잘리는 점은 문자열 슬라이싱과 같습니다. 슬라이싱과 복사의 관계는 이 챕터 마지막 레슨에서 더 자세히 확인합니다."],"code":{"source":"scores = [70, 85, 90]\nprint(scores[0])\nprint(scores[-1])\nprint(scores[1:3])\nif scores:\n    print(scores[len(scores) - 1])","kind":"python","output":"70\n90\n[85, 90]\n90","error":null,"caption":"리스트에서 한 항목을 읽은 결과와 여러 항목을 담은 리스트를 구분합니다."}},{"title":"항목 대입은 수정이고 append는 끝에 하나를 더합니다.","body":["리스트는 만들어진 뒤 항목을 바꿀 수 있습니다. scores[1] = 88은 기존 두 번째 항목을 88로 바꾸며 항목 수는 유지합니다. 문자열은 특정 위치를 직접 바꿀 수 없었지만 리스트는 가능합니다. 단, 이미 존재하는 위치여야 하므로 없는 끝 위치에 대입한다고 새 항목이 생기지는 않습니다.","items.append(value)는 끝에 value 하나를 추가하는 메서드입니다. 원래 리스트를 직접 변경하므로 items.append(\"지우개\")라는 호출 자체로 추가가 끝납니다. append의 반환값은 변경한 리스트가 아니라 None입니다.","따라서 items = items.append(\"지우개\")라고 쓰면 이름 items를 None에 다시 연결해 버립니다. 원래 리스트를 바꾸는 작업과 반환값을 사용하는 작업을 구분하세요. 문자열 메서드가 돌려준 새 문자열을 대입했던 방식과 모든 메서드가 같지는 않습니다."],"code":{"source":"scores = [70, 85]\nscores[1] = 88\nresult = scores.append(92)\nprint(scores)\nprint(len(scores))\nprint(result)","kind":"python","output":"[70, 88, 92]\n3\nNone","error":null,"caption":"항목 수정은 개수를 유지하고 append는 하나 늘립니다. 반환값 result는 None입니다."}},{"title":"pop은 꺼낸 값을 돌려주고 del은 지정 위치를 지웁니다.","body":["items.pop()은 마지막 항목을 리스트에서 제거하고 그 값을 반환합니다. items.pop(0)처럼 인덱스를 주면 그 위치의 항목을 꺼냅니다. 제거한 값을 이후 출력하거나 계산할 필요가 있을 때 반환값을 이름에 연결할 수 있습니다.","del items[0]은 그 위치의 항목을 지우는 문장입니다. del은 괄호로 호출하는 메서드가 아니고, 꺼낸 값을 반환받는 식으로 사용하지 않습니다. 항목을 지우면 그 뒤 항목들의 인덱스가 하나씩 앞으로 당겨집니다.","빈 리스트의 pop이나 존재하지 않는 인덱스의 pop·del도 IndexError를 일으킵니다. 작업 전 현재 항목 수를 확인해야 합니다. 리스트를 for로 읽는 도중에 항목을 지우면 아직 읽지 않은 항목의 위치가 바뀌어 건너뛸 수 있으므로, 이번 레슨에서는 삭제 작업을 반복과 분리해 순서대로 확인합니다."],"code":{"source":"tasks = [\"읽기\", \"쓰기\", \"복습\"]\nfinished = tasks.pop(0)\nprint(finished)\nprint(tasks)\ndel tasks[1]\nprint(tasks)\nlast = tasks.pop()\nprint(last)\nprint(tasks)","kind":"python","output":"읽기\n['쓰기', '복습']\n['쓰기']\n쓰기\n[]","error":null,"caption":"매 작업 뒤의 현재 리스트를 기준으로 다음 인덱스를 읽습니다."}}],"worked":{"question":"준비물 목록 [\"펜\", \"종이\"]의 첫 항목을 연필로 바꾸고 지우개를 추가한 뒤, 마지막 항목을 꺼내 별도로 보여 주세요.","code":{"source":"items = [\"펜\", \"종이\"]\nitems[0] = \"연필\"\nitems.append(\"지우개\")\nprint(items)\nremoved = items.pop()\nprint(\"꺼낸 항목:\", removed)\nprint(\"남은 목록:\", items)","kind":"python","output":"['연필', '종이', '지우개']\n꺼낸 항목: 지우개\n남은 목록: ['연필', '종이']","error":null,"caption":"수정·추가·꺼내기는 서로 다른 상태 변화를 만듭니다."},"steps":["인덱스 0의 펜을 연필로 바꾸어 두 항목이라는 길이는 유지합니다.","append가 끝에 지우개 하나를 추가해 세 항목이 됩니다. 반환값을 다시 items에 대입하지 않습니다.","pop은 마지막 항목 지우개를 제거하며 그 값을 반환합니다. removed는 꺼낸 문자열을, items는 남은 두 항목의 리스트를 가리킵니다."],"answer":"위치 대입은 기존 항목 수정, append는 추가, pop은 제거와 반환입니다. 각 동작 뒤에 목록과 필요한 반환값을 따로 확인합니다."},"misconception":{"question":"리스트 메서드는 실행 뒤 항상 그 리스트를 반환하나요?","answer":"그렇지 않습니다. append는 원래 리스트를 변경하고 None을 반환하지만, pop은 제거한 항목을 반환합니다. 메서드가 무엇을 변경하는지와 무엇을 돌려주는지는 따로 확인해야 합니다. items = items.append(...)라고 쓰면 items가 리스트가 아니라 None에 연결됩니다."},"keypoints":["리스트는 대괄호 안에 순서대로 담은 값들의 묶음입니다. len은 항목 수이며 인덱스는 0부터 시작하고 음수는 뒤에서 셉니다.","존재하는 위치의 대입은 항목 수정, append는 끝에 항목 하나 추가입니다. append는 리스트를 직접 변경하며 None을 반환합니다.","pop은 제거한 항목을 반환하고 del은 지정 위치를 지웁니다. 삭제 뒤의 인덱스 변화와 빈 리스트·범위를 벗어난 위치를 확인합니다."],"examples":[{"question":"책, 노트, 책을 그 순서로 담은 리스트를 직접 만들고 전체 목록·항목 수·첫 항목·마지막 항목을 차례로 출력하세요. 같은 책이 두 번 있어도 항목 수가 3인 이유를 설명하세요.","skill":"리스트 생성과 위치 조회","solution":{"answer":"목록은 ['책', '노트', '책'], 항목 수는 3이며 첫 항목과 마지막 항목은 모두 책입니다.","code":{"source":"items = [\"책\", \"노트\", \"책\"]\nprint(items)\nprint(len(items))\nprint(items[0])\nprint(items[-1])","kind":"python","output":"['책', '노트', '책']\n3\n책\n책","error":null}},"explanation":"리스트는 같은 값을 자동으로 합치지 않습니다. 두 위치에 있는 책을 각각 하나의 항목으로 담으므로 길이는 3입니다."},{"question":"아래 코드에서 출력될 세 리스트를 먼저 적고 실행하세요. 첫 변경이 항목 수를 유지하고, 뒤의 두 변경이 수를 늘리거나 줄이는 이유를 설명하세요.","skill":"수정·추가·삭제 상태 추적","solution":{"answer":"순서대로 [4, 9, 6], [4, 9, 6, 8], [9, 6, 8]입니다.","code":{"source":"values = [4, 5, 6]\nvalues[1] = 9\nprint(values)\nvalues.append(8)\nprint(values)\ndel values[0]\nprint(values)","kind":"python","output":"[4, 9, 6]\n[4, 9, 6, 8]\n[9, 6, 8]","error":null}},"explanation":"위치 대입은 한 항목을 교체합니다. append는 끝에 추가하고 del은 첫 항목을 지우므로, 삭제 후 9가 인덱스 0이 됩니다.","code":"values = [4, 5, 6]\nvalues[1] = 9\nprint(values)\nvalues.append(8)\nprint(values)\ndel values[0]\nprint(values)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드는 목록에 파랑을 추가하려는데 None을 출력합니다. 이유를 설명하고 items가 두 색을 담은 리스트로 남도록 고치세요.","skill":"append 반환값을 잘못 대입한 코드 수정","solution":{"answer":"append의 반환값 None을 items에 대입한 것이 문제입니다. 대입 없이 호출하면 ['빨강', '파랑']이 남습니다.","code":{"source":"items = [\"빨강\"]\nitems.append(\"파랑\")\nprint(items)","kind":"python","output":"['빨강', '파랑']","error":null}},"explanation":"append는 호출하는 동안 기존 리스트를 바꿉니다. 반환값을 다시 저장할 필요가 없으며 그 반환값은 새 리스트가 아닙니다.","code":"items = [\"빨강\"]\nitems = items.append(\"파랑\")\nprint(items)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드의 오류 종류를 확인하고 마지막 값 30을 읽도록 고치세요. 이어서 빈 리스트일 때는 인덱스를 사용하지 않고 비어 있음이라고 출력하도록 if·else를 작성해 두 경우를 확인하세요.","skill":"끝 인덱스와 빈 리스트 경계","solution":{"answer":"len(values)는 2라서 인덱스 2는 범위 밖이며 IndexError가 납니다. 비어 있지 않을 때 [-1]을 읽으면 30이고, 빈 리스트에서는 비어 있음을 출력합니다.","code":{"source":"values = [10, 30]\nif values:\n    print(values[-1])\nelse:\n    print(\"비어 있음\")\nvalues = []\nif values:\n    print(values[-1])\nelse:\n    print(\"비어 있음\")","kind":"python","output":"30\n비어 있음","error":null}},"explanation":"항목 수와 마지막 인덱스는 다릅니다. 빈 리스트는 참 거짓 판정에서 거짓이므로 if로 나눈 뒤 존재하는 경우에만 마지막 항목을 읽습니다.","code":"values = [10, 30]\nprint(values[len(values)])","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"대기 목록 [\"민수\", \"지연\", \"하나\"]에서 첫 사람을 꺼내 이름을 출력하세요. 이어서 남은 목록의 마지막 사람은 이름을 따로 쓰지 않고 삭제하세요. 최종 목록을 출력하고 pop과 del을 선택한 이유를 적으세요.","skill":"제거한 값의 필요 여부에 맞는 작업 선택","solution":{"answer":"민수를 꺼내 출력하고 하나를 삭제하므로 최종 목록은 ['지연']입니다.","code":{"source":"waiting = [\"민수\", \"지연\", \"하나\"]\ncalled = waiting.pop(0)\nprint(called)\ndel waiting[-1]\nprint(waiting)","kind":"python","output":"민수\n['지연']","error":null}},"explanation":"첫 항목은 제거한 이름을 사용해야 하므로 pop의 반환값을 받습니다. 마지막 항목은 제거만 필요하므로 del을 사용할 수 있습니다. 같은 요구를 만족하는 다른 풀이도 가능합니다."}]},{"id":"python-l027","order":2,"title":"튜플과 언패킹","subtitle":"함께 쓰는 값들을 순서대로 묶고, 각 역할에 맞는 이름으로 나누어 받습니다.","minutes":13,"goal":"튜플을 만들고 항목을 읽거나 언패킹하며, 항목 교체와 이름의 재대입을 구분한다.","intro":"좌표의 가로·세로 값이나 상품의 이름·가격처럼 함께 전달하고 싶은 값이 있습니다. 목록의 항목을 계속 추가하고 지우기보다 한 묶음의 각 자리 의미를 유지하고 싶을 때 튜플을 사용할 수 있습니다. 리스트의 위치 개념을 이어 받아, 묶인 값을 이름으로 나누어 읽는 언패킹까지 살펴봅시다.","sections":[{"title":"튜플은 순서 있는 값의 묶음입니다.","body":["튜플은 여러 값을 순서대로 담지만, 만들어진 튜플의 항목을 다른 값으로 교체하거나 항목 수를 직접 바꿀 수 없는 자료형입니다. point = (3, 5)처럼 적으면 두 값을 담은 튜플을 만듭니다. 여기서는 괄호로 묶음을 분명히 표시합니다.","리스트처럼 인덱스로 읽고 len으로 항목 수를 확인할 수 있습니다. point[0]은 3, point[-1]은 5입니다. 서로 다른 종류의 값도 함께 묶을 수 있으므로 (\"공책\", 1500)처럼 첫 자리는 이름, 둘째 자리는 가격이라는 약속을 둘 수 있습니다.","튜플 자체가 각 자리의 의미를 붙여 주는 것은 아닙니다. 좌표라면 가로·세로 순서인지, 세로·가로 순서인지 프로그램에서 일관되게 정해야 합니다. 필요한 목적에 맞는 자료형을 고르는 것이지, 길이가 짧다는 이유만으로 반드시 튜플을 써야 하는 것은 아닙니다."],"code":{"source":"point = (3, 5)\nprint(point)\nprint(len(point))\nprint(point[0])\nprint(point[-1])\nproduct = (\"공책\", 1500)\nprint(product)","kind":"python","output":"(3, 5)\n2\n3\n5\n('공책', 1500)","error":null,"caption":"튜플의 순서를 읽을 수 있지만 그 위치에 새 값을 대입할 수는 없습니다."}},{"title":"한 항목의 튜플에는 쉼표가 필요합니다.","body":["항목이 하나인 튜플은 (7,)처럼 쉼표를 넣어 적습니다. (7)은 계산 순서를 묶는 괄호 안에 정수 7을 쓴 것이며 튜플이 아닙니다. 빈 튜플은 ()로 적습니다.","튜플을 구성할 때는 쉼표가 중요한 역할을 합니다. 예를 들어 3, 5도 튜플을 만들 수 있지만, 처음에는 (3, 5)로 괄호까지 표시하면 한 묶음이라는 의도가 잘 보입니다. 한 항목의 끝 쉼표를 생략하면 값의 종류가 달라지는 점을 특히 확인하세요.","type으로 한 항목의 튜플과 정수를 비교할 수 있습니다. 튜플에는 항목 수를 나타내는 len을 적용할 수 있지만 정수는 항목의 묶음이 아니므로 같은 방식으로 길이를 구할 수 없습니다."],"code":{"source":"number = (7)\nsingle = (7,)\nempty = ()\nprint(type(number))\nprint(type(single))\nprint(single)\nprint(len(single))\nprint(len(empty))","kind":"python","output":"<class 'int'>\n<class 'tuple'>\n(7,)\n1\n0","error":null,"caption":"괄호 모양만 보지 말고 쉼표와 실제 타입을 함께 확인합니다."}},{"title":"언패킹은 항목을 각 이름에 순서대로 연결합니다.","body":["x, y = point는 point에 담긴 두 항목을 첫 이름 x와 둘째 이름 y에 순서대로 연결합니다. 묶음을 풀어 여러 이름으로 받는 이런 대입을 언패킹이라고 부릅니다. 각 값의 역할이 드러나는 이름을 쓰면 인덱스만 읽는 것보다 뜻이 분명해집니다.","이번에 사용하는 기본 언패킹은 이름 수와 항목 수가 정확히 같아야 합니다. 두 항목을 이름 세 개로 받거나 세 항목을 이름 두 개로 받으면 ValueError가 납니다. 항목이 자동으로 버려지거나 부족한 자리에 값이 채워지는 것은 아닙니다.","오른쪽 값들을 먼저 구한 뒤 왼쪽 이름들에 연결합니다. 그래서 left, right = right, left로 두 값을 교환할 수 있습니다. 첫 대입 때문에 원래 left를 잃는 순차 대입과 다릅니다. 언패킹은 리스트에도 사용할 수 있지만, 여기서는 튜플로 원리를 확인합니다."],"code":{"source":"point = (3, 5)\nx, y = point\nprint(x)\nprint(y)\nx, y = y, x\nprint(x)\nprint(y)","kind":"python","output":"3\n5\n5\n3","error":null,"caption":"교환할 때 오른쪽의 기존 y와 x를 먼저 얻은 뒤 두 이름을 다시 연결합니다."}},{"title":"튜플 항목을 바꾸는 것과 새 튜플을 대입하는 것은 다릅니다.","body":["point[0] = 8처럼 튜플의 특정 위치에 대입하면 TypeError가 납니다. 튜플은 해당 자리가 어떤 값을 가리키는지 직접 교체할 수 없기 때문입니다. 리스트의 항목 대입과 차이가 있습니다.","다른 좌표가 필요하다면 point = (8, point[1])처럼 새 튜플을 만들고 point라는 이름을 다시 연결할 수 있습니다. 이름을 재대입하는 것은 기존 튜플 내부를 고치는 일이 아닙니다. 기존 튜플에 연결된 다른 이름이 있다면 그 이름은 이전 묶음을 계속 가리킵니다.","튜플이 불변이라는 것은 튜플 자체의 항목 연결과 길이를 바꿀 수 없다는 뜻입니다. 튜플 안에 리스트 같은 변경 가능한 값이 들어 있다면 그 값의 내부까지 모두 변경 불가능해지는 것은 아닙니다. 중첩된 값과 공유 관계는 이 챕터의 별칭과 얕은 복사 레슨에서 이어 봅니다."],"code":{"source":"point = (3, 5)\nbefore = point\npoint = (8, point[1])\nprint(point)\nprint(before)","kind":"python","output":"(8, 5)\n(3, 5)","error":null,"caption":"새 튜플로 이름을 다시 연결해도 이전 튜플의 두 값은 그대로입니다."}}],"worked":{"question":"상품 정보 (\"연필\", 800, 3)은 이름·단가·수량 순서입니다. 세 이름으로 나누어 받고 총액을 계산해 출력해 보세요.","code":{"source":"item = (\"연필\", 800, 3)\nname, price, quantity = item\ntotal = price * quantity\nprint(name)\nprint(\"총액:\", total)\nprint(item)","kind":"python","output":"연필\n총액: 2400\n('연필', 800, 3)","error":null,"caption":"언패킹한 이름으로 각 자리의 역할을 드러낸 뒤 계산합니다."},"steps":["튜플의 첫 항목 연필을 name, 둘째 항목 800을 price, 셋째 항목 3을 quantity에 연결합니다. 이름 수와 항목 수는 모두 세 개입니다.","가격과 수량이라는 뜻이 분명한 이름을 사용해 800 × 3을 계산합니다. total은 정수 2400입니다.","언패킹은 item의 항목을 제거하거나 교체하지 않습니다. 원래 튜플은 세 항목을 그대로 담고 있습니다."],"answer":"순서에 대한 약속을 정하고 같은 수의 이름으로 언패킹하면, 인덱스 대신 각 값의 의미를 드러내는 이름으로 계산할 수 있습니다."},"misconception":{"question":"튜플은 불변이므로 튜플을 가리키는 변수에도 다른 값을 대입할 수 없나요?","answer":"변수 이름은 다른 값에 다시 연결할 수 있습니다. 제한되는 것은 기존 튜플의 항목 교체나 길이 변경입니다. point = (8, 5)는 새 튜플에 이름을 연결하지만 point[0] = 8은 기존 튜플 항목을 바꾸려고 하므로 실패합니다."},"keypoints":["튜플은 순서대로 묶인 값을 인덱스와 len으로 읽을 수 있지만 항목을 직접 교체하거나 추가·삭제할 수 없습니다.","한 항목은 (value,)처럼 쉼표를 쓰며 빈 튜플은 ()입니다. (value)는 괄호로 값 하나를 묶은 식입니다.","언패킹은 항목을 같은 수의 이름에 순서대로 연결합니다. 오른쪽을 먼저 평가하며 기존 튜플을 변경하는 작업은 아닙니다."],"examples":[{"question":"가로 12, 세로 8을 그 순서로 담은 튜플 size를 만들고 항목 수와 두 값을 인덱스로 출력하세요. 이어서 width, height로 언패킹해 넓이를 계산하세요.","skill":"순서 있는 묶음과 역할 이름","solution":{"answer":"항목 수는 2, 값은 12와 8, 넓이는 96입니다.","code":{"source":"size = (12, 8)\nprint(len(size))\nprint(size[0])\nprint(size[1])\nwidth, height = size\nprint(width * height)","kind":"python","output":"2\n12\n8\n96","error":null}},"explanation":"인덱스는 위치를 보여 주고 언패킹한 이름은 각 위치의 의미를 드러냅니다. width와 height를 계산에 사용해도 size 자체는 바뀌지 않습니다."},{"question":"아래 두 값의 타입을 예상하고 실행하세요. a도 한 항목짜리 튜플이 되도록 고치고, 두 값의 길이를 각각 출력하세요.","skill":"한 항목 튜플의 쉼표","solution":{"answer":"원래 a는 str이고 b는 tuple입니다. a = ('노트',)로 고치면 두 값의 길이가 모두 1입니다.","code":{"source":"a = (\"노트\",)\nb = (\"노트\",)\nprint(type(a))\nprint(type(b))\nprint(len(a))\nprint(len(b))","kind":"python","output":"<class 'tuple'>\n<class 'tuple'>\n1\n1","error":null}},"explanation":"문자열을 괄호로만 감싸면 여전히 문자열입니다. 한 항목의 튜플을 만들려면 쉼표가 필요합니다.","code":"a = (\"노트\")\nb = (\"노트\",)\nprint(type(a))\nprint(type(b))","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드의 오류 종류를 확인하세요. 이름·가격·수량을 모두 사용하도록 언패킹을 고치고, 이름과 가격 × 수량을 각각 출력하세요.","skill":"언패킹 항목 수 맞추기","solution":{"answer":"세 항목을 두 이름에 받으려 해서 ValueError가 납니다. 세 번째 이름 quantity를 추가하면 지우개와 2000을 출력합니다.","code":{"source":"item = (\"지우개\", 500, 4)\nname, price, quantity = item\nprint(name)\nprint(price * quantity)","kind":"python","output":"지우개\n2000","error":null}},"explanation":"기본 언패킹은 항목을 자동으로 버리지 않습니다. 요구한 세 값을 모두 사용할 수 있게 이름 수와 순서를 맞춥니다.","code":"item = (\"지우개\", 500, 4)\nname, price = item\nprint(name)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드는 튜플의 첫 값을 직접 고치려다 오류가 납니다. 오류 종류를 확인하고, 기존 튜플을 직접 바꾸지 않으면서 point가 (9, 4)를 가리키도록 새 튜플을 대입하세요.","skill":"튜플 항목 변경과 재대입 구분","solution":{"answer":"항목 대입은 TypeError입니다. point = (9, point[1])로 새 튜플에 연결하면 (9, 4)가 됩니다.","code":{"source":"point = (2, 4)\npoint = (9, point[1])\nprint(point)","kind":"python","output":"(9, 4)","error":null}},"explanation":"기존 두 번째 값을 읽어 새 튜플의 두 번째 자리에 사용합니다. 튜플 내부를 수정하지 않고 변수 이름을 새 묶음에 연결합니다.","code":"point = (2, 4)\npoint[0] = 9\nprint(point)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 순차 대입은 두 값을 맞바꾸려는데 둘 다 9가 됩니다. 오른쪽 값들을 먼저 묶어 평가하는 언패킹 대입으로 고쳐 9와 4를 출력하세요.","skill":"언패킹으로 값 교환","solution":{"answer":"left, right = right, left로 쓰면 left는 9, right는 4입니다.","code":{"source":"left = 4\nright = 9\nleft, right = right, left\nprint(left)\nprint(right)","kind":"python","output":"9\n4","error":null}},"explanation":"순차 대입은 첫 줄에서 left의 이전 연결을 바꿔 버립니다. 언패킹 대입은 오른쪽의 원래 right와 left를 먼저 구한 뒤 두 이름을 연결하므로 이전 4를 잃지 않습니다.","code":"left = 4\nright = 9\nleft = right\nright = left\nprint(left)\nprint(right)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"}]},{"id":"python-l028","order":3,"title":"딕셔너리의 키와 값","subtitle":"몇 번째인지 대신 어떤 이름표인지를 기준으로 값을 찾습니다.","minutes":15,"goal":"딕셔너리의 키로 값을 조회·추가·갱신하고, 없는 키를 in과 get으로 구분해 처리한다.","intro":"리스트로 준비물을 담을 때는 위치가 유용하지만, 연필의 재고를 찾으려면 연필이라는 이름표가 더 자연스럽습니다. 딕셔너리는 키라는 이름표와 값을 연결합니다. 같은 대괄호라도 리스트에서는 위치를, 딕셔너리에서는 키를 지정한다는 차이부터 확인해 봅시다.","sections":[{"title":"키와 값을 한 쌍씩 연결합니다.","body":["딕셔너리는 키와 값의 연결을 담는 자료형입니다. {\"연필\": 3, \"공책\": 2}처럼 중괄호 안에 키: 값을 적고 쌍들을 쉼표로 구분합니다. inventory[\"연필\"]은 연필이라는 키에 연결된 값 3을 읽습니다. {}는 빈 딕셔너리입니다.","키는 위치 번호와 다릅니다. inventory[0]은 첫 항목을 달라는 뜻이 아니라 정수 0이라는 키를 찾는 요청입니다. 정수 키도 사용할 수 있지만 여기서는 주로 의미가 드러나는 문자열을 사용합니다. 문자열이나 정수는 키로 쓸 수 있고, 변경 가능한 리스트는 키로 쓸 수 없습니다.","한 딕셔너리에서 같은 키는 하나의 값에 연결됩니다. 같은 키를 다시 지정하면 그 키의 값이 갱신되며 같은 이름표가 두 항목으로 늘어나지 않습니다. len(inventory)는 키와 값 쌍의 수입니다. 값은 같은 숫자가 여러 키에 연결되어도 괜찮습니다."],"code":{"source":"inventory = {\"연필\": 3, \"공책\": 2}\nprint(inventory[\"연필\"])\nprint(inventory[\"공책\"])\nprint(len(inventory))\nrooms = {101: \"학습실\", 202: \"회의실\"}\nprint(rooms[101])\nprint({})","kind":"python","output":"3\n2\n2\n학습실\n{}","error":null,"caption":"딕셔너리의 대괄호에는 찾을 키를 씁니다. 정수 키도 항목 위치와는 별개입니다."}},{"title":"키에 대입하면 추가하거나 기존 값을 갱신합니다.","body":["inventory[\"연필\"] = 5는 이미 있는 키의 값을 5로 갱신합니다. inventory[\"지우개\"] = 1은 그 키가 없으면 새 키와 값의 쌍을 추가합니다. 같은 대입 문법이라도 키가 있었는지에 따라 항목 수의 변화가 달라집니다.","딕셔너리는 키를 처음 추가한 순서를 유지합니다. 기존 키의 값만 갱신하면 그 키의 위치는 바뀌지 않고, 새 키는 뒤에 추가됩니다. 이 순서는 숫자 크기나 가나다순으로 자동 정렬한다는 뜻이 아닙니다.","값을 계산해 다시 저장할 수도 있습니다. inventory[\"연필\"] = inventory[\"연필\"] + 2는 현재 값을 먼저 읽어 2를 더한 뒤 같은 키의 값을 갱신합니다. 오른쪽에서 읽을 키가 실제로 있는지를 먼저 확인해야 합니다."],"code":{"source":"inventory = {\"연필\": 3, \"공책\": 2}\ninventory[\"연필\"] = inventory[\"연필\"] + 2\nprint(inventory)\ninventory[\"지우개\"] = 1\nprint(inventory)\nprint(len(inventory))","kind":"python","output":"{'연필': 5, '공책': 2}\n{'연필': 5, '공책': 2, '지우개': 1}\n3","error":null,"caption":"기존 키 갱신은 개수를 유지하고 새 키 추가는 개수를 늘립니다."}},{"title":"in은 키의 존재를, get은 없을 때의 값을 다룹니다.","body":["없는 키를 inventory[\"자\"]처럼 바로 읽으면 KeyError가 납니다. \"자\" in inventory는 그 키가 있는지 True 또는 False로 알려 주므로, if로 확인한 뒤 대괄호 조회를 할 수 있습니다. 딕셔너리의 in은 값이 아니라 키를 검사합니다.","inventory.get(\"자\", 0)은 자라는 키가 있으면 연결된 값을, 없으면 기본값 0을 반환합니다. get은 메서드이며 첫 인자로 찾을 키, 둘째 인자로 없을 때 반환할 기본값을 받습니다. 기본값을 생략한 get(\"자\")는 키가 없을 때 None을 반환합니다.","get으로 기본값을 읽어도 그 키가 자동으로 추가되지는 않습니다. 또 실제 값으로 None이 저장될 수 있다면 get의 None 결과만으로 키가 없다고 단정할 수 없습니다. 키의 존재 자체를 구분해야 할 때는 in을 사용합니다. 값이 0이어도 키는 있을 수 있으므로 if inventory.get(\"연필\"):와 키 검사도 다른 질문입니다."],"code":{"source":"inventory = {\"연필\": 0, \"공책\": 2}\nprint(\"연필\" in inventory)\nprint(2 in inventory)\nprint(inventory.get(\"자\", 0))\nprint(inventory.get(\"자\"))\nprint(\"자\" in inventory)\nif \"연필\" in inventory:\n    print(\"연필 재고:\", inventory[\"연필\"])","kind":"python","output":"True\nFalse\n0\nNone\nFalse\n연필 재고: 0","error":null,"caption":"값 2가 있어도 정수 키 2가 있는 것은 아닙니다. get의 기본값 조회는 딕셔너리를 변경하지 않습니다."}},{"title":"del은 키와 값의 연결을 제거합니다.","body":["del inventory[\"공책\"]은 공책이라는 키와 그에 연결된 값을 딕셔너리에서 제거합니다. 리스트에서 위치를 지정해 삭제했던 del과 모양은 비슷하지만, 여기서는 키를 지정합니다. 없는 키를 삭제하려고 해도 KeyError가 납니다.","키가 있을 때만 삭제하려면 if \"공책\" in inventory:로 존재를 먼저 검사합니다. 재고를 0으로 바꾸는 것과 항목을 삭제하는 것은 다릅니다. 0으로 갱신하면 상품 키가 남고, del을 사용하면 그 키 자체가 없어집니다.","키를 삭제한 뒤 다시 추가하면 새로 추가된 순서에 놓입니다. 그에 비해 기존 키의 값만 갱신하면 순서를 유지합니다. 자료를 특정 순서로 보여 줘야 한다면 추가·삭제·갱신 중 어떤 작업을 했는지도 구분해서 읽으세요. 여러 키와 값을 순회하는 방법은 뒤 레슨에서 다룹니다."],"code":{"source":"inventory = {\"연필\": 3, \"공책\": 2}\ninventory[\"연필\"] = 0\nif \"공책\" in inventory:\n    del inventory[\"공책\"]\nprint(inventory)\nprint(\"연필\" in inventory)\nprint(\"공책\" in inventory)\ninventory[\"공책\"] = 1\nprint(inventory)","kind":"python","output":"{'연필': 0}\nTrue\nFalse\n{'연필': 0, '공책': 1}","error":null,"caption":"0개인 상품과 등록되지 않은 상품은 다른 상태입니다."}}],"worked":{"question":"판매 기록 \"연필 공책 연필 지우개 연필\"에서 상품별 등장 횟수를 세어 보세요. 처음 나온 상품은 기존 횟수를 0으로 보고 하나를 더합니다.","code":{"source":"text = \"연필 공책 연필 지우개 연필\"\ncounts = {}\nfor name in text.split():\n    counts[name] = counts.get(name, 0) + 1\nprint(counts)\nprint(counts[\"연필\"])","kind":"python","output":"{'연필': 3, '공책': 1, '지우개': 1}\n3","error":null,"caption":"문자열 분리와 앞 챕터의 누적 갱신을 키별 기록으로 연결합니다."},"steps":["split()이 상품 이름들의 리스트를 만듭니다. 처음 counts에는 키가 없으므로 첫 연필의 get 결과는 기본값 0입니다. 1을 더해 연필 키에 저장합니다.","다음 연필을 만날 때는 이미 저장된 1을 읽어 2로 갱신합니다. 각 이름마다 자기 키의 횟수를 이어갑니다.","마지막에는 연필 3, 공책 1, 지우개 1입니다. 딕셔너리 출력의 키 순서는 처음 추가된 연필·공책·지우개 순서이며 횟수로 정렬한 결과가 아닙니다."],"answer":"키마다 누적값을 저장하면 이름별 횟수를 셀 수 있습니다. get의 기본값으로 첫 등장을 처리하고, 대입으로 새 값을 실제 딕셔너리에 반영합니다."},"misconception":{"question":"get으로 0이 나왔으면 그 키가 딕셔너리에 없다는 뜻인가요?","answer":"반드시 그렇지는 않습니다. 원래 저장된 값이 0일 수도 있고, 키가 없어서 기본값 0을 받은 것일 수도 있습니다. 키의 존재를 알아야 한다면 in으로 따로 검사합니다. get의 기본값을 받는 것만으로 새 키가 등록되는 것도 아닙니다."},"keypoints":["딕셔너리는 키와 값을 연결합니다. 대괄호에는 위치가 아니라 키를 쓰며, len은 키와 값 쌍의 수입니다.","키에 대입하면 새 키는 추가되고 기존 키는 갱신됩니다. 추가 순서를 유지하며 같은 키를 갱신해도 개수나 순서가 바뀌지 않습니다.","없는 키의 직접 조회·삭제는 KeyError입니다. in은 키 존재를, get은 없을 때의 반환값을 다루며 기본값 조회는 새 키를 추가하지 않습니다."],"examples":[{"question":"서울의 온도 18과 부산의 온도 21을 도시 이름을 키로 한 딕셔너리에 담으세요. 서울의 온도와 등록된 도시 수를 출력하고, temperature[0]을 첫 도시 조회에 쓰면 안 되는 이유를 설명하세요.","skill":"키와 위치의 차이","solution":{"answer":"서울의 온도는 18, 도시 수는 2입니다. 0은 첫 위치가 아니라 정수 키이므로 이 딕셔너리에는 없습니다.","code":{"source":"temperature = {\"서울\": 18, \"부산\": 21}\nprint(temperature[\"서울\"])\nprint(len(temperature))","kind":"python","output":"18\n2","error":null}},"explanation":"도시 이름이 찾기 위한 키입니다. 딕셔너리가 추가 순서를 유지해도 대괄호 정수가 위치 인덱스로 바뀌지는 않습니다."},{"question":"아래 코드의 네 출력을 예상하고 실행하세요. 값 2가 있는데도 2 in stock이 거짓인 이유와, 재고 0인 연필 키가 존재하는 이유를 설명하세요.","skill":"키 존재와 값의 구별","solution":{"answer":"출력은 True, False, True, 0입니다. in은 키를 확인하므로 값 2는 검사 대상이 아닙니다.","code":{"source":"stock = {\"연필\": 0, \"공책\": 2}\nprint(\"공책\" in stock)\nprint(2 in stock)\nprint(\"연필\" in stock)\nprint(stock[\"연필\"])","kind":"python","output":"True\nFalse\nTrue\n0","error":null}},"explanation":"키의 존재 여부와 연결된 재고 수는 서로 다른 정보입니다. 연필은 키로 등록되어 있고 그 값이 0입니다.","code":"stock = {\"연필\": 0, \"공책\": 2}\nprint(\"공책\" in stock)\nprint(2 in stock)\nprint(\"연필\" in stock)\nprint(stock[\"연필\"])","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드의 오류 종류를 확인하세요. 자 키가 없으면 0을 출력하도록 get으로 바꾸고, 그 뒤에도 자 키가 추가되지 않았는지 in으로 확인하세요.","skill":"없는 키와 기본값 조회","solution":{"answer":"직접 조회는 KeyError입니다. get(\"자\", 0)은 0을 반환하고, 이후 \"자\" in stock은 False입니다.","code":{"source":"stock = {\"연필\": 3}\nprint(stock.get(\"자\", 0))\nprint(\"자\" in stock)","kind":"python","output":"0\nFalse","error":null}},"explanation":"get은 없을 때 반환할 값을 정할 수 있지만 새 항목을 저장하지는 않습니다. 새 키를 등록하려면 별도로 대입해야 합니다.","code":"stock = {\"연필\": 3}\nprint(stock[\"자\"])","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"scores = {\"수학\": 80, \"파이썬\": 90}에서 수학을 85로 갱신하고 영어 70을 추가하세요. 파이썬 키를 삭제한 뒤 전체 딕셔너리와 항목 수를 출력하세요. 각 단계의 개수 변화를 설명하세요.","skill":"갱신·추가·삭제의 차이","solution":{"answer":"최종 딕셔너리는 {'수학': 85, '영어': 70}, 항목 수는 2입니다. 개수는 갱신 뒤 2, 추가 뒤 3, 삭제 뒤 2입니다.","code":{"source":"scores = {\"수학\": 80, \"파이썬\": 90}\nscores[\"수학\"] = 85\nscores[\"영어\"] = 70\ndel scores[\"파이썬\"]\nprint(scores)\nprint(len(scores))","kind":"python","output":"{'수학': 85, '영어': 70}\n2","error":null}},"explanation":"기존 키의 값을 바꿔도 키는 늘어나지 않습니다. 새 키를 추가하면 하나 늘고 del로 연결을 지우면 하나 줄어듭니다. 남은 키는 처음 추가된 상대적 순서를 유지합니다."},{"question":"문자열 \"파랑 빨강 파랑 빨강 파랑\"을 split으로 나누고, 각 색이 몇 번 등장하는지 딕셔너리에 누적하세요. 결과와 등장하지 않은 초록의 횟수 0을 출력하되 초록 키를 새로 추가하지 마세요.","skill":"키별 누적과 기본값의 조합","solution":{"answer":"결과는 {'파랑': 3, '빨강': 2}이고 초록 조회는 0입니다. 마지막에 초록 키의 존재를 확인하면 False입니다.","code":{"source":"text = \"파랑 빨강 파랑 빨강 파랑\"\ncounts = {}\nfor color in text.split():\n    counts[color] = counts.get(color, 0) + 1\nprint(counts)\nprint(counts.get(\"초록\", 0))\nprint(\"초록\" in counts)","kind":"python","output":"{'파랑': 3, '빨강': 2}\n0\nFalse","error":null}},"explanation":"등장한 색은 get으로 이전 횟수를 읽고 대입으로 갱신합니다. 등장하지 않은 초록은 조회만 하므로 기본값을 반환해도 등록되지는 않습니다."}]},{"id":"python-l029","order":4,"title":"집합과 중복 제거","subtitle":"위치보다 포함 여부와 서로 다른 값의 종류가 중요할 때 집합을 사용합니다.","minutes":14,"goal":"집합으로 중복과 포함 여부를 다루고, 순서가 필요한 목록과 구분하여 기본 집합 연산을 적용한다.","intro":"신청 목록에 같은 이름이 여러 번 들어 있어도 서로 다른 신청자가 몇 명인지는 따로 알고 싶을 수 있습니다. 앞에서 리스트는 순서와 같은 값의 반복을 보존했고, 딕셔너리는 키와 값을 연결했습니다. 이번에는 값이 들어 있는지와 서로 다른 값의 종류에 초점을 맞추는 집합을 살펴봅니다.","sections":[{"title":"집합은 같은 값을 한 번만 보관합니다.","body":["집합의 타입 이름은 set입니다. {\"독서\", \"코딩\", \"독서\"}처럼 값들을 중괄호 안에 적으면 같은 값은 하나로 다룹니다. set(목록)은 이미 있는 리스트 등의 값을 읽어 집합을 만들며, 원래 목록을 수정하지 않습니다. len으로 집합에 담긴 서로 다른 값의 개수를 셀 수 있습니다.","빈 집합은 set()으로 만듭니다. {}는 앞 레슨에서 배운 빈 딕셔너리이므로 기호 모양이 비슷해도 구별해야 합니다. 딕셔너리의 중괄호 안에는 키: 값 관계가 있고, 집합에는 값만 있습니다.","집합의 출력이나 순회 순서는 정해진 학습 결과로 기대하지 않습니다. sorted(values)는 값들을 정렬한 새 리스트로 돌려주는 함수입니다. 아래처럼 모두 같은 종류인 문자열이나 숫자를 정렬하면 내용을 일정한 순서로 확인하기 쉽습니다. sorted가 원래 집합에 순서를 붙이거나 집합을 리스트로 바꾸어 저장하는 것은 아닙니다."],"code":{"source":"names = [\"민서\", \"지우\", \"민서\"]\nunique = set(names)\nprint(len(unique))\nprint(sorted(unique))\nprint(names)\nprint(type(set()))\nprint(type({}))","kind":"python","output":"2\n['민서', '지우']\n['민서', '지우', '민서']\n<class 'set'>\n<class 'dict'>","error":null}},{"title":"집합에서는 위치 대신 포함 여부를 묻습니다.","body":["\"독서\" in hobbies는 독서라는 값이 집합에 있는지 True 또는 False로 알려 줍니다. \"운동\" not in hobbies는 운동이 없는지 확인합니다. 리스트나 딕셔너리에서 썼던 in도 자료형에 따라 무엇이 포함되는지 읽어야 합니다. 딕셔너리에서는 키, 여기서는 집합의 값입니다.","집합에는 첫 번째·두 번째 위치라는 약속이 없습니다. hobbies[0]처럼 인덱스로 조회하면 TypeError가 납니다. 순서를 유지하거나 같은 값의 횟수를 보존해야 한다면 리스트가 목적에 더 잘 맞습니다.","for로 집합의 값들을 방문할 수 있지만 어느 값이 먼저 나올지 의존하지 않습니다. 정렬해 보여 주려면 sorted로 얻은 리스트를 순회할 수 있습니다. 같은 값이 두 번 왔다는 정보는 집합을 만드는 순간 사라지므로 나중에 집합만으로 원래의 횟수와 순서를 복원할 수 없습니다."],"code":{"source":"hobbies = {\"독서\", \"코딩\"}\nprint(\"독서\" in hobbies)\nprint(\"운동\" not in hobbies)\nfor hobby in sorted(hobbies):\n    print(hobby)","kind":"python","output":"True\nTrue\n독서\n코딩","error":null}},{"title":"추가와 제거는 원래 집합을 변경합니다.","body":["values.add(value)는 값을 집합에 추가합니다. 이미 있는 값이면 하나를 더 쌓지 않습니다. values.discard(value)는 값이 있으면 제거하고, 없어도 오류 없이 그대로 둡니다. 두 메서드 모두 원래 집합을 변경하고 반환값은 None입니다.","따라서 values = values.add(\"새 값\")처럼 쓰면 이름을 None에 다시 연결하게 됩니다. 집합을 바꾸려는 목적이면 values.add(\"새 값\")를 실행한 다음 values를 읽습니다. 처리 결과를 새 이름에 연결하는 문자열 메서드와 구별하세요.","집합에 담는 값은 해시 가능한 값이어야 합니다. 해시는 값을 찾아 비교할 때 쓰는 정수 표식이며, 해시 가능한 값은 실행 중 같은 객체의 표식이 변하지 않고 같은 것으로 비교되는 값은 같은 표식을 가진다는 약속을 지킵니다. 세부 계산법보다 이번에는 문자열과 정수를 사용할 수 있다는 점부터 확인하면 됩니다. 리스트는 해시 가능하지 않아 직접 집합의 원소가 될 수 없으므로 TypeError가 납니다. 튜플도 안의 값이 모두 해시 가능할 때 사용할 수 있으며, 단순히 괄호로 감쌌다는 이유만으로 모든 내용이 허용되는 것은 아닙니다."],"code":{"source":"tags = {\"기초\"}\nresult = tags.add(\"연습\")\ntags.add(\"연습\")\ntags.discard(\"준비\")\nprint(sorted(tags))\nprint(result)\ntags.discard(\"기초\")\nprint(sorted(tags))","kind":"python","output":"['기초', '연습']\nNone\n['연습']","error":null}},{"title":"공통 값과 합친 값도 집합으로 표현합니다.","body":["두 집합 a와 b에서 a & b는 양쪽에 모두 있는 값의 집합인 교집합입니다. a | b는 어느 한쪽에라도 있는 값을 합친 합집합이고, a - b는 a에는 있지만 b에는 없는 차집합입니다. 이름보다 어떤 포함 조건을 표현하는지 먼저 읽으세요.","이 연산들은 결과 집합을 돌려주며 a와 b를 직접 수정하지 않습니다. a - b와 b - a는 출발점이 다르므로 결과가 같을 필요가 없습니다. 공통 원소가 없어 빈 집합이 나오는 것도 정상입니다.","정렬된 표시를 보고 집합 자체가 순서를 저장한다고 오해하지 마세요. 집합 연산으로 포함 관계를 계산하고, 결과를 사람에게 보여 줄 때만 sorted로 정렬한 리스트를 사용합니다."],"code":{"source":"morning = {\"민서\", \"지우\"}\nevening = {\"지우\", \"하린\"}\nprint(sorted(morning & evening))\nprint(sorted(morning | evening))\nprint(sorted(morning - evening))\nprint(sorted(evening - morning))","kind":"python","output":"['지우']\n['민서', '지우', '하린']\n['민서']\n['하린']","error":null}}],"worked":{"question":"같은 사람이 여러 번 신청한 목록에서 서로 다른 신청자 수를 구하고, 이미 확인한 사람을 제외한 나머지를 이름순으로 보여 주려면 어떻게 연결할까요?","code":{"source":"requests = [\"하린\", \"민서\", \"하린\", \"지우\"]\npeople = set(requests)\nchecked = {\"민서\"}\nwaiting = people - checked\nprint(len(people))\nprint(sorted(waiting))\nprint(requests)","kind":"python","output":"3\n['지우', '하린']\n['하린', '민서', '하린', '지우']","error":null},"steps":["set(requests)는 중복된 하린을 한 번만 담아 서로 다른 세 이름을 보관합니다. requests의 순서와 중복은 그대로 남습니다.","people - checked는 신청자 중 확인한 사람 집합에 없는 값을 고릅니다. 민서를 제외한 지우와 하린이 남습니다.","집합의 내부 순서에 기대지 않고 sorted(waiting)으로 표시용 리스트를 만듭니다. 처음 신청한 사람의 순서가 필요하다면 이 정렬 결과만으로 대신할 수는 없습니다."],"answer":"중복 여부 계산에는 집합을, 원래 신청 순서와 반복 기록에는 리스트를 사용합니다. 하나의 자료형으로 모든 정보를 보존하려 하지 않고 목적을 나눕니다."},"misconception":{"question":"집합으로 중복을 없앤 뒤 다시 리스트로 만들면 처음 순서도 돌아오나요?","answer":"집합은 위치와 중복 횟수를 보관하지 않으므로 원래 순서를 복원할 수 없습니다. sorted로 얻은 결과는 정렬 순서이고, 처음 나온 순서가 아닙니다. 처음 순서나 같은 값의 횟수가 필요하다면 원래 리스트를 유지해야 합니다."},"keypoints":["set은 중복을 한 번만 보관하며 포함 여부를 다룹니다. 빈 집합은 set(), 빈 딕셔너리는 {}입니다.","집합에는 인덱스와 순서 약속이 없습니다. sorted는 표시할 새 리스트를 만들 뿐 원래 순서를 복원하지 않습니다.","add·discard는 원래 집합을 바꾸고 None을 반환합니다. &, |, -는 포함 관계를 계산한 결과 집합을 돌려줍니다."],"examples":[{"question":"신청 번호 codes = [4, 2, 4, 1, 2]에서 서로 다른 번호의 개수와 작은 번호부터 정렬한 표시를 출력하세요. codes도 출력해 원본의 중복이 남는지 확인하세요.","skill":"중복과 원본 보존","solution":{"answer":"서로 다른 번호는 3개이고 정렬된 표시는 [1, 2, 4]입니다. 원래 codes는 바뀌지 않습니다.","code":{"source":"codes = [4, 2, 4, 1, 2]\nunique = set(codes)\nprint(len(unique))\nprint(sorted(unique))\nprint(codes)","kind":"python","output":"3\n[1, 2, 4]\n[4, 2, 4, 1, 2]","error":null}},"explanation":"set은 읽어 온 값을 중복 없이 담지만 전달받은 리스트를 수정하지 않습니다. sorted 결과는 정렬된 새 리스트입니다."},{"question":"아래 코드는 집합의 첫 값을 읽으려 합니다. 오류 종류를 확인한 뒤 마지막 줄을 값 \"B\"가 포함되어 있는지 출력하도록 고치세요. 특정 위치를 읽는 것이 이번 목적에 맞지 않는 이유도 적으세요.","skill":"집합의 조회 방식","solution":{"answer":"원본은 TypeError가 납니다. \"B\" in labels로 고치면 True입니다. 집합에는 첫 위치라는 약속이 없습니다.","code":{"source":"labels = {\"A\", \"B\"}\nprint(\"B\" in labels)","kind":"python","output":"True","error":null}},"explanation":"집합이 보관하는 것은 포함 관계이지 순서가 아닙니다. 포함 여부를 묻는 요구에는 in의 결과가 맞습니다.","code":"labels = {\"A\", \"B\"}\nprint(labels[0])","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래 코드는 값을 추가한 뒤 tags가 None이 됩니다. 반환값을 tags에 대입하지 않도록 고쳐 기초·연습 두 값이 남게 하세요. 이어 없는 값 준비를 discard해도 되는지 확인하세요.","skill":"변경 메서드의 반환값","solution":{"answer":"tags.add(\"연습\")를 독립된 명령으로 실행하면 됩니다. 정렬해 보면 ['기초', '연습']이며 없는 값의 discard는 오류를 내지 않습니다.","code":{"source":"tags = {\"기초\"}\ntags.add(\"연습\")\ntags.discard(\"준비\")\nprint(sorted(tags))","kind":"python","output":"['기초', '연습']","error":null}},"explanation":"add는 원래 집합을 바꾸고 None을 반환합니다. 그 None에 이름을 다시 연결하지 않아야 다음에도 집합을 사용할 수 있습니다.","code":"tags = {\"기초\"}\ntags = tags.add(\"연습\")\nprint(tags)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"reading = {\"민서\", \"지우\"}, coding = {\"지우\", \"도윤\"}에서 두 활동을 모두 하는 사람, 하나 이상 하는 사람, 독서만 하는 사람을 각각 이름순으로 출력하세요.","skill":"포함 관계의 조합","solution":{"answer":"교집합은 지우, 합집합은 도윤·민서·지우, reading에서 coding을 뺀 결과는 민서입니다.","code":{"source":"reading = {\"민서\", \"지우\"}\ncoding = {\"지우\", \"도윤\"}\nprint(sorted(reading & coding))\nprint(sorted(reading | coding))\nprint(sorted(reading - coding))","kind":"python","output":"['지우']\n['도윤', '민서', '지우']\n['민서']","error":null}},"explanation":"모두는 &, 하나 이상은 |, 독서에는 있으나 코딩에는 없음은 reading - coding으로 옮깁니다. 차집합의 왼쪽이 기준 집합입니다."},{"question":"위치 쌍 (1, 2)를 빈 집합에 추가하고, 같은 쌍을 다시 추가한 뒤 개수와 포함 여부를 출력하세요. 아래처럼 리스트 [1, 2]를 추가하면 왜 실패하는지도 확인하세요.","skill":"집합 원소의 조건","solution":{"answer":"튜플 (1, 2)를 두 번 추가해도 개수는 1이고 포함 여부는 True입니다. 리스트를 추가하는 원본은 TypeError입니다.","code":{"source":"points = set()\npoints.add((1, 2))\npoints.add((1, 2))\nprint(len(points))\nprint((1, 2) in points)","kind":"python","output":"1\nTrue","error":null}},"explanation":"여기서는 두 정수로 된 튜플이 해시 가능하므로 원소가 됩니다. 리스트는 직접 원소로 넣을 수 없습니다. 빈 집합을 만들 때도 {}가 아니라 set()을 사용합니다.","code":"points = set()\npoints.add([1, 2])","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"}]},{"id":"python-l030","order":5,"title":"컬렉션 순회와 간단한 컴프리헨션","subtitle":"반복해서 읽을 값과 새로 만들 결과를 구분하며 변환과 필터 규칙을 표현합니다.","minutes":16,"goal":"리스트·딕셔너리의 순회 대상을 구분하고 한 단계 리스트 컴프리헨션으로 변환과 필터를 작성한다.","intro":"자료를 담는 그릇을 골랐다면 그 안의 값에 같은 일을 적용할 차례입니다. 챕터 5의 for를 리스트와 딕셔너리에 연결하고, 읽는 원본과 새로 모을 결과를 분리해 봅시다. 반복의 동작을 이해한 뒤에는 한 단계의 변환이나 필터를 짧은 형태로 표현할 수도 있습니다.","sections":[{"title":"리스트를 순회하면 항목의 값을 차례로 읽습니다.","body":["for value in values:는 리스트의 첫 항목부터 차례로 값을 읽어 value에 연결합니다. 반복 변수에 다른 숫자를 대입한다고 원래 리스트의 해당 항목을 바꾸지는 않습니다. 원래 리스트를 변경하려면 앞 레슨처럼 인덱스로 대입하는 별도의 작업이 필요합니다.","enumerate(values)는 순서 번호와 값을 함께 읽게 하는 도구입니다. for index, value in enumerate(values):처럼 두 이름으로 언패킹합니다. 번호는 기본적으로 0부터 시작하고, enumerate(values, start=1)은 1부터 표시 번호를 붙입니다. start=1로 얻은 번호는 그대로 리스트 인덱스가 되는 것은 아닙니다.","읽는 중인 리스트의 항목을 추가하거나 삭제하면 다음에 방문할 항목이 달라져 건너뛰기나 예상 밖의 반복이 생길 수 있습니다. 이 레슨에서는 원본을 읽는 동안 그대로 두고 별도 결과 리스트에 값을 모읍니다."],"code":{"source":"items = [\"공책\", \"연필\"]\nfor number, item in enumerate(items, start=1):\n    print(number, item)\nfor item in items:\n    item = \"읽음\"\nprint(items)","kind":"python","output":"1 공책\n2 연필\n['공책', '연필']","error":null}},{"title":"딕셔너리는 키만 읽을지 키와 값을 읽을지 정합니다.","body":["for key in stock:처럼 딕셔너리를 직접 순회하면 키를 읽습니다. 값을 얻으려면 stock[key]로 조회할 수 있습니다. stock.items()는 각 키와 값을 한 쌍으로 함께 읽게 하며, for name, count in stock.items():에서 두 이름으로 언패킹합니다.","딕셔너리는 키가 들어온 순서를 유지합니다. 이것은 이름순이나 값 크기순으로 자동 정렬한다는 뜻이 아닙니다. 모든 키가 문자열인 이번 예제에서 이름순으로 보여 주려면 sorted(stock)으로 정렬한 키 리스트를 얻어 순회할 수 있습니다.","stock.values()는 값들만 읽게 합니다. 키가 필요한 작업에 값 순회만 사용하거나, 키 순회 결과를 값이라고 생각하지 않도록 무엇을 읽는지 명시하세요. 순회 중에 딕셔너리의 키를 추가하거나 삭제하지 않습니다."],"code":{"source":"stock = {\"연필\": 3, \"공책\": 2}\nfor name, count in stock.items():\n    print(name, count)\nprint(\"이름순\")\nfor name in sorted(stock):\n    print(name, stock[name])","kind":"python","output":"연필 3\n공책 2\n이름순\n공책 2\n연필 3","error":null}},{"title":"컴프리헨션은 새 리스트를 만드는 반복 규칙입니다.","body":["numbers의 각 수를 두 배로 만든 리스트가 필요하다면, 빈 결과 리스트를 만들고 for 안에서 계산한 값을 append할 수 있습니다. [number * 2 for number in numbers]도 같은 변환 규칙을 한 단계로 적은 리스트 컴프리헨션입니다.","먼저 for number in numbers에서 원본의 각 값을 읽고, 맨 앞의 number * 2를 계산해 결과 리스트에 차례로 담는다고 읽습니다. 대괄호는 새 리스트라는 결과 형식을 나타냅니다. 식을 짧게 썼다고 원본 리스트를 직접 수정하는 것은 아닙니다.","입력이 비어 있으면 선택할 값이 없으므로 결과도 빈 리스트입니다. 여기서는 한 겹의 for와 간단한 계산만 사용합니다. 중간 단계를 설명하기 어렵거나 출력·여러 상태 변경이 필요하면 일반 for로 나누어 쓰는 것이 읽기 쉽습니다."],"code":{"source":"numbers = [2, 5, -1]\ndoubled = []\nfor number in numbers:\n    doubled.append(number * 2)\nshort = [number * 2 for number in numbers]\nprint(doubled)\nprint(short)\nprint(numbers)","kind":"python","output":"[4, 10, -2]\n[4, 10, -2]\n[2, 5, -1]","error":null}},{"title":"뒤의 if는 넣을 값을 고르는 필터입니다.","body":["[number for number in numbers if number > 0]은 원본을 읽으면서 양수인 값만 새 리스트에 담습니다. 마지막 if는 어떤 값을 결과에 넣을지 고르는 필터입니다. 먼저 조건을 통과한 값에 맨 앞의 식을 적용합니다.","[number * 2 for number in numbers if number > 0]이라면 양수만 남긴 뒤 그 값들을 두 배로 표시합니다. 조건을 만족하는 값이 없으면 결과가 빈 리스트인 것이 정상입니다. 필터는 원본에서 항목을 지우는 명령이 아닙니다.","일반 for 안의 if·append와 한 단계씩 대응시켜 읽어 보세요. 같은 결과를 얻는 다른 코드도 가능합니다. 한 줄이라는 이유보다 원본·선택 조건·결과 식이 명확히 드러나는지를 기준으로 사용합니다."],"code":{"source":"numbers = [-2, 0, 3, 5]\npositive = [number for number in numbers if number > 0]\ndoubled_positive = [number * 2 for number in numbers if number > 0]\nprint(positive)\nprint(doubled_positive)\nprint(numbers)","kind":"python","output":"[3, 5]\n[6, 10]\n[-2, 0, 3, 5]","error":null}}],"worked":{"question":"가격 목록에서 1000원 이상인 물품만 고르고, 각 가격에 배송비 200원을 더한 새 목록을 만들려면 선택과 계산을 어떻게 나누어야 할까요?","code":{"source":"prices = [800, 1500, 1000, 600]\ntotals = []\nfor price in prices:\n    if price >= 1000:\n        totals.append(price + 200)\nshort = [price + 200 for price in prices if price >= 1000]\nprint(totals)\nprint(short)\nprint(prices)","kind":"python","output":"[1700, 1200]\n[1700, 1200]\n[800, 1500, 1000, 600]","error":null},"steps":["for는 원래 순서대로 800, 1500, 1000, 600을 읽습니다. 필터 price >= 1000을 통과하는 값은 1500과 1000입니다.","선택한 각 값에 200을 더해 1700과 1200을 새 결과 리스트에 담습니다. 원래 가격의 위치를 직접 덮어쓰지 않습니다.","컴프리헨션에서는 마지막 if가 선택, 앞의 price + 200이 변환을 맡습니다. 두 코드의 결과가 같고 prices도 그대로인지 함께 확인합니다."],"answer":"원본을 읽고 조건으로 고른 다음 결과 식을 계산해 새 리스트에 담습니다. 선택 기준과 표시할 값을 분리하면 한 줄 표현도 같은 반복으로 설명할 수 있습니다."},"misconception":{"question":"컴프리헨션에 if가 있으면 원본 리스트에서 조건에 맞지 않는 값이 삭제되나요?","answer":"아닙니다. 컴프리헨션은 조건을 만족하는 값으로 새 리스트를 만듭니다. 원본에서 삭제하는 연산은 하지 않습니다. 원본과 결과를 함께 출력해 구분하세요. 다만 새 리스트라는 사실이 그 안에 담긴 변경 가능한 값까지 모두 복사했다는 뜻은 아니며, 그 차이는 다음 레슨에서 살펴봅니다."},"keypoints":["for는 컬렉션에서 무엇을 읽는지 먼저 정합니다. 리스트는 항목, 딕셔너리 직접 순회는 키, items는 키·값 쌍입니다.","enumerate는 순서 번호와 값을 함께 줍니다. 표시 번호의 시작과 실제 리스트 인덱스를 구분합니다.","[식 for 이름 in 원본 if 조건]은 선택한 값으로 새 리스트를 만듭니다. 같은 원리를 일반 for·if·append로 설명할 수 있어야 합니다."],"examples":[{"question":"아래 반복을 실행한 뒤 numbers가 바뀌는지 확인하세요. 원본은 유지하면서 각 수에 1을 더한 새 리스트를 만들고 출력하도록 코드를 추가하세요.","skill":"반복 변수와 원본 구분","solution":{"answer":"원래 numbers는 [2, 4]입니다. 새 결과는 [3, 5]입니다.","code":{"source":"numbers = [2, 4]\nfor number in numbers:\n    number = number + 1\nprint(numbers)\nresult = [number + 1 for number in numbers]\nprint(result)","kind":"python","output":"[2, 4]\n[3, 5]","error":null}},"explanation":"반복 변수 number에 계산 결과를 대입하는 것은 리스트 항목의 변경이 아닙니다. 별도 리스트의 append나 컴프리헨션으로 계산 결과를 모아야 합니다.","code":"numbers = [2, 4]\nfor number in numbers:\n    number = number + 1\nprint(numbers)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"책 목록 books = [\"기초\", \"연습\", \"복습\"]을 enumerate로 읽어 1 기초, 2 연습, 3 복습을 각각 한 줄에 출력하세요. 번호 3을 그대로 books[3]에 쓰면 안 되는 이유도 설명하세요.","skill":"표시 번호와 인덱스","solution":{"answer":"enumerate의 start=1을 사용합니다. 세 항목의 인덱스는 0, 1, 2여서 books[3]은 범위 밖입니다.","code":{"source":"books = [\"기초\", \"연습\", \"복습\"]\nfor number, book in enumerate(books, start=1):\n    print(number, book)","kind":"python","output":"1 기초\n2 연습\n3 복습","error":null}},"explanation":"enumerate가 붙이는 표시 번호를 1부터 정해도 리스트의 위치 번호 자체가 바뀌지는 않습니다."},{"question":"stock = {\"연필\": 4, \"공책\": 1}에서 items로 키와 값을 함께 읽고 재고가 2개 이상인 물품만 이름과 재고를 출력하세요. 딕셔너리 자체를 순회할 때 무엇을 받는지도 적으세요.","skill":"키·값 순회와 조건","solution":{"answer":"출력은 연필 4입니다. 딕셔너리를 직접 순회하면 키를 받으므로 items로 쌍을 읽습니다.","code":{"source":"stock = {\"연필\": 4, \"공책\": 1}\nfor name, count in stock.items():\n    if count >= 2:\n        print(name, count)","kind":"python","output":"연필 4","error":null}},"explanation":"두 이름의 언패킹으로 물품 이름과 재고를 나누어 받고, 재고 조건은 숫자 값에 적용합니다."},{"question":"values = [1, 4, 6]의 각 값에서 1을 뺀 새 리스트를 일반 for·append와 한 단계 컴프리헨션으로 각각 만드세요. 두 결과와 원본을 출력해 비교하세요.","skill":"반복과 변환식 대응","solution":{"answer":"두 결과는 모두 [0, 3, 5]이고 values는 [1, 4, 6]입니다.","code":{"source":"values = [1, 4, 6]\nlong = []\nfor value in values:\n    long.append(value - 1)\nshort = [value - 1 for value in values]\nprint(long)\nprint(short)\nprint(values)","kind":"python","output":"[0, 3, 5]\n[0, 3, 5]\n[1, 4, 6]","error":null}},"explanation":"맨 앞의 value - 1이 결과에 넣을 식입니다. 원본을 읽어 새 리스트에 담는다는 점은 일반 반복과 같습니다."},{"question":"values = [-1, 0, 2, 5]에서 0 이상인 값만 골라 10을 더한 새 리스트를 컴프리헨션으로 만드세요. 이어 같은 코드를 values = [-3, -1]로 새로 실행해 조건을 통과한 값이 없을 때도 확인하세요.","skill":"필터와 경계값","solution":{"answer":"첫 결과는 [10, 12, 15], 두 번째는 []입니다. 0도 조건에 포함합니다.","code":{"source":"values = [-1, 0, 2, 5]\nresult = [value + 10 for value in values if value >= 0]\nprint(result)\nvalues = [-3, -1]\nresult = [value + 10 for value in values if value >= 0]\nprint(result)","kind":"python","output":"[10, 12, 15]\n[]","error":null}},"explanation":"필터 value >= 0은 0을 남깁니다. 조건을 통과한 값에만 + 10을 적용하며 선택된 값이 없으면 빈 리스트가 됩니다."}]},{"id":"python-l031","order":6,"title":"컬렉션의 별칭과 얕은 복사","subtitle":"이름이 가리키는 리스트와 그 안의 값들을 나누어 추적합니다.","minutes":16,"goal":"대입으로 같은 리스트를 공유하는 경우와 바깥 리스트만 복사하는 경우를 구분하고 중첩 변경의 영향을 추적한다.","intro":"목록을 다른 변수에도 저장한 뒤 한쪽을 고쳤는데 양쪽 출력이 바뀌면 당황할 수 있습니다. 앞에서 문자열은 내부를 바꿀 수 없었지만 리스트는 항목을 바꿀 수 있었습니다. 이제 값의 변경과 이름의 재대입, 바깥 목록의 복사와 그 안쪽 값의 공유를 따로 읽어 봅시다.","sections":[{"title":"다른 이름에 대입해도 리스트를 복사하지는 않습니다.","body":["alias = original은 original이 가리키는 리스트를 alias라는 이름으로도 가리키게 합니다. 같은 리스트를 부르는 이름이 하나 더 생긴 상태를 여기서는 별칭이라고 합니다. 리스트 항목들을 새로 복사하라는 명령이 아닙니다.","alias.append(\"복습\")처럼 리스트 자체를 변경하면 original로 읽어도 바뀐 항목이 보입니다. 두 이름이 같은 리스트를 읽기 때문입니다. original과 alias가 서로 값을 주고받아 동기화하는 별도 목록 두 개가 아닙니다.","그림 대신 이름 → 리스트를 떠올리면 됩니다. 두 이름의 화살표가 같은 리스트를 가리키는 동안 항목 대입·append·del 같은 변경은 어느 이름에서 읽어도 관찰됩니다."],"code":{"source":"original = [\"기초\", \"연습\"]\nalias = original\nalias.append(\"복습\")\nprint(original)\nprint(alias)","kind":"python","output":"['기초', '연습', '복습']\n['기초', '연습', '복습']","error":null}},{"title":"copy와 전체 슬라이스는 새 바깥 리스트를 만듭니다.","body":["original.copy()는 original의 항목들을 같은 순서로 담은 새 리스트를 돌려줍니다. original[:]처럼 전체 범위를 슬라이싱해도 새 바깥 리스트를 얻습니다. 문자열에서 부분을 읽었던 슬라이싱을 리스트에도 적용할 수 있습니다.","copied = original.copy() 다음에 copied.append(...)를 하면 새 바깥 리스트에 항목을 추가합니다. original의 길이는 바뀌지 않습니다. copied[0] = ...도 복사한 리스트의 그 칸을 다른 값에 연결하는 변경입니다.","이 복사는 항목으로 들어 있던 값들을 연결해 담는 얕은 복사입니다. 정수·문자열만 담긴 예제에서는 각 칸을 교체해도 원본에 영향이 없지만, 안쪽에 변경 가능한 리스트가 있으면 그 안쪽 값은 여전히 공유할 수 있습니다."],"code":{"source":"original = [10, 20]\ncopied = original.copy()\nsliced = original[:]\ncopied[0] = 99\nsliced.append(30)\nprint(original)\nprint(copied)\nprint(sliced)","kind":"python","output":"[10, 20]\n[99, 20]\n[10, 20, 30]","error":null}},{"title":"안쪽 리스트는 얕은 복사 뒤에도 공유될 수 있습니다.","body":["rows = [[1, 2], [3, 4]]는 리스트의 각 항목이 다시 리스트인 중첩 구조입니다. rows[0]은 첫 안쪽 리스트 [1, 2]이고, rows[0][1]은 그 리스트의 두 번째 값 2입니다. 대괄호를 한 단계씩 읽으면 어느 목록의 어느 칸인지 구별할 수 있습니다.","copied = rows.copy()는 바깥 리스트만 새로 만듭니다. copied[0]과 rows[0]은 같은 안쪽 리스트를 가리키므로 copied[0].append(9)나 copied[0][0] = 8은 원본 쪽에서도 보입니다.","반면 copied[1] = [0]은 복사한 바깥 리스트의 두 번째 칸을 다른 리스트에 연결합니다. 원래 rows[1]의 연결은 유지됩니다. 안쪽 리스트를 변경한 것인지, 바깥 리스트의 칸을 다른 값으로 교체한 것인지를 따로 추적하세요.","새 바깥 리스트를 얻었다는 사실만으로 모든 깊이의 값이 독립적이라고 결론내릴 수 없습니다. 더 깊은 복사 방법을 외우기보다 이번에는 어느 단계가 새로 생겼고 어느 값이 공유되는지 설명하는 것이 목표입니다."],"code":{"source":"rows = [[1, 2], [3, 4]]\ncopied = rows.copy()\ncopied[0].append(9)\ncopied[1] = [0]\nprint(rows)\nprint(copied)","kind":"python","output":"[[1, 2, 9], [3, 4]]\n[[1, 2, 9], [0]]","error":null}},{"title":"이름의 재대입과 공유한 값의 변경은 다릅니다.","body":["alias = [새 항목]은 alias라는 이름을 다른 리스트에 다시 연결합니다. 이미 공유하던 리스트의 항목을 변경하는 동작이 아닙니다. 따라서 original이라는 다른 이름의 연결은 그대로 남습니다.","alias.append(...)는 이름을 새 값에 연결하는 대입이 아니라, 그때 alias가 가리키는 리스트를 변경하는 호출입니다. original[0] = ...도 original이라는 이름 자체를 바꾸지 않고 그 리스트의 칸을 바꿉니다.","복사가 필요한지는 다음 작업에 따라 정합니다. 같은 목록을 함께 수정하려면 공유가 의도일 수 있고, 바깥 항목 구성을 따로 바꾸려면 새 리스트가 필요합니다. 중첩된 값까지 독립적이어야 한다면 얕은 복사만으로 충분한지 다시 판단해야 합니다."],"code":{"source":"original = [1, 2]\nalias = original\nalias = [7, 8]\nalias.append(9)\nprint(original)\nprint(alias)","kind":"python","output":"[1, 2]\n[7, 8, 9]","error":null}}],"worked":{"question":"원본 두 줄을 복사해 첫 줄에는 값을 덧붙이고 두 번째 줄은 통째로 교체했습니다. 어떤 변경이 원본에도 보이는지 단계별로 예측해 봅시다.","code":{"source":"original = [[\"읽기\"], [\"쓰기\"]]\nplan = original.copy()\nplan[0].append(\"복습\")\nplan[1] = [\"실습\"]\nplan.append([\"기록\"])\nprint(original)\nprint(plan)","kind":"python","output":"[['읽기', '복습'], ['쓰기']]\n[['읽기', '복습'], ['실습'], ['기록']]","error":null},"steps":["copy는 바깥 목록만 새로 만들고 읽기·쓰기라는 안쪽 리스트는 공유합니다.","plan[0].append는 공유한 첫 안쪽 리스트를 바꾸므로 original에서도 복습이 보입니다. plan[1] = [\"실습\"]은 복사한 바깥 칸의 연결만 바꾸므로 original의 쓰기는 남습니다.","plan.append는 새 바깥 리스트에 세 번째 칸을 추가합니다. original 바깥 리스트의 길이는 2로 유지됩니다."],"answer":"안쪽 리스트의 변경은 공유한 양쪽에서 보이고, 복사한 바깥 리스트의 칸 교체와 항목 추가는 그 바깥 리스트에만 영향을 줍니다."},"misconception":{"question":"copy로 새 리스트를 만들었으니 안쪽 값도 전부 따로 복사된 건가요?","answer":"copy와 전체 슬라이스는 바깥 리스트만 새로 만드는 얕은 복사입니다. 각 칸이 가리키는 안쪽 리스트는 공유될 수 있습니다. copied[0].append는 공유한 안쪽 값을 바꾸고, copied[0] = [...]는 복사한 바깥 칸의 연결만 바꾼다는 차이를 추적해야 합니다."},"keypoints":["b = a는 같은 리스트를 가리키는 이름을 추가합니다. 리스트 변경과 이름 재대입은 다른 동작입니다.","a.copy()와 a[:]는 새 바깥 리스트를 만들며, 그 바깥 리스트의 항목 추가·교체는 원본 바깥 리스트와 분리됩니다.","얕은 복사는 안쪽의 변경 가능한 값까지 전부 복사하지 않습니다. 어느 리스트의 어느 칸을 바꾸는지 단계별로 읽습니다."],"examples":[{"question":"아래 두 출력 값을 먼저 예상하고 실행하세요. alias[0]의 변경이 original에서도 보이는 이유를 이름과 리스트의 관계로 설명하세요.","skill":"별칭으로 공유한 변경","solution":{"answer":"두 출력은 모두 [9, 2]입니다. 두 이름이 같은 리스트를 가리킵니다.","code":{"source":"original = [1, 2]\nalias = original\nalias[0] = 9\nprint(original)\nprint(alias)","kind":"python","output":"[9, 2]\n[9, 2]","error":null}},"explanation":"alias = original은 복사가 아니라 이름 연결입니다. 첫 칸을 교체한 리스트 하나를 두 이름으로 읽습니다.","code":"original = [1, 2]\nalias = original\nalias[0] = 9\nprint(original)\nprint(alias)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"원본 list_a = [3, 4]를 유지하면서 list_b에만 5를 추가하고 싶습니다. 아래 대입 한 곳을 copy 호출로 고친 뒤 두 리스트를 출력하세요.","skill":"독립된 바깥 리스트","solution":{"answer":"list_b = list_a.copy()로 고치면 원본은 [3, 4], 결과는 [3, 4, 5]입니다.","code":{"source":"list_a = [3, 4]\nlist_b = list_a.copy()\nlist_b.append(5)\nprint(list_a)\nprint(list_b)","kind":"python","output":"[3, 4]\n[3, 4, 5]","error":null}},"explanation":"append가 어느 리스트를 변경하는지 먼저 구분합니다. 새 바깥 리스트를 만들면 list_b의 추가가 list_a의 길이를 늘리지 않습니다.","code":"list_a = [3, 4]\nlist_b = list_a\nlist_b.append(5)\nprint(list_a)\nprint(list_b)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"items = [\"A\", \"B\"]에서 전체 슬라이스로 새 리스트 result를 만들고 result[1]만 \"C\"로 바꾸세요. 원본이 유지되는지 확인하고, 두 리스트의 칸이 왜 따로 바뀌는지 설명하세요.","skill":"슬라이싱과 칸 교체","solution":{"answer":"items는 ['A', 'B'], result는 ['A', 'C']입니다.","code":{"source":"items = [\"A\", \"B\"]\nresult = items[:]\nresult[1] = \"C\"\nprint(items)\nprint(result)","kind":"python","output":"['A', 'B']\n['A', 'C']","error":null}},"explanation":"items[:]는 두 문자열을 연결해 담은 새 바깥 리스트를 만듭니다. result[1] 대입은 그 새 리스트의 칸만 다른 문자열에 연결합니다."},{"question":"아래 출력 두 줄을 예상하고 실행하세요. copied[0].append와 copied[1] 대입이 각각 어느 단계의 리스트에 작용하는지 설명하세요.","skill":"중첩 구조의 얕은 복사","solution":{"answer":"rows는 [[1, 7], [2]], copied는 [[1, 7], [9]]입니다. 첫 안쪽 리스트만 양쪽에 변경이 보입니다.","code":{"source":"rows = [[1], [2]]\ncopied = rows.copy()\ncopied[0].append(7)\ncopied[1] = [9]\nprint(rows)\nprint(copied)","kind":"python","output":"[[1, 7], [2]]\n[[1, 7], [9]]","error":null}},"explanation":"copy는 바깥을 새로 만들지만 안쪽 값은 공유합니다. append는 그 안쪽을 바꾸며, copied[1] 대입은 새 바깥 리스트의 칸만 교체합니다.","code":"rows = [[1], [2]]\ncopied = rows.copy()\ncopied[0].append(7)\ncopied[1] = [9]\nprint(rows)\nprint(copied)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"},{"question":"아래에서 alias를 새 리스트에 재대입한 뒤 변경하면 original도 바뀔까요? 출력 두 줄을 먼저 적고 실행하세요. alias = [8] 대신 alias.append(8)을 사용한 경우와 결과를 비교하세요.","skill":"재대입과 변경의 구분","solution":{"answer":"원본 코드는 [1, 2]와 [8, 9]를 출력합니다. 재대입 대신 append(8)을 했다면 같은 리스트에 8과 9가 추가되어 두 출력 모두 [1, 2, 8, 9]입니다.","code":{"source":"original = [1, 2]\nalias = original\nalias = [8]\nalias.append(9)\nprint(original)\nprint(alias)","kind":"python","output":"[1, 2]\n[8, 9]","error":null}},"explanation":"재대입은 alias의 연결을 다른 리스트로 바꾸지만 append는 연결된 리스트 자체를 변경합니다. 나머지 이름 original의 연결이 바뀌는지는 따로 추적합니다.","code":"original = [1, 2]\nalias = original\nalias = [8]\nalias.append(9)\nprint(original)\nprint(alias)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드"}]}],"review":[{"question":"같은 곡을 여러 번 재생한 순서가 중요합니다. 기록은 \"봄\", \"여름\", \"봄\"입니다. 원래 순서와 두 번의 봄을 보존할 자료형을 골라 만들고 첫 항목과 길이를 출력하세요. 집합으로 대신하면 어떤 정보가 사라지는지도 설명하세요.","skill":"자료구조 선택: 순서와 중복","solution":{"answer":"리스트 ['봄', '여름', '봄']이 맞고 첫 항목은 봄, 길이는 3입니다. 집합은 봄의 반복과 재생 위치를 보존하지 않습니다.","code":{"source":"plays = [\"봄\", \"여름\", \"봄\"]\nprint(plays[0])\nprint(len(plays))","kind":"python","output":"봄\n3","error":null}},"explanation":"여러 값이라는 사실만으로 집합을 고르지 않습니다. 이 요구에서는 같은 값이 나온 횟수와 순서가 기록의 일부이므로 리스트를 유지합니다.","related":["python-l026","python-l029"]},{"question":"책의 한 위치를 두 정수 3과 7의 고정된 쌍으로 묶고, 각 책의 대출 가능 수량은 책 이름으로 찾고 갱신하려 합니다. 위치에는 튜플, 수량에는 딕셔너리를 사용해 각각 만들고 위치 언패킹 값과 \"기초\"의 수량 2를 출력하세요. 두 자료형의 선택 이유도 적으세요.","skill":"자료구조 선택: 묶음과 이름표","solution":{"answer":"위치는 (3, 7)을 row, column으로 언패킹하고 수량은 {'기초': 2}에서 키로 조회합니다. 출력은 3 7과 2입니다.","code":{"source":"position = (3, 7)\nrow, column = position\navailable = {\"기초\": 2}\nprint(row, column)\nprint(available[\"기초\"])","kind":"python","output":"3 7\n2","error":null}},"explanation":"튜플은 함께 묶은 위치 쌍을 바꾸지 않겠다는 목적이고, 딕셔너리는 책 이름이라는 키로 수량을 찾고 갱신하는 목적입니다. 정해진 순서의 쌍과 키-값 관계는 다른 요구입니다.","related":["python-l027","python-l028"]},{"question":"신청한 활동은 [\"독서\", \"코딩\", \"독서\", \"운동\"]입니다. 서로 다른 활동의 수와 코딩 포함 여부만 필요할 때 알맞은 자료형으로 변환하고 두 결과를 출력하세요. 정렬된 표시도 출력하되 이것이 신청 순서를 복원한 것인지 설명하세요.","skill":"자료구조 선택: 포함과 중복 제거","solution":{"answer":"집합으로 변환하면 서로 다른 활동은 3개이고 코딩 포함은 True입니다. 정렬 표시는 ['독서', '운동', '코딩']이며 원래 신청 순서는 아닙니다.","code":{"source":"requests = [\"독서\", \"코딩\", \"독서\", \"운동\"]\nactivities = set(requests)\nprint(len(activities))\nprint(\"코딩\" in activities)\nprint(sorted(activities))","kind":"python","output":"3\nTrue\n['독서', '운동', '코딩']","error":null}},"explanation":"집합은 존재 여부와 중복 제거에 맞습니다. 정렬한 새 리스트는 표시를 위한 순서이며 집합에 담으며 잃은 신청 순서나 횟수를 되살리지 않습니다.","related":["python-l029"]},{"question":"아래 코드를 실행하기 전에 removed와 마지막 queue를 예상하세요. pop의 반환값과 del의 동작, append를 서로 구분해 결과가 나온 이유를 설명하세요.","skill":"변경 결과: 위치와 반환값","solution":{"answer":"removed는 B이고 마지막 queue는 ['C', 'D']입니다. pop은 뺀 값을 돌려주고 del은 지정한 위치를 삭제합니다.","code":{"source":"queue = [\"A\", \"B\", \"C\"]\nremoved = queue.pop(1)\nqueue.append(\"D\")\ndel queue[0]\nprint(removed)\nprint(queue)","kind":"python","output":"B\n['C', 'D']","error":null}},"explanation":"처음 pop(1)이 B를 빼면 A·C가 남습니다. D를 추가한 뒤 del queue[0]이 A를 삭제하므로 C·D가 남습니다. 삭제 후 인덱스는 남은 항목의 현재 위치로 다시 읽습니다.","code":"queue = [\"A\", \"B\", \"C\"]\nremoved = queue.pop(1)\nqueue.append(\"D\")\ndel queue[0]\nprint(removed)\nprint(queue)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드","related":["python-l026"]},{"question":"아래 출력 세 줄을 예상한 뒤 실행하세요. get으로 기본값을 읽었을 때 키가 자동 추가되는지 설명하고, 이어서 note 키에 실제 값 0을 넣은 뒤 포함 여부와 값을 확인하세요.","skill":"변경 결과: 없는 키와 저장된 0","solution":{"answer":"처음은 0, False, 1입니다. get은 키를 추가하지 않습니다. 직접 note에 0을 대입한 뒤에는 True와 0입니다.","code":{"source":"counts = {\"pen\": 2}\nprint(counts.get(\"note\", 0))\nprint(\"note\" in counts)\nprint(len(counts))\ncounts[\"note\"] = 0\nprint(\"note\" in counts)\nprint(counts[\"note\"])","kind":"python","output":"0\nFalse\n1\nTrue\n0","error":null}},"explanation":"없을 때 돌려줄 기본값과 딕셔너리에 저장된 값은 다릅니다. 실제 0도 유효한 값일 수 있으므로 존재 여부는 in으로, 값은 조회로 구분합니다.","code":"counts = {\"pen\": 2}\nprint(counts.get(\"note\", 0))\nprint(\"note\" in counts)\nprint(len(counts))","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드","related":["python-l028"]},{"question":"아래 파일은 튜플의 값을 서로 바꾸려고 합니다. 오류 종류를 확인하고, 튜플 항목을 수정하는 대신 새 튜플 (오른쪽 값, 왼쪽 값)을 만들어 pair에 다시 대입하세요. 두 이름으로 언패킹하여 8 3을 출력하세요.","skill":"변경 결과: 튜플과 재대입","solution":{"answer":"원본은 TypeError입니다. left, right = pair로 읽고 pair = (right, left)로 다시 연결하면 8 3을 출력할 수 있습니다.","code":{"source":"pair = (3, 8)\nleft, right = pair\npair = (right, left)\nleft, right = pair\nprint(left, right)","kind":"python","output":"8 3","error":null}},"explanation":"튜플 내부 항목 대입은 허용되지 않지만 이름을 새 튜플에 연결하는 대입은 가능합니다. 값을 읽은 순서와 새로 묶은 순서를 나누어 생각합니다.","code":"pair = (3, 8)\npair[0] = 8\npair[1] = 3","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드","related":["python-l027"]},{"question":"주문 orders = {\"연필\": 3, \"공책\": 0, \"지우개\": 2}에서 items로 읽어 수량이 양수인 주문만 이름과 수량을 한 줄씩 출력하고 전체 양수 수량의 합도 마지막에 출력하세요. 원본의 항목을 삭제하지 말고 조건으로 고르세요.","skill":"순회 적용: 키·값과 누적","solution":{"answer":"연필 3, 지우개 2가 나오고 합은 5입니다. 0인 공책은 출력·합계에서 제외합니다.","code":{"source":"orders = {\"연필\": 3, \"공책\": 0, \"지우개\": 2}\ntotal = 0\nfor name, count in orders.items():\n    if count > 0:\n        print(name, count)\n        total = total + count\nprint(total)","kind":"python","output":"연필 3\n지우개 2\n5","error":null}},"explanation":"items의 쌍을 이름과 수량으로 언패킹합니다. if가 선택한 값만 출력하고 누적하면 읽는 딕셔너리를 변경하지 않아도 요구를 만족합니다.","related":["python-l028","python-l030"]},{"question":"길이 목록 lengths = [0, 3, -1, 5]에서 양수인 길이만 골라 두 배로 만든 리스트를 컴프리헨션으로 작성하세요. 같은 결과를 일반 for·if·append로도 만들고 원본이 유지되는지 확인하세요.","skill":"순회 적용: 필터와 변환","solution":{"answer":"두 결과는 [6, 10]이고 원본은 [0, 3, -1, 5]입니다. 0은 양수가 아니어서 제외됩니다.","code":{"source":"lengths = [0, 3, -1, 5]\nshort = [length * 2 for length in lengths if length > 0]\nlong = []\nfor length in lengths:\n    if length > 0:\n        long.append(length * 2)\nprint(short)\nprint(long)\nprint(lengths)","kind":"python","output":"[6, 10]\n[6, 10]\n[0, 3, -1, 5]","error":null}},"explanation":"조건 length > 0은 먼저 담을 대상을 고르고, 결과 식 length * 2가 선택한 값을 변환합니다. 새 결과를 만드는 작업이므로 원본에서 항목을 지우거나 교체하지 않습니다.","related":["python-l030"]},{"question":"아래 코드에서 마지막 original, first, second를 예상한 뒤 실행하세요. 같은 리스트의 변경과 first라는 이름의 재대입을 구분하고, second가 어느 목록을 계속 읽는지 설명하세요.","skill":"별칭 오개념: 연결과 변경","solution":{"answer":"original과 second는 모두 ['A', 'B']이고 first는 ['C']입니다. second는 처음 공유한 리스트를 계속 가리킵니다.","code":{"source":"original = [\"A\"]\nfirst = original\nsecond = first\nfirst.append(\"B\")\nfirst = [\"C\"]\nprint(original)\nprint(first)\nprint(second)","kind":"python","output":"['A', 'B']\n['C']\n['A', 'B']","error":null}},"explanation":"first.append가 공유한 리스트에 B를 넣습니다. 이후 first = [\"C\"]는 first의 연결만 바꾸므로 original과 second가 가리키는 리스트는 남아 있습니다.","code":"original = [\"A\"]\nfirst = original\nsecond = first\nfirst.append(\"B\")\nfirst = [\"C\"]\nprint(original)\nprint(first)\nprint(second)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드","related":["python-l026","python-l031"]},{"question":"원본 original = [[1, 2], [3, 4]]의 각 행은 정수만 담은 리스트입니다. 아래처럼 바깥만 copy한 뒤 첫 행을 바꾸면 원본도 바뀝니다. 각 행을 copy해 새 바깥 리스트에 담는 한 단계 컴프리헨션으로 고쳐, working[0][0]을 9로 바꾸어도 원본은 유지되게 하세요.","skill":"별칭 오개념: 얕은 복사의 범위","solution":{"answer":"working = [row.copy() for row in original]로 각 행을 따로 복사하면 원본은 [[1, 2], [3, 4]], 작업용은 [[9, 2], [3, 4]]입니다.","code":{"source":"original = [[1, 2], [3, 4]]\nworking = [row.copy() for row in original]\nworking[0][0] = 9\nprint(original)\nprint(working)","kind":"python","output":"[[1, 2], [3, 4]]\n[[9, 2], [3, 4]]","error":null}},"explanation":"단순 original.copy()는 안쪽 행을 공유합니다. 각 행이 정수만 담는다는 이번 전제에서는 행별로 새 리스트를 만들면 안쪽 칸 교체도 분리됩니다. 더 깊이 중첩된 값까지 모두 복사하는 일반 해법이라고 확대하지 않습니다.","code":"original = [[1, 2], [3, 4]]\nworking = original.copy()\nworking[0][0] = 9\nprint(original)","codeKind":"python","codeLabel":"직접 확인하거나 고칠 코드","related":["python-l030","python-l031"]}]}];
